function fmtNumber(value) {
  return Number(value || 0).toLocaleString("ko-KR");
}

function fmtPrice(value) {
  if (!value) return "확인불가";
  return `${Number(value).toLocaleString("ko-KR")}원`;
}

function fmtPercent(value) {
  if (value === null || value === undefined || Number.isNaN(Number(value))) return "확인불가";
  return `${Number(value).toFixed(2)}%`;
}

function fmtAvailability(place) {
  const available = Number(place.availableRooms);
  const total = Number(place.totalRooms);
  const rate = Number(place.availabilityRate);
  if (Number.isFinite(available) && Number.isFinite(total) && total > 0) {
    const rateText = Number.isFinite(rate) ? ` · 잔여율 ${(rate * 100).toFixed(0)}%` : "";
    return `잔여 ${available}/${total}${rateText}`;
  }
  return "확인불가";
}

function availabilityUnitLabel(item = {}) {
  if (item.availabilityUnit) return item.availabilityUnit;
  if (item.listType === "객실 묶음 상품리스트") return "묶음상품";
  if (item.listType === "객실별 예약리스트") return "객실상품";
  return "상품/재고";
}

function fmtRemainingStock(item = {}) {
  const available = Number(item.availableRooms);
  const total = Number(item.totalRooms);
  if (Number.isFinite(available) && Number.isFinite(total) && total > 0) {
    return `잔여 ${fmtNumber(available)}/${fmtNumber(total)} ${availabilityUnitLabel(item)}`;
  }
  return "잔여 확인불가";
}

function fmtSoldOut(item) {
  const soldOut = Number(item.soldOutRooms);
  const total = Number(item.totalRooms);
  const rate = Number(item.soldOutRate);
  if (Number.isFinite(soldOut) && Number.isFinite(total) && total > 0) {
    const resolvedRate = Number.isFinite(rate) ? rate : soldOut / total;
    return `판매완료/마감 ${fmtNumber(soldOut)}/${fmtNumber(total)} · ${fmtAvailabilityRate(resolvedRate)}`;
  }
  return "";
}

function dateDiffDays(startDate, endDate) {
  const start = new Date(`${startDate}T00:00:00Z`);
  const end = new Date(`${endDate}T00:00:00Z`);
  if (Number.isNaN(start.getTime()) || Number.isNaN(end.getTime())) return 0;
  return Math.round((end - start) / 86400000);
}

function bookingDaysFromInputs(checkIn, checkOut) {
  const diff = dateDiffDays(checkIn, checkOut);
  return diff > 1 ? Math.min(31, diff + 1) : 1;
}

function fmtWeeklyReservation(item = {}) {
  const avg = Number(item.weeklyAvgReservationRate);
  const detail = item.weeklyReservationRateDetail || "";
  if (!Number.isFinite(avg) && !detail) return "";
  return [
    Number.isFinite(avg) ? `평균 예약률 ${fmtAvailabilityRate(avg)}` : "",
    detail ? `날짜별 예약률: ${detail}` : ""
  ].filter(Boolean).join(" · ");
}

function companyKey(value) {
  return String(value || "").replace(/\s+/g, "").toLowerCase();
}

function companyPlatformMap() {
  const map = new Map();
  for (const company of state.data?.companyPlatforms || []) {
    map.set(company.key || companyKey(company.name), company);
  }
  return map;
}

function platformTone(platform = "") {
  if (platform.includes("네이버")) return "naver";
  if (platform.includes("여기")) return "yeogi";
  if (platform.includes("떠나요")) return "ddnayo";
  if (platform.includes("야놀자") || platform.includes("NOL")) return "nol";
  return "other";
}

function renderCompanyPlatforms(item, platformMap) {
  const company = platformMap.get(companyKey(item.name));
  const rows = company?.platforms || [];
  if (!rows.length) return "";
  return `
    <details class="company-platforms">
      <summary>플랫폼 ${fmtNumber(rows.length)}개 더보기</summary>
      <div class="company-platform-list">
        ${rows.map((row) => `
          <a class="company-platform ${platformTone(row.platform)}" href="${row.url || "#"}" target="${row.url ? "_blank" : "_self"}" rel="noreferrer">
            <span class="company-platform-name">${row.platform}</span>
            <span class="company-platform-body">
              <strong>${row.rank ? `${row.rank}위` : row.group || "확인"}</strong>
              <small>${[row.price, row.stock, row.status].filter(Boolean).join(" · ") || "내용 확인"}</small>
              ${row.inventoryNote ? `<small>${row.inventoryNote}</small>` : ""}
            </span>
          </a>
        `).join("")}
      </div>
    </details>
  `;
}

function fmtDayUseStock(item) {
  const available = Number(item.dayUseAvailableStock);
  const total = Number(item.dayUseTotalStock);
  if (Number.isFinite(available) && Number.isFinite(total) && total > 0) {
    return `데이유즈재고 ${fmtNumber(available)}/${fmtNumber(total)}`;
  }
  return "";
}

function fmtSearchVolume(traffic) {
  if (!traffic?.collectableCount && !traffic?.collectable) return "확인불가";
  return fmtNumber(traffic.totalSearchVolume || 0);
}

function fmtTrafficCtr(traffic) {
  if (!traffic?.collectableCount && !traffic?.collectable) return "확인불가";
  return fmtPercent(traffic.combinedCtr);
}

function nowTime() {
  return new Date().toLocaleTimeString("ko-KR", { hour: "2-digit", minute: "2-digit" });
}

function addFeedback(message, type = "info") {
  if (!els.feedbackList) return;
  const item = document.createElement("div");
  item.className = `feedback-message ${type}`;
  const time = document.createElement("span");
  const body = document.createElement("strong");
  time.textContent = nowTime();
  body.textContent = message;
  item.append(time, body);
  els.feedbackList.prepend(item);
  while (els.feedbackList.children.length > 8) els.feedbackList.lastElementChild.remove();
}

function status(text) {
  els.statusPill.textContent = text;
}

async function fetchJson(url, options = {}) {
  const method = String(options.method || "GET").toUpperCase();
  const headers = new Headers(options.headers || {});
  if (["POST", "PUT", "PATCH", "DELETE"].includes(method) && state.auth.session?.csrfToken) {
    headers.set("X-CSRF-Token", state.auth.session.csrfToken);
  }
  const response = await fetch(url, { ...options, headers });
  const data = await response.json();
  if (!response.ok) {
    const error = new Error(data.error || "요청에 실패했습니다.");
    error.status = response.status;
    error.code = data.code || "";
    if (["AUTH_MFA_REQUIRED", "AUTH_MFA_ENROLLMENT_REQUIRED"].includes(error.code)) {
      showMfaGate({
        account: state.auth.session?.account,
        mfa: {
          ...(state.auth.session?.mfa || {}),
          ...(data.mfa || {}),
          challengeRequired: error.code === "AUTH_MFA_REQUIRED",
          enrollmentRequired: error.code === "AUTH_MFA_ENROLLMENT_REQUIRED"
        }
      }, error.message);
    }
    throw error;
  }
  return data;
}

function ensureAuthShell() {
  if (!document.getElementById("authGate")) {
    document.body.insertAdjacentHTML("afterbegin", `
      <div class="auth-gate" id="authGate" hidden>
        <section class="auth-card" aria-labelledby="authTitle">
          <div class="auth-brand"><span>숙박업 데이터랩</span><strong id="authTitle">계정 로그인</strong></div>
          <form class="auth-login-form" id="authLoginForm">
            <label><span>아이디</span><input name="username" autocomplete="username" required></label>
            <label><span>비밀번호</span><input name="password" type="password" autocomplete="current-password" required></label>
            <button class="primary-button" type="submit">로그인</button>
            <p class="auth-message" id="authMessage" aria-live="polite"></p>
          </form>
          <div class="auth-mfa-panel" id="authMfaPanel" hidden>
            <p class="auth-link-summary" id="authMfaSummary">관리자 2단계 인증이 필요합니다.</p>
            <button class="primary-button" id="authMfaEnrollButton" type="button" hidden>인증 앱 등록 시작</button>
            <div class="auth-mfa-setup" id="authMfaSetup" hidden>
              <span>인증 앱에 아래 설정 키를 등록한 뒤 현재 코드를 입력하세요.</span>
              <code id="authMfaSecret"></code>
            </div>
            <form class="auth-link-form" id="authMfaForm">
              <label><span>인증 코드 또는 복구 코드</span><input name="code" inputmode="numeric" autocomplete="one-time-code" required></label>
              <button class="primary-button" type="submit">관리자 확인</button>
            </form>
            <div class="auth-mfa-recovery" id="authMfaRecovery" hidden>
              <strong>복구 코드는 지금 한 번만 표시됩니다.</strong>
              <div id="authMfaRecoveryCodes"></div>
              <button class="primary-button" id="authMfaContinueButton" type="button">확인하고 관리자 화면 열기</button>
            </div>
            <p class="auth-message" id="authMfaMessage" aria-live="polite"></p>
          </div>
          <details class="auth-reset">
            <summary>비밀번호 재설정 요청</summary>
            <form id="authResetRequestForm">
              <label><span>아이디</span><input name="username" autocomplete="username" required></label>
              <button class="secondary-button" type="submit">요청 접수</button>
            </form>
            <p id="authResetMessage" aria-live="polite"></p>
          </details>
          <div class="auth-link-panel" id="authLinkPanel" hidden>
            <p class="auth-link-summary" id="authLinkSummary"></p>
            <form class="auth-link-form" id="authLinkForm">
              <label><span>새 비밀번호</span><input name="newPassword" type="password" minlength="10" autocomplete="new-password" required></label>
              <label><span>새 비밀번호 확인</span><input name="confirmPassword" type="password" minlength="10" autocomplete="new-password" required></label>
              <button class="primary-button" type="submit">비밀번호 설정</button>
            </form>
            <p class="auth-message" id="authLinkMessage" aria-live="polite"></p>
          </div>
        </section>
      </div>
    `);
  }

  if (!document.getElementById("authSessionBar")) {
    const target = businessMode()
      ? document.querySelector(".business-controls")
      : document.querySelector(".topbar");
    target?.insertAdjacentHTML("beforeend", `
      <div class="auth-session-bar" id="authSessionBar" hidden>
        <span id="authSessionIdentity"></span>
        <button class="ghost-button" id="authLogoutButton" type="button">로그아웃</button>
      </div>
    `);
  }
}

function showAuthGate(message = "") {
  document.body.classList.add("auth-required");
  const gate = document.getElementById("authGate");
  const messageBox = document.getElementById("authMessage");
  if (gate) gate.hidden = false;
  if (messageBox) messageBox.textContent = message;
  const login = document.getElementById("authLoginForm");
  const reset = document.querySelector(".auth-reset");
  if (login) login.hidden = false;
  if (reset) reset.hidden = false;
  const mfaPanel = document.getElementById("authMfaPanel");
  if (mfaPanel) mfaPanel.hidden = true;
}

function showMfaGate(session = {}, message = "") {
  document.body.classList.add("auth-required");
  const gate = document.getElementById("authGate");
  const title = document.getElementById("authTitle");
  const login = document.getElementById("authLoginForm");
  const reset = document.querySelector(".auth-reset");
  const linkPanel = document.getElementById("authLinkPanel");
  const panel = document.getElementById("authMfaPanel");
  const summary = document.getElementById("authMfaSummary");
  const enroll = document.getElementById("authMfaEnrollButton");
  const form = document.getElementById("authMfaForm");
  const messageBox = document.getElementById("authMfaMessage");
  const enrollmentRequired = Boolean(session.mfa?.enrollmentRequired);
  if (gate) gate.hidden = false;
  if (login) login.hidden = true;
  if (reset) reset.hidden = true;
  if (linkPanel) linkPanel.hidden = true;
  if (panel) panel.hidden = false;
  if (title) title.textContent = enrollmentRequired ? "관리자 MFA 등록" : "관리자 2단계 확인";
  if (summary) summary.textContent = enrollmentRequired
    ? "상용 관리자 작업을 시작하려면 인증 앱 등록이 필요합니다."
    : "인증 앱의 6자리 코드 또는 사용하지 않은 복구 코드를 입력하세요.";
  if (enroll) enroll.hidden = !enrollmentRequired;
  if (form) form.hidden = enrollmentRequired;
  if (messageBox) messageBox.textContent = message;
  state.auth.session = { ...(state.auth.session || {}), ...session };
}

function showMfaRecoveryCodes(codes = []) {
  const recovery = document.getElementById("authMfaRecovery");
  const list = document.getElementById("authMfaRecoveryCodes");
  const form = document.getElementById("authMfaForm");
  const setup = document.getElementById("authMfaSetup");
  if (form) form.hidden = true;
  if (setup) setup.hidden = true;
  if (recovery) recovery.hidden = false;
  if (list) list.innerHTML = codes.map((code) => `<code>${escapeHtml(code)}</code>`).join("");
}

function showAuthenticatedSession(session) {
  document.body.classList.remove("auth-required");
  const gate = document.getElementById("authGate");
  const bar = document.getElementById("authSessionBar");
  const identity = document.getElementById("authSessionIdentity");
  if (gate) gate.hidden = true;
  if (bar) bar.hidden = false;
  if (identity) {
    const account = session.account || {};
    identity.textContent = `${account.displayName || account.username || "사용자"} · ${account.role === "admin" ? "관리자" : "사업자"}`;
    if (account.mustResetPassword) identity.dataset.warning = "true";
  }
}

function currentAuthLink() {
  const params = new URLSearchParams(String(window.location.hash || "").replace(/^#/, ""));
  if (params.get("invite")) return { mode: "invite", token: params.get("invite") };
  if (params.get("reset")) return { mode: "reset", token: params.get("reset") };
  return null;
}

async function prepareAuthLinkFlow() {
  const flow = currentAuthLink();
  if (!flow) return false;
  state.auth.linkFlow = flow;
  const loginForm = document.getElementById("authLoginForm");
  const reset = document.querySelector(".auth-reset");
  const panel = document.getElementById("authLinkPanel");
  const title = document.getElementById("authTitle");
  const summary = document.getElementById("authLinkSummary");
  const message = document.getElementById("authLinkMessage");
  showAuthGate();
  if (loginForm) loginForm.hidden = true;
  if (reset) reset.hidden = true;
  if (panel) panel.hidden = false;
  if (title) title.textContent = flow.mode === "invite" ? "초대 계정 활성화" : "비밀번호 재설정";
  if (summary) summary.textContent = flow.mode === "invite" ? "초대 정보를 확인하는 중입니다." : "새 비밀번호를 설정하면 기존 로그인 세션이 종료됩니다.";
  if (flow.mode === "invite") {
    try {
      const result = await fetchJson("/api/auth/invitations/inspect", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ token: flow.token })
      });
      const invitation = result.invitation || {};
      if (summary) summary.textContent = `${invitation.username || "초대 계정"} · ${invitation.role === "admin" ? "관리자" : "사업자"} · 허용 업체 ${(invitation.companyIds || []).length}개`;
    } catch (error) {
      if (message) message.textContent = error.message;
      document.getElementById("authLinkForm")?.setAttribute("hidden", "");
    }
  }
  return true;
}

async function loadAuthSession() {
  const response = await fetch("/api/auth/session", { headers: { Accept: "application/json" } });
  const session = await response.json();
  state.auth.session = session;
  return session;
}

async function beginMfaEnrollment(target = "gate") {
  const result = await fetchJson("/api/admin/auth/mfa/enroll", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: "{}"
  });
  if (target === "console") {
    const setup = document.getElementById("authMfaConsoleSetup");
    const secret = document.getElementById("authMfaConsoleSecret");
    if (setup) setup.hidden = false;
    if (secret) secret.textContent = result.secret || "";
    return result;
  }
  const enroll = document.getElementById("authMfaEnrollButton");
  const setup = document.getElementById("authMfaSetup");
  const secret = document.getElementById("authMfaSecret");
  const form = document.getElementById("authMfaForm");
  if (enroll) enroll.hidden = true;
  if (setup) setup.hidden = false;
  if (secret) secret.textContent = result.secret || "";
  if (form) form.hidden = false;
  state.auth.mfaEnrollmentPending = true;
  return result;
}

function wireAuthEvents() {
  document.getElementById("authLoginForm")?.addEventListener("submit", async (event) => {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    const message = document.getElementById("authMessage");
    if (message) message.textContent = "로그인 중입니다.";
    try {
      const result = await fetchJson("/api/auth/login", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ username: form.get("username"), password: form.get("password") })
      });
      if (result.mfa?.challengeRequired || result.mfa?.enrollmentRequired) {
        window.location.assign("/admin");
        return;
      }
      const currentPath = businessMode() ? "/app" : "/admin";
      window.location.assign(result.redirectTo === currentPath ? currentPath : result.redirectTo);
    } catch (error) {
      if (message) message.textContent = error.message;
    }
  });

  document.getElementById("authMfaEnrollButton")?.addEventListener("click", () => {
    const message = document.getElementById("authMfaMessage");
    if (message) message.textContent = "인증 앱 설정 키를 생성하는 중입니다.";
    beginMfaEnrollment().then(() => {
      if (message) message.textContent = "설정 키를 등록한 뒤 현재 6자리 코드를 입력하세요.";
    }).catch((error) => { if (message) message.textContent = error.message; });
  });

  document.getElementById("authMfaForm")?.addEventListener("submit", async (event) => {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    const code = form.get("code");
    const message = document.getElementById("authMfaMessage");
    const endpoint = state.auth.mfaEnrollmentPending ? "/api/admin/auth/mfa/confirm" : "/api/auth/mfa/challenge";
    if (message) message.textContent = "인증 코드를 확인하는 중입니다.";
    try {
      const result = await fetchJson(endpoint, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ code })
      });
      if (result.recoveryCodes?.length) {
        showMfaRecoveryCodes(result.recoveryCodes);
        if (message) message.textContent = "복구 코드를 안전한 곳에 보관하세요.";
        return;
      }
      window.location.assign("/admin");
    } catch (error) {
      if (message) message.textContent = error.message;
    }
  });

  document.getElementById("authMfaContinueButton")?.addEventListener("click", () => window.location.assign("/admin"));

  document.getElementById("authResetRequestForm")?.addEventListener("submit", async (event) => {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    const message = document.getElementById("authResetMessage");
    try {
      const result = await fetchJson("/api/auth/password-reset/request", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ username: form.get("username") })
      });
      if (message) message.textContent = result.message;
    } catch (error) {
      if (message) message.textContent = error.message;
    }
  });

  document.getElementById("authLinkForm")?.addEventListener("submit", async (event) => {
    event.preventDefault();
    const flow = state.auth.linkFlow;
    const form = new FormData(event.currentTarget);
    const password = String(form.get("newPassword") || "");
    const confirmation = String(form.get("confirmPassword") || "");
    const message = document.getElementById("authLinkMessage");
    if (!flow) return;
    if (password !== confirmation) {
      if (message) message.textContent = "비밀번호 확인이 일치하지 않습니다.";
      return;
    }
    try {
      const endpoint = flow.mode === "invite" ? "/api/auth/invitations/accept" : "/api/auth/password-reset/confirm";
      await fetchJson(endpoint, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(flow.mode === "invite"
          ? { token: flow.token, newPassword: password }
          : { token: flow.token, newPassword: password })
      });
      history.replaceState(null, "", window.location.pathname);
      if (message) message.textContent = flow.mode === "invite" ? "계정이 활성화되었습니다. 로그인 화면으로 이동합니다." : "비밀번호가 변경되었습니다. 로그인 화면으로 이동합니다.";
      setTimeout(() => window.location.assign("/app"), 700);
    } catch (error) {
      if (message) message.textContent = error.message;
    }
  });

  document.getElementById("authLogoutButton")?.addEventListener("click", async () => {
    await fetchJson("/api/auth/logout", { method: "POST", headers: { "Content-Type": "application/json" }, body: "{}" });
    window.location.assign(businessMode() ? "/app" : "/admin");
  });
}

