function resetAuthAccountForm(account = null) {
  if (!els.authAccountForm) return;
  els.authAccountForm.reset();
  state.auth.editingUserId = account?.userId || "";
  els.authAccountForm.elements.userId.value = account?.userId || "";
  els.authAccountForm.elements.username.value = account?.username || "";
  els.authAccountForm.elements.displayName.value = account?.displayName || "";
  els.authAccountForm.elements.role.value = account?.role || "business";
  els.authAccountForm.elements.status.value = account?.status || "active";
  els.authAccountForm.elements.companyIds.value = (account?.companyIds || []).join(", ");
  els.authAccountForm.elements.username.readOnly = Boolean(account?.userId);
}

function renderAuthAccounts() {
  if (!els.authAccountSummary || !els.authAccountList || !els.authResetRequestList) return;
  const report = state.auth.accounts || { items: [], summary: {} };
  const summary = report.summary || {};
  els.authAccountSummary.innerHTML = `
    <span><strong>${fmtNumber(summary.active || 0)}</strong><em>활성 계정</em></span>
    <span><strong>${fmtNumber(summary.admins || 0)}</strong><em>관리자</em></span>
    <span><strong>${fmtNumber(summary.businesses || 0)}</strong><em>사업자</em></span>
  `;
  els.authAccountList.innerHTML = (report.items || []).length ? (report.items || []).map((account) => `
    <div class="auth-account-row">
      <div><strong>${escapeHtml(account.displayName || account.username)}</strong><span>${escapeHtml(account.username)}</span></div>
      <span class="status-chip ${account.status === "active" ? "success" : "muted"}">${account.status === "active" ? "활성" : "비활성"}</span>
      <span>${account.role === "admin" ? `관리자 · MFA ${account.mfa?.enabled ? "등록" : "미등록"}` : `사업자 · ${(account.companyIds || []).length}개 업체`}</span>
      <span>${account.mustResetPassword ? "비밀번호 변경 필요" : account.lastLoginAt ? `최근 로그인 ${escapeHtml(account.lastLoginAt.slice(0, 10))}` : "로그인 전"}</span>
      <div class="button-pair">
        <button class="ghost-button tiny-button" type="button" data-auth-account-edit="${escapeHtml(account.userId)}">수정</button>
        <button class="ghost-button tiny-button" type="button" data-auth-account-reset="${escapeHtml(account.username)}">재설정</button>
      </div>
    </div>
  `).join("") : `<div class="empty">등록된 계정이 없습니다.</div>`;

  const resets = state.auth.passwordResetRequests?.items || [];
  els.authResetRequestList.innerHTML = resets.length ? resets.slice(0, 20).map((item) => `
    <div class="auth-reset-row"><strong>${escapeHtml(item.username || item.userId)}</strong><span>${escapeHtml(item.status)} · ${escapeHtml(item.deliveryStatus || "pending")}</span><span>${escapeHtml(item.requestedAt || "")}</span></div>
  `).join("") : `<div class="empty">재설정 요청이 없습니다.</div>`;

  renderAuthInvitations();
  renderAuthSecurity();
}

function inviteStatusLabel(status = "") {
  return ({ pending: "발송 완료", accepted: "활성화 완료", expired: "만료", cancelled: "취소", superseded: "재발급됨", activation_failed: "활성화 실패", processing: "활성화 중" })[status] || status;
}

function renderAuthInvitations() {
  if (!els.authInviteSummary || !els.authInviteList) return;
  const report = state.auth.invitations || { items: [], summary: {}, deliveryConnector: {} };
  const summary = report.summary || {};
  const connector = report.deliveryConnector || {};
  els.authInviteSummary.innerHTML = `
    <span><strong>${fmtNumber(summary.pending || 0)}</strong><em>대기</em></span>
    <span><strong>${fmtNumber(summary.accepted || 0)}</strong><em>활성화</em></span>
    <span><strong>${fmtNumber(summary.deliveryAttention || 0)}</strong><em>전달 확인</em></span>
    <span><strong>${escapeHtml(connector.activeMode || "mock")}</strong><em>${connector.realConfigured ? "실메일 연결" : "mock 전달"}</em></span>
  `;
  els.authInviteList.innerHTML = (report.items || []).length ? report.items.slice(0, 50).map((item) => {
    const canReissue = item.status !== "accepted" && item.status !== "processing";
    const canCancel = item.status === "pending";
    return `
      <div class="auth-invite-row">
        <div><strong>${escapeHtml(item.displayName || item.username)}</strong><span>${escapeHtml(item.username)} · ${item.role === "admin" ? "관리자" : `사업자 ${(item.companyIds || []).length}개 업체`}</span></div>
        <span class="status-chip ${item.status === "accepted" ? "success" : item.status === "pending" ? "warning" : "muted"}">${escapeHtml(inviteStatusLabel(item.status))}</span>
        <span>${escapeHtml(item.deliveryMode || "-")} · ${escapeHtml(item.deliveryStatus || "pending")}</span>
        <time>${escapeHtml(String(item.expiresAt || "").slice(0, 10))}</time>
        <div class="button-pair">
          ${canReissue ? `<button class="ghost-button tiny-button" type="button" data-auth-invite-reissue="${escapeHtml(item.inviteId)}">재발급</button>` : ""}
          ${canCancel ? `<button class="ghost-button tiny-button" type="button" data-auth-invite-cancel="${escapeHtml(item.inviteId)}">취소</button>` : ""}
        </div>
      </div>
    `;
  }).join("") : `<div class="empty">발급된 초대가 없습니다.</div>`;
}

function authDeliveryStatusLabel(status = "") {
  return ({
    sending: "전송 중",
    succeeded: "provider 접수",
    delivered: "전달 완료",
    retry_required: "재시도 필요",
    review_required: "검수 필요",
    bounced: "반송",
    complained: "수신 거부",
    failed: "실패",
    processing: "처리 중"
  })[status] || status || "미확인";
}

function authDeliveryTone(status = "") {
  if (["succeeded", "delivered"].includes(status)) return "success";
  if (["retry_required", "review_required", "bounced", "complained"].includes(status)) return "warning";
  return status === "failed" ? "danger" : "muted";
}

function renderAuthDeliveries() {
  if (!els.authDeliverySummary || !els.authDeliveryDiagnostics || !els.authDeliveryList) return;
  const report = state.auth.deliveries || { summary: {}, connector: {}, diagnostics: {}, items: [], retryQueue: [] };
  const summary = report.summary || {};
  const connector = report.connector || {};
  const diagnostics = report.diagnostics || {};
  const queueByDelivery = new Map((report.retryQueue || []).map((item) => [item.lastDeliveryId, item]));
  els.authDeliverySummary.innerHTML = `
    <span><strong>${fmtNumber((summary.succeeded || 0) + (summary.delivered || 0))}</strong><em>접수·전달</em></span>
    <span><strong>${fmtNumber(summary.retryQueued || 0)}</strong><em>재시도 대기</em></span>
    <span><strong>${fmtNumber(summary.bounced || 0)}</strong><em>반송</em></span>
    <span><strong>${fmtNumber((summary.failed || 0) + (summary.reviewRequired || 0))}</strong><em>실패·검수</em></span>
    <span><strong>${fmtNumber(summary.providerIdsRecorded || 0)}</strong><em>provider ID</em></span>
    <span><strong>${fmtNumber(summary.webhookEvents || 0)}</strong><em>웹훅 이벤트</em></span>
  `;
  const diagnosticRows = [
    ["실행 모드", `${connector.activeMode || "mock"} · ${connector.provider || "generic_http"}`, connector.activeMode === "real"],
    ["운영 준비", connector.operationalReady ? "완료" : "설정 필요", connector.operationalReady],
    ["재시도 암호화", connector.queueEncryptionConfigured ? "정상" : "키 필요", connector.queueEncryptionConfigured],
    ["웹훅 검증", connector.webhookConfigured ? "정상" : "서명 키 필요", connector.webhookConfigured],
    ["재시도 워커", diagnostics.retryWorkerEnabled ? `${fmtNumber(diagnostics.retryWorkerIntervalSeconds || 0)}초 주기` : connector.activeMode === "mock" ? "mock 비활성" : "비활성", diagnostics.retryWorkerEnabled || connector.activeMode === "mock"],
    ["다음 재시도", diagnostics.nextRetryAt ? String(diagnostics.nextRetryAt).slice(0, 16).replace("T", " ") : "대기 없음", !diagnostics.pendingRetryCount]
  ];
  els.authDeliveryDiagnostics.innerHTML = diagnosticRows.map(([label, value, ready]) => `
    <span><em>${escapeHtml(label)}</em><strong>${escapeHtml(value)}</strong><i class="status-chip ${ready ? "success" : "warning"}">${ready ? "정상" : "확인"}</i></span>
  `).join("");
  els.authDeliveryList.innerHTML = (report.items || []).length ? report.items.map((item) => {
    const queue = queueByDelivery.get(item.deliveryId);
    const canRetry = item.status === "retry_required" || ["pending", "failed", "review_required"].includes(queue?.status);
    const canResend = ["bounced", "complained", "failed", "review_required"].includes(item.status);
    return `
      <article class="auth-delivery-row">
        <div><strong>${escapeHtml(item.recipient || "수신자 미확인")}</strong><span>${item.kind === "account_invitation" ? "계정 초대" : "비밀번호 재설정"} · ${escapeHtml(item.provider || "-")}</span></div>
        <span class="status-chip ${authDeliveryTone(item.status)}">${escapeHtml(authDeliveryStatusLabel(item.status))}</span>
        <div class="auth-delivery-ids"><span>내부 ${escapeHtml(item.deliveryId || "-")}</span><span>provider ${escapeHtml(item.providerDeliveryId || "대기")}</span></div>
        <div class="auth-delivery-attempt"><span>${fmtNumber(item.attemptNumber || 1)}회 시도</span><span>${queue ? `큐 ${escapeHtml(queue.status)}` : escapeHtml(item.queueStatus || "직접 전송")}</span></div>
        <time>${escapeHtml(String(item.completedAt || item.requestedAt || "").slice(0, 16).replace("T", " "))}</time>
        <div class="button-pair">
          ${canRetry ? `<button class="secondary-button tiny-button" type="button" data-auth-delivery-retry="${escapeHtml(item.deliveryId)}">지금 재시도</button>` : ""}
          ${canResend ? `<button class="ghost-button tiny-button" type="button" data-auth-delivery-resend="${escapeHtml(item.deliveryId)}">새 링크 재전송</button>` : ""}
        </div>
      </article>
    `;
  }).join("") : `<div class="empty">선택한 상태의 이메일 전달 이력이 없습니다.</div>`;
}

function authAuditLabel(eventType = "") {
  return ({
    login_succeeded: "로그인 성공",
    login_failed: "로그인 실패",
    login_blocked: "로그인 잠금",
    logout: "로그아웃",
    password_reset_requested: "재설정 요청",
    password_reset_blocked: "재설정 제한",
    password_changed: "비밀번호 변경",
    password_change_failed: "비밀번호 변경 실패",
    account_created: "계정 생성",
    account_updated: "계정 변경",
    permission_changed: "권한 변경",
    tenant_access_denied: "테넌트 접근 차단",
    security_lock_released: "잠금 해제",
    invitation_issued: "초대 발급",
    invitation_reissued: "초대 재발급",
    invitation_cancelled: "초대 취소",
    invitation_accepted: "초대 활성화",
    invitation_activation_failed: "초대 활성화 실패",
    invitation_delivery_blocked: "초대 발급 제한",
    account_invitation_delivery: "초대 전달",
    password_reset_delivery: "재설정 전달",
    auth_delivery_webhook: "이메일 상태 웹훅",
    auth_delivery_retry_run: "이메일 재시도 실행",
    auth_delivery_manual_resend: "새 링크 재전송",
    login_password_succeeded: "비밀번호 확인",
    mfa_enrollment_started: "MFA 등록 시작",
    mfa_enabled: "MFA 등록 완료",
    mfa_challenge_succeeded: "MFA 확인 성공",
    mfa_challenge_failed: "MFA 확인 실패",
    mfa_challenge_blocked: "MFA 확인 잠금",
    mfa_recovery_code_used: "복구 코드 사용",
    mfa_recovery_codes_regenerated: "복구 코드 재발급",
    mfa_disabled: "MFA 비활성화",
    mfa_step_up_denied: "MFA 미확인 차단"
  })[eventType] || eventType || "인증 이벤트";
}

function renderAuthSecurity() {
  if (!els.authSecuritySummary || !els.authSecurityLocks || !els.authAuditList) return;
  const report = state.auth.security || { summary: {}, locks: [], items: [], policies: {} };
  const summary = report.summary || {};
  const cards = [
    [summary.loginSuccesses || 0, "로그인 성공"],
    [summary.loginFailures || 0, "실패·잠금"],
    [summary.tenantDenials || 0, "테넌트 차단"],
    [summary.accountChanges || 0, "계정·권한 변경"],
    [summary.passwordChanges || 0, "비밀번호 변경"],
    [summary.activeLocks || 0, "활성 잠금"]
  ];
  els.authSecuritySummary.innerHTML = cards.map(([value, label]) => `<span><strong>${fmtNumber(value)}</strong><em>${label}</em></span>`).join("");

  const login = report.policies?.login || {};
  const reset = report.policies?.passwordReset || {};
  const invitation = report.policies?.invitation || {};
  const mfa = report.policies?.mfa || {};
  if (els.authSecurityPolicy) {
    els.authSecurityPolicy.innerHTML = `
      <span>로그인: 계정 ${fmtNumber(login.accountMaxAttempts || 0)}회 · IP ${fmtNumber(login.ipMaxAttempts || 0)}회 · ${fmtNumber(login.lockMinutes || 0)}분 잠금</span>
      <span>재설정: 계정 ${fmtNumber(reset.accountMaxRequests || 0)}회 · IP ${fmtNumber(reset.ipMaxRequests || 0)}회 · ${fmtNumber(reset.lockMinutes || 0)}분 제한</span>
      <span>초대: 계정 ${fmtNumber(invitation.accountMaxDeliveries || 0)}회 · IP ${fmtNumber(invitation.ipMaxDeliveries || 0)}회 · ${fmtNumber(invitation.lockMinutes || 0)}분 제한</span>
      <span>MFA: 계정 ${fmtNumber(mfa.accountMaxAttempts || 0)}회 · IP ${fmtNumber(mfa.ipMaxAttempts || 0)}회 · ${fmtNumber(mfa.sessionMinutes || 0)}분 확인 유지</span>
    `;
  }

  els.authSecurityLocks.innerHTML = (report.locks || []).length ? report.locks.map((item) => `
    <div class="auth-lock-row">
      <div><strong>${escapeHtml(item.label || item.scope)}</strong><span>${escapeHtml(({ login: "로그인", password_reset: "비밀번호 재설정", invitation_delivery: "초대 발급", invitation_activation: "초대 활성화", mfa_challenge: "MFA 확인" })[item.action] || item.action)} · ${fmtNumber(item.failureCount || 0)}회</span></div>
      <span class="status-chip warning">${escapeHtml(String(item.lockedUntil || "").slice(0, 16).replace("T", " "))}까지</span>
      <button class="ghost-button tiny-button" type="button" data-auth-lock-unlock="${escapeHtml(item.lockId)}">잠금 해제</button>
    </div>
  `).join("") : `<div class="empty">활성 잠금이 없습니다.</div>`;

  els.authAuditList.innerHTML = (report.items || []).length ? report.items.slice(0, 80).map((item) => `
    <div class="auth-audit-row">
      <div><strong>${escapeHtml(authAuditLabel(item.eventType))}</strong><span>${escapeHtml(item.actorUsername || item.targetUsername || item.companyId || "시스템")}</span></div>
      <span class="status-chip ${item.outcome === "succeeded" || item.outcome === "accepted" ? "success" : item.outcome === "blocked" || item.outcome === "denied" ? "warning" : "muted"}">${escapeHtml(item.outcome || "recorded")}</span>
      <time>${escapeHtml(String(item.occurredAt || "").slice(0, 16).replace("T", " "))}</time>
    </div>
  `).join("") : `<div class="empty">선택 기간의 감사 이력이 없습니다.</div>`;
}

function authKeyEvidenceLabel(status = "") {
  return {
    passed: "통과",
    warning: "확인 필요",
    blocked: "적용 차단",
    failed: "실패",
    pending: "대기",
    manual_confirmation: "수동 확인"
  }[status] || status || "미실행";
}

function authKeyItemLabel(item = {}) {
  return {
    current_key_configuration: "현재 키 설정",
    version_lineage: "버전 연결",
    transition_window: "제한된 전환 기간",
    previous_key_configuration: "이전 키 설정",
    session_invalidation_impact: "세션 폐기 영향",
    mfa_reencryption: "MFA 재암호화",
    retry_queue_reencryption: "이메일 재시도 큐 재암호화",
    webhook_transition: "웹훅 서명 전환",
    login: "로그인과 세션 경계",
    mfa: "MFA 현재 키 복호화",
    csrf: "CSRF 현재 키 서명",
    invitation: "초대 자격정보 저장",
    email_retry: "이메일 재시도 현재 키 왕복",
    webhook: "웹훅 서명 경계",
    rotation_state: "적용 버전 증적",
    current_version_active: "현재 버전 활성화",
    post_rotation_smoke: "적용 후 보안 스모크 통과",
    mfa_current_only: "MFA가 현재 키만 사용",
    queue_current_only: "재시도 큐가 현재 키만 사용",
    provider_current_signature: "provider 현재 웹훅 서명 확인",
    previous_keys_removed: "이전 키 환경변수 제거",
    transition_closed: "전환 기간 종료"
  }[item.checkId || item.id] || item.label || item.checkId || item.id || "-";
}

function authKeyRecoveryCopy(item = {}) {
  return {
    preserve_previous: ["이전 키링 유지", "복호화 불가 또는 스모크 실패가 남아 있으면 이전 키와 전환 기간을 제거하지 않습니다."],
    stop_retries: ["위험한 재시도 중지", "큐 복호화가 차단되면 수동 이메일 재시도를 멈추고 암호화 큐 파일을 그대로 보존합니다."],
    inspect_evidence: ["안전한 증적 확인", "키 값을 로그에 옮기지 않고 사전점검·회전 이력·스모크 실패 분류만 확인합니다."],
    restore_configuration: ["직전 정상 설정 복원", "관리형 비밀 저장소에서 직전 버전과 키 구성을 복원하고 한 인스턴스로 재기동한 뒤 사전점검을 반복합니다."],
    restore_data_only_if_needed: ["복호화 불가 시에만 데이터 복구", "올바른 현재·이전 키링으로도 MFA 또는 큐가 읽히지 않을 때만 검증된 DATA_DIR 백업을 사용합니다."],
    retest_before_resume: ["복구 증명", "재시도 재개나 이전 키 제거 전에 6개 인증 경계 스모크를 다시 실행합니다."]
  }[item.id] || [item.label || "-", item.action || ""];
}

function renderAuthKeyEvidence(run, emptyMessage) {
  if (!run) return `<div class="empty">${escapeHtml(emptyMessage)}</div>`;
  return `
    <div class="auth-key-evidence-head">
      <div><strong>${escapeHtml(run.runId || "-")}</strong><span>${escapeHtml(run.generatedAt || "-")}</span></div>
      <span class="status-chip ${productQaTone(run.status)}">${escapeHtml(authKeyEvidenceLabel(run.status))}</span>
    </div>
    ${(run.checks || []).map((item) => `
      <div class="auth-key-evidence-row">
        <div><strong>${escapeHtml(authKeyItemLabel(item))}</strong><span>${escapeHtml(item.detail || "")}</span></div>
        <span class="status-chip ${productQaTone(item.status)}">${escapeHtml(authKeyEvidenceLabel(item.status))}</span>
      </div>
    `).join("")}
  `;
}

function renderAuthKeyRotation() {
  if (!els.authKeyRotationSummary || !els.authKeyRotationMatrix || !els.authKeyRotationHistory) return;
  const report = state.auth.keyRotation;
  if (!report) {
    els.authKeyRotationSummary.innerHTML = `<div class="empty">키 회전 상태를 불러오는 중입니다.</div>`;
    return;
  }
  const summary = report.summary || {};
  const statusLabel = report.status === "ready" ? "정상" : report.status === "action_required" ? "교체 필요" : "적용 차단";
  const statusTone = report.status === "ready" ? "success" : report.status === "action_required" ? "warning" : "danger";
  els.authKeyRotationSummary.innerHTML = [
    [`<span class="status-chip ${statusTone}">${statusLabel}</span>`, "회전 상태"],
    [escapeHtml(report.currentVersion || "-"), "현재 버전"],
    [fmtNumber(summary.activeSessions || 0), "폐기 대상 세션"],
    [fmtNumber(summary.mfaReencryptRequired || 0), "MFA 재암호화"],
    [fmtNumber(summary.queueReencryptRequired || 0), "큐 재암호화"],
    [fmtNumber(summary.unreadableRecords || 0), "복호화 불가"]
  ].map(([value, label]) => `<span><strong>${value}</strong><em>${label}</em></span>`).join("");

  const keyLabels = { csrf: "CSRF", mfa: "MFA", emailQueue: "이메일 큐", emailWebhook: "이메일 웹훅" };
  const transition = report.policy?.transition || {};
  const rows = Object.entries(report.keyConfiguration || {}).map(([key, item]) => `
    <span>${escapeHtml(keyLabels[key] || key)}: 현재 ${item.currentConfigured ? "설정" : "미설정"} · 이전 ${item.previousConfigured ? "설정" : "없음"} · 전환 검증 ${item.transitionVerificationActive ? "활성" : "비활성"}</span>
  `).join("");
  els.authKeyRotationMatrix.innerHTML = `
    <span>활성 버전 ${escapeHtml(report.activeVersion || "미적용")} → 배포 버전 ${escapeHtml(report.currentVersion || "-")}</span>
    <span>전환 창 ${transition.active ? "활성" : escapeHtml(transition.reason || "비활성")} ${transition.until ? `· ${escapeHtml(String(transition.until).slice(0, 16).replace("T", " "))}까지` : ""}</span>
    <span>차단 사유 ${report.blockers?.length ? escapeHtml(report.blockers.join(", ")) : "없음"}</span>
    <span>인증·보안 ${escapeHtml(report.lock?.version || "1.0")} ${report.lock?.status === "locked" ? "잠금" : "검토 필요"} · 재귀적 품질 확장 중단</span>
    ${rows}
  `;
  if (els.authKeyRotationPreflight) {
    els.authKeyRotationPreflight.innerHTML = renderAuthKeyEvidence(report.preflight?.latest, "사전점검 이력이 없습니다.");
  }
  if (els.authKeyRotationSmoke) {
    els.authKeyRotationSmoke.innerHTML = renderAuthKeyEvidence(report.postRotationSmoke?.latest, "보안 스모크 이력이 없습니다.");
  }
  if (els.authKeyRotationOperations) {
    const recovery = report.operations?.recoveryProcedure || [];
    const removal = report.operations?.previousKeyRemovalChecklist || [];
    els.authKeyRotationOperations.innerHTML = `
      <div class="auth-key-operation-column">
        <strong>실패 시 복구 순서</strong>
        ${recovery.map((item, index) => { const copy = authKeyRecoveryCopy(item); return `<div class="auth-key-operation-row"><b>${index + 1}</b><span><strong>${escapeHtml(copy[0])}</strong><em>${escapeHtml(copy[1])}</em></span></div>`; }).join("")}
      </div>
      <div class="auth-key-operation-column">
        <strong>이전 키 제거 체크리스트</strong>
        ${removal.map((item) => `<div class="auth-key-operation-row"><span class="status-chip ${productQaTone(item.status)}">${escapeHtml(authKeyEvidenceLabel(item.status))}</span><span><strong>${escapeHtml(authKeyItemLabel(item))}</strong><em>${escapeHtml(item.detail || "")}</em></span></div>`).join("")}
      </div>
    `;
  }
  els.authKeyRotationHistory.innerHTML = (report.history || []).length ? report.history.map((item) => `
    <div class="auth-audit-row">
      <div><strong>${item.outcome === "succeeded" ? "키 회전 적용" : "키 회전 실패"}</strong><span>${escapeHtml(item.fromVersion || "미적용")} → ${escapeHtml(item.toVersion || "-")}</span></div>
      <span class="status-chip ${item.outcome === "succeeded" ? "success" : "warning"}">${escapeHtml(item.outcome || "recorded")}</span>
      <time>${escapeHtml(String(item.occurredAt || "").slice(0, 16).replace("T", " "))}</time>
    </div>
  `).join("") : `<div class="empty">회전 이력이 없습니다.</div>`;
  if (els.authKeyRotationApplyButton) {
    els.authKeyRotationApplyButton.disabled = !report.canApply;
    els.authKeyRotationApplyButton.title = report.canApply ? "재암호화 후 모든 세션을 종료합니다." : "차단 항목을 먼저 해결해야 합니다.";
  }
  if (els.authKeyRotationSmokeButton) {
    els.authKeyRotationSmokeButton.disabled = report.activeVersion !== report.currentVersion;
    els.authKeyRotationSmokeButton.title = report.activeVersion === report.currentVersion
      ? "현재 버전 적용 후 인증 경계를 점검합니다."
      : "키 회전 적용과 재로그인을 먼저 완료해야 합니다.";
  }
}

function renderAuthMfa() {
  if (!els.authMfaAdminStatus) return;
  const report = state.auth.mfa || { mfa: {}, policy: {} };
  const mfa = report.mfa || {};
  const policy = report.policy || {};
  const statusLabel = mfa.enabled ? "등록 완료" : mfa.status === "pending" ? "등록 확인 대기" : mfa.status === "account_session_required" ? "계정 로그인 전환 필요" : "미등록";
  const tone = mfa.enabled ? "success" : mfa.status === "pending" ? "warning" : "danger";
  els.authMfaAdminStatus.innerHTML = `
    <span class="status-chip ${tone}">${statusLabel}</span>
    <span>현재 세션 ${mfa.verified ? "확인 완료" : "확인 필요"}</span>
    <span>복구 코드 ${fmtNumber(mfa.recoveryCodesRemaining || 0)}개</span>
    <span>확인 유지 ${fmtNumber(policy.sessionMinutes || 0)}분</span>
    <span>${mfa.encryptionConfigured ? "암호화 키 정상" : "암호화 키 설정 필요"}</span>
  `;
  const enroll = document.getElementById("authMfaConsoleEnrollButton");
  const regenerate = document.getElementById("authMfaConsoleRegenerateButton");
  if (enroll) {
    enroll.hidden = Boolean(mfa.enabled);
    enroll.disabled = !mfa.encryptionConfigured || mfa.status === "account_session_required";
    enroll.title = mfa.status === "account_session_required"
      ? "관리자 계정 로그인 구조를 먼저 설정해야 합니다."
      : mfa.encryptionConfigured ? "인증 앱 등록 시작" : "AUTH_MFA_ENCRYPTION_KEY 설정이 필요합니다.";
  }
  if (regenerate) regenerate.hidden = !mfa.enabled;
  const disable = document.querySelector(".auth-mfa-disable");
  if (disable) disable.hidden = !mfa.enabled;
}

function renderConsoleRecoveryCodes(codes = []) {
  const panel = els.authMfaConsoleRecovery;
  if (!panel) return;
  panel.hidden = false;
  panel.innerHTML = `<strong>지금 한 번만 표시됩니다. 별도 보관 후 화면을 닫으세요.</strong><div>${codes.map((code) => `<code>${escapeHtml(code)}</code>`).join("")}</div>`;
}

async function confirmConsoleMfa(event) {
  event.preventDefault();
  const form = new FormData(event.currentTarget);
  const result = await fetchJson("/api/admin/auth/mfa/confirm", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ code: form.get("code") })
  });
  renderConsoleRecoveryCodes(result.recoveryCodes || []);
  if (els.authMfaConsoleSetup) els.authMfaConsoleSetup.hidden = true;
  if (els.authMfaAdminMessage) els.authMfaAdminMessage.textContent = "MFA 등록이 완료되었습니다.";
  state.auth.session = await loadAuthSession();
  await loadAuthAccounts();
}

async function regenerateConsoleMfaCodes() {
  const result = await fetchJson("/api/admin/auth/mfa/recovery-codes/regenerate", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: "{}"
  });
  renderConsoleRecoveryCodes(result.recoveryCodes || []);
  if (els.authMfaAdminMessage) els.authMfaAdminMessage.textContent = "기존 복구 코드를 폐기하고 새 코드를 발급했습니다.";
  await loadAuthAccounts();
}

async function disableConsoleMfa(event) {
  event.preventDefault();
  const form = new FormData(event.currentTarget);
  await fetchJson("/api/admin/auth/mfa/disable", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ password: form.get("password"), code: form.get("code") })
  });
  window.location.assign("/admin");
}

async function loadAuthAccounts() {
  const days = els.authSecurityDays?.value || "30";
  const deliveryStatus = els.authDeliveryStatusFilter?.value || "";
  const [accounts, resets, security, invitations, deliveries, mfa, keyRotation] = await Promise.all([
    fetchJson("/api/admin/auth/accounts"),
    fetchJson("/api/admin/auth/password-reset-requests"),
    fetchJson(`/api/admin/auth/security?days=${encodeURIComponent(days)}&limit=100`),
    fetchJson("/api/admin/auth/invitations?limit=200"),
    fetchJson(`/api/admin/auth/deliveries?limit=100&status=${encodeURIComponent(deliveryStatus)}`),
    fetchJson("/api/admin/auth/mfa"),
    fetchJson("/api/admin/auth/key-rotation")
  ]);
  state.auth.accounts = accounts;
  state.auth.passwordResetRequests = resets;
  state.auth.security = security;
  state.auth.invitations = invitations;
  state.auth.deliveries = deliveries;
  state.auth.mfa = mfa;
  state.auth.keyRotation = keyRotation;
  renderAuthAccounts();
  renderAuthDeliveries();
  renderAuthMfa();
  renderAuthKeyRotation();
}

async function applyAuthKeyRotation() {
  const report = state.auth.keyRotation;
  if (!report?.canApply) return;
  const confirmed = window.confirm(`보안 키 ${report.currentVersion} 버전을 적용하면 모든 로그인 세션이 종료됩니다. 계속하시겠습니까?`);
  if (!confirmed) return;
  if (els.authKeyRotationMessage) els.authKeyRotationMessage.textContent = "MFA와 이메일 재시도 큐를 재암호화하고 세션을 종료하는 중입니다.";
  const result = await fetchJson("/api/admin/auth/key-rotation/apply", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ confirmVersion: report.currentVersion })
  });
  if (els.authKeyRotationMessage) {
    els.authKeyRotationMessage.textContent = `적용 완료: MFA ${fmtNumber(result.mfa?.reencrypted || 0)}건, 큐 ${fmtNumber(result.queue?.reencrypted || 0)}건, 세션 ${fmtNumber(result.sessions?.revoked || 0)}건 종료.`;
  }
  setTimeout(() => window.location.assign("/admin"), 900);
}

async function runAuthKeyRotationDryRun() {
  if (els.authKeyRotationMessage) els.authKeyRotationMessage.textContent = "키 값 없이 회전 영향과 차단 조건을 점검하는 중입니다.";
  if (els.authKeyRotationDryRunButton) els.authKeyRotationDryRunButton.disabled = true;
  try {
    const result = await fetchJson("/api/admin/auth/key-rotation/dry-run", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: "{}"
    });
    state.auth.keyRotation = result.report;
    renderAuthKeyRotation();
    if (els.authKeyRotationMessage) {
      els.authKeyRotationMessage.textContent = `사전점검 ${authKeyEvidenceLabel(result.run?.status)}: 차단 ${fmtNumber(result.run?.summary?.blocked || 0)}건, 확인 ${fmtNumber(result.run?.summary?.warning || 0)}건.`;
    }
  } finally {
    if (els.authKeyRotationDryRunButton) els.authKeyRotationDryRunButton.disabled = false;
  }
}

async function runAuthKeyRotationSmoke() {
  if (els.authKeyRotationMessage) els.authKeyRotationMessage.textContent = "로그인·MFA·CSRF·초대·이메일 큐·웹훅 경계를 점검하는 중입니다.";
  if (els.authKeyRotationSmokeButton) els.authKeyRotationSmokeButton.disabled = true;
  try {
    const result = await fetchJson("/api/admin/auth/key-rotation/smoke-test", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: "{}"
    });
    state.auth.keyRotation = result.report;
    renderAuthKeyRotation();
    if (els.authKeyRotationMessage) {
      els.authKeyRotationMessage.textContent = `보안 스모크 ${authKeyEvidenceLabel(result.run?.status)}: 통과 ${fmtNumber(result.run?.summary?.passed || 0)}건, 실패 ${fmtNumber(result.run?.summary?.failed || 0)}건.`;
    }
  } finally {
    if (els.authKeyRotationSmokeButton) els.authKeyRotationSmokeButton.disabled = false;
  }
}

function showAuthDeliveryPreview(message, link = "") {
  if (!els.authInviteMessage) return;
  els.authInviteMessage.textContent = message;
  if (!link) return;
  const anchor = document.createElement("a");
  anchor.href = link;
  anchor.target = "_blank";
  anchor.rel = "noopener noreferrer";
  anchor.textContent = " mock 링크 열기";
  els.authInviteMessage.append(anchor);
}

async function issueAuthInvitation(event) {
  event.preventDefault();
  const form = new FormData(event.currentTarget);
  const payload = {
    username: form.get("username"),
    displayName: form.get("displayName"),
    role: form.get("role"),
    companyIds: String(form.get("companyIds") || "").split(",").map((item) => item.trim()).filter(Boolean)
  };
  const result = await fetchJson("/api/admin/auth/invitations", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload)
  });
  event.currentTarget.reset();
  showAuthDeliveryPreview(`초대를 발급했습니다. 전달 상태: ${result.delivery?.status || "pending"}`, result.delivery?.previewLink || "");
  await loadAuthAccounts();
}

async function changeAuthInvitation(inviteId, action) {
  const result = await fetchJson(`/api/admin/auth/invitations/${action}`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ inviteId })
  });
  if (action === "reissue") showAuthDeliveryPreview(`초대를 재발급했습니다. 전달 상태: ${result.delivery?.status || "pending"}`, result.delivery?.previewLink || "");
  else showAuthDeliveryPreview("초대를 취소했습니다.");
  await loadAuthAccounts();
}

async function unlockAuthSecurityLock(lockId) {
  await fetchJson("/api/admin/auth/security/unlock", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ lockId })
  });
  if (els.authAccountMessage) els.authAccountMessage.textContent = "인증 잠금을 해제했습니다.";
  await loadAuthAccounts();
}

async function saveAuthAccount(event) {
  event.preventDefault();
  const form = new FormData(event.currentTarget);
  const payload = {
    userId: form.get("userId") || undefined,
    username: form.get("username"),
    displayName: form.get("displayName"),
    role: form.get("role"),
    status: form.get("status"),
    companyIds: String(form.get("companyIds") || "").split(",").map((item) => item.trim()).filter(Boolean),
    password: form.get("password") || undefined
  };
  await fetchJson("/api/admin/auth/accounts", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload)
  });
  if (els.authAccountMessage) els.authAccountMessage.textContent = "계정이 저장되었습니다.";
  resetAuthAccountForm();
  await loadAuthAccounts();
}

async function createAdminPasswordReset(username) {
  const result = await fetchJson("/api/admin/auth/password-reset-requests", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ username })
  });
  if (result.resetLink) showAuthDeliveryPreview(`비밀번호 재설정 링크를 발급했습니다. 전달 상태: ${result.delivery?.status || "pending"}`, result.resetLink);
  else if (els.authAccountMessage) els.authAccountMessage.textContent = result.request ? `재설정 전달 상태: ${result.delivery?.status || "pending"}` : "활성 계정을 찾지 못했습니다.";
  await loadAuthAccounts();
}

async function runAuthDeliveryRetries(deliveryId = "") {
  const result = await fetchJson("/api/admin/auth/deliveries/retries/run", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ deliveryId: deliveryId || undefined, limit: deliveryId ? 1 : 20, force: Boolean(deliveryId) })
  });
  if (els.authDeliveryMessage) els.authDeliveryMessage.textContent = `${fmtNumber(result.attempted || 0)}건의 이메일 전달을 재시도했습니다.`;
  await loadAuthAccounts();
}

async function resendAuthDelivery(deliveryId) {
  const result = await fetchJson("/api/admin/auth/deliveries/resend", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ deliveryId })
  });
  if (els.authDeliveryMessage) els.authDeliveryMessage.textContent = `새 일회용 링크를 발급해 재전송했습니다. 상태: ${authDeliveryStatusLabel(result.delivery?.status)}`;
  if (result.delivery?.previewLink) showAuthDeliveryPreview("mock 재전송 링크가 생성되었습니다.", result.delivery.previewLink);
  await loadAuthAccounts();
}

function wireAuthAccountEvents() {
  if (!els.authAccountPanel || els.authAccountPanel.dataset.wired === "true") return;
  els.authAccountPanel.dataset.wired = "true";
  els.authAccountRefreshButton?.addEventListener("click", () => loadAuthAccounts().catch((error) => { els.authAccountMessage.textContent = error.message; }));
  els.authSecurityRefreshButton?.addEventListener("click", () => loadAuthAccounts().catch((error) => { els.authAccountMessage.textContent = error.message; }));
  els.authKeyRotationRefreshButton?.addEventListener("click", () => loadAuthAccounts().catch((error) => { if (els.authKeyRotationMessage) els.authKeyRotationMessage.textContent = error.message; }));
  els.authKeyRotationDryRunButton?.addEventListener("click", () => runAuthKeyRotationDryRun().catch((error) => { if (els.authKeyRotationMessage) els.authKeyRotationMessage.textContent = error.message; }));
  els.authKeyRotationSmokeButton?.addEventListener("click", () => runAuthKeyRotationSmoke().catch((error) => { if (els.authKeyRotationMessage) els.authKeyRotationMessage.textContent = error.message; }));
  els.authKeyRotationApplyButton?.addEventListener("click", () => applyAuthKeyRotation().catch((error) => { if (els.authKeyRotationMessage) els.authKeyRotationMessage.textContent = error.message; }));
  els.authSecurityDays?.addEventListener("change", () => loadAuthAccounts().catch((error) => { els.authAccountMessage.textContent = error.message; }));
  els.authDeliveryStatusFilter?.addEventListener("change", () => loadAuthAccounts().catch((error) => { els.authDeliveryMessage.textContent = error.message; }));
  els.authDeliveryRefreshButton?.addEventListener("click", () => loadAuthAccounts().catch((error) => { els.authDeliveryMessage.textContent = error.message; }));
  els.authDeliveryRunQueueButton?.addEventListener("click", () => runAuthDeliveryRetries().catch((error) => { els.authDeliveryMessage.textContent = error.message; }));
  els.authAccountNewButton?.addEventListener("click", () => resetAuthAccountForm());
  document.getElementById("authMfaConsoleEnrollButton")?.addEventListener("click", () => {
    if (els.authMfaAdminMessage) els.authMfaAdminMessage.textContent = "인증 앱 설정 키를 생성하는 중입니다.";
    beginMfaEnrollment("console").then(() => {
      if (els.authMfaAdminMessage) els.authMfaAdminMessage.textContent = "설정 키 등록 후 현재 코드를 입력하세요.";
    }).catch((error) => { if (els.authMfaAdminMessage) els.authMfaAdminMessage.textContent = error.message; });
  });
  document.getElementById("authMfaConsoleRegenerateButton")?.addEventListener("click", () => regenerateConsoleMfaCodes().catch((error) => {
    if (els.authMfaAdminMessage) els.authMfaAdminMessage.textContent = error.message;
  }));
  els.authMfaConsoleConfirmForm?.addEventListener("submit", (event) => confirmConsoleMfa(event).catch((error) => {
    if (els.authMfaAdminMessage) els.authMfaAdminMessage.textContent = error.message;
  }));
  els.authMfaConsoleDisableForm?.addEventListener("submit", (event) => disableConsoleMfa(event).catch((error) => {
    if (els.authMfaAdminMessage) els.authMfaAdminMessage.textContent = error.message;
  }));
  els.authAccountForm?.addEventListener("submit", (event) => saveAuthAccount(event).catch((error) => { els.authAccountMessage.textContent = error.message; }));
  els.authInviteForm?.addEventListener("submit", (event) => issueAuthInvitation(event).catch((error) => { els.authInviteMessage.textContent = error.message; }));
  els.authAccountList?.addEventListener("click", (event) => {
    const editButton = event.target.closest("[data-auth-account-edit]");
    if (editButton) {
      const account = state.auth.accounts?.items?.find((item) => item.userId === editButton.dataset.authAccountEdit);
      resetAuthAccountForm(account || null);
      els.authAccountForm?.scrollIntoView({ behavior: "smooth", block: "center" });
      return;
    }
    const resetButton = event.target.closest("[data-auth-account-reset]");
    if (resetButton) createAdminPasswordReset(resetButton.dataset.authAccountReset).catch((error) => { els.authAccountMessage.textContent = error.message; });
  });
  els.authSecurityLocks?.addEventListener("click", (event) => {
    const button = event.target.closest("[data-auth-lock-unlock]");
    if (button) unlockAuthSecurityLock(button.dataset.authLockUnlock).catch((error) => { els.authAccountMessage.textContent = error.message; });
  });
  els.authInviteList?.addEventListener("click", (event) => {
    const reissue = event.target.closest("[data-auth-invite-reissue]");
    if (reissue) {
      changeAuthInvitation(reissue.dataset.authInviteReissue, "reissue").catch((error) => { els.authInviteMessage.textContent = error.message; });
      return;
    }
    const cancel = event.target.closest("[data-auth-invite-cancel]");
    if (cancel) changeAuthInvitation(cancel.dataset.authInviteCancel, "cancel").catch((error) => { els.authInviteMessage.textContent = error.message; });
  });
  els.authDeliveryList?.addEventListener("click", (event) => {
    const retry = event.target.closest("[data-auth-delivery-retry]");
    if (retry) {
      runAuthDeliveryRetries(retry.dataset.authDeliveryRetry).catch((error) => { els.authDeliveryMessage.textContent = error.message; });
      return;
    }
    const resend = event.target.closest("[data-auth-delivery-resend]");
    if (resend) resendAuthDelivery(resend.dataset.authDeliveryResend).catch((error) => { els.authDeliveryMessage.textContent = error.message; });
  });
}

function escapeHtml(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

