function ensureExternalConnectorUiOptions() {
  if (els.interestJobStatusFilterSelect && !els.interestJobStatusFilterSelect.querySelector('option[value="retry_scheduled"]')) {
    const option = document.createElement("option");
    option.value = "retry_scheduled";
    option.textContent = "재시도 예약";
    els.interestJobStatusFilterSelect.append(option);
  }
  const today = new Date();
  const endDate = today.toISOString().slice(0, 10);
  const start = new Date(today);
  start.setDate(start.getDate() - 29);
  const startDate = start.toISOString().slice(0, 10);
  if (els.externalConnectorStartDateInput && !els.externalConnectorStartDateInput.value) {
    els.externalConnectorStartDateInput.value = startDate;
  }
  if (els.externalConnectorEndDateInput && !els.externalConnectorEndDateInput.value) {
    els.externalConnectorEndDateInput.value = endDate;
  }
  if (els.externalConnectorOperationStartDateInput && !els.externalConnectorOperationStartDateInput.value) {
    els.externalConnectorOperationStartDateInput.value = startDate;
  }
  if (els.externalConnectorOperationEndDateInput && !els.externalConnectorOperationEndDateInput.value) {
    els.externalConnectorOperationEndDateInput.value = endDate;
  }
  if (els.externalConnectorAlertQualityMonthInput && !els.externalConnectorAlertQualityMonthInput.value) {
    els.externalConnectorAlertQualityMonthInput.value = endDate.slice(0, 7);
  }
  if (els.externalConnectorSnsPlatformsInput && !els.externalConnectorSnsPlatformsInput.value) {
    els.externalConnectorSnsPlatformsInput.value = "instagram, blog, youtube, community";
  }
  if (els.externalConnectorOtaChannelsInput && !els.externalConnectorOtaChannelsInput.value) {
    els.externalConnectorOtaChannelsInput.value = "naver, yanolja, yeogi, onda";
  }
}

