async function openYeogiSearch() {
  const url = yeogiSearchUrl();
  window.open(url, "_blank", "noopener,noreferrer");
  setYeogiImportStatus("여기어때 결과 화면을 열었습니다. 모바일에서는 그 화면의 숙소 목록 텍스트를 복사한 뒤 앱으로 돌아와 붙여넣으세요.", "check");
  addFeedback("여기어때 결과 화면을 열었습니다.", "info");
}

async function submitYeogiImport() {
  if (!state.activeRunId) {
    setYeogiImportStatus("먼저 실행 결과를 선택하세요.", "warning");
    syncYeogiManualInterface();
    addFeedback("여기어때 데이터를 합칠 실행 결과가 필요합니다.", "warning");
    return;
  }

  const sourceText = els.yeogiImportInput.value.trim();
  const preview = previewYeogiImport(sourceText);
  if (!sourceText) {
    setYeogiImportStatus("붙여넣기 데이터가 필요합니다.", "warning");
    syncYeogiManualInterface();
    addFeedback("CSV, HTML, 텍스트 중 하나를 붙여넣어야 합니다.", "warning");
    return;
  }
  if (looksLikeYeogiExtractScript(sourceText)) {
    setYeogiImportStatus("추출 코드가 아니라 여기어때 페이지에서 실행한 결과 CSV/HTML/텍스트를 붙여넣어야 합니다.", "warning");
    syncYeogiManualInterface();
    addFeedback("결과 입력칸에 추출 코드가 들어 있어 병합을 중단했습니다.", "warning");
    return;
  }
  if (!preview.ready) {
    setYeogiImportStatus("숙소명 또는 가격 후보가 부족합니다. 여기어때 결과 화면의 텍스트나 추출 CSV를 다시 붙여넣으세요.", "warning");
    syncYeogiManualInterface();
    addFeedback("여기어때 붙여넣기 데이터가 부족해 병합을 중단했습니다.", "warning");
    return;
  }

  els.yeogiImportButton.disabled = true;
  setYeogiImportStatus("여기어때 결과를 병합 중입니다.", "progress");
  addFeedback("여기어때 보조 수집 데이터를 병합합니다.", "progress");

  try {
    const result = await fetchJson("/api/yeogi-import", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ runId: state.activeRunId, sourceText })
    });
    state.runs = result.runs;
    state.data = result.data;
    state.activeRegion = state.data.regions[0]?.region || null;
    state.mapBounds = computeMapBounds(state.data.regions);
    renderRuns();
    renderAll();
    els.yeogiImportInput.value = "";
    setYeogiImportStatus(`여기어때 ${fmtNumber(result.importedCount)}건 병합 완료`, "ready");
    status("준비");
    addFeedback(`여기어때 ${fmtNumber(result.importedCount)}건을 현재 결과에 반영했습니다.`, "success");
  } catch (error) {
    setYeogiImportStatus(`병합 실패: ${error.message}`, "error");
    addFeedback(`여기어때 병합 실패: ${error.message}`, "error");
  } finally {
    syncYeogiManualInterface();
  }
}

function masterDbAvailable() {
  return Boolean(els.masterDbPanel && els.masterCompanyList && els.masterCompanyDetail);
}

function renderMasterDbStatus() {
  if (!masterDbAvailable()) return;
  const statusData = state.masterDb.status;
  if (!statusData) {
    els.masterDbStatus.textContent = "운영 데이터 상태를 불러오지 못했습니다. 새로고침 후에도 반복되면 DB 파일 경로를 확인하세요.";
    return;
  }
  els.masterDbStatus.innerHTML = `
    <span>업체 DB <strong>${fmtNumber(statusData.counts?.companies || 0)}</strong></span>
    <span>자동 관측값 <strong>${fmtNumber(statusData.counts?.observations || 0)}</strong></span>
    <span>검수 프로필 <strong>${fmtNumber(statusData.counts?.verifiedProfiles || 0)}</strong></span>
    <span>수정 이력 <strong>${fmtNumber(statusData.counts?.verifiedChangeLogs || 0)}</strong></span>
    <span>리드타임 패턴 <strong>${fmtNumber(statusData.counts?.leadtimePatterns || 0)}</strong></span>
    <span>관심도 신호 <strong>${fmtNumber(statusData.counts?.interestSignals || 0)}</strong></span>
    <span>수집 큐 <strong>${fmtNumber(statusData.counts?.interestSignalJobs || 0)}</strong></span>
    <span>실행계획 <strong>${fmtNumber((statusData.counts?.strategyExecutionPlans || 0) + (statusData.counts?.strategyExperimentPlans || 0))}</strong></span>
    <span>품질 히스토리 <strong>${fmtNumber((statusData.counts?.strategyQualityHistory || 0) + (statusData.counts?.experimentQualityHistory || 0))}</strong></span>
  `;
  if (statusData.counts?.locationCards !== undefined) {
    const cardStatus = document.createElement("span");
    cardStatus.innerHTML = `입지카드 <strong>${fmtNumber(statusData.counts.locationCards || 0)}</strong> · 공개 <strong>${fmtNumber(statusData.counts.publicLocationCards || 0)}</strong>`;
    els.masterDbStatus.append(cardStatus);
  }
  if (statusData.counts?.locationCardRequests !== undefined) {
    const requestStatus = document.createElement("span");
    const byStatus = statusData.counts.locationCardRequestsByStatus || {};
    requestStatus.innerHTML = `입지 요청 <strong>${fmtNumber(statusData.counts.locationCardRequests || 0)}</strong> · 접수 <strong>${fmtNumber(byStatus.requested || 0)}</strong> · 초안 <strong>${fmtNumber(byStatus.draft_created || 0)}</strong>`;
    els.masterDbStatus.append(requestStatus);
  }
  if (statusData.counts?.dataReliabilityActionQueue !== undefined) {
    const queueStatus = document.createElement("span");
    const byStatus = statusData.counts.dataReliabilityActionQueueByStatus || {};
    queueStatus.innerHTML = `보강 큐 <strong>${fmtNumber(statusData.counts.dataReliabilityActionQueue || 0)}</strong> · 대기 <strong>${fmtNumber(byStatus.open || 0)}</strong> · 진행 <strong>${fmtNumber(byStatus.in_progress || 0)}</strong>`;
    els.masterDbStatus.append(queueStatus);
  }
}

function productQaTone(status = "") {
  if (["passed", "ready", "succeeded", "copied"].includes(status)) return "good";
  if (["blocked", "failed"].includes(status)) return "danger";
  return "warning";
}

function productQaLabel(status = "") {
  return {
    passed: "Passed",
    warning: "Needs attention",
    blocked: "Blocked",
    ready: "Ready",
    needs_attention: "Needs attention",
    manual: "Manual check",
    needs_data: "Needs data",
    real_ready: "Real ready",
    configured_validate: "Validate",
    mock_until_configured: "Mock fallback",
    succeeded: "Succeeded",
    partial: "Partial",
    copied: "Copied",
    skipped: "Skipped",
    missing: "Missing",
    planned: "Planned",
    in_progress: "In progress",
    failed: "Failed",
    not_run: "Not run"
  }[status] || status || "Unknown";
}

function commercialLaunchDecisionLabel(status = "") {
  return {
    go: "GO",
    no_go: "NO-GO",
    hold: "HOLD",
    pending_review: "Pending review",
    review_required: "Review required",
    approved: "Approved"
  }[status] || productQaLabel(status);
}

function commercialLaunchDecisionTone(status = "") {
  if (["go", "approved"].includes(status)) return "good";
  if (["no_go", "blocked", "failed"].includes(status)) return "danger";
  return "warning";
}

function commercialLaunchRcStatusLabel(status = "") {
  return {
    blocked: "Blocked",
    in_progress: "In progress",
    local_rehearsal_complete: "Local complete",
    operator_review: "Operator review",
    ready_for_final_review: "Ready for final review",
    pending: "Pending",
    passed: "Passed",
    warning: "Warning"
  }[status] || productQaLabel(status);
}

function commercialLaunchRcStatusTone(status = "") {
  if (["passed", "ready_for_final_review", "local_rehearsal_complete"].includes(status)) return "good";
  if (["blocked", "failed"].includes(status)) return "danger";
  return "warning";
}

const commercialLaunchRcOwnerDefinitions = [
  ["releaseOwner", "Release owner"],
  ["rollbackOwner", "Rollback owner"],
  ["smokeTestOwner", "Smoke-test owner"],
  ["customerSupportOwner", "Customer support owner"],
  ["incidentCommunicationOwner", "Incident communication owner"]
];

function commercialLaunchRcStepAction(stepId = "") {
  return {
    current_backup: { action: "create_backup", label: "Create backup" },
    restore_rehearsal: { action: "record_restore", label: "Record restore result" },
    auth_key_activation: { action: "auth_preflight", label: "Run key preflight" },
    auth_post_rotation_smoke: { action: "auth_smoke", label: "Run auth smoke" },
    deployment_smoke: { action: "deployment_smoke", label: "Run deployment smoke" }
  }[stepId] || null;
}

function renderCommercialLaunchRc() {
  if (!els.commercialLaunchRcPanel || !els.commercialLaunchRcSummary || !els.commercialLaunchRcSteps) return;
  const report = state.masterDb.commercialLaunchRc;
  if (!report) {
    els.commercialLaunchRcSummary.innerHTML = `<div class="empty">Loading RC rehearsal.</div>`;
    els.commercialLaunchRcSteps.innerHTML = `<div class="empty">Loading operational sequence.</div>`;
    return;
  }
  const rehearsal = report.rehearsal || {};
  const summary = report.summary || {};
  const comparison = report.environmentComparison || {};
  const runtime = report.runtime || {};
  const releaseCandidate = report.releaseCandidate || {};
  const key = report.keyActivation || {};
  const saved = Boolean(rehearsal.rehearsalId);
  els.commercialLaunchRcSummary.innerHTML = `
    <span class="launch-decision-summary ${commercialLaunchRcStatusTone(summary.status)}"><strong>${escapeHtml(commercialLaunchRcStatusLabel(summary.status))}</strong><em>RC state</em></span>
    <span><strong>${escapeHtml(runtime.label || runtime.environment || "-")}</strong><em>Executed here</em></span>
    <span><strong>${escapeHtml(rehearsal.requestedEnvironment || "-")}</strong><em>Claimed environment</em></span>
    <span class="launch-decision-summary ${commercialLaunchRcStatusTone(releaseCandidate.status)}"><strong>${escapeHtml(releaseCandidate.shortDetectedCommit || "not deployed")}</strong><em>Running release source</em></span>
    <span><strong>${fmtNumber(summary.passed || 0)}/${fmtNumber(summary.total || 0)}</strong><em>Passed steps</em></span>
    <span><strong>${escapeHtml(`${key.activeVersion || "uninitialized"} / ${key.currentVersion || "-"}`)}</strong><em>Active / current key</em></span>
  `;
  if (els.commercialLaunchRcEnvironmentInput) els.commercialLaunchRcEnvironmentInput.value = rehearsal.requestedEnvironment || runtime.environment || "local";
  if (els.commercialLaunchRcTargetInput) els.commercialLaunchRcTargetInput.value = rehearsal.targetUrl || runtime.defaultUrl || "";
  if (els.commercialLaunchRcExpectedCommitInput) els.commercialLaunchRcExpectedCommitInput.value = rehearsal.expectedCommit || "";
  if (els.commercialLaunchRcMfaRecoveryInput) els.commercialLaunchRcMfaRecoveryInput.checked = Boolean(rehearsal.confirmations?.mfaRecoveryVerified);
  if (els.commercialLaunchRcWebhookInput) els.commercialLaunchRcWebhookInput.checked = Boolean(rehearsal.confirmations?.providerWebhookVerified);
  if (els.commercialLaunchRcNotesInput) els.commercialLaunchRcNotesInput.value = rehearsal.notes || "";
  if (els.commercialLaunchRcOwnerFields) {
    els.commercialLaunchRcOwnerFields.innerHTML = commercialLaunchRcOwnerDefinitions.map(([keyName, label]) => `
      <label><span>${escapeHtml(label)}</span><input data-launch-rc-owner="${escapeHtml(keyName)}" maxlength="160" value="${escapeHtml(rehearsal.owners?.[keyName] || "")}" placeholder="name or on-call role"></label>
    `).join("");
  }
  if (els.commercialLaunchRcOperatorActions) {
    const operatorActions = report.operatorActions || [];
    els.commercialLaunchRcOperatorActions.innerHTML = operatorActions.length ? `
      <div class="external-connector-compare-head"><strong>Required operator actions</strong><span>Only passed evidence can move to the manual Go / No-Go gate</span></div>
      ${operatorActions.map((item) => `
        <article class="deployment-readiness-card commercial-launch-rc-action-card">
          <div><strong>${fmtNumber(item.order)}. ${escapeHtml(item.label || item.stepId)}</strong><span class="interest-badge ${commercialLaunchRcStatusTone(item.status)}">${escapeHtml(commercialLaunchRcStatusLabel(item.status))}</span></div>
          <p>${escapeHtml(item.requiredAction || "Operator review is required.")}</p>
          ${item.href ? `<a class="ghost-button tiny-button" href="${escapeHtml(item.href)}">Open source panel</a>` : ""}
        </article>
      `).join("")}
    ` : `<div class="empty">All RC steps passed. Review the ready evidence before the separate manual release decision.</div>`;
  }
  if (els.commercialLaunchRcConnectorModes) {
    const connectors = rehearsal.connectorModes || [];
    els.commercialLaunchRcConnectorModes.innerHTML = connectors.length ? `
      <div class="external-connector-compare-head"><strong>Connector launch modes</strong><span>Real requires a ready adapter; mock requires a release note</span></div>
      <div class="commercial-launch-rc-connector-grid">${connectors.map((connector) => `
        <article class="commercial-launch-rc-connector ${connector.mode === "real" && !connector.realReady ? "blocked" : ""}">
          <div><strong>${escapeHtml(connector.label || connector.connectorId)}</strong><span class="interest-badge ${connector.realReady ? "good" : "warning"}">${connector.realReady ? "Real ready" : "Mock available"}</span></div>
          <label><span>Launch mode</span><select data-launch-rc-connector-mode="${escapeHtml(connector.connectorId)}"><option value="" ${!connector.mode ? "selected" : ""}>Decide</option><option value="mock" ${connector.mode === "mock" ? "selected" : ""}>Mock</option><option value="real" ${connector.mode === "real" ? "selected" : ""}>Real</option></select></label>
          <label><span>Decision note</span><input data-launch-rc-connector-note="${escapeHtml(connector.connectorId)}" maxlength="500" value="${escapeHtml(connector.notes || "")}" placeholder="quota, limitation, or cutover evidence"></label>
        </article>
      `).join("")}</div>
    ` : `<div class="empty">No external connectors were returned.</div>`;
  }
  const steps = report.steps || [];
  els.commercialLaunchRcSteps.innerHTML = steps.length ? steps.map((step) => {
    const action = commercialLaunchRcStepAction(step.stepId);
    return `
      <article class="commercial-launch-rc-step ${escapeHtml(step.status)}">
        <span class="commercial-launch-rc-order">${fmtNumber(step.order)}</span>
        <div>
          <header><strong>${escapeHtml(step.label || step.stepId)}</strong><span class="interest-badge ${commercialLaunchRcStatusTone(step.status)}">${escapeHtml(commercialLaunchRcStatusLabel(step.status))}</span></header>
          <p>${escapeHtml(step.detail || "")}</p>
          <small>${escapeHtml(step.action || "")}</small>
          <div class="button-pair">
            ${action ? `<button class="ghost-button tiny-button" type="button" data-launch-rc-action="${escapeHtml(action.action)}" ${saved ? "" : "disabled"}>${escapeHtml(action.label)}</button>` : ""}
            ${step.href ? `<a class="ghost-button tiny-button" href="${escapeHtml(step.href)}">Open source panel</a>` : ""}
          </div>
        </div>
      </article>
    `;
  }).join("") : `<div class="empty">No RC operation steps were returned.</div>`;
  if (els.commercialLaunchRcHistory) {
    const history = report.history || [];
    els.commercialLaunchRcHistory.innerHTML = history.length ? history.map((item) => `
      <article class="deployment-readiness-card commercial-launch-rc-history-card">
        <div><strong>${escapeHtml(item.requestedEnvironment || "local")}</strong><span class="interest-badge ${item.requestedEnvironment === runtime.environment ? "good" : "warning"}">${item.requestedEnvironment === runtime.environment ? "This runtime" : "Other runtime"}</span></div>
        <p>${escapeHtml(item.targetUrl || "No target URL")}</p>
        <p>${escapeHtml(`Expected ${item.expectedCommit ? item.expectedCommit.slice(0, 12) : "missing"} / executed ${item.executedCommit ? item.executedCommit.slice(0, 12) : "missing"}`)}</p>
        <small>${escapeHtml([item.rehearsalId, item.updatedAt, item.updatedBy].filter(Boolean).join(" / "))}</small>
      </article>
    `).join("") : `<div class="empty">No saved rehearsal yet. Local, staging, and Render histories stay separate.</div>`;
  }
  if (els.commercialLaunchRcSaveButton) els.commercialLaunchRcSaveButton.textContent = saved ? "Save rehearsal" : "Create rehearsal";
  if (els.commercialLaunchRcSyncButton) els.commercialLaunchRcSyncButton.disabled = !saved;
  if (els.commercialLaunchRcApplyEvidenceButton) {
    els.commercialLaunchRcApplyEvidenceButton.disabled = !(report.evidenceSuggestions || []).some((item) => item.ready);
  }
  els.commercialLaunchRcPanel.dataset.environmentMatch = comparison.matches ? "true" : "false";
}

function collectCommercialLaunchRcPayload() {
  const report = state.masterDb.commercialLaunchRc || {};
  const owners = Object.fromEntries(Array.from(els.commercialLaunchRcOwnerFields?.querySelectorAll("[data-launch-rc-owner]") || []).map((input) => [input.dataset.launchRcOwner, input.value]));
  const connectorModes = Array.from(els.commercialLaunchRcConnectorModes?.querySelectorAll("[data-launch-rc-connector-mode]") || []).map((select) => {
    const connectorId = select.dataset.launchRcConnectorMode || "";
    const note = els.commercialLaunchRcConnectorModes?.querySelector(`[data-launch-rc-connector-note="${CSS.escape(connectorId)}"]`);
    return { connectorId, mode: select.value, notes: note?.value || "" };
  });
  return {
    rehearsalId: report.rehearsal?.rehearsalId || "",
    requestedEnvironment: els.commercialLaunchRcEnvironmentInput?.value || "local",
    targetUrl: els.commercialLaunchRcTargetInput?.value || "",
    expectedCommit: els.commercialLaunchRcExpectedCommitInput?.value || "",
    owners,
    connectorModes,
    confirmations: {
      mfaRecoveryVerified: Boolean(els.commercialLaunchRcMfaRecoveryInput?.checked),
      providerWebhookVerified: Boolean(els.commercialLaunchRcWebhookInput?.checked)
    },
    notes: els.commercialLaunchRcNotesInput?.value || ""
  };
}

async function saveCommercialLaunchRc() {
  if (els.commercialLaunchRcSaveButton) els.commercialLaunchRcSaveButton.disabled = true;
  try {
    state.masterDb.commercialLaunchRc = await fetchJson("/api/admin/master-db/commercial-launch-rc-rehearsals", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(collectCommercialLaunchRcPayload())
    });
    renderCommercialLaunchRc();
    addFeedback("RC rehearsal saved. Final release approval was not changed.", "success");
  } finally {
    if (els.commercialLaunchRcSaveButton) els.commercialLaunchRcSaveButton.disabled = false;
  }
}

async function runCommercialLaunchRcAction(action = "") {
  const rehearsalId = state.masterDb.commercialLaunchRc?.rehearsal?.rehearsalId || "";
  if (!rehearsalId) throw new Error("Create the RC rehearsal before running evidence actions.");
  const payload = action === "record_restore" ? {
    status: els.commercialLaunchRcRestoreStatus?.value || "planned",
    notes: els.commercialLaunchRcRestoreNotes?.value || ""
  } : {};
  state.masterDb.commercialLaunchRc = await fetchJson(`/api/admin/master-db/commercial-launch-rc-rehearsals/${encodeURIComponent(rehearsalId)}/actions/${encodeURIComponent(action)}`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload)
  });
  renderCommercialLaunchRc();
  await loadCommercialLaunchGate({ includeRc: false });
  addFeedback(`RC action completed: ${action}.`, "success");
}

function applyCommercialLaunchRcEvidence() {
  const suggestions = state.masterDb.commercialLaunchRc?.readyEvidence || [];
  let applied = 0;
  suggestions.forEach((item) => {
    const checkbox = els.commercialLaunchGateEvidence?.querySelector(`[data-launch-evidence-confirmed="${CSS.escape(item.evidenceId)}"]`);
    const reference = els.commercialLaunchGateEvidence?.querySelector(`[data-launch-evidence-reference="${CSS.escape(item.evidenceId)}"]`);
    if (!checkbox || !reference) return;
    checkbox.checked = true;
    reference.value = item.reference || "";
    checkbox.closest(".commercial-launch-evidence-row")?.classList.add("confirmed");
    applied += 1;
  });
  syncCommercialLaunchGateApprovalState();
  addFeedback(`${applied} ready RC evidence item(s) copied into the manual gate form. Save or approve remains manual.`, applied ? "success" : "warning");
}

function renderCommercialLaunchGate() {
  if (!els.commercialLaunchGateSummary || !els.commercialLaunchGateAutomaticChecks || !els.commercialLaunchGateEvidence) return;
  const report = state.masterDb.commercialLaunchGate;
  if (!report) {
    els.commercialLaunchGateSummary.innerHTML = `<div class="empty">Loading launch gate.</div>`;
    els.commercialLaunchGateAutomaticChecks.innerHTML = `<div class="empty">Loading automatic checks.</div>`;
    els.commercialLaunchGateEvidence.innerHTML = `<div class="empty">Loading required evidence.</div>`;
    return;
  }
  const summary = report.summary || {};
  const automatic = summary.automatic || {};
  const manual = summary.manualEvidence || {};
  const checks = report.automaticChecks || [];
  const evidence = report.requiredEvidence || [];
  const latest = report.latestReview || null;
  els.commercialLaunchGateSummary.innerHTML = `
    <span class="launch-decision-summary ${commercialLaunchDecisionTone(summary.launchDecision)}"><strong>${escapeHtml(commercialLaunchDecisionLabel(summary.launchDecision))}</strong><em>Release decision</em></span>
    <span><strong>${fmtNumber(automatic.readyRate || 0)}%</strong><em>Automatic ready</em></span>
    <span><strong>${fmtNumber(summary.blockerCount || 0)}</strong><em>Blockers</em></span>
    <span><strong>${fmtNumber(summary.warningCount || 0)}</strong><em>Warnings</em></span>
    <span><strong>${fmtNumber(manual.completed || 0)}/${fmtNumber(manual.total || 0)}</strong><em>Manual evidence</em></span>
  `;
  els.commercialLaunchGateAutomaticChecks.innerHTML = checks.length ? checks.map((item) => `
    <article class="product-qa-item commercial-launch-check">
      <div>
        <strong>${escapeHtml(item.label || item.checkId || "-")}</strong>
        <span class="interest-badge ${productQaTone(item.status)}">${escapeHtml(productQaLabel(item.status))}</span>
      </div>
      <p>${escapeHtml(item.detail || "")}</p>
      <small>${escapeHtml(item.action || "")}</small>
      ${item.href ? `<a class="ghost-button tiny-button" href="${escapeHtml(item.href)}">Open source check</a>` : ""}
    </article>
  `).join("") : `<div class="empty">No automatic checks were returned.</div>`;
  els.commercialLaunchGateEvidence.innerHTML = evidence.length ? evidence.map((item) => `
    <label class="commercial-launch-evidence-row ${item.confirmed && item.reference ? "confirmed" : "pending"}">
      <input type="checkbox" data-launch-evidence-confirmed="${escapeHtml(item.evidenceId)}" ${item.confirmed ? "checked" : ""}>
      <span>
        <strong>${escapeHtml(item.label || item.evidenceId || "-")}</strong>
        <small>${escapeHtml(item.description || "")}</small>
        <input type="text" maxlength="500" data-launch-evidence-reference="${escapeHtml(item.evidenceId)}" value="${escapeHtml(item.reference || "")}" placeholder="Evidence reference, run id, ticket, or operator note">
      </span>
    </label>
  `).join("") : `<div class="empty">No manual evidence requirements were returned.</div>`;
  if (els.commercialLaunchGateApproverInput) els.commercialLaunchGateApproverInput.value = latest?.finalApprover || state.auth.session?.account?.username || "";
  if (els.commercialLaunchGateReleaseNoteInput) els.commercialLaunchGateReleaseNoteInput.value = latest?.releaseNote || "";

  const snapshot = report.approvalSnapshot;
  if (els.commercialLaunchGateSnapshot) {
    els.commercialLaunchGateSnapshot.innerHTML = snapshot ? `
      <article class="deployment-readiness-card commercial-launch-snapshot-card">
        <div>
          <strong>Before review</strong>
          <span class="interest-badge ${commercialLaunchDecisionTone(snapshot.before?.currentRecommendation)}">${escapeHtml(commercialLaunchDecisionLabel(snapshot.before?.currentRecommendation || "pending_review"))}</span>
        </div>
        <p>${escapeHtml(`Automatic ${snapshot.before?.automaticSummary?.readyRate || 0}% / blocked ${snapshot.before?.automaticSummary?.blocked || 0} / warning ${snapshot.before?.automaticSummary?.warning || 0}`)}</p>
        <small>${escapeHtml(snapshot.before?.automaticFingerprint || "No fingerprint")}</small>
      </article>
      <article class="deployment-readiness-card commercial-launch-snapshot-card">
        <div>
          <strong>After review</strong>
          <span class="interest-badge ${commercialLaunchDecisionTone(snapshot.after?.finalDecision)}">${escapeHtml(commercialLaunchDecisionLabel(snapshot.after?.finalDecision || "hold"))}</span>
        </div>
        <p>${escapeHtml(`Evidence ${snapshot.after?.completedEvidence || 0}/${snapshot.after?.requiredEvidence || 0} / captured ${snapshot.after?.capturedAt || "-"}`)}</p>
        <small>${snapshot.changedSinceApproval ? "Automatic checks changed after approval. A new review is required." : "The saved decision matches the current automatic state."}</small>
      </article>
    ` : `<div class="empty">No approval snapshot yet. Save a hold or approval decision to create one.</div>`;
  }
  if (els.commercialLaunchGateHistory) {
    const history = report.history || [];
    els.commercialLaunchGateHistory.innerHTML = history.length ? history.slice(0, 10).map((item) => `
      <article class="deployment-readiness-card commercial-launch-history-card">
        <div>
          <strong>${escapeHtml(item.finalApprover || item.reviewedBy || "Administrator")}</strong>
          <span class="interest-badge ${commercialLaunchDecisionTone(item.finalDecision)}">${escapeHtml(commercialLaunchDecisionLabel(item.finalDecision))}</span>
        </div>
        <p>${escapeHtml([item.reviewedAt, item.reviewedBy].filter(Boolean).join(" / "))}</p>
        <small>${escapeHtml(item.releaseNote || "No release note")}</small>
      </article>
    `).join("") : `<div class="empty">No launch decision history yet.</div>`;
  }
  syncCommercialLaunchGateApprovalState();
  renderCommercialLaunchRc();
}

function collectCommercialLaunchGateEvidence() {
  return Array.from(els.commercialLaunchGateEvidence?.querySelectorAll("[data-launch-evidence-confirmed]") || []).map((checkbox) => {
    const evidenceId = checkbox.dataset.launchEvidenceConfirmed || "";
    const reference = els.commercialLaunchGateEvidence?.querySelector(`[data-launch-evidence-reference="${CSS.escape(evidenceId)}"]`);
    return {
      evidenceId,
      confirmed: Boolean(checkbox.checked),
      reference: reference?.value || ""
    };
  });
}

function syncCommercialLaunchGateApprovalState() {
  if (!els.commercialLaunchGateApproveButton) return;
  const report = state.masterDb.commercialLaunchGate || {};
  const evidence = collectCommercialLaunchGateEvidence();
  const evidenceReady = evidence.length > 0 && evidence.every((item) => item.confirmed && item.reference.trim());
  const identityReady = Boolean(els.commercialLaunchGateApproverInput?.value.trim() && els.commercialLaunchGateReleaseNoteInput?.value.trim());
  els.commercialLaunchGateApproveButton.disabled = Number(report.summary?.blockerCount || 0) > 0 || !evidenceReady || !identityReady;
}

async function loadCommercialLaunchGate(options = {}) {
  if (!els.commercialLaunchGatePanel) return;
  const includeRc = options.includeRc !== false;
  const [gate, rc] = await Promise.all([
    fetchJson("/api/admin/master-db/commercial-launch-gate"),
    includeRc ? fetchJson("/api/admin/master-db/commercial-launch-rc-rehearsals") : Promise.resolve(state.masterDb.commercialLaunchRc)
  ]);
  state.masterDb.commercialLaunchGate = gate;
  state.masterDb.commercialLaunchRc = rc;
  renderCommercialLaunchGate();
}

async function saveCommercialLaunchGateDecision(decision = "hold") {
  const payload = {
    decision,
    finalApprover: els.commercialLaunchGateApproverInput?.value || "",
    releaseNote: els.commercialLaunchGateReleaseNoteInput?.value || "",
    manualEvidence: collectCommercialLaunchGateEvidence()
  };
  if (els.commercialLaunchGateHoldButton) els.commercialLaunchGateHoldButton.disabled = true;
  if (els.commercialLaunchGateApproveButton) els.commercialLaunchGateApproveButton.disabled = true;
  try {
    const result = await fetchJson("/api/admin/master-db/commercial-launch-gate", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload)
    });
    state.masterDb.commercialLaunchGate = result.report;
    renderCommercialLaunchGate();
    addFeedback(decision === "approved" ? "Commercial release approved." : "Commercial release hold saved.", decision === "approved" ? "success" : "warning");
  } finally {
    if (els.commercialLaunchGateHoldButton) els.commercialLaunchGateHoldButton.disabled = false;
    syncCommercialLaunchGateApprovalState();
  }
}

function renderDeploymentReadiness() {
  if (!els.deploymentReadinessSummary || !els.deploymentReadinessChecklist || !els.deploymentReadinessGuide) return;
  const report = state.masterDb.deploymentReadiness;
  if (!report) {
    els.deploymentReadinessSummary.innerHTML = `<div class="empty">Loading deployment readiness summary.</div>`;
    els.deploymentReadinessChecklist.innerHTML = `<div class="empty">Loading deployment checklist.</div>`;
    els.deploymentReadinessGuide.innerHTML = `<div class="empty">Loading operation guide.</div>`;
    return;
  }
  const summary = report.summary || {};
  const environment = report.environment || {};
  const runtime = environment.runtime || {};
  const items = report.checklist || [];
  const paths = report.paths || [];
  const envGroups = report.envGroups || [];
  const mockToReal = report.mockToRealChecklist || [];
  const smokeTests = report.smokeTests || [];
  els.deploymentReadinessSummary.innerHTML = `
    <span><strong>${escapeHtml(productQaLabel(summary.readiness))}</strong><em>Deploy state</em></span>
    <span><strong>${fmtNumber(summary.readyRate || 0)}%</strong><em>Ready rate</em></span>
    <span><strong>${escapeHtml(runtime.renderDetected ? "Render" : "Local")}</strong><em>Runtime</em></span>
    <span><strong>${escapeHtml(runtime.authRequired ? "On" : "Off")}</strong><em>Admin PIN</em></span>
    <span><strong>${fmtNumber(summary.blocked || 0)}</strong><em>Blocked</em></span>
  `;
  els.deploymentReadinessChecklist.innerHTML = items.length ? items.map((item) => `
    <article class="product-qa-item">
      <div>
        <strong>${escapeHtml(item.label || item.id || "-")}</strong>
        <span class="interest-badge ${productQaTone(item.status)}">${escapeHtml(productQaLabel(item.status))}</span>
      </div>
      <p>${escapeHtml(item.summary || "")}</p>
      <small>${escapeHtml(item.action || "")}</small>
      ${item.href ? `<a class="ghost-button tiny-button" href="${escapeHtml(item.href)}">${escapeHtml(item.href.startsWith("/") ? "Open flow" : "Open section")}</a>` : ""}
    </article>
  `).join("") : `<div class="empty">No deployment checklist rows were returned.</div>`;

  const pathCards = paths.map((item) => `
    <article class="deployment-readiness-card">
      <div>
        <strong>${escapeHtml(item.label || "Path")}</strong>
        <span class="interest-badge ${productQaTone(item.status)}">${escapeHtml(productQaLabel(item.status))}</span>
      </div>
      <p>${escapeHtml(item.path || "")}</p>
      <small>${escapeHtml([item.exists ? "exists" : "missing", item.writable ? "writable" : "not writable", item.insideRepo ? "inside repo" : "outside repo"].join(" · "))}</small>
    </article>
  `).join("");
  const envCards = envGroups.map((group) => {
    const vars = (group.items || group.envVars || []).map((item) => `
      <span class="deployment-env-chip ${item.configured ? "ready" : "missing"}">${escapeHtml(item.name)} ${item.configured ? "set" : "missing"}</span>
    `).join("");
    return `
      <article class="deployment-readiness-card">
        <div>
          <strong>${escapeHtml(group.label || group.groupId || group.connectorId || "Env group")}</strong>
          <span class="interest-badge ${productQaTone(group.mode === "real_ready" ? "passed" : "warning")}">${escapeHtml(productQaLabel(group.mode || "manual"))}</span>
        </div>
        <div class="deployment-env-list">${vars || `<span class="deployment-env-chip ready">No required env</span>`}</div>
        ${(group.missingFields || []).length ? `<small>Missing: ${escapeHtml(group.missingFields.join(", "))}</small>` : `<small>Ready for configured mode.</small>`}
      </article>
    `;
  }).join("");
  const transitionCards = mockToReal.map((item) => `
    <article class="deployment-readiness-card">
      <div>
        <strong>${escapeHtml(item.label || item.connectorId || "Connector")}</strong>
        <span class="interest-badge ${productQaTone(item.mode === "real_ready" ? "passed" : "warning")}">${escapeHtml(productQaLabel(item.mode || ""))}</span>
      </div>
      <p>${escapeHtml((item.conditions || []).slice(0, 2).join(" / "))}</p>
      <small>${escapeHtml((item.quotaRetryPolicy || []).slice(0, 2).join(" / "))}</small>
    </article>
  `).join("");
  const smokeCards = smokeTests.map((item) => `
    <article class="deployment-readiness-card">
      <div>
        <strong>${escapeHtml(item.method || "GET")} ${escapeHtml(item.target || "")}</strong>
        <span class="interest-badge ${productQaTone(item.status === "ready" ? "passed" : item.status === "blocked" ? "blocked" : "warning")}">${escapeHtml(productQaLabel(item.status || "manual"))}</span>
      </div>
      <p>${escapeHtml(item.expected || "")}</p>
      <small>${escapeHtml(item.owner || "operator")}</small>
    </article>
  `).join("");
  els.deploymentReadinessGuide.innerHTML = `
    <div class="deployment-guide-group">
      <strong>Data paths</strong>
      ${pathCards || `<div class="empty">No path readiness data.</div>`}
    </div>
    <div class="deployment-guide-group">
      <strong>Environment variables</strong>
      ${envCards || `<div class="empty">No environment groups.</div>`}
    </div>
    <div class="deployment-guide-group">
      <strong>Mock to real connector cutover</strong>
      ${transitionCards || `<div class="empty">No connector transition checklist.</div>`}
    </div>
    <div class="deployment-guide-group">
      <strong>Post-deploy smoke tests</strong>
      ${smokeCards || `<div class="empty">No smoke tests.</div>`}
    </div>
  `;
}

