async function createBackupRestoreSnapshot() {
  const payload = {
    includeOutputs: els.backupIncludeOutputsInput ? Boolean(els.backupIncludeOutputsInput.checked) : true,
    createdBy: els.backupCreatedByInput?.value || "admin",
    notes: els.backupNotesInput?.value || ""
  };
  els.backupCreateButton.disabled = true;
  try {
    const result = await fetchJson("/api/admin/master-db/backup-restore-backups", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload)
    });
    addFeedback(`Backup created: ${result.backup?.backupId || "manual backup"}`, "success");
    if (els.backupNotesInput) els.backupNotesInput.value = "";
    await loadBackupRestoreReadiness();
  } finally {
    els.backupCreateButton.disabled = false;
  }
}

async function saveBackupRestoreRehearsal(event) {
  event.preventDefault();
  const payload = {
    backupId: els.backupRehearsalBackupIdInput?.value || "",
    status: els.backupRehearsalStatusSelect?.value || "planned",
    checkedBy: els.backupRehearsalCheckedByInput?.value || "admin",
    notes: els.backupRehearsalNotesInput?.value || ""
  };
  const result = await fetchJson("/api/admin/master-db/backup-restore-rehearsals", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload)
  });
  addFeedback(`Restore rehearsal saved: ${result.rehearsal?.backupId || payload.backupId}`, "success");
  if (els.backupRehearsalNotesInput) els.backupRehearsalNotesInput.value = "";
  await loadBackupRestoreReadiness();
}

function renderSmokeTestReport() {
  if (!els.smokeTestSummary || !els.smokeTestChecklist || !els.smokeTestHistory) return;
  const report = state.masterDb.smokeTestReport;
  if (!report) {
    els.smokeTestSummary.innerHTML = `<div class="empty">Loading smoke test history.</div>`;
    els.smokeTestChecklist.innerHTML = `<div class="empty">Loading latest smoke checks.</div>`;
    els.smokeTestHistory.innerHTML = `<div class="empty">Loading smoke test run history.</div>`;
    return;
  }
  const historySummary = report.summary || {};
  const latest = report.latestRun || null;
  const latestSummary = latest?.summary || {};
  const steps = latest?.steps || report.checklist || [];
  const runs = report.items || [];
  els.smokeTestSummary.innerHTML = `
    <span><strong>${escapeHtml(productQaLabel(latest?.status || "not_run"))}</strong><em>Latest status</em></span>
    <span><strong>${fmtNumber(latestSummary.readyRate || 0)}%</strong><em>Latest ready</em></span>
    <span><strong>${fmtNumber(historySummary.total || 0)}</strong><em>Total runs</em></span>
    <span><strong>${fmtNumber(historySummary.failed || 0)}</strong><em>Failed runs</em></span>
    <span><strong>${escapeHtml(historySummary.latestTriggeredAt || "-")}</strong><em>Latest time</em></span>
  `;
  els.smokeTestChecklist.innerHTML = steps.length ? steps.map((step) => `
    <article class="product-qa-item">
      <div>
        <strong>${escapeHtml(step.label || step.stepId || "-")}</strong>
        <span class="interest-badge ${productQaTone(step.status)}">${escapeHtml(productQaLabel(step.status))}</span>
      </div>
      <p>${escapeHtml(step.detail || step.target || "")}</p>
      <small>${escapeHtml(step.failureReason || step.target || "")}</small>
    </article>
  `).join("") : `<div class="empty">No smoke test has been run yet.</div>`;
  els.smokeTestHistory.innerHTML = runs.length ? runs.slice(0, 10).map((run) => {
    const failures = run.failureReasons || [];
    return `
      <article class="deployment-readiness-card smoke-test-run-card">
        <div>
          <strong>${escapeHtml(run.runId || "-")}</strong>
          <span class="interest-badge ${productQaTone(run.status)}">${escapeHtml(productQaLabel(run.status))}</span>
        </div>
        <p>${escapeHtml([run.triggeredAt, run.triggeredBy, run.sampleCompanyId].filter(Boolean).join(" · "))}</p>
        <small>${fmtNumber(run.summary?.passed || 0)} passed · ${fmtNumber(run.summary?.warning || 0)} warning · ${fmtNumber(run.summary?.failed || 0)} failed</small>
        ${failures.length ? `<small>${escapeHtml(failures.slice(0, 2).map((item) => `${item.label}: ${item.failureReason}`).join(" / "))}</small>` : ""}
      </article>
    `;
  }).join("") : `<div class="empty">No smoke test run history yet. Run the smoke test after deploy.</div>`;
}

async function loadSmokeTestReport() {
  if (!els.smokeTestPanel) return;
  state.masterDb.smokeTestReport = await fetchJson("/api/admin/master-db/deployment-smoke-tests");
  renderSmokeTestReport();
}

async function runSmokeTestReport() {
  const payload = {
    triggeredBy: els.smokeTestTriggeredByInput?.value || "admin"
  };
  els.smokeTestRunButton.disabled = true;
  try {
    const result = await fetchJson("/api/admin/master-db/deployment-smoke-tests/run", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload)
    });
    addFeedback(`Smoke test ${result.run?.status || "completed"}: ${result.run?.runId || ""}`, result.run?.status === "failed" ? "error" : "success");
    await loadSmokeTestReport();
    await loadDeploymentOperationAlerts();
    await loadDeploymentOperationAlertQuality();
    await loadDeploymentOperationQualityActions();
    await loadDeploymentOperationQualityRecommendationAdjustments();
    await loadDeploymentOperationQualityAutoApprovalPerformance();
    await loadDeploymentOperationQualityReassessmentBundle();
  } finally {
    els.smokeTestRunButton.disabled = false;
  }
}

function deploymentOperationAlertStatusLabel(status = "") {
  return {
    open: "Open",
    in_progress: "In progress",
    resolved: "Resolved",
    dismissed: "Dismissed"
  }[status] || status || "-";
}

function deploymentOperationAlertPriorityLabel(priority = "") {
  return {
    high: "High",
    medium: "Medium",
    low: "Low"
  }[priority] || priority || "-";
}

function deploymentOperationAlertTypeLabel(type = "") {
  return {
    smoke_failure: "Smoke failure",
    backup_restore_unready: "Backup/restore gap",
    security_blocked: "Security blocked",
    deployment_blocked: "Deploy blocked"
  }[type] || type || "-";
}

function deploymentOperationAlertDueLabel(dueState = "") {
  return {
    overdue: "Overdue",
    this_week: "This week",
    upcoming: "Upcoming",
    no_due: "No due",
    closed: "Closed"
  }[dueState] || dueState || "-";
}

function deploymentOperationAlertTone(value = "") {
  if (["high", "open", "overdue", "smoke_failure", "security_blocked", "deployment_blocked"].includes(value)) return "danger";
  if (["medium", "in_progress", "this_week", "backup_restore_unready"].includes(value)) return "warning";
  if (["resolved", "low", "closed"].includes(value)) return "good";
  return "muted";
}

function deploymentOperationAlertStatusOptions(current = "open") {
  return ["open", "in_progress", "resolved", "dismissed"].map((status) => (
    `<option value="${status}"${status === current ? " selected" : ""}>${escapeHtml(deploymentOperationAlertStatusLabel(status))}</option>`
  )).join("");
}

function deploymentOperationAlertPriorityOptions(current = "medium") {
  return ["high", "medium", "low"].map((priority) => (
    `<option value="${priority}"${priority === current ? " selected" : ""}>${escapeHtml(deploymentOperationAlertPriorityLabel(priority))}</option>`
  )).join("");
}

function deploymentOperationAlertLogEventLabel(value = "") {
  return {
    resolved: "Resolved",
    dismissed: "Dismissed",
    reopened: "Reopened",
    status_changed: "Status changed",
    updated: "Updated"
  }[value] || value || "Updated";
}

function deploymentOperationAlertChangeText(change = {}) {
  const labels = {
    status: "status",
    priority: "priority",
    assignee: "owner",
    dueDate: "due date",
    memo: "memo"
  };
  return `${labels[change.field] || change.field}: ${change.before || "-"} -> ${change.after || "-"}`;
}

function renderDeploymentOperationAlertHistory(item = {}) {
  const history = item.changeHistory || [];
  const resolution = item.resolutionHistory || [];
  if (!history.length) {
    return `<div class="deployment-operation-alert-history empty-history"><span>No change history yet.</span></div>`;
  }
  return `
    <div class="deployment-operation-alert-history">
      <div>
        <strong>Change history</strong>
        ${history.slice(0, 5).map((log) => `
          <span>
            <b>${escapeHtml(deploymentOperationAlertLogEventLabel(log.eventType))}</b>
            <em>${escapeHtml(log.changedAt || "-")} / ${escapeHtml(log.changedBy || "-")}</em>
            <small>${escapeHtml((log.changes || []).map(deploymentOperationAlertChangeText).join(" / ") || "No field changes")}</small>
          </span>
        `).join("")}
      </div>
      <div>
        <strong>Resolved / dismissed</strong>
        ${resolution.length ? resolution.slice(0, 4).map((log) => `
          <span>
            <b>${escapeHtml(deploymentOperationAlertLogEventLabel(log.eventType))}</b>
            <em>${escapeHtml(log.changedAt || "-")} / ${escapeHtml(log.changedBy || "-")}</em>
            <small>${escapeHtml(log.previousStatus || "-")} -> ${escapeHtml(log.nextStatus || "-")}</small>
          </span>
        `).join("") : `<span><em>No resolved or dismissed events yet.</em></span>`}
      </div>
    </div>
  `;
}

function deploymentOperationAlertQuery() {
  const params = new URLSearchParams({ limit: "100" });
  if (els.deploymentOperationAlertStatusFilter?.value) params.set("status", els.deploymentOperationAlertStatusFilter.value);
  if (els.deploymentOperationAlertPriorityFilter?.value) params.set("priority", els.deploymentOperationAlertPriorityFilter.value);
  if (els.deploymentOperationAlertTypeFilter?.value) params.set("alertType", els.deploymentOperationAlertTypeFilter.value);
  if (els.deploymentOperationAlertAssigneeFilter?.value?.trim()) params.set("assignee", els.deploymentOperationAlertAssigneeFilter.value.trim());
  if (els.deploymentOperationAlertDueFilter?.value) params.set("dueState", els.deploymentOperationAlertDueFilter.value);
  return `?${params.toString()}`;
}

function renderDeploymentOperationAlerts() {
  if (!els.deploymentOperationAlertSummary || !els.deploymentOperationAlertList) return;
  const queue = state.masterDb.deploymentOperationAlertQueue;
  if (!queue) {
    els.deploymentOperationAlertSummary.innerHTML = `<div class="empty">Loading operation alerts.</div>`;
    els.deploymentOperationAlertList.innerHTML = `<div class="empty">Loading operation alerts.</div>`;
    return;
  }
  const summary = queue.summary || {};
  els.deploymentOperationAlertSummary.innerHTML = `
    <span><strong>${fmtNumber(summary.active || 0)}</strong><em>Active</em></span>
    <span><strong>${fmtNumber(summary.high || 0)}</strong><em>High</em></span>
    <span><strong>${fmtNumber(summary.overdue || 0)}</strong><em>Overdue</em></span>
    <span><strong>${fmtNumber(summary.smokeFailures || 0)}</strong><em>Smoke</em></span>
    <span><strong>${fmtNumber(summary.backupUnready || 0)}</strong><em>Backup</em></span>
    <span><strong>${fmtNumber(summary.blockedGates || 0)}</strong><em>Blocked gates</em></span>
  `;
  const items = queue.items || [];
  if (!items.length) {
    els.deploymentOperationAlertList.innerHTML = `<div class="empty">No operation alerts match the current filters. If smoke tests pass and readiness gates are stable, this queue can remain empty.</div>`;
    return;
  }
  els.deploymentOperationAlertList.innerHTML = items.map((item) => `
    <article class="deployment-operation-alert-card ${escapeHtml(deploymentOperationAlertTone(item.priority))}" data-deployment-operation-alert-id="${escapeHtml(item.alertId || "")}">
      <div class="deployment-operation-alert-head">
        <div>
          <strong>${escapeHtml(item.title || deploymentOperationAlertTypeLabel(item.alertType))}</strong>
          <small>${escapeHtml([deploymentOperationAlertTypeLabel(item.alertType), item.sourceModule, item.sourceStatus].filter(Boolean).join(" / "))}</small>
        </div>
        <div class="calibration-audit-queue-badges">
          <span class="calibration-audit-queue-badge ${deploymentOperationAlertTone(item.priority)}">${escapeHtml(deploymentOperationAlertPriorityLabel(item.priority))}</span>
          <span class="calibration-audit-queue-badge ${deploymentOperationAlertTone(item.status)}">${escapeHtml(deploymentOperationAlertStatusLabel(item.status))}</span>
          <span class="calibration-audit-queue-badge ${deploymentOperationAlertTone(item.dueState)}">${escapeHtml(deploymentOperationAlertDueLabel(item.dueState))}</span>
          ${item.stale ? `<span class="calibration-audit-queue-badge muted">Stale source</span>` : ""}
        </div>
      </div>
      <p>${escapeHtml(item.description || "No description.")}</p>
      ${item.failureReason ? `<small class="deployment-operation-alert-reason">${escapeHtml(item.failureReason)}</small>` : ""}
      <div class="deployment-operation-alert-action">
        <strong>Recommended action</strong>
        <p>${escapeHtml(item.recommendedAction || "Review the linked operation gate and update this alert after verification.")}</p>
        ${item.href ? `<a class="ghost-button tiny-button" href="${escapeHtml(item.href)}">Open source</a>` : ""}
      </div>
      <div class="deployment-operation-alert-evidence">
        ${(item.evidence || []).slice(0, 4).map((line) => `<span>${escapeHtml(line)}</span>`).join("") || `<span>No evidence summary.</span>`}
      </div>
      <div class="deployment-operation-alert-controls">
        <label><span>Status</span><select data-deployment-operation-alert-field="status">${deploymentOperationAlertStatusOptions(item.status || "open")}</select></label>
        <label><span>Priority</span><select data-deployment-operation-alert-field="priority">${deploymentOperationAlertPriorityOptions(item.priority || "medium")}</select></label>
        <label><span>Owner</span><input data-deployment-operation-alert-field="assignee" value="${escapeHtml(item.assignee || "")}" placeholder="owner"></label>
        <label><span>Due date</span><input data-deployment-operation-alert-field="dueDate" type="date" value="${escapeHtml(item.dueDate || "")}"></label>
        <label class="wide"><span>Memo</span><textarea data-deployment-operation-alert-field="memo" rows="2" placeholder="response memo">${escapeHtml(item.memo || "")}</textarea></label>
        <button class="secondary-button tiny-button" type="button" data-deployment-operation-alert-save="${escapeHtml(item.alertId || "")}">Save</button>
      </div>
      <small class="deployment-operation-alert-meta">first ${escapeHtml(item.firstSeenAt || "-")} / last ${escapeHtml(item.lastSeenAt || "-")} / updated ${escapeHtml(item.updatedAt || "-")}</small>
      ${renderDeploymentOperationAlertHistory(item)}
    </article>
  `).join("");
}

async function loadDeploymentOperationAlerts() {
  if (!els.deploymentOperationAlertPanel) return;
  state.masterDb.deploymentOperationAlertQueue = await fetchJson(`/api/admin/master-db/deployment-operation-alerts${deploymentOperationAlertQuery()}`);
  renderDeploymentOperationAlerts();
}

function collectDeploymentOperationAlertPayload(card) {
  const field = (name) => card.querySelector(`[data-deployment-operation-alert-field="${name}"]`);
  return {
    status: field("status")?.value || "open",
    priority: field("priority")?.value || "medium",
    assignee: field("assignee")?.value || "",
    dueDate: field("dueDate")?.value || "",
    memo: field("memo")?.value || "",
    updatedBy: "admin"
  };
}

async function saveDeploymentOperationAlert(alertId = "") {
  if (!alertId) return;
  const card = Array.from(els.deploymentOperationAlertList?.querySelectorAll("[data-deployment-operation-alert-id]") || [])
    .find((item) => item.dataset.deploymentOperationAlertId === alertId);
  if (!card) return;
  await fetchJson(`/api/admin/master-db/deployment-operation-alerts/${encodeURIComponent(alertId)}`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(collectDeploymentOperationAlertPayload(card))
  });
  await loadDeploymentOperationAlerts();
  await loadDeploymentOperationAlertQuality();
  await loadDeploymentOperationQualityActions();
  await loadDeploymentOperationQualityRecommendationAdjustments();
  await loadDeploymentOperationQualityAutoApprovalPerformance();
  await loadDeploymentOperationQualityReassessmentBundle();
  addFeedback("Operation alert saved.", "success");
}

function deploymentOperationAlertQualityTone(value = "") {
  if (value === "danger") return "danger";
  if (value === "warning") return "warning";
  if (value === "normal") return "good";
  return "muted";
}

function deploymentOperationAlertQualityHoursLabel(value) {
  if (value === null || value === undefined || Number.isNaN(Number(value))) return "-";
  return `${Number(value).toLocaleString("ko-KR", { maximumFractionDigits: 1 })}h`;
}

function deploymentOperationAlertQualityPercentLabel(value) {
  if (value === null || value === undefined || Number.isNaN(Number(value))) return "-";
  return `${fmtNumber(value)}%`;
}

function deploymentOperationAlertQualityValueLabel(issue = {}) {
  if (issue.value === null || issue.value === undefined || Number.isNaN(Number(issue.value))) return "-";
  if (issue.unit === "hours") return deploymentOperationAlertQualityHoursLabel(issue.value);
  if (issue.unit === "percent") return deploymentOperationAlertQualityPercentLabel(issue.value);
  return fmtNumber(issue.value);
}

function renderDeploymentOperationAlertQualityIssues(row = {}, limit = 3) {
  const issues = (row.warningIssues || []).slice(0, limit);
  if (!issues.length) {
    return `<span class="deployment-operation-alert-quality-issue good">No warning</span>`;
  }
  return issues.map((issue) => `
    <span class="deployment-operation-alert-quality-issue ${deploymentOperationAlertQualityTone(issue.level)}">
      <b>${escapeHtml(issue.label || issue.field || "Metric")}</b>
      <em>${escapeHtml(deploymentOperationAlertQualityValueLabel(issue))}</em>
    </span>
  `).join("");
}

function renderDeploymentOperationAlertQualityImprovements(items = [], limit = 3) {
  const rows = (items || []).filter(Boolean).slice(0, limit);
  if (!rows.length) {
    return `<li>Current response quality is inside the operating standard.</li>`;
  }
  return rows.map((item) => `<li>${escapeHtml(item)}</li>`).join("");
}

function renderDeploymentOperationAlertQuality() {
  if (!els.deploymentOperationAlertQualitySummary || !els.deploymentOperationAlertQualityTable) return;
  const report = state.masterDb.deploymentOperationAlertQuality;
  if (!report) {
    els.deploymentOperationAlertQualitySummary.innerHTML = `<div class="empty">Loading response quality.</div>`;
    if (els.deploymentOperationAlertQualityWarnings) els.deploymentOperationAlertQualityWarnings.innerHTML = `<div class="empty">Loading quality warnings.</div>`;
    if (els.deploymentOperationAlertQualityMonthly) els.deploymentOperationAlertQualityMonthly.innerHTML = `<div class="empty">Loading monthly warning badges.</div>`;
    if (els.deploymentOperationAlertQualityStandards) els.deploymentOperationAlertQualityStandards.innerHTML = `<div class="empty">Loading operation standards.</div>`;
    els.deploymentOperationAlertQualityTable.innerHTML = `<div class="empty">Loading owner performance.</div>`;
    return;
  }
  const summary = report.summary || {};
  const warningSummary = report.warningSummary || {};
  els.deploymentOperationAlertQualitySummary.innerHTML = `
    <span class="deployment-operation-alert-quality-status ${deploymentOperationAlertQualityTone(summary.healthGrade)}"><strong>${escapeHtml(summary.healthLabel || "-")}</strong><em>Quality</em></span>
    <span><strong>${fmtNumber(summary.handledCount || 0)}</strong><em>Handled</em></span>
    <span><strong>${deploymentOperationAlertQualityHoursLabel(summary.avgProcessingHours)}</strong><em>Avg time</em></span>
    <span><strong>${deploymentOperationAlertQualityPercentLabel(summary.delayedResolutionRate)}</strong><em>Late resolved</em></span>
    <span><strong>${deploymentOperationAlertQualityPercentLabel(summary.dismissedRatio)}</strong><em>Dismissed</em></span>
    <span><strong>${deploymentOperationAlertQualityPercentLabel(summary.reopenRate)}</strong><em>Reopen</em></span>
  `;
  if (els.deploymentOperationAlertQualityWarnings) {
    const overallWarnings = warningSummary.overall || {};
    const ownerWarnings = warningSummary.byAssignee || {};
    const warningBadges = [
      ...(overallWarnings.warningBadges || []).map((item) => ({ ...item, scopeLabel: "Overall" })),
      ...(ownerWarnings.warningBadges || [])
    ].slice(0, 8);
    const improvementItems = [
      ...(overallWarnings.improvementItems || []),
      ...(ownerWarnings.improvementItems || [])
    ].filter((item, index, arr) => item && arr.indexOf(item) === index);
    els.deploymentOperationAlertQualityWarnings.innerHTML = `
      <article class="deployment-operation-alert-quality-warning-card ${deploymentOperationAlertQualityTone(overallWarnings.highestGrade || summary.healthGrade)}">
        <div>
          <strong>Operating warning level</strong>
          <span class="calibration-audit-queue-badge ${deploymentOperationAlertQualityTone(overallWarnings.highestGrade || summary.healthGrade)}">${escapeHtml(overallWarnings.highestLabel || summary.healthLabel || "Normal")}</span>
        </div>
        <p>${fmtNumber(ownerWarnings.dangerRows || 0)} risk owners, ${fmtNumber(ownerWarnings.warningRows || 0)} watch owners, ${fmtNumber(ownerWarnings.issueCount || 0)} warning checks.</p>
        <div class="deployment-operation-alert-quality-badges">
          ${warningBadges.length ? warningBadges.map((issue) => `
            <span class="deployment-operation-alert-quality-issue ${deploymentOperationAlertQualityTone(issue.level)}">
              <b>${escapeHtml(issue.scopeLabel || issue.label || "Metric")}</b>
              <em>${escapeHtml(issue.label || issue.field || "Metric")} · ${escapeHtml(deploymentOperationAlertQualityValueLabel(issue))}</em>
            </span>
          `).join("") : `<span class="deployment-operation-alert-quality-issue good"><b>No warning</b><em>All tracked checks are inside the standard.</em></span>`}
        </div>
      </article>
      <article class="deployment-operation-alert-quality-warning-card">
        <div>
          <strong>Improvement needed</strong>
          <span>${fmtNumber(improvementItems.length)} item${improvementItems.length === 1 ? "" : "s"}</span>
        </div>
        <ul>${renderDeploymentOperationAlertQualityImprovements(improvementItems, 5)}</ul>
      </article>
    `;
  }
  if (els.deploymentOperationAlertQualityMonthly) {
    const months = report.monthly || [];
    els.deploymentOperationAlertQualityMonthly.innerHTML = months.length ? months.map((row) => `
      <article class="deployment-operation-alert-quality-month-card ${deploymentOperationAlertQualityTone(row.healthGrade)}">
        <div>
          <strong>${escapeHtml(row.label || row.key || "-")}</strong>
          <span class="calibration-audit-queue-badge ${deploymentOperationAlertQualityTone(row.healthGrade)}">${escapeHtml(row.healthLabel || "-")}</span>
        </div>
        <div class="deployment-operation-alert-quality-month-metrics">
          <span><b>${fmtNumber(row.handledCount || 0)}</b><em>Handled</em></span>
          <span><b>${deploymentOperationAlertQualityHoursLabel(row.avgProcessingHours)}</b><em>Avg</em></span>
          <span><b>${deploymentOperationAlertQualityPercentLabel(row.delayedResolutionRate)}</b><em>Late</em></span>
          <span><b>${deploymentOperationAlertQualityPercentLabel(row.reopenRate)}</b><em>Reopen</em></span>
        </div>
        <div class="deployment-operation-alert-quality-badges">${renderDeploymentOperationAlertQualityIssues(row, 2)}</div>
      </article>
    `).join("") : `<div class="empty">No monthly response quality data yet.</div>`;
  }
  if (els.deploymentOperationAlertQualityStandards) {
    const standards = report.operationStandards || [];
    els.deploymentOperationAlertQualityStandards.innerHTML = standards.length ? standards.map((item) => `
      <span>
        <strong>${escapeHtml(item.label || item.field || "-")}</strong>
        <em>${escapeHtml(item.summary || "")}</em>
      </span>
    `).join("") : `<div class="empty">No operation standards were returned.</div>`;
  }
  const rows = report.byAssignee || [];
  if (!rows.length) {
    els.deploymentOperationAlertQualityTable.innerHTML = `<div class="empty">No response quality logs for this month yet.</div>`;
    return;
  }
  els.deploymentOperationAlertQualityTable.innerHTML = `
    <table class="master-mini-table deployment-operation-alert-quality-owner-table">
      <thead>
        <tr>
          <th>Owner</th>
          <th>Quality</th>
          <th>Handled</th>
          <th>Avg time</th>
          <th>Late</th>
          <th>Resolved</th>
          <th>Dismissed</th>
          <th>Reopen</th>
          <th>Warnings</th>
          <th>Improve</th>
        </tr>
      </thead>
      <tbody>
        ${rows.map((row) => `
          <tr>
            <td><strong>${escapeHtml(row.label || row.key || "unassigned")}</strong></td>
            <td><span class="calibration-audit-queue-badge ${deploymentOperationAlertQualityTone(row.healthGrade)}">${escapeHtml(row.healthLabel || "-")}</span></td>
            <td>${fmtNumber(row.handledCount || 0)} / ${fmtNumber(row.changeCount || 0)}</td>
            <td>${deploymentOperationAlertQualityHoursLabel(row.avgProcessingHours)}</td>
            <td>${deploymentOperationAlertQualityPercentLabel(row.delayedResolutionRate)}</td>
            <td>${deploymentOperationAlertQualityPercentLabel(row.resolvedRatio)}</td>
            <td>${deploymentOperationAlertQualityPercentLabel(row.dismissedRatio)}</td>
            <td>${deploymentOperationAlertQualityPercentLabel(row.reopenRate)}</td>
            <td><div class="deployment-operation-alert-quality-badges">${renderDeploymentOperationAlertQualityIssues(row, 2)}</div></td>
            <td><ul class="deployment-operation-alert-quality-mini-list">${renderDeploymentOperationAlertQualityImprovements(row.improvementItems || [], 2)}</ul></td>
          </tr>
        `).join("")}
      </tbody>
    </table>
  `;
}

async function loadDeploymentOperationAlertQuality() {
  if (!els.deploymentOperationAlertQualitySummary || !els.deploymentOperationAlertQualityTable) return;
  const params = new URLSearchParams();
  if (els.deploymentOperationAlertQualityMonthInput?.value) params.set("month", els.deploymentOperationAlertQualityMonthInput.value);
  state.masterDb.deploymentOperationAlertQuality = await fetchJson(`/api/admin/master-db/deployment-operation-alert-quality?${params.toString()}`);
  if (els.deploymentOperationAlertQualityMonthInput && state.masterDb.deploymentOperationAlertQuality?.filters?.month) {
    els.deploymentOperationAlertQualityMonthInput.value = state.masterDb.deploymentOperationAlertQuality.filters.month;
  }
  renderDeploymentOperationAlertQuality();
}

function deploymentOperationQualityActionStatusLabel(value = "") {
  return {
    candidate: "Candidate",
    reviewing: "Reviewing",
    saved: "Saved",
    in_progress: "In progress",
    done: "Done",
    dismissed: "Dismissed"
  }[value] || value || "Candidate";
}

function deploymentOperationQualityActionStatusTone(value = "") {
  if (value === "done") return "good";
  if (value === "reviewing" || value === "in_progress") return "warning";
  if (value === "dismissed") return "muted";
  return "neutral";
}

function deploymentOperationQualityActionDueLabel(value = "") {
  return {
    overdue: "Overdue",
    this_week: "This week",
    upcoming: "Upcoming",
    no_due: "No due",
    closed: "Closed"
  }[value] || "No due";
}

function deploymentOperationQualityActionStatusOptions(status = "candidate") {
  return ["candidate", "reviewing", "saved", "in_progress", "done", "dismissed"].map((value) => (
    `<option value="${value}"${status === value ? " selected" : ""}>${deploymentOperationQualityActionStatusLabel(value)}</option>`
  )).join("");
}

function deploymentOperationQualityActionValueLabel(item = {}) {
  const unit = item.rootMetric === "avgProcessingHours" ? "hours" : "percent";
  return deploymentOperationAlertQualityValueLabel({ value: item.rootMetricValue, unit });
}

function deploymentOperationQualityHistoryAdjustmentTone(adjustment = {}) {
  if (!adjustment.applied) return "muted";
  if (["boost", "reinforce"].includes(adjustment.direction)) return "good";
  if (adjustment.direction === "downgrade") return "danger";
  if (adjustment.direction === "caution") return "warning";
  return "muted";
}

function renderDeploymentOperationQualityHistoryAdjustment(adjustment = {}) {
  if (!adjustment?.applied) return "";
  const tone = deploymentOperationQualityHistoryAdjustmentTone(adjustment);
  const afterPriority = adjustment.active ? adjustment.adjustedPriority : adjustment.proposedPriority || adjustment.adjustedPriority;
  const priorityText = adjustment.originalPriority && afterPriority
    ? `${adjustment.originalPriority} -> ${afterPriority}`
    : "priority reviewed";
  const reason = adjustment.recommendationCorrectionBasis || adjustment.adminReason || "History evidence adjusted this recommendation.";
  return `
    <div class="deployment-operation-quality-history-adjustment ${tone}">
      <div>
        <strong>History-based recommendation correction</strong>
        <span>${escapeHtml(priorityText)} · score ${fmtNumber(adjustment.historyEffectScore || 0)} · samples ${fmtNumber(adjustment.sampleSize || 0)}</span>
      </div>
      <p>${escapeHtml(reason)}</p>
      <small>Metric ${fmtNumber(adjustment.metricSampleSize || 0)} · owner ${fmtNumber(adjustment.assigneeSampleSize || 0)} · month ${fmtNumber(adjustment.monthSampleSize || 0)} · recurrence ${fmtNumber(adjustment.recurrenceRate || 0)}%</small>
    </div>
  `;
}

function deploymentOperationQualityActionsQuery() {
  const params = new URLSearchParams();
  if (els.deploymentOperationAlertQualityMonthInput?.value) params.set("month", els.deploymentOperationAlertQualityMonthInput.value);
  if (els.deploymentOperationQualityActionStatusFilter?.value) params.set("status", els.deploymentOperationQualityActionStatusFilter.value);
  if (els.deploymentOperationQualityActionAssigneeFilter?.value) params.set("assignee", els.deploymentOperationQualityActionAssigneeFilter.value);
  if (els.deploymentOperationQualityActionDueStateFilter?.value) params.set("dueState", els.deploymentOperationQualityActionDueStateFilter.value);
  if (els.deploymentOperationQualityActionPriorityFilter?.value) params.set("priority", els.deploymentOperationQualityActionPriorityFilter.value);
  if (els.deploymentOperationQualityActionRiskFilter?.value) params.set("riskLevel", els.deploymentOperationQualityActionRiskFilter.value);
  if (els.deploymentOperationQualityActionMetricFilter?.value) params.set("rootMetric", els.deploymentOperationQualityActionMetricFilter.value);
  if (els.deploymentOperationQualityActionScopeFilter?.value) params.set("scopeType", els.deploymentOperationQualityActionScopeFilter.value);
  return `/api/admin/master-db/deployment-operation-quality-actions?${params.toString()}`;
}

function renderDeploymentOperationQualityActionFocus(focus = {}) {
  const overdue = focus.overdue || [];
  const thisWeek = focus.thisWeek || [];
  const owners = focus.ownerUnresolved || [];
  const rowText = (item) => `${item.title || item.actionId || "-"} / ${item.assignee || "unassigned"} / ${item.dueDate || "-"}`;
  return `
    <div class="deployment-operation-quality-action-focus">
      <section>
        <strong>Overdue</strong>
        ${overdue.length ? overdue.map((item) => `<span>${escapeHtml(rowText(item))}</span>`).join("") : `<span>No overdue quality actions.</span>`}
      </section>
      <section>
        <strong>This week</strong>
        ${thisWeek.length ? thisWeek.map((item) => `<span>${escapeHtml(rowText(item))}</span>`).join("") : `<span>No quality actions due this week.</span>`}
      </section>
      <section>
        <strong>Open by owner</strong>
        ${owners.length ? owners.slice(0, 6).map((row) => `<span>${escapeHtml(row.owner || "unassigned")} · open ${fmtNumber(row.open || 0)} · overdue ${fmtNumber(row.overdue || 0)} · high ${fmtNumber(row.highRisk || 0)}</span>`).join("") : `<span>No unresolved owner workload.</span>`}
      </section>
    </div>
  `;
}

function renderDeploymentOperationQualityOperationalQueue(queue = {}) {
  const overdue = queue.overdueItems || [];
  const thisWeek = queue.thisWeekItems || [];
  const owners = queue.ownerUnresolved || [];
  const metrics = queue.metricUnresolved || [];
  const itemText = (item) => `${item.title || item.actionId || "-"} / ${item.assignee || "unassigned"} / ${item.dueDate || "-"}`;
  return `
    <div class="deployment-operation-quality-operational-queue">
      <section>
        <strong>Late actions</strong>
        ${overdue.length ? overdue.map((item) => `<span>${escapeHtml(itemText(item))}</span>`).join("") : `<span>No late saved actions.</span>`}
      </section>
      <section>
        <strong>This week</strong>
        ${thisWeek.length ? thisWeek.map((item) => `<span>${escapeHtml(itemText(item))}</span>`).join("") : `<span>No saved actions due this week.</span>`}
      </section>
      <section>
        <strong>Unresolved by owner</strong>
        ${owners.length ? owners.slice(0, 8).map((row) => `<span>${escapeHtml(row.owner || "unassigned")} · unresolved ${fmtNumber(row.unresolved || 0)} · late ${fmtNumber(row.overdue || 0)} · high ${fmtNumber(row.highRisk || 0)} · next ${escapeHtml(row.nextDueDate || "-")}</span>`).join("") : `<span>No unresolved saved owner workload.</span>`}
      </section>
      <section>
        <strong>Unresolved by metric</strong>
        ${metrics.length ? metrics.slice(0, 8).map((row) => `<span>${escapeHtml(row.rootMetricLabel || row.rootMetric || "-")} · unresolved ${fmtNumber(row.unresolved || 0)} · late ${fmtNumber(row.overdue || 0)} · high ${fmtNumber(row.highRisk || 0)}</span>`).join("") : `<span>No unresolved root metric workload.</span>`}
      </section>
    </div>
  `;
}

function renderDeploymentOperationQualityActionCard(item = {}) {
  const completedLabel = item.completionQualitySnapshot
    ? `${item.completionQualitySnapshot.capturedAt || "-"} · ${item.completionQualitySnapshot.summary?.healthLabel || item.completionQualitySnapshot.summary?.healthGrade || "-"} · active at completion ${fmtNumber(item.completionQualitySnapshot.operationalQueue?.activeCount || 0)}`
    : "";
  return `
    <article class="deployment-operation-quality-action-card ${deploymentOperationAlertQualityTone(item.riskLevel)}" data-deployment-operation-quality-action-id="${escapeHtml(item.actionId || "")}">
      <div class="deployment-operation-quality-action-head">
        <div>
          <strong>${escapeHtml(item.title || "Quality improvement action")}</strong>
          <small>${escapeHtml([item.sourceMonth, item.scopeType === "assignee" ? "Owner" : "Monthly", item.scopeLabel || item.scopeKey].filter(Boolean).join(" · "))}</small>
        </div>
        <div class="calibration-audit-queue-badges">
          <span class="calibration-audit-queue-badge ${deploymentOperationAlertQualityTone(item.riskLevel)}">${escapeHtml(item.riskLabel || item.riskLevel || "-")}</span>
          <span class="calibration-audit-queue-badge ${deploymentOperationQualityActionStatusTone(item.status)}">${escapeHtml(deploymentOperationQualityActionStatusLabel(item.status))}</span>
          <span class="calibration-audit-queue-badge ${item.priority === "high" ? "danger" : item.priority === "medium" ? "warning" : "muted"}">${escapeHtml(item.priority || "-")}</span>
          <span class="calibration-audit-queue-badge ${item.dueState === "overdue" ? "danger" : item.dueState === "this_week" ? "warning" : "muted"}">${escapeHtml(deploymentOperationQualityActionDueLabel(item.dueState))}</span>
          ${item.historyPriorityAdjustment?.applied ? `<span class="calibration-audit-queue-badge ${deploymentOperationQualityHistoryAdjustmentTone(item.historyPriorityAdjustment)}">history ${escapeHtml(item.historyPriorityAdjustment.direction || "adjusted")}</span>` : ""}
          ${item.stale ? `<span class="calibration-audit-queue-badge muted">Stale</span>` : ""}
        </div>
      </div>
      <p>${escapeHtml(item.description || "Review this warning and decide whether it needs an operator action.")}</p>
      <div class="deployment-operation-quality-action-metrics">
        <span><strong>${escapeHtml(item.rootMetricLabel || item.rootMetric || "-")}</strong><em>Root metric</em></span>
        <span><strong>${escapeHtml(deploymentOperationQualityActionValueLabel(item))}</strong><em>Observed</em></span>
        <span><strong>${escapeHtml(item.dueDate || "-")}</strong><em>Due date</em></span>
        <span><strong>${escapeHtml(item.assignee || "unassigned")}</strong><em>Owner</em></span>
      </div>
      <div class="deployment-operation-quality-action-recommendation">
        <strong>Recommended action</strong>
        <p>${escapeHtml(item.recommendedAction || "Review the source warning, assign an owner, and set a target date.")}</p>
      </div>
      ${renderDeploymentOperationQualityHistoryAdjustment(item.historyPriorityAdjustment)}
      ${item.completionQualitySnapshot ? `<div class="deployment-operation-quality-action-snapshot"><strong>Completion snapshot</strong><span>${escapeHtml(completedLabel)}</span></div>` : ""}
      <div class="deployment-operation-quality-action-controls">
        <label><span>Status</span><select data-deployment-operation-quality-action-field="status">${deploymentOperationQualityActionStatusOptions(item.status || "candidate")}</select></label>
        <label><span>Owner</span><input data-deployment-operation-quality-action-field="assignee" value="${escapeHtml(item.assignee || "")}" placeholder="owner"></label>
        <label><span>Due date</span><input data-deployment-operation-quality-action-field="dueDate" type="date" value="${escapeHtml(item.dueDate || "")}"></label>
        <label class="wide"><span>Memo</span><textarea data-deployment-operation-quality-action-field="memo" rows="2" placeholder="review memo">${escapeHtml(item.memo || "")}</textarea></label>
        <button class="secondary-button tiny-button" type="button" data-deployment-operation-quality-action-save="${escapeHtml(item.actionId || "")}">Save</button>
      </div>
    </article>
  `;
}

function renderDeploymentOperationQualityActionGroup(title = "", description = "", items = [], emptyText = "") {
  return `
    <section class="deployment-operation-quality-action-group">
      <div class="deployment-operation-quality-action-group-head">
        <strong>${escapeHtml(title)}</strong>
        <span>${escapeHtml(description)}</span>
      </div>
      ${items.length ? items.map(renderDeploymentOperationQualityActionCard).join("") : `<div class="empty">${escapeHtml(emptyText || "No actions in this section.")}</div>`}
    </section>
  `;
}

