function adminSubscriptionAvailable() {
  return Boolean(els.adminSubscriptionConsole && els.adminSubscriptionSummary && els.adminSubscriptionList);
}

function commercialPlanLabel(plan = "") {
  return ({ free: "무료", basic: "기본", pro: "프로" })[plan] || plan || "-";
}

function subscriptionStatusLabel(status = "") {
  return ({ trial: "체험", active: "정상", past_due: "결제 확인", paused: "일시중지", cancelled: "해지" })[status] || status || "-";
}

function subscriptionStatusTone(status = "") {
  if (status === "active") return "good";
  if (status === "past_due") return "warning";
  if (["paused", "cancelled"].includes(status)) return "muted";
  return "neutral";
}

function planTone(plan = "") {
  if (plan === "pro") return "good";
  if (plan === "basic") return "neutral";
  return "muted";
}

function renderPlanFeatureSummary(access = {}) {
  const features = access.featureAccess || {};
  const items = [
    features.report?.label || "리포트",
    features.regionCard?.label || "지역카드",
    features.strategyRecommendations?.label || "전략 추천",
    features.executionPlan?.allowed ? "실행계획 가능" : "실행계획 잠금",
    features.monthlyRetrospective?.allowed ? "월간 회고 가능" : "월간 회고 잠금"
  ];
  return items.map((item) => `<span>${escapeHtml(item)}</span>`).join("");
}

