function calibrationAuditReviewStatusOptions(current = "pending") {
  return [
    ["pending", "Pending"],
    ["in_review", "In review"],
    ["action_required", "Action required"],
    ["resolved", "Resolved"],
    ["deferred", "Deferred"]
  ].map(([value, label]) => `<option value="${value}" ${String(current || "pending") === value ? "selected" : ""}>${label}</option>`).join("");
}

function auditReviewHistoryLabel(log = {}) {
  const fields = (log.changedFields || []).join(", ") || "review fields";
  const summary = log.summary || "";
  return `${log.operationType || "single"} / ${fields}${summary ? ` / ${summary}` : ""}`;
}

function renderCalibrationAuditReviewHistory(summary = {}, logs = []) {
  const recent = logs.length ? logs : summary.recent || [];
  if (!summary.count && !recent.length) {
    return `<div class="calibration-audit-review-history empty-history">No review change history yet.</div>`;
  }
  return `
    <details class="calibration-audit-review-history">
      <summary>
        <strong>${fmtNumber(summary.count || recent.length)} change${(summary.count || recent.length) === 1 ? "" : "s"}</strong>
        <span>latest ${escapeHtml(summary.latestChangedAt || recent[0]?.changedAt || "-")} by ${escapeHtml(summary.latestChangedBy || recent[0]?.changedBy || "-")}</span>
      </summary>
      <div>
        ${recent.slice(0, 5).map((log) => `
          <article>
            <strong>${escapeHtml(log.changedAt || "-")} · ${escapeHtml(log.changedBy || "-")}</strong>
            <span>${escapeHtml(auditReviewHistoryLabel(log))}</span>
          </article>
        `).join("")}
      </div>
    </details>
  `;
}

function renderCalibrationAuditBulkHistory(history = {}) {
  const operations = history.recentBulkOperations || history.bulkOperations || [];
  if (!operations.length) return "";
  return `
    <div class="calibration-audit-bulk-history">
      <div>
        <strong>Recent bulk operations</strong>
        <span>${fmtNumber(history.totalLogs || 0)} review log rows</span>
      </div>
      ${operations.slice(0, 5).map((operation) => `
        <article>
          <strong>${escapeHtml(operation.changedAt || "-")} · ${escapeHtml(operation.changedBy || "-")}</strong>
          <span>${fmtNumber(operation.itemCount || 0)} items / ${(operation.changedFields || []).map(escapeHtml).join(", ") || "fields"} / ${escapeHtml(operation.operationId || "")}</span>
        </article>
      `).join("")}
    </div>
    ${renderBusinessPlanAccessPanel()}
  `;
}

function fmtQualityDays(value) {
  if (value === null || value === undefined || Number.isNaN(Number(value))) return "-";
  return `${Number(value).toFixed(2)}d`;
}

function slaTone(level = "") {
  if (level === "danger") return "danger";
  if (level === "warning") return "warning";
  return "good";
}

function renderSlaBadge(sla = {}) {
  const level = sla.level || "normal";
  return `<span class="calibration-audit-sla ${escapeHtml(slaTone(level))}">${escapeHtml(sla.label || level)}</span>`;
}

function renderOperationWarningBadge(row = {}) {
  const warning = row.operationWarning || {};
  const level = warning.severity || warning.level || row.warningSeverity || row.slaLevel || row.sla?.level || "normal";
  const label = warning.label || row.warningLabel || row.slaWarningLabel || row.slaLabel || (level === "danger" ? "Risk" : level === "warning" ? "Warning" : "Normal");
  return `<span class="calibration-audit-sla ${escapeHtml(slaTone(level))}">${escapeHtml(label)}</span>`;
}

function renderSlaImprovementItems(sla = {}) {
  const items = sla.improvementItems || [];
  if (!items.length) return `<span class="calibration-audit-sla-note">No SLA improvement required.</span>`;
  return `<span class="calibration-audit-sla-note">${items.map((item) => escapeHtml(item.label || item.key || "")).filter(Boolean).join(" / ")}</span>`;
}

function renderOperationWarningItems(row = {}) {
  const warning = row.operationWarning || {};
  const items = warning.improvementItems || row.slaImprovementItems || row.sla?.improvementItems || [];
  if (!items.length) return `<span class="calibration-audit-sla-note">No operation warning.</span>`;
  return `<span class="calibration-audit-sla-note">${items.map((item) => escapeHtml(item.label || item.key || "")).filter(Boolean).join(" / ")}</span>`;
}

function slaActionPriorityOptions(current = "medium") {
  return [
    ["urgent", "Urgent"],
    ["high", "High"],
    ["medium", "Medium"],
    ["low", "Low"]
  ].map(([value, label]) => `<option value="${value}" ${String(current || "medium") === value ? "selected" : ""}>${label}</option>`).join("");
}

function slaActionStatusOptions(current = "candidate") {
  return [
    ["candidate", "Candidate"],
    ["planned", "Planned"],
    ["in_progress", "In progress"],
    ["done", "Done"],
    ["dismissed", "Dismissed"]
  ].map(([value, label]) => `<option value="${value}" ${String(current || "candidate") === value ? "selected" : ""}>${label}</option>`).join("");
}

function slaRecommendationAdjustmentTone(item = {}) {
  if (item.status === "approved" || item.activeApplied) return "good";
  if (item.status === "rejected" || item.workflowStatus === "rejected") return "danger";
  if (item.direction === "downgrade") return "warning";
  if (item.direction === "caution") return "warning";
  if (item.direction === "boost") return "good";
  return "neutral";
}

function renderSlaHistoryAdjustment(adjustment = {}) {
  if (!adjustment || !adjustment.applied) return "";
  const workflowStatus = adjustment.workflowStatus || (adjustment.activeApplied ? "approved" : "proposed");
  const tone = slaRecommendationAdjustmentTone({ ...adjustment, status: workflowStatus });
  const isActive = adjustment.activeApplied || workflowStatus === "active";
  const activeText = isActive
    ? "History adjustment is active in this recommendation."
    : workflowStatus === "rejected"
      ? "Adjustment was rejected and is not active."
      : "Proposal is waiting for admin approval and is not active yet.";
  const adjustedPriority = adjustment.adjustedPriority || adjustment.proposedPriority || adjustment.activePriority || "-";
  const workflowTone = workflowStatus === "active" ? tone : workflowStatus === "approved" ? "good" : workflowStatus === "rejected" ? "danger" : "warning";
  const basis = adjustment.calculationBasis || {};
  const basisText = basis.issueWeight
    ? `Basis: issue ${basis.issueWeight}% / assignee ${basis.assigneeWeight}% / month ${basis.monthWeight}%. Boost: ${basis.boostRule}. Downgrade: ${basis.downgradeRule}.`
    : "";
  return `
    <div class="calibration-sla-history-adjustment ${escapeHtml(tone)}">
      <strong>History adjustment</strong>
      <span>
        ${calibrationAuditQueueBadge(`score ${fmtNumber(adjustment.historyEffectScore || 0)}`, tone)}
        ${calibrationAuditQueueBadge(adjustment.direction || "neutral", tone)}
        ${calibrationAuditQueueBadge(workflowStatus, workflowTone)}
        ${calibrationAuditQueueBadge(`${adjustment.originalPriority || "-"} -> ${adjustedPriority}`, tone)}
      </span>
      <p>${escapeHtml(activeText)} ${escapeHtml((adjustment.reasons || []).join(" "))}</p>
      ${basisText ? `<small>${escapeHtml(basisText)}</small>` : ""}
    </div>
  `;
}

function renderCalibrationSlaActions(slaActions = {}) {
  const actions = slaActions.items || [];
  if (!actions.length) return "";
  const summary = slaActions.summary || {};
  return `
    <div class="calibration-sla-actions">
      <div class="calibration-sla-actions-head">
        <div>
          <strong>SLA improvement actions</strong>
          <span>${fmtNumber(summary.open || 0)} open / ${fmtNumber(summary.saved || 0)} saved / ${fmtNumber(summary.generated || 0)} generated</span>
        </div>
      </div>
      <div class="calibration-sla-action-list">
        ${actions.slice(0, 8).map((action) => `
          <article class="calibration-sla-action ${escapeHtml(action.slaLevel || "warning")}" data-calibration-sla-action-id="${escapeHtml(action.actionId || "")}" data-sla-action-source-key="${escapeHtml(action.sourceKey || "")}" data-sla-action-source-type="${escapeHtml(action.sourceType || "summary")}" data-sla-action-source-label="${escapeHtml(action.sourceLabel || "")}" data-sla-action-month="${escapeHtml(action.month || "")}" data-sla-action-owner="${escapeHtml(action.owner || "")}" data-sla-action-level="${escapeHtml(action.slaLevel || "")}" data-sla-action-issue-key="${escapeHtml(action.issueKey || "")}" data-sla-action-severity="${escapeHtml(action.severity || "")}" data-sla-action-root-metric="${escapeHtml(action.rootMetric || "")}" data-sla-action-source-metrics="${escapeHtml(JSON.stringify(action.sourceMetrics || {}))}">
            <div>
              <strong>${escapeHtml(action.sourceLabel || action.sourceType || "SLA")}</strong>
              <span>${renderSlaBadge({ level: action.slaLevel, label: action.slaLevel === "danger" ? "Risk" : "Watch" })} ${escapeHtml(action.rootMetric || action.issueKey || "")} · ${escapeHtml(action.candidateStatus || "")}</span>
            </div>
            <p>${escapeHtml(action.recommendation || "")}</p>
            ${renderSlaHistoryAdjustment(action.historyAdjustment)}
            <div class="calibration-sla-action-grid">
              <label>
                <span>Priority</span>
                <select data-sla-action-field="priority">${slaActionPriorityOptions(action.priority)}</select>
              </label>
              <label>
                <span>Assignee</span>
                <input data-sla-action-field="assignee" value="${escapeHtml(action.assignee || action.owner || "")}">
              </label>
              <label>
                <span>Target</span>
                <input type="date" data-sla-action-field="targetDate" value="${escapeHtml(action.targetDate || "")}">
              </label>
              <label>
                <span>Status</span>
                <select data-sla-action-field="status">${slaActionStatusOptions(action.status)}</select>
              </label>
              <label class="wide">
                <span>Recommended action</span>
                <textarea data-sla-action-field="recommendation" rows="2">${escapeHtml(action.recommendation || "")}</textarea>
              </label>
              <button class="secondary-button" type="button" data-calibration-sla-action-save="${escapeHtml(action.actionId || "")}">Save action</button>
            </div>
          </article>
        `).join("")}
      </div>
    </div>
  `;
}

