function calibrationAuditQueueTone(item = {}) {
  if (item.isOverdue) return "danger";
  if (item.isThisWeek) return "warning";
  if (item.reviewStatus === "resolved") return "good";
  if (item.reviewStatus === "deferred") return "muted";
  return "neutral";
}

function calibrationAuditQueueBadge(label, tone = "neutral") {
  return `<span class="calibration-audit-queue-badge ${escapeHtml(tone)}">${escapeHtml(label)}</span>`;
}

function calibrationSlaActionQueueTone(action = {}) {
  if (action.status === "done") return "good";
  if (action.status === "dismissed") return "muted";
  if (action.isOverdue) return "danger";
  if (action.riskLevel === "high" || action.slaLevel === "danger") return "danger";
  if (action.isThisWeek || action.priority === "urgent" || action.priority === "high") return "warning";
  return "neutral";
}

function renderSlaActionCompletionSnapshot(snapshot = {}) {
  if (!snapshot || !snapshot.capturedAt) return "";
  const current = snapshot.current || {};
  const deltas = snapshot.deltas || {};
  return `
    <div class="calibration-sla-snapshot">
      <strong>Completion snapshot</strong>
      <span>${escapeHtml(snapshot.improvementState || "unknown")} / captured ${escapeHtml(snapshot.capturedAt || "")}</span>
      <div>
        <em>Avg ${fmtQualityDays(current.avgProcessingDays)} (${deltas.avgProcessingDays ?? "-"})</em>
        <em>Delay ${fmtPercent(current.delayedResolutionRate || 0)} (${deltas.delayedResolutionRate ?? "-"})</em>
        <em>Reopen ${fmtPercent(current.reopenRate || 0)} (${deltas.reopenRate ?? "-"})</em>
        <em>Open delay ${fmtNumber(current.unresolvedDelayedItems || 0)} (${deltas.unresolvedDelayedItems ?? "-"})</em>
      </div>
    </div>
  `;
}

function renderEffectQualitySlaActionCompletionSnapshot(snapshot = {}) {
  if (!snapshot || !snapshot.capturedAt) return "";
  const row = snapshot.owner || snapshot.month || snapshot.summary || {};
  return `
    <div class="calibration-sla-snapshot">
      <strong>Completion snapshot</strong>
      <span>Captured ${escapeHtml(snapshot.capturedAt || "")} / ${escapeHtml(snapshot.assignee || "unassigned")}</span>
      <div>
        <em>SLA ${escapeHtml(row.sla?.label || row.sla?.level || "-")}</em>
        <em>Avg ${slaQualityRereviewHours(row.avgProcessingHours)}</em>
        <em>Reopen ${fmtPercent(row.reopenRate || 0)}</em>
        <em>Overdue ${fmtNumber(row.delayedIncompleteItems || 0)}</em>
        <em>Link open ${fmtNumber(row.activeLinkUnprocessed || 0)}</em>
      </div>
    </div>
  `;
}

function renderCalibrationSlaActionQueue() {
  if (!els.calibrationSlaActionQueueSummary || !els.calibrationSlaActionQueueList) return;
  const queue = state.masterDb.calibrationSlaActionQueue;
  if (!queue) {
    els.calibrationSlaActionQueueSummary.innerHTML = `<span>SLA 개선 액션 큐를 불러오는 중입니다.</span>`;
    els.calibrationSlaActionQueueList.innerHTML = `<div class="empty">SLA 개선 액션 큐를 불러오는 중입니다.</div>`;
    return;
  }
  const summary = queue.summary || {};
  const focus = queue.focus || {};
  const ownerRows = focus.ownerOpen || [];
  els.calibrationSlaActionQueueSummary.innerHTML = `
    <span><strong>${fmtNumber(summary.open || 0)}</strong><em>Open</em></span>
    <span><strong>${fmtNumber(summary.overdue || 0)}</strong><em>Overdue</em></span>
    <span><strong>${fmtNumber(summary.thisWeek || 0)}</strong><em>This week</em></span>
    <span><strong>${fmtNumber(summary.urgent || 0)}</strong><em>Urgent</em></span>
    <span><strong>${fmtNumber(summary.highRisk || 0)}</strong><em>High risk</em></span>
    <span><strong>${fmtNumber(summary.done || 0)}</strong><em>Done</em></span>
  `;
  const focusSummary = `
    <div class="calibration-sla-action-focus">
      <section>
        <strong>Delayed actions</strong>
        ${(focus.overdue || []).length ? (focus.overdue || []).slice(0, 5).map((item) => `<span>${escapeHtml(item.sourceLabel || item.actionId)} / ${escapeHtml(item.assignee || "unassigned")} / ${escapeHtml(item.targetDate || "-")}</span>`).join("") : `<span>지연 액션이 없습니다.</span>`}
      </section>
      <section>
        <strong>This week</strong>
        ${(focus.thisWeek || []).length ? (focus.thisWeek || []).slice(0, 5).map((item) => `<span>${escapeHtml(item.sourceLabel || item.actionId)} / ${escapeHtml(item.assignee || "unassigned")} / ${escapeHtml(item.targetDate || "-")}</span>`).join("") : `<span>이번 주 처리 액션이 없습니다.</span>`}
      </section>
      <section>
        <strong>Owner open</strong>
        ${ownerRows.length ? ownerRows.slice(0, 5).map((row) => `<span>${escapeHtml(row.owner || "unassigned")} / ${fmtNumber(row.open)} open / ${fmtNumber(row.overdue)} overdue</span>`).join("") : `<span>담당자별 미해결 큐가 없습니다.</span>`}
      </section>
    </div>
  `;
  const items = queue.items || [];
  els.calibrationSlaActionQueueList.innerHTML = `
    ${focusSummary}
    <div class="calibration-sla-action-list">
      ${items.length ? items.map((action) => `
        <article class="calibration-sla-action ${escapeHtml(calibrationSlaActionQueueTone(action))}" data-calibration-sla-action-id="${escapeHtml(action.actionId || "")}" data-sla-action-source-key="${escapeHtml(action.sourceKey || "")}" data-sla-action-source-type="${escapeHtml(action.sourceType || "summary")}" data-sla-action-source-label="${escapeHtml(action.sourceLabel || "")}" data-sla-action-month="${escapeHtml(action.month || "")}" data-sla-action-owner="${escapeHtml(action.owner || "")}" data-sla-action-level="${escapeHtml(action.slaLevel || "")}" data-sla-action-issue-key="${escapeHtml(action.issueKey || "")}" data-sla-action-severity="${escapeHtml(action.severity || "")}" data-sla-action-root-metric="${escapeHtml(action.rootMetric || "")}" data-sla-action-source-metrics="${escapeHtml(JSON.stringify(action.sourceMetrics || {}))}">
          <div>
            <strong>${escapeHtml(action.sourceLabel || action.actionId || "SLA action")}</strong>
            <span>
              ${renderSlaBadge({ level: action.slaLevel, label: action.slaLevel === "danger" ? "Risk" : "Watch" })}
              ${calibrationAuditQueueBadge(action.dueState || "no_due", action.isOverdue ? "danger" : action.isThisWeek ? "warning" : "neutral")}
              ${calibrationAuditQueueBadge(`priority ${action.priority || "medium"}`, action.priority === "urgent" || action.priority === "high" ? "warning" : "neutral")}
              ${calibrationAuditQueueBadge(`risk ${action.riskLevel || "low"}`, action.riskLevel === "high" ? "danger" : action.riskLevel === "medium" ? "warning" : "neutral")}
              ${calibrationAuditQueueBadge(action.candidateStatus || "saved", action.isSaved ? "good" : "muted")}
            </span>
          </div>
          <p>${escapeHtml(action.rootMetric || action.issueKey || "")} / ${escapeHtml(action.recommendation || "")}</p>
          ${renderSlaHistoryAdjustment(action.historyAdjustment)}
          ${renderSlaActionCompletionSnapshot(action.completionQualitySnapshot)}
          <div class="calibration-sla-action-grid">
            <label>
              <span>Priority</span>
              <select data-sla-action-field="priority">${slaActionPriorityOptions(action.priority)}</select>
            </label>
            <label>
              <span>Assignee</span>
              <input data-sla-action-field="assignee" value="${escapeHtml(action.assignee || action.owner || "")}">
            </label>
            <label>
              <span>Target</span>
              <input type="date" data-sla-action-field="targetDate" value="${escapeHtml(action.targetDate || "")}">
            </label>
            <label>
              <span>Status</span>
              <select data-sla-action-field="status">${slaActionStatusOptions(action.status)}</select>
            </label>
            <label class="wide">
              <span>Recommended action</span>
              <textarea data-sla-action-field="recommendation" rows="2">${escapeHtml(action.recommendation || "")}</textarea>
            </label>
            <button class="secondary-button" type="button" data-calibration-sla-action-save="${escapeHtml(action.actionId || "")}">Save action</button>
          </div>
        </article>
      `).join("") : `<div class="empty">현재 필터에 맞는 SLA 개선 액션이 없습니다. SLA v1.0은 잠금 상태이므로 새 확장 없이 기존 액션만 확인합니다.</div>`}
    </div>
  `;
}

function calibrationSlaReassessmentTone(item = {}) {
  const stateValue = item.reassessment?.evaluationState || "";
  if (stateValue === "improved") return "good";
  if (stateValue === "worse") return "danger";
  if (item.reassessment?.followUpNeeded) return "warning";
  return "neutral";
}

function renderSlaReassessmentMetric(label, beforeValue, afterValue, deltaValue, formatter = (value) => fmtNumber(value)) {
  return `
    <span>
      <strong>${escapeHtml(label)}</strong>
      <em>${formatter(beforeValue)} -> ${formatter(afterValue)} / ${deltaValue ?? "-"}</em>
    </span>
  `;
}

function renderSlaReassessmentCard(item = {}) {
  const reassessment = item.reassessment || {};
  const snapshot = reassessment.snapshotMetrics || {};
  const current = reassessment.currentMetrics || {};
  const deltas = reassessment.deltas || {};
  const followUpButton = reassessment.followUpNeeded
    ? `<button class="secondary-button" type="button" data-calibration-sla-followup-create="${escapeHtml(item.actionId || "")}">Create follow-up action</button>`
    : "";
  return `
    <article class="calibration-sla-reassessment-card ${escapeHtml(calibrationSlaReassessmentTone(item))}">
      <div>
        <strong>${escapeHtml(item.sourceLabel || item.actionId || "Completed SLA action")}</strong>
        <span>
          ${calibrationAuditQueueBadge(reassessment.evaluationState || "unchanged", calibrationSlaReassessmentTone(item))}
          ${calibrationAuditQueueBadge(`score ${fmtNumber(reassessment.effectScore || 0)}`, reassessment.effectScore >= 70 ? "good" : reassessment.effectScore < 45 ? "danger" : "warning")}
          ${calibrationAuditQueueBadge(reassessment.recurrence ? "recurrence" : "no recurrence", reassessment.recurrence ? "danger" : "good")}
          ${calibrationAuditQueueBadge(reassessment.followUpNeeded ? "follow-up needed" : "no follow-up", reassessment.followUpNeeded ? "warning" : "good")}
        </span>
      </div>
      <p>${escapeHtml(reassessment.followUpReason || item.recommendation || "No follow-up reason.")}</p>
      <div class="calibration-sla-reassessment-metrics">
        ${renderSlaReassessmentMetric("Avg", snapshot.avgProcessingDays, current.avgProcessingDays, deltas.avgProcessingDays, fmtQualityDays)}
        ${renderSlaReassessmentMetric("Delay", snapshot.delayedResolutionRate || 0, current.delayedResolutionRate || 0, deltas.delayedResolutionRate, fmtPercent)}
        ${renderSlaReassessmentMetric("Reopen", snapshot.reopenRate || 0, current.reopenRate || 0, deltas.reopenRate, fmtPercent)}
        ${renderSlaReassessmentMetric("Open delay", snapshot.unresolvedDelayedItems || 0, current.unresolvedDelayedItems || 0, deltas.unresolvedDelayedItems, fmtNumber)}
      </div>
      <small>Completed ${escapeHtml(item.completedAt || item.updatedAt || "-")} / post logs ${fmtNumber(reassessment.postCompletionLogCount || 0)} / current SLA ${escapeHtml(reassessment.currentSla?.level || "normal")}</small>
      <div class="calibration-sla-reassessment-actions">
        ${followUpButton}
      </div>
    </article>
  `;
}

function renderCalibrationSlaReassessment() {
  if (!els.calibrationSlaReassessmentSummary || !els.calibrationSlaReassessmentList) return;
  const report = state.masterDb.calibrationSlaReassessment;
  if (!report) {
    els.calibrationSlaReassessmentSummary.innerHTML = `<span>SLA 액션 사후 재평가를 불러오는 중입니다.</span>`;
    els.calibrationSlaReassessmentList.innerHTML = `<div class="empty">SLA 액션 사후 재평가를 불러오는 중입니다.</div>`;
    return;
  }
  const summary = report.summary || {};
  els.calibrationSlaReassessmentSummary.innerHTML = `
    <span><strong>${fmtNumber(summary.total || 0)}</strong><em>Completed</em></span>
    <span><strong>${fmtNumber(summary.improved || 0)}</strong><em>Improved</em></span>
    <span><strong>${fmtNumber(summary.unchanged || 0)}</strong><em>Unchanged</em></span>
    <span><strong>${fmtNumber(summary.worse || 0)}</strong><em>Worse</em></span>
    <span><strong>${fmtNumber(summary.recurrence || 0)}</strong><em>Recurrence</em></span>
    <span><strong>${fmtNumber(summary.followUpNeeded || 0)}</strong><em>Follow-up</em></span>
    <span><strong>${fmtNumber(summary.averageEffectScore || 0)}</strong><em>Avg score</em></span>
  `;
  const items = report.items || [];
  els.calibrationSlaReassessmentList.innerHTML = items.length
    ? items.map(renderSlaReassessmentCard).join("")
    : `<div class="empty">현재 필터에 맞는 완료 액션 사후 재평가가 없습니다.</div>`;
}

function renderSlaHistoryGroupRows(rows = [], emptyText = "No history group yet.") {
  if (!rows.length) return `<p>${escapeHtml(emptyText)}</p>`;
  return `
    <div class="sla-history-group-list">
      ${rows.slice(0, 6).map((row) => `
        <article>
          <strong>${escapeHtml(row.label || row.key || "unknown")}</strong>
          <span>score ${fmtNumber(row.averageEffectScore || 0)} / improved ${fmtPercent(row.improvedRate || 0)} / recurrence ${fmtPercent(row.recurrenceRate || 0)}</span>
          <small>${fmtNumber(row.total || 0)} evals / follow-up ${fmtNumber(row.followUpCreated || 0)}/${fmtNumber(row.followUpNeeded || 0)}</small>
        </article>
      `).join("")}
    </div>
  `;
}

function renderSlaReassessmentHistory() {
  if (!els.slaReassessmentHistorySummary || !els.slaReassessmentHistoryList) return;
  const report = state.masterDb.slaReassessmentHistory;
  if (!report) {
    els.slaReassessmentHistorySummary.innerHTML = `<span>SLA 사후 평가 히스토리를 불러오는 중입니다.</span>`;
    els.slaReassessmentHistoryList.innerHTML = `<div class="empty">SLA 사후 평가 히스토리를 불러오는 중입니다.</div>`;
    return;
  }
  const summary = report.summary || {};
  const aggregates = report.aggregates || {};
  els.slaReassessmentHistorySummary.innerHTML = `
    <span><strong>${fmtNumber(summary.total || 0)}</strong><em>History</em></span>
    <span><strong>${fmtNumber(summary.improved || 0)}</strong><em>Improved</em></span>
    <span><strong>${fmtNumber(summary.worse || 0)}</strong><em>Worse</em></span>
    <span><strong>${fmtNumber(summary.recurrence || 0)}</strong><em>Recurrence</em></span>
    <span><strong>${fmtNumber(summary.followUpCreated || 0)}</strong><em>Follow-up made</em></span>
    <span><strong>${fmtNumber(summary.averageEffectScore || 0)}</strong><em>Avg score</em></span>
  `;
  const items = report.items || [];
  els.slaReassessmentHistoryList.innerHTML = `
    <div class="sla-history-aggregates">
      <section>
        <strong>Effective action types</strong>
        ${renderSlaHistoryGroupRows(aggregates.effectiveActionTypes || [], "No effective action type yet.")}
      </section>
      <section>
        <strong>Weak action types</strong>
        ${renderSlaHistoryGroupRows(aggregates.weakActionTypes || [], "No weak action type yet.")}
      </section>
      <section>
        <strong>Assignee summary</strong>
        ${renderSlaHistoryGroupRows(aggregates.byAssignee || [], "No assignee history yet.")}
      </section>
    </div>
    <div class="sla-history-items">
      ${items.length ? items.slice(0, 12).map((item) => `
        <article class="sla-history-item ${escapeHtml(item.evaluationState || "unchanged")}">
          <div>
            <strong>${escapeHtml(item.sourceLabel || item.actionId || "SLA action")}</strong>
            <span>
              ${calibrationAuditQueueBadge(item.evaluationState || "unchanged", item.evaluationState === "improved" ? "good" : item.evaluationState === "worse" ? "danger" : "warning")}
              ${calibrationAuditQueueBadge(`score ${fmtNumber(item.effectScore || 0)}`, item.effectScore >= 70 ? "good" : item.effectScore < 45 ? "danger" : "warning")}
              ${calibrationAuditQueueBadge(item.followUpCreated ? "follow-up created" : item.followUpNeeded ? "follow-up needed" : "no follow-up", item.followUpCreated ? "good" : item.followUpNeeded ? "warning" : "neutral")}
            </span>
          </div>
          <p>${escapeHtml(item.issueKey || item.rootMetric || "unknown")} / ${escapeHtml(item.followUpReason || "No reassessment note.")}</p>
          <small>${escapeHtml(item.evaluatedAt || "-")} / ${escapeHtml(item.assignee || item.owner || "unassigned")} / recurrence ${item.recurrence ? "yes" : "no"}</small>
        </article>
      `).join("") : `<div class="empty">No SLA reassessment history rows match the current filters.</div>`}
    </div>
  `;
}

function renderSlaRecommendationAdjustmentImpact(item = {}) {
  const impact = item.impactComparison || {};
  const afterPriority = item.status === "approved" && item.activePriority ? item.activePriority : item.proposedPriority;
  const policy = item.autoApprovalPolicy || {};
  const policyText = policy.riskLevel
    ? `auto risk ${policy.riskLevel} / ${policy.eligible ? "eligible" : "manual"}`
    : "auto policy not evaluated";
  const workflowText = item.manualApprovalRequired
    ? item.status === "approved"
      ? "admin approved active"
      : item.status === "rejected"
        ? "admin rejected inactive"
        : "admin approval required"
    : item.status === "approved" && item.approvalMode === "auto"
      ? "low-risk auto approved"
      : item.status || "proposed";
  return `
    <div class="sla-recommendation-adjustment-impact">
      <span><strong>Workflow</strong><em>${escapeHtml(workflowText)}</em></span>
      <span><strong>Priority</strong><em>${escapeHtml(impact.priorityBefore || item.originalPriority || "-")} -> ${escapeHtml(afterPriority || impact.priorityAfterApproval || "-")}</em></span>
      <span><strong>Effect</strong><em>score ${fmtNumber(impact.historyEffectScore ?? item.historyEffectScore ?? 0)} / samples ${fmtNumber(impact.sampleSize ?? item.sampleSize ?? 0)}</em></span>
      <span><strong>Rates</strong><em>improved ${fmtPercent(impact.improvementRate ?? item.improvementRate ?? 0)} / worse ${fmtPercent(impact.worseRate ?? item.worseRate ?? 0)} / recurrence ${fmtPercent(impact.recurrenceRate ?? item.recurrenceRate ?? 0)}</em></span>
      <span><strong>Auto approval</strong><em>${escapeHtml(policyText)}</em></span>
    </div>
    <div class="sla-recommendation-adjustment-copy">
      <span><strong>Before</strong><em>${escapeHtml(impact.recommendationBefore || item.recommendationBefore || "No previous recommendation text.")}</em></span>
      <span><strong>After</strong><em>${escapeHtml(impact.recommendationAfter || item.recommendationAfter || "No proposed recommendation text.")}</em></span>
    </div>
  `;
}

function renderSlaRecommendationAdjustmentDecisionHistory(history = []) {
  if (!history.length) return "";
  return `
    <div class="sla-recommendation-adjustment-copy">
      ${history.slice(0, 3).map((item) => `
        <span>
          <strong>${escapeHtml(item.decision || item.status || "decision")}</strong>
          <em>${escapeHtml(item.decidedAt || item.reviewedAt || "-")} / ${escapeHtml(item.decidedBy || item.reviewedBy || "-")} / ${escapeHtml(item.reviewReason || item.reason || "No review note.")}</em>
        </span>
      `).join("")}
    </div>
  `;
}

function renderSlaRecommendationAutoPolicy(policy = {}) {
  if (!els.slaRecommendationAdjustmentPolicy) return;
  if (!policy || !policy.policyVersion) {
    els.slaRecommendationAdjustmentPolicy.innerHTML = "";
    return;
  }
  els.slaRecommendationAdjustmentPolicy.innerHTML = `
    <span><strong>${escapeHtml(policy.policyVersion || "-")}</strong><em>Policy</em></span>
    <span><strong>${fmtNumber(policy.minSampleSize || 0)}</strong><em>Min samples</em></span>
    <span><strong>${fmtNumber(policy.minHistoricalApprovalSuccessRate || 0)}%</strong><em>Past approval</em></span>
    <span><strong>${fmtNumber(policy.maxPriorityStepChange || 0)}</strong><em>Max priority step</em></span>
    <span><strong>${fmtNumber(policy.boost?.minEffectScore || 0)} / ${fmtNumber(policy.boost?.maxRecurrenceRate || 0)}%</strong><em>Boost score / recurrence</em></span>
    <span><strong>${fmtNumber(policy.downgrade?.maxEffectScore || 0)} / ${fmtNumber(policy.downgrade?.minRecurrenceRate || 0)}%</strong><em>Downgrade score / recurrence</em></span>
  `;
}

function renderSlaQualityRereviewActionRecommendationAutoPolicy(policy = {}) {
  if (!els.slaQualityRereviewActionRecommendationAdjustmentPolicy) return;
  if (!policy || !policy.policyVersion) {
    els.slaQualityRereviewActionRecommendationAdjustmentPolicy.innerHTML = "";
    return;
  }
  els.slaQualityRereviewActionRecommendationAdjustmentPolicy.innerHTML = `
    <span><strong>${escapeHtml(policy.policyVersion || "-")}</strong><em>Auto policy</em></span>
    <span><strong>${fmtNumber(policy.minSampleSize || 0)}</strong><em>Min samples</em></span>
    <span><strong>${fmtNumber(policy.minHistoricalApprovalSuccessRate || 0)}%</strong><em>Past approval</em></span>
    <span><strong>${fmtNumber(policy.maxPriorityStepChange || 0)}</strong><em>Max priority step</em></span>
    <span><strong>${fmtNumber(policy.boost?.minEffectScore || 0)} / ${fmtNumber(policy.boost?.maxRecurrenceRate || 0)}%</strong><em>Boost score / recurrence</em></span>
    <span><strong>${fmtNumber(policy.downgrade?.maxEffectScore || 0)} / ${fmtNumber(policy.downgrade?.minRecurrenceRate || 0)}%</strong><em>Downgrade score / recurrence</em></span>
  `;
}

function renderSlaRecommendationAdjustmentReview(item = {}) {
  if (item.status === "proposed") {
    return `
      <div class="sla-recommendation-adjustment-review">
        <label class="field wide">
          <span>Review note</span>
          <textarea data-sla-recommendation-adjustment-review-note rows="2" placeholder="approval or rejection reason"></textarea>
        </label>
        <div>
          <button class="secondary-button" type="button" data-sla-recommendation-adjustment-decision="approved" data-sla-recommendation-adjustment-id="${escapeHtml(item.adjustmentId || "")}">Approve</button>
          <button class="ghost-button" type="button" data-sla-recommendation-adjustment-decision="rejected" data-sla-recommendation-adjustment-id="${escapeHtml(item.adjustmentId || "")}">Reject</button>
        </div>
      </div>
    `;
  }
  const rollbackButton = item.status === "approved" && item.approvalMode === "auto" && item.rollbackAvailable
    ? `
      <div class="sla-recommendation-adjustment-review">
        <label class="field wide">
          <span>Rollback note</span>
          <textarea data-sla-recommendation-adjustment-rollback-note rows="2" placeholder="rollback reason"></textarea>
        </label>
        <div>
          <button class="ghost-button" type="button" data-sla-recommendation-adjustment-rollback="${escapeHtml(item.adjustmentId || "")}">Rollback auto approval</button>
        </div>
      </div>
    `
    : "";
  return `
    <small class="sla-recommendation-adjustment-review-log">
      ${escapeHtml(item.approvalMode === "auto" ? `auto ${item.status || "reviewed"}` : item.status || "reviewed")} by ${escapeHtml(item.reviewedBy || item.updatedBy || "-")} at ${escapeHtml(item.reviewedAt || item.updatedAt || "-")}
      ${item.reviewReason ? ` / ${escapeHtml(item.reviewReason)}` : ""}
      ${item.rolledBackAt ? ` / rolled back ${escapeHtml(item.rolledBackAt)} by ${escapeHtml(item.rolledBackBy || "-")}` : ""}
    </small>
    ${rollbackButton}
  `;
}

function renderSlaRecommendationAdjustmentCard(item = {}) {
  const tone = slaRecommendationAdjustmentTone(item);
  const priorityAfter = item.status === "approved" && item.activePriority ? item.activePriority : item.proposedPriority;
  return `
    <article class="sla-recommendation-adjustment ${escapeHtml(tone)}" data-sla-recommendation-adjustment-card="${escapeHtml(item.adjustmentId || "")}">
      <div class="sla-recommendation-adjustment-head">
        <div>
          <strong>${escapeHtml(item.sourceLabel || item.sourceKey || "SLA recommendation")}</strong>
          <span>
            ${calibrationAuditQueueBadge(item.status || "proposed", tone)}
            ${calibrationAuditQueueBadge(item.approvalMode === "auto" ? "auto" : item.status === "proposed" ? "manual review" : "manual", item.approvalMode === "auto" ? "good" : item.status === "proposed" ? "warning" : "neutral")}
            ${calibrationAuditQueueBadge(item.direction || "neutral", tone)}
            ${calibrationAuditQueueBadge(`${item.originalPriority || "-"} -> ${priorityAfter || "-"}`, tone)}
            ${calibrationAuditQueueBadge(item.owner || "unassigned", "neutral")}
          </span>
        </div>
        <small>${escapeHtml(item.month || "-")} / ${escapeHtml(item.issueKey || item.rootMetric || "-")}</small>
      </div>
      <p>${escapeHtml(item.reason || "No adjustment reason.")}</p>
      ${renderSlaRecommendationAdjustmentImpact(item)}
      <small class="sla-recommendation-adjustment-meta">
        proposed ${escapeHtml(item.proposedAt || "-")} by ${escapeHtml(item.proposedBy || "system")}
        ${item.status === "approved" ? ` / active priority ${escapeHtml(item.activePriority || item.proposedPriority || "-")}` : ""}
      </small>
      ${renderSlaRecommendationAdjustmentReview(item)}
    </article>
  `;
}

function renderSlaRecommendationAdjustments() {
  if (!els.slaRecommendationAdjustmentSummary || !els.slaRecommendationAdjustmentList) return;
  const report = state.masterDb.slaRecommendationAdjustments;
  if (!report) {
    els.slaRecommendationAdjustmentSummary.innerHTML = `<span>SLA 추천 보정안을 불러오는 중입니다.</span>`;
    if (els.slaRecommendationAdjustmentPolicy) els.slaRecommendationAdjustmentPolicy.innerHTML = "";
    els.slaRecommendationAdjustmentList.innerHTML = `<div class="empty">SLA 추천 보정안을 불러오는 중입니다.</div>`;
    return;
  }
  const summary = report.summary || {};
  renderSlaRecommendationAutoPolicy(report.autoApprovalPolicy || {});
  els.slaRecommendationAdjustmentSummary.innerHTML = `
    <span><strong>${fmtNumber(summary.total || 0)}</strong><em>Filtered</em></span>
    <span><strong>${fmtNumber(summary.manualRequired || summary.proposed || 0)}</strong><em>Manual review</em></span>
    <span><strong>${fmtNumber(summary.autoApproved || 0)}</strong><em>Auto approved</em></span>
    <span><strong>${fmtNumber(summary.approved || 0)}</strong><em>Approved</em></span>
    <span><strong>${fmtNumber(summary.rejected || 0)}</strong><em>Rejected</em></span>
    <span><strong>${fmtNumber(summary.rollbackAvailable || 0)}</strong><em>Rollback ready</em></span>
    <span><strong>${fmtNumber(summary.boost || 0)} / ${fmtNumber(summary.downgrade || 0)}</strong><em>Boost / down</em></span>
    <span><strong>${fmtNumber(summary.averageEffectScore || 0)}</strong><em>Avg score</em></span>
  `;
  const items = report.items || [];
  const manualItems = items.filter((item) => item.status === "proposed");
  const autoItems = items.filter((item) => item.status === "approved" && item.approvalMode === "auto");
  const reviewedItems = items.filter((item) => !(item.status === "proposed") && !(item.status === "approved" && item.approvalMode === "auto"));
  els.slaRecommendationAdjustmentList.innerHTML = items.length ? `
    <section class="sla-recommendation-adjustment-section">
      <strong>Manual review required</strong>
      ${manualItems.length ? manualItems.map(renderSlaRecommendationAdjustmentCard).join("") : `<div class="empty">현재 필터에 맞는 수동 검수 보정안이 없습니다.</div>`}
    </section>
    <section class="sla-recommendation-adjustment-section">
      <strong>Auto-approved history</strong>
      ${autoItems.length ? autoItems.map(renderSlaRecommendationAdjustmentCard).join("") : `<div class="empty">현재 필터에 맞는 자동승인 이력이 없습니다.</div>`}
    </section>
    <section class="sla-recommendation-adjustment-section">
      <strong>Manual decisions and rollbacks</strong>
      ${reviewedItems.length ? reviewedItems.map(renderSlaRecommendationAdjustmentCard).join("") : `<div class="empty">현재 필터에 맞는 승인/반려 또는 rollback 이력이 없습니다.</div>`}
    </section>
  ` : `<div class="empty">현재 필터에 맞는 SLA 추천 보정안이 없습니다.</div>`;
}

function renderSlaQualityRereviewActionRecommendationAdjustmentReview(item = {}) {
  if (item.status === "proposed") {
    return `
      <div class="sla-recommendation-adjustment-review">
        <label class="field wide">
          <span>Review note</span>
          <textarea data-sla-quality-rereview-action-recommendation-adjustment-review-note rows="2" placeholder="approval or rejection reason"></textarea>
        </label>
        <div>
          <button class="secondary-button" type="button" data-sla-quality-rereview-action-recommendation-adjustment-decision="approved" data-sla-quality-rereview-action-recommendation-adjustment-id="${escapeHtml(item.adjustmentId || "")}">Approve</button>
          <button class="ghost-button" type="button" data-sla-quality-rereview-action-recommendation-adjustment-decision="rejected" data-sla-quality-rereview-action-recommendation-adjustment-id="${escapeHtml(item.adjustmentId || "")}">Reject</button>
        </div>
      </div>
    `;
  }
  return `
    <small class="sla-recommendation-adjustment-review-log">
      ${escapeHtml(item.approvalMode === "auto" ? `auto ${item.status || "reviewed"}` : item.status || "reviewed")} by ${escapeHtml(item.reviewedBy || item.updatedBy || "-")} at ${escapeHtml(item.reviewedAt || item.updatedAt || "-")}
      ${item.reviewReason ? ` / ${escapeHtml(item.reviewReason)}` : ""}
      ${item.rollbackAvailable ? " / rollback ready" : ""}
    </small>
  `;
}

function renderSlaQualityRereviewActionRecommendationAdjustmentCard(item = {}) {
  const tone = slaRecommendationAdjustmentTone(item);
  const priorityAfter = item.status === "approved" && item.activePriority ? item.activePriority : item.proposedPriority;
  return `
    <article class="sla-recommendation-adjustment ${escapeHtml(tone)}" data-sla-quality-rereview-action-recommendation-adjustment-card="${escapeHtml(item.adjustmentId || "")}">
      <div class="sla-recommendation-adjustment-head">
        <div>
          <strong>${escapeHtml(item.sourceLabel || item.sourceKey || "Re-review action recommendation")}</strong>
          <span>
            ${calibrationAuditQueueBadge(item.status || "proposed", tone)}
            ${calibrationAuditQueueBadge(item.approvalMode === "auto" ? "auto approved" : item.status === "proposed" ? "manual review" : "manual", item.approvalMode === "auto" ? "good" : item.status === "proposed" ? "warning" : "neutral")}
            ${item.manualApprovalRequired ? calibrationAuditQueueBadge("approval required", "warning") : ""}
            ${item.status === "approved" && item.approvalMode === "auto" ? calibrationAuditQueueBadge("low risk", "good") : ""}
            ${item.rollbackAvailable ? calibrationAuditQueueBadge("rollback ready", "warning") : ""}
            ${calibrationAuditQueueBadge(item.direction || "neutral", tone)}
            ${calibrationAuditQueueBadge(`${item.originalPriority || "-"} -> ${priorityAfter || "-"}`, tone)}
            ${calibrationAuditQueueBadge(item.owner || "unassigned", "neutral")}
          </span>
        </div>
        <small>${escapeHtml(item.month || "-")} / ${escapeHtml(item.issueKey || item.rootMetric || "-")}</small>
      </div>
      <p>${escapeHtml(item.reason || "No adjustment reason.")}</p>
      ${renderSlaRecommendationAdjustmentImpact(item)}
      ${renderSlaRecommendationAdjustmentDecisionHistory(item.decisionHistory || [])}
      <small class="sla-recommendation-adjustment-meta">
        proposed ${escapeHtml(item.proposedAt || "-")} by ${escapeHtml(item.proposedBy || "system")}
        ${item.status === "approved" ? ` / active priority ${escapeHtml(item.activePriority || item.proposedPriority || "-")}` : ""}
      </small>
      ${renderSlaQualityRereviewActionRecommendationAdjustmentReview(item)}
    </article>
  `;
}

function renderSlaQualityRereviewActionRecommendationAdjustments() {
  if (!els.slaQualityRereviewActionRecommendationAdjustmentSummary || !els.slaQualityRereviewActionRecommendationAdjustmentList) return;
  const report = state.masterDb.slaQualityRereviewActionRecommendationAdjustments;
  if (!report) {
    els.slaQualityRereviewActionRecommendationAdjustmentSummary.innerHTML = `<span>재검수 액션 추천 보정안을 불러오는 중입니다.</span>`;
    if (els.slaQualityRereviewActionRecommendationAdjustmentPolicy) els.slaQualityRereviewActionRecommendationAdjustmentPolicy.innerHTML = "";
    els.slaQualityRereviewActionRecommendationAdjustmentList.innerHTML = `<div class="empty">재검수 액션 추천 보정안을 불러오는 중입니다.</div>`;
    return;
  }
  const summary = report.summary || {};
  renderSlaQualityRereviewActionRecommendationAutoPolicy(report.autoApprovalPolicy || {});
  els.slaQualityRereviewActionRecommendationAdjustmentSummary.innerHTML = `
    <span><strong>${fmtNumber(summary.total || 0)}</strong><em>Filtered</em></span>
    <span><strong>${fmtNumber(summary.manualRequired || summary.proposed || 0)}</strong><em>Manual review</em></span>
    <span><strong>${fmtNumber(summary.autoApproved || 0)}</strong><em>Auto approved</em></span>
    <span><strong>${fmtNumber(summary.approved || 0)}</strong><em>Approved</em></span>
    <span><strong>${fmtNumber(summary.rejected || 0)}</strong><em>Rejected</em></span>
    <span><strong>${fmtNumber(summary.rollbackAvailable || 0)}</strong><em>Rollback ready</em></span>
    <span><strong>${fmtNumber(summary.boost || 0)} / ${fmtNumber(summary.downgrade || 0)}</strong><em>Boost / down</em></span>
    <span><strong>${fmtNumber(summary.averageEffectScore || 0)}</strong><em>Avg score</em></span>
    <span><strong>${fmtNumber(summary.averageRecurrenceRate || 0)}%</strong><em>Avg recurrence</em></span>
  `;
  const items = report.items || [];
  const proposedItems = items.filter((item) => item.status === "proposed");
  const autoItems = items.filter((item) => item.status === "approved" && item.approvalMode === "auto");
  const reviewedItems = items.filter((item) => item.status !== "proposed" && !(item.status === "approved" && item.approvalMode === "auto"));
  els.slaQualityRereviewActionRecommendationAdjustmentList.innerHTML = items.length ? `
    <section class="sla-recommendation-adjustment-section">
      <strong>Manual review required</strong>
      ${proposedItems.length ? proposedItems.map(renderSlaQualityRereviewActionRecommendationAdjustmentCard).join("") : `<div class="empty">현재 필터에 맞는 재검수 액션 제안 보정안이 없습니다.</div>`}
    </section>
    <section class="sla-recommendation-adjustment-section">
      <strong>Auto-approved history</strong>
      ${autoItems.length ? autoItems.map(renderSlaQualityRereviewActionRecommendationAdjustmentCard).join("") : `<div class="empty">현재 필터에 맞는 재검수 액션 자동승인 이력이 없습니다.</div>`}
    </section>
    <section class="sla-recommendation-adjustment-section">
      <strong>Manual decisions</strong>
      ${reviewedItems.length ? reviewedItems.map(renderSlaQualityRereviewActionRecommendationAdjustmentCard).join("") : `<div class="empty">현재 필터에 맞는 재검수 액션 수동 결정 이력이 없습니다.</div>`}
    </section>
  ` : `<div class="empty">현재 필터에 맞는 재검수 액션 추천 보정안이 없습니다.</div>`;
}

function slaAutoApprovalPerformanceTone(item = {}) {
  const outcome = item.outcome?.outcome || item.outcome || "";
  if (outcome === "successful") return "good";
  if (outcome === "false_positive" || outcome === "rolled_back") return "danger";
  if (outcome === "mixed" || outcome === "pending") return "warning";
  return "neutral";
}

function renderSlaAutoApprovalAggregateRows(rows = [], emptyText = "No aggregate rows yet.") {
  if (!rows.length) return `<div class="empty">${escapeHtml(emptyText)}</div>`;
  return `
    <div class="sla-auto-approval-table">
      <table>
        <thead>
          <tr><th>Segment</th><th>Total</th><th>Evaluated</th><th>Success</th><th>Rollback</th><th>Recurrence</th><th>False positive</th><th>Avg score</th></tr>
        </thead>
        <tbody>
          ${rows.slice(0, 8).map((row) => `
            <tr>
              <td>${escapeHtml(row.label || row.key || "-")}</td>
              <td>${fmtNumber(row.total || 0)}</td>
              <td>${fmtNumber(row.evaluated || 0)}</td>
              <td>${fmtPercent(row.successRate || 0)}</td>
              <td>${fmtPercent(row.rollbackRate || 0)}</td>
              <td>${fmtPercent(row.recurrenceRate || 0)}</td>
              <td>${fmtPercent(row.falsePositiveRate || 0)}</td>
              <td>${fmtNumber(row.avgEffectScore || 0)}</td>
            </tr>
          `).join("")}
        </tbody>
      </table>
    </div>
  `;
}

function renderSlaAutoApprovalPolicyCandidates(candidates = []) {
  return `
    <section>
      <strong>Policy adjustment candidates</strong>
      ${candidates.length ? candidates.slice(0, 8).map((item) => `
        <article class="sla-auto-approval-candidate ${escapeHtml(item.priority === "high" ? "danger" : item.priority === "medium" ? "warning" : "good")}">
          <div>
            <strong>${escapeHtml(item.target || item.type || "candidate")}</strong>
            <span>
              ${calibrationAuditQueueBadge(item.priority || "medium", item.priority === "high" ? "danger" : item.priority === "medium" ? "warning" : "good")}
              ${calibrationAuditQueueBadge(item.type || "policy", "neutral")}
            </span>
          </div>
          <p>${escapeHtml(item.basis || "")}</p>
          <small>${escapeHtml(item.recommendation || "")}</small>
        </article>
      `).join("") : `<div class="empty">No policy adjustment candidate yet.</div>`}
    </section>
  `;
}

function renderSlaAutoApprovalPerformanceItems(items = []) {
  if (!items.length) return `<div class="empty">현재 필터에 맞는 자동승인 성과 이력이 없습니다.</div>`;
  return `
    <section>
      <strong>Recent auto approvals</strong>
      ${items.slice(0, 12).map((item) => {
        const tone = slaAutoApprovalPerformanceTone(item);
        const outcome = item.outcome || {};
        return `
          <article class="sla-auto-approval-row ${escapeHtml(tone)}">
            <div>
              <strong>${escapeHtml(item.sourceLabel || item.sourceKey || "Auto approval")}</strong>
              <span>
                ${calibrationAuditQueueBadge(outcome.outcome || "pending", tone)}
                ${calibrationAuditQueueBadge(item.issueKey || item.rootMetric || "issue", "neutral")}
                ${calibrationAuditQueueBadge(item.owner || "unassigned", "neutral")}
                ${calibrationAuditQueueBadge(`${item.originalPriority || "-"} -> ${item.activePriority || item.proposedPriority || "-"}`, tone)}
              </span>
            </div>
            <p>
              score ${fmtNumber(outcome.avgEffectScore || 0)} / evaluated ${fmtNumber(outcome.evaluatedCount || 0)}
              / success ${outcome.successful ? "yes" : "no"} / false positive ${outcome.falsePositive ? "yes" : "no"}
            </p>
            <small>
              approved ${escapeHtml(item.approvedAt || "-")} / rollback ${item.rolledBackAt ? escapeHtml(item.rolledBackAt) : "none"}
              / recurrence ${fmtPercent(outcome.recurrenceRate || 0)}
            </small>
          </article>
        `;
      }).join("")}
    </section>
  `;
}

function renderSlaAutoApprovalPerformance() {
  if (!els.slaAutoApprovalPerformanceSummary || !els.slaAutoApprovalPerformanceList) return;
  const report = state.masterDb.slaAutoApprovalPerformance;
  if (!report) {
    els.slaAutoApprovalPerformanceSummary.innerHTML = `<span>SLA 자동승인 성과를 불러오는 중입니다.</span>`;
    els.slaAutoApprovalPerformanceList.innerHTML = `<div class="empty">SLA 자동승인 성과를 불러오는 중입니다.</div>`;
    return;
  }
  const summary = report.summary || {};
  els.slaAutoApprovalPerformanceSummary.innerHTML = `
    <span><strong>${fmtNumber(summary.total || 0)}</strong><em>Auto approvals</em></span>
    <span><strong>${fmtNumber(summary.evaluated || 0)}</strong><em>Evaluated</em></span>
    <span><strong>${fmtPercent(summary.successRate || 0)}</strong><em>Success</em></span>
    <span><strong>${fmtPercent(summary.rollbackRate || 0)}</strong><em>Rollback</em></span>
    <span><strong>${fmtPercent(summary.recurrenceRate || 0)}</strong><em>Recurrence</em></span>
    <span><strong>${fmtPercent(summary.falsePositiveRate || 0)}</strong><em>False positive</em></span>
    <span><strong>${fmtNumber(summary.avgEffectScore || 0)}</strong><em>Avg score</em></span>
  `;
  const aggregates = report.aggregates || {};
  els.slaAutoApprovalPerformanceList.innerHTML = `
    <div class="sla-auto-approval-grid">
      ${renderSlaAutoApprovalPolicyCandidates(report.policyAdjustmentCandidates || [])}
      <section>
        <strong>By month</strong>
        ${renderSlaAutoApprovalAggregateRows(aggregates.byMonth || [], "No monthly auto-approval performance yet.")}
      </section>
      <section>
        <strong>By issue</strong>
        ${renderSlaAutoApprovalAggregateRows(aggregates.byIssue || [], "No issue auto-approval performance yet.")}
      </section>
      <section>
        <strong>By assignee</strong>
        ${renderSlaAutoApprovalAggregateRows(aggregates.byOwner || [], "No assignee auto-approval performance yet.")}
      </section>
      ${renderSlaAutoApprovalPerformanceItems(report.items || [])}
    </div>
  `;
}

function renderSlaQualityRereviewActionRecommendationAutoApprovalPerformance() {
  if (!els.slaQualityRereviewActionRecommendationAutoApprovalPerformanceSummary || !els.slaQualityRereviewActionRecommendationAutoApprovalPerformanceList) return;
  const report = state.masterDb.slaQualityRereviewActionRecommendationAutoApprovalPerformance;
  if (!report) {
    els.slaQualityRereviewActionRecommendationAutoApprovalPerformanceSummary.innerHTML = `<span>재검수 액션 자동승인 성과를 불러오는 중입니다.</span>`;
    els.slaQualityRereviewActionRecommendationAutoApprovalPerformanceList.innerHTML = `<div class="empty">재검수 액션 자동승인 성과를 불러오는 중입니다.</div>`;
    return;
  }
  const summary = report.summary || {};
  els.slaQualityRereviewActionRecommendationAutoApprovalPerformanceSummary.innerHTML = `
    <span><strong>${fmtNumber(summary.total || 0)}</strong><em>Auto approvals</em></span>
    <span><strong>${fmtNumber(summary.evaluated || 0)}</strong><em>Evaluated</em></span>
    <span><strong>${fmtPercent(summary.successRate || 0)}</strong><em>Success</em></span>
    <span><strong>${fmtPercent(summary.rollbackRate || 0)}</strong><em>Rollback</em></span>
    <span><strong>${fmtPercent(summary.recurrenceRate || 0)}</strong><em>Recurrence</em></span>
    <span><strong>${fmtPercent(summary.falsePositiveRate || 0)}</strong><em>False positive</em></span>
    <span><strong>${fmtNumber(summary.avgEffectScore || 0)}</strong><em>Avg score</em></span>
  `;
  const aggregates = report.aggregates || {};
  els.slaQualityRereviewActionRecommendationAutoApprovalPerformanceList.innerHTML = `
    <div class="sla-auto-approval-grid">
      ${renderSlaQualityRereviewActionAutoPolicyWorkflow(report.policyAdjustmentWorkflow || {})}
      ${renderSlaQualityRereviewActionAutoPolicyEffectiveness(report.policyEffectiveness || {})}
      <section>
        <strong>By month</strong>
        ${renderSlaAutoApprovalAggregateRows(aggregates.byMonth || [], "No monthly re-review auto-approval performance yet.")}
      </section>
      <section>
        <strong>By root metric</strong>
        ${renderSlaAutoApprovalAggregateRows(aggregates.byIssue || [], "No root-metric re-review auto-approval performance yet.")}
      </section>
      <section>
        <strong>By assignee</strong>
        ${renderSlaAutoApprovalAggregateRows(aggregates.byOwner || [], "No assignee re-review auto-approval performance yet.")}
      </section>
      ${renderSlaAutoApprovalPerformanceItems(report.items || [])}
    </div>
  `;
}

function slaAutoPolicyAdjustmentTone(item = {}) {
  if (item.status === "approved") return "good";
  if (item.status === "rejected") return "neutral";
  if (item.priority === "urgent" || item.priority === "high") return "danger";
  if (item.priority === "medium") return "warning";
  return "good";
}

function slaPolicyQualityCalibrationTone(calibration = {}) {
  if (calibration.direction === "boost") return "good";
  if (calibration.direction === "downgrade") return "warning";
  if (calibration.previousQuality?.total) return "neutral";
  return "muted";
}

function slaPolicyQualityCalibrationSummary(calibration = {}) {
  const previous = calibration.previousQuality || {};
  if (!calibration.reason && !previous.total) return "";
  const suggestedAfter = calibration.suggestedPriorityAfter || calibration.suggestedCalibration?.priorityAfter || calibration.priorityAfter || "-";
  const activeAfter = calibration.active ? calibration.priorityAfter || suggestedAfter : `${calibration.priorityAfter || calibration.priorityBefore || "-"} pending ${suggestedAfter}`;
  return [
    `${calibration.direction || "neutral"} ${calibration.priorityBefore || "-"} -> ${activeAfter}`,
    `approval ${fmtPercent(previous.approvalRate || 0)}`,
    `success ${fmtPercent(previous.approvalSuccessRate || 0)}`,
    `repeat ${fmtPercent(previous.repeatRecommendationRate || 0)}`,
    `rejection ${fmtPercent(previous.rejectionRate || 0)}`,
    `history ${fmtNumber(previous.total || 0)}`
  ].concat(previous.topRejectionReason ? [`top rejection: ${previous.topRejectionReason}`] : []).join(" / ");
}

function renderSlaPolicyQualityCalibration(calibration = {}) {
  const previous = calibration.previousQuality || {};
  const summary = slaPolicyQualityCalibrationSummary(calibration);
  if (!summary) return "";
  return `
    <span><strong>Quality calibration</strong><em>${escapeHtml(calibration.reason || summary)}</em></span>
    <span><strong>Previous quality</strong><em>${escapeHtml(summary)}</em></span>
  `;
}

function renderSlaAutoPolicyValue(label, beforeValue, afterValue, suffix = "") {
  const changed = String(beforeValue ?? "") !== String(afterValue ?? "");
  return `
    <span class="${changed ? "changed" : ""}">
      <strong>${escapeHtml(label)}</strong>
      <em>${escapeHtml(beforeValue ?? "-")}${suffix} -> ${escapeHtml(afterValue ?? "-")}${suffix}</em>
    </span>
  `;
}

function renderSlaAutoPolicyReview(item = {}) {
  if (item.status === "proposed") {
    return `
      <div class="sla-recommendation-adjustment-review">
        <label class="field wide">
          <span>Review note</span>
          <textarea data-sla-auto-policy-adjustment-review-note rows="2" placeholder="approval or rejection reason"></textarea>
        </label>
        <div>
          <button class="secondary-button" type="button" data-sla-auto-policy-adjustment-decision="approved" data-sla-auto-policy-adjustment-id="${escapeHtml(item.policyAdjustmentId || "")}">Approve</button>
          <button class="ghost-button" type="button" data-sla-auto-policy-adjustment-decision="rejected" data-sla-auto-policy-adjustment-id="${escapeHtml(item.policyAdjustmentId || "")}">Reject</button>
        </div>
      </div>
    `;
  }
  return `
    <small class="sla-recommendation-adjustment-review-log">
      ${escapeHtml(item.status || "reviewed")} by ${escapeHtml(item.reviewedBy || item.updatedBy || "-")} at ${escapeHtml(item.reviewedAt || item.updatedAt || "-")}
      ${item.reviewReason ? ` / ${escapeHtml(item.reviewReason)}` : ""}
    </small>
  `;
}

function renderSlaAutoPolicyAdjustmentCard(item = {}) {
  const tone = slaAutoPolicyAdjustmentTone(item);
  const before = item.beforePolicy || {};
  const after = item.afterPolicy || {};
  const impact = item.expectedImpact || {};
  const source = item.sourceContext || {};
  const generatedFromEffect = source.source === "sla_policy_effectiveness";
  const qualityCalibration = item.qualityCalibration || source.qualityCalibration || {};
  return `
    <article class="sla-auto-policy-adjustment ${escapeHtml(tone)}" data-sla-auto-policy-adjustment-card="${escapeHtml(item.policyAdjustmentId || "")}">
      <div class="sla-recommendation-adjustment-head">
        <div>
          <strong>${escapeHtml(item.target || item.issueKey || item.candidateType || "Policy adjustment")}</strong>
          <span>
            ${calibrationAuditQueueBadge(item.status || "proposed", item.status === "approved" ? "good" : item.status === "rejected" ? "muted" : tone)}
            ${calibrationAuditQueueBadge(item.priority || "medium", tone)}
            ${calibrationAuditQueueBadge(item.candidateType || "policy", "neutral")}
            ${generatedFromEffect ? calibrationAuditQueueBadge("effect based", "warning") : ""}
            ${item.sourceEffectOutcome ? calibrationAuditQueueBadge(item.sourceEffectOutcome, item.sourceEffectOutcome === "worse" ? "danger" : item.sourceEffectOutcome === "improved" ? "good" : "warning") : ""}
            ${slaPolicyQualityCalibrationSummary(qualityCalibration) ? calibrationAuditQueueBadge(`quality ${qualityCalibration.direction || "neutral"}`, slaPolicyQualityCalibrationTone(qualityCalibration)) : ""}
            ${item.duplicateStatus ? calibrationAuditQueueBadge(item.duplicateStatus, item.duplicateStatus === "created" ? "good" : "warning") : ""}
          </span>
        </div>
        <small>${escapeHtml(item.policyAdjustmentId || "")}</small>
      </div>
      <p>${escapeHtml(item.basis || "")}</p>
      <div class="sla-auto-policy-impact">
        ${renderSlaAutoPolicyValue("Enabled", before.issueAutoApprovalEnabled ? "yes" : "no", after.issueAutoApprovalEnabled ? "yes" : "no")}
        ${renderSlaAutoPolicyValue("Min samples", before.minSampleSize, after.minSampleSize)}
        ${renderSlaAutoPolicyValue("Past approval", before.minHistoricalApprovalSuccessRate, after.minHistoricalApprovalSuccessRate, "%")}
        ${renderSlaAutoPolicyValue("Priority step", before.maxPriorityStepChange, after.maxPriorityStepChange)}
        <span class="${Number(impact.expectedSuccessRateChange || 0) ? "changed" : ""}">
          <strong>Expected success</strong>
          <em>${fmtPercent(impact.currentSuccessRate || 0)} -> ${fmtPercent(impact.expectedSuccessRate || 0)} (${Number(impact.expectedSuccessRateChange || 0) >= 0 ? "+" : ""}${fmtNumber(impact.expectedSuccessRateChange || 0)}p)</em>
        </span>
        <span>
          <strong>Impact scope</strong>
          <em>${escapeHtml(impact.scope || "issue_policy")} / evaluated ${fmtNumber(impact.evaluated || 0)}</em>
        </span>
      </div>
      <div class="sla-recommendation-adjustment-copy">
        <span><strong>Recommendation</strong><em>${escapeHtml(item.recommendation || "No recommendation text.")}</em></span>
        <span><strong>Patch</strong><em>${escapeHtml(JSON.stringify(item.policyPatch || {}))}</em></span>
        ${generatedFromEffect ? `<span><strong>Generated from</strong><em>${escapeHtml(source.policyAdjustmentId || item.sourcePolicyAdjustmentId || "-")} / ${escapeHtml(source.suggestionType || "-")} / score ${escapeHtml(item.sourceEffectScore ?? source.effectScore ?? "-")}</em></span>` : ""}
        ${renderSlaPolicyQualityCalibration(qualityCalibration)}
        ${item.duplicateStatus ? `<span><strong>Duplicate status</strong><em>${escapeHtml(item.duplicateStatus || "-")}${item.duplicateOfPolicyAdjustmentId ? ` / ${escapeHtml(item.duplicateOfPolicyAdjustmentId)}` : ""}</em></span>` : ""}
      </div>
      ${renderSlaAutoPolicyReview(item)}
    </article>
  `;
}

function renderSlaAutoPolicyAdjustments() {
  if (!els.slaAutoPolicyAdjustmentsSummary || !els.slaAutoPolicyAdjustmentsList) return;
  const report = state.masterDb.slaAutoPolicyAdjustments;
  if (!report) {
    els.slaAutoPolicyAdjustmentsSummary.innerHTML = `<span>Loading SLA auto-approval policy proposals.</span>`;
    els.slaAutoPolicyAdjustmentsList.innerHTML = `<div class="empty">SLA auto-approval policy proposals are loading.</div>`;
    return;
  }
  const summary = report.summary || {};
  const activePolicy = report.activePolicy || {};
  els.slaAutoPolicyAdjustmentsSummary.innerHTML = `
    <span><strong>${fmtNumber(summary.total || 0)}</strong><em>Filtered</em></span>
    <span><strong>${fmtNumber(summary.proposed || 0)}</strong><em>Proposed</em></span>
    <span><strong>${fmtNumber(summary.approved || 0)}</strong><em>Approved</em></span>
    <span><strong>${fmtNumber(summary.rejected || 0)}</strong><em>Rejected</em></span>
    <span><strong>${fmtNumber(summary.high || 0)} / ${fmtNumber(summary.medium || 0)}</strong><em>High / medium</em></span>
    <span><strong>${fmtNumber(summary.expectedSuccessRateChangeAvg || 0)}p</strong><em>Avg impact</em></span>
    <span><strong>${escapeHtml(activePolicy.policyVersion || "-")}</strong><em>Active policy</em></span>
    <span><strong>${fmtNumber(activePolicy.activeAdjustmentIds?.length || 0)}</strong><em>Applied patches</em></span>
  `;
  const items = report.items || [];
  const proposed = items.filter((item) => item.status === "proposed");
  const history = items.filter((item) => item.status !== "proposed");
  els.slaAutoPolicyAdjustmentsList.innerHTML = items.length ? `
    <section class="sla-recommendation-adjustment-section">
      <strong>Review queue</strong>
      ${proposed.length ? proposed.map(renderSlaAutoPolicyAdjustmentCard).join("") : `<div class="empty">No proposed policy adjustments match the current filters.</div>`}
    </section>
    <section class="sla-recommendation-adjustment-section">
      <strong>Approval history</strong>
      ${history.length ? history.map(renderSlaAutoPolicyAdjustmentCard).join("") : `<div class="empty">No approved or rejected policy adjustments match the current filters.</div>`}
    </section>
  ` : `<div class="empty">No SLA auto-approval policy proposals match the current filters.</div>`;
}

function renderSlaQualityRereviewActionAutoPolicyReview(item = {}) {
  if (item.status === "proposed") {
    return `
      <div class="sla-recommendation-adjustment-review">
        <label class="field wide">
          <span>Review note</span>
          <textarea data-sla-quality-rereview-action-auto-policy-adjustment-review-note rows="2" placeholder="approval or rejection reason"></textarea>
        </label>
        <div>
          <button class="secondary-button" type="button" data-sla-quality-rereview-action-auto-policy-adjustment-decision="approved" data-sla-quality-rereview-action-auto-policy-adjustment-id="${escapeHtml(item.policyAdjustmentId || "")}">Approve</button>
          <button class="ghost-button" type="button" data-sla-quality-rereview-action-auto-policy-adjustment-decision="rejected" data-sla-quality-rereview-action-auto-policy-adjustment-id="${escapeHtml(item.policyAdjustmentId || "")}">Reject</button>
        </div>
      </div>
    `;
  }
  return `
    <small class="sla-recommendation-adjustment-review-log">
      ${escapeHtml(item.status || "reviewed")} by ${escapeHtml(item.reviewedBy || item.updatedBy || "-")} at ${escapeHtml(item.reviewedAt || item.updatedAt || "-")}
      ${item.reviewReason ? ` / ${escapeHtml(item.reviewReason)}` : ""}
    </small>
  `;
}

function renderSlaQualityRereviewActionAutoPolicyLearningReview(item = {}) {
  if (item.status === "proposed") {
    const suggested = item.suggestedLearning || {};
    const priorityOptions = ["urgent", "high", "medium", "low"].map((priority) => `
      <option value="${escapeHtml(priority)}" ${priority === (suggested.priorityAfter || suggested.priorityBefore || "medium") ? "selected" : ""}>${escapeHtml(priority)}</option>
    `).join("");
    return `
      <div class="sla-recommendation-adjustment-review">
        <label class="field wide">
          <span>Review note</span>
          <textarea data-sla-quality-rereview-auto-policy-learning-review-note rows="2" placeholder="approval or rejection reason"></textarea>
        </label>
        <label class="field">
          <span>Override priority</span>
          <select data-sla-quality-rereview-auto-policy-learning-override-priority>${priorityOptions}</select>
        </label>
        <label class="field wide">
          <span>Override note</span>
          <textarea data-sla-quality-rereview-auto-policy-learning-override-note rows="2" placeholder="why this active learning differs from the suggestion"></textarea>
        </label>
        <div>
          <button class="secondary-button" type="button" data-sla-quality-rereview-auto-policy-learning-decision="approved" data-sla-quality-rereview-auto-policy-learning-id="${escapeHtml(item.calibrationId || "")}">Approve</button>
          <button class="ghost-button" type="button" data-sla-quality-rereview-auto-policy-learning-decision="rejected" data-sla-quality-rereview-auto-policy-learning-id="${escapeHtml(item.calibrationId || "")}">Reject</button>
          <button class="secondary-button" type="button" data-sla-quality-rereview-auto-policy-learning-decision="override" data-sla-quality-rereview-auto-policy-learning-id="${escapeHtml(item.calibrationId || "")}">Override</button>
        </div>
      </div>
    `;
  }
  return `
    <small class="sla-recommendation-adjustment-review-log">
      ${escapeHtml(item.status || "reviewed")} by ${escapeHtml(item.reviewedBy || item.updatedBy || "-")} at ${escapeHtml(item.reviewedAt || item.updatedAt || "-")}
      ${item.reviewReason ? ` / ${escapeHtml(item.reviewReason)}` : ""}
      ${item.overrideReason ? ` / override: ${escapeHtml(item.overrideReason)}` : ""}
    </small>
  `;
}

function renderSlaQualityRereviewActionAutoPolicyLearningCard(item = {}) {
  const suggested = item.suggestedLearning || {};
  const active = item.activeLearning || null;
  const previous = item.previousQuality || suggested.previousQuality || {};
  const simulation = item.simulation || {};
  const expectedBefore = simulation.expectedImpactBefore || {};
  const expectedAfter = simulation.expectedImpactAfter || {};
  const tone = item.status === "rejected" ? "neutral" : item.status === "approved" || item.status === "overridden" ? "good" : suggested.direction === "downgrade" ? "warning" : suggested.direction === "boost" ? "good" : "neutral";
  return `
    <article class="sla-auto-policy-adjustment ${escapeHtml(tone)}" data-sla-quality-rereview-auto-policy-learning-card="${escapeHtml(item.calibrationId || "")}">
      <div class="sla-recommendation-adjustment-head">
        <div>
          <strong>${escapeHtml(item.candidateType || "effect candidate learning")}</strong>
          <span>
            ${calibrationAuditQueueBadge(item.status || "proposed", item.status === "approved" || item.status === "overridden" ? "good" : item.status === "rejected" ? "muted" : "warning")}
            ${calibrationAuditQueueBadge(suggested.direction || "neutral", suggested.direction === "boost" ? "good" : suggested.direction === "downgrade" ? "warning" : "neutral")}
            ${active ? calibrationAuditQueueBadge("active", "good") : calibrationAuditQueueBadge("not active", "warning")}
          </span>
        </div>
        <small>${escapeHtml(item.calibrationId || "")}</small>
      </div>
      <div class="sla-auto-policy-impact">
        <span class="${suggested.priorityBefore !== suggested.priorityAfter ? "changed" : ""}">
          <strong>Suggested priority</strong>
          <em>${escapeHtml(suggested.priorityBefore || "-")} -> ${escapeHtml(suggested.priorityAfter || "-")}</em>
        </span>
        <span class="${active ? "changed" : ""}">
          <strong>Active priority</strong>
          <em>${escapeHtml(suggested.priorityBefore || "-")} -> ${escapeHtml(active?.priorityAfter || suggested.priorityBefore || "-")}</em>
        </span>
        <span>
          <strong>Expected success</strong>
          <em>${fmtPercent(expectedBefore.currentSuccessRate || 0)} -> ${fmtPercent(expectedAfter.expectedSuccessRate || expectedBefore.expectedSuccessRate || 0)}</em>
        </span>
        <span>
          <strong>Prior quality</strong>
          <em>success ${fmtPercent(previous.approvalSuccessRate || 0)} / repeat ${fmtPercent(previous.repeatRecommendationRate || 0)} / reject ${fmtPercent(previous.rejectionRate || 0)}</em>
        </span>
      </div>
      <div class="sla-recommendation-adjustment-copy">
        <span><strong>Suggested reason</strong><em>${escapeHtml(suggested.reason || "-")}</em></span>
        <span><strong>Before recommendation</strong><em>${escapeHtml(simulation.recommendationBefore || "-")}</em></span>
        <span><strong>Suggested recommendation</strong><em>${escapeHtml(simulation.suggestedRecommendationAfter || "-")}</em></span>
        <span><strong>Active recommendation</strong><em>${escapeHtml(simulation.activeRecommendationAfter || "-")}</em></span>
        <span><strong>Top rejection</strong><em>${escapeHtml(previous.topRejectionReason || "-")}${previous.topRejectionCount ? ` / ${fmtNumber(previous.topRejectionCount)} cases` : ""}</em></span>
      </div>
      ${renderSlaQualityRereviewActionAutoPolicyLearningReview(item)}
    </article>
  `;
}

function renderSlaQualityRereviewActionAutoPolicyLearningWorkflow(workflow = {}) {
  const summary = workflow.summary || {};
  const items = workflow.items || [];
  const proposed = items.filter((item) => item.status === "proposed");
  const history = items.filter((item) => item.status !== "proposed");
  return `
    <section class="sla-policy-candidate-quality">
      <strong>Quality learning review</strong>
      <div class="sla-policy-quality-summary">
        <span><strong>${fmtNumber(summary.proposed || 0)}</strong><em>Proposed</em></span>
        <span><strong>${fmtNumber(summary.active || 0)}</strong><em>Active</em></span>
        <span><strong>${fmtNumber(summary.approved || 0)}</strong><em>Approved</em></span>
        <span><strong>${fmtNumber(summary.overridden || 0)}</strong><em>Overridden</em></span>
        <span><strong>${fmtNumber(summary.rejected || 0)}</strong><em>Rejected</em></span>
        <span><strong>${fmtNumber(summary.boost || 0)} / ${fmtNumber(summary.downgrade || 0)}</strong><em>Boost / down</em></span>
      </div>
      ${proposed.length ? proposed.map(renderSlaQualityRereviewActionAutoPolicyLearningCard).join("") : `<div class="empty">No proposed re-review effect quality learning adjustments yet.</div>`}
      ${history.length ? `
        <section class="sla-recommendation-adjustment-section">
          <strong>Learning approval history</strong>
          ${history.map(renderSlaQualityRereviewActionAutoPolicyLearningCard).join("")}
        </section>
      ` : ""}
    </section>
  `;
}

function slaQualityRereviewActionAutoPolicyLearningPerformanceTone(item = {}) {
  if (item.performanceState === "weak_active" || item.reReviewNeeded) return "danger";
  if (item.performanceState === "strong_match") return "good";
  if (item.performanceState === "pending") return "warning";
  if (item.status === "rejected") return "neutral";
  return "warning";
}

function renderSlaQualityRereviewActionAutoPolicyLearningPerformanceCard(item = {}) {
  const tone = slaQualityRereviewActionAutoPolicyLearningPerformanceTone(item);
  const before = item.before || {};
  const after = item.after || {};
  const delta = item.delta || {};
  const reasonChange = item.rejectionReasonChange || {};
  return `
    <article class="sla-auto-policy-adjustment ${escapeHtml(tone)}">
      <div class="sla-recommendation-adjustment-head">
        <div>
          <strong>${escapeHtml(item.candidateType || "quality learning performance")}</strong>
          <span>
            ${calibrationAuditQueueBadge(item.status || "reviewed", item.active ? "good" : item.status === "rejected" ? "muted" : "warning")}
            ${calibrationAuditQueueBadge(item.performanceState || "watch", tone)}
            ${calibrationAuditQueueBadge(`score ${item.performanceScore ?? "-"}`, tone)}
            ${item.reReviewNeeded ? calibrationAuditQueueBadge("re-review", "danger") : ""}
          </span>
        </div>
        <small>${escapeHtml(item.calibrationId || "")}</small>
      </div>
      <div class="sla-policy-effect-metrics">
        ${renderSlaPolicyEffectMetric("Approval", before.approvalRate, after.approvalRate, delta.approvalRate, false)}
        ${renderSlaPolicyEffectMetric("Approved success", before.approvalSuccessRate, after.approvalSuccessRate, delta.approvalSuccessRate, false)}
        ${renderSlaPolicyEffectMetric("Repeat", before.repeatRecommendationRate, after.repeatRecommendationRate, delta.repeatRecommendationRate, true)}
        ${renderSlaPolicyEffectMetric("Rejection", before.rejectionRate, after.rejectionRate, delta.rejectionRate, true)}
      </div>
      <div class="sla-recommendation-adjustment-copy">
        <span><strong>Decision</strong><em>${escapeHtml(item.decisionType || "-")} by ${escapeHtml(item.decisionBy || "-")} at ${escapeHtml(item.decisionAt || "-")}</em></span>
        <span><strong>Priority</strong><em>${escapeHtml(item.priorityBefore || "-")} -> ${escapeHtml(item.activePriorityAfter || item.suggestedPriorityAfter || "-")} / suggested ${escapeHtml(item.suggestedPriorityAfter || "-")}</em></span>
        <span><strong>Rejection reason</strong><em>${escapeHtml(reasonChange.beforeTopReason || "-")} -> ${escapeHtml(reasonChange.afterTopReason || "-")}${reasonChange.changed ? " / changed" : ""}</em></span>
        ${item.reviewReason ? `<span><strong>Review reason</strong><em>${escapeHtml(item.reviewReason)}</em></span>` : ""}
        ${item.overrideReason ? `<span><strong>Override reason</strong><em>${escapeHtml(item.overrideReason)}</em></span>` : ""}
        ${item.reReviewReason ? `<span><strong>Re-review reason</strong><em>${escapeHtml(item.reReviewReason)}</em></span>` : ""}
      </div>
    </article>
  `;
}

function renderSlaQualityRereviewActionAutoPolicyLearningPerformanceRows(rows = [], emptyText = "No rows yet.") {
  if (!rows.length) return `<div class="empty">${escapeHtml(emptyText)}</div>`;
  return `
    <div class="sla-auto-approval-table">
      <table>
        <thead>
          <tr><th>Group</th><th>Total</th><th>Active</th><th>Weak</th><th>Score</th><th>Approval delta</th><th>Success delta</th><th>Repeat delta</th><th>Top rejection</th></tr>
        </thead>
        <tbody>
          ${rows.map((row) => `
            <tr>
              <td>${escapeHtml(row.label || row.key || "-")}</td>
              <td>${fmtNumber(row.total || 0)}</td>
              <td>${fmtNumber(row.active || 0)}</td>
              <td>${fmtNumber(row.weakActive || 0)}</td>
              <td>${fmtNumber(row.avgPerformanceScore || 0)}</td>
              <td>${deltaText(row.avgApprovalRateDelta || 0)}</td>
              <td>${deltaText(row.avgApprovalSuccessDelta || 0)}</td>
              <td>${deltaText(row.avgRepeatDelta || 0)}</td>
              <td>${escapeHtml(row.topRejectionReasonAfter || "-")}</td>
            </tr>
          `).join("")}
        </tbody>
      </table>
    </div>
  `;
}

function renderSlaQualityRereviewActionAutoPolicyLearningRereviewCandidate(candidate = {}) {
  const tone = candidate.priority === "urgent" ? "danger" : "warning";
  const after = candidate.after || {};
  return `
    <span class="${escapeHtml(tone)}">
      <strong>${escapeHtml(candidate.candidateType || "quality learning")} / ${escapeHtml(candidate.priority || "high")}</strong>
      <em>${escapeHtml(candidate.reason || "Active quality learning needs re-review.")}</em>
      <small>${escapeHtml(candidate.rereviewId || "-")} / due ${escapeHtml(candidate.dueDate || "-")} / score ${fmtNumber(candidate.performanceScore || 0)} / success ${fmtPercent(after.approvalSuccessRate || 0)} / repeat ${fmtPercent(after.repeatRecommendationRate || 0)}</small>
    </span>
  `;
}

function renderSlaQualityRereviewActionAutoPolicyLearningSlaActionQueue(queue = {}) {
  const summary = queue.summary || {};
  const items = queue.items || [];
  const focus = queue.focus || {};
  const ownerRows = summary.ownerUnresolved || [];
  const focusActionText = (action = {}) => [
    action.sourceLabel || action.sourceType || "Action",
    action.assignee || action.owner || "unassigned",
    action.targetDate ? `due ${action.targetDate}` : "no due",
    action.issueKey || action.rootMetric || ""
  ].filter(Boolean).join(" / ");
  if (!summary.total && !items.length) return "";
  return `
    <div class="sla-rereview-action-queue">
      <div class="calibration-sla-actions-head compact">
        <div>
          <strong>Saved effect-quality learning action operations queue</strong>
          <span>Filter by status, assignee, target timing, priority, risk, and root metric.</span>
        </div>
      </div>
      <div class="sla-policy-quality-summary">
        <span><strong>${fmtNumber(summary.open || 0)}</strong><em>Saved open</em></span>
        <span><strong>${fmtNumber(summary.overdue || 0)}</strong><em>Overdue</em></span>
        <span><strong>${fmtNumber(summary.thisWeek || 0)}</strong><em>This week</em></span>
        <span><strong>${fmtNumber(summary.highRisk || 0)}</strong><em>High risk</em></span>
        <span><strong>${fmtNumber(summary.urgent || 0)}</strong><em>Urgent</em></span>
        <span><strong>${fmtNumber(summary.unassigned || 0)}</strong><em>Unassigned</em></span>
        <span><strong>${fmtNumber(summary.completedWithSnapshot || 0)}</strong><em>Snapshots</em></span>
      </div>
      ${focus.overdue?.length || focus.thisWeek?.length || focus.ownerUnresolved?.length ? `
        <div class="calibration-sla-action-focus">
          <section>
            <strong>Delayed actions</strong>
            ${(focus.overdue || []).length ? focus.overdue.map((action) => `<span>${escapeHtml(focusActionText(action))}</span>`).join("") : `<span>No delayed saved actions.</span>`}
          </section>
          <section>
            <strong>This week</strong>
            ${(focus.thisWeek || []).length ? focus.thisWeek.map((action) => `<span>${escapeHtml(focusActionText(action))}</span>`).join("") : `<span>No saved actions due this week.</span>`}
          </section>
          <section>
            <strong>Owner unresolved</strong>
            ${(focus.ownerUnresolved || []).length ? focus.ownerUnresolved.map((row) => `<span>${escapeHtml(row.owner || "unassigned")} / open ${fmtNumber(row.open || 0)} / overdue ${fmtNumber(row.overdue || 0)} / risk ${fmtNumber(row.highRisk || 0)}</span>`).join("") : `<span>No unresolved owner load.</span>`}
          </section>
        </div>
      ` : ""}
      ${ownerRows.length ? `
        <div class="sla-auto-approval-table">
          <table>
            <thead>
              <tr><th>Owner</th><th>Open</th><th>Overdue</th><th>This week</th><th>Risk</th><th>Top issue</th></tr>
            </thead>
            <tbody>
              ${ownerRows.map((row) => `
                <tr>
                  <td>${escapeHtml(row.owner || "unassigned")}</td>
                  <td>${fmtNumber(row.open || 0)}</td>
                  <td>${fmtNumber(row.overdue || 0)}</td>
                  <td>${fmtNumber(row.thisWeek || 0)}</td>
                  <td>${fmtNumber(row.highRisk || 0)} / ${fmtNumber(row.urgent || 0)}</td>
                  <td>${escapeHtml(row.topIssue || "-")}</td>
                </tr>
              `).join("")}
            </tbody>
          </table>
        </div>
      ` : ""}
      ${items.length ? `
        <div class="sla-auto-approval-table">
          <table>
            <thead>
              <tr><th>Action</th><th>Status</th><th>Assignee</th><th>Target</th><th>Priority</th><th>Risk</th><th>Metric</th><th>Snapshot</th></tr>
            </thead>
            <tbody>
              ${items.slice(0, 40).map((action) => `
                <tr>
                  <td><strong>${escapeHtml(action.sourceLabel || action.sourceType || "Action")}</strong><small>${escapeHtml(action.actionId || "-")}</small></td>
                  <td>${calibrationAuditQueueBadge(action.status || "candidate", action.status === "done" ? "good" : action.status === "dismissed" ? "muted" : action.dueState === "overdue" ? "danger" : "neutral")}</td>
                  <td>${escapeHtml(action.assignee || action.owner || "unassigned")}</td>
                  <td>${escapeHtml(action.targetDate || "-")}<small>${escapeHtml(action.dueState || "")}</small></td>
                  <td>${calibrationAuditQueueBadge(action.priority || "-", action.priority === "urgent" || action.priority === "high" ? "danger" : "neutral")}</td>
                  <td>${calibrationAuditQueueBadge(action.riskLevel || action.slaLevel || "-", action.riskLevel === "high" || action.slaLevel === "danger" ? "danger" : "warning")}</td>
                  <td>${escapeHtml(action.issueKey || "-")}<small>${escapeHtml(action.rootMetric || "")}</small></td>
                  <td>${action.completionQualitySnapshot?.capturedAt ? `<small>${escapeHtml(action.completionQualitySnapshot.capturedAt)}</small>` : "-"}</td>
                </tr>
              `).join("")}
            </tbody>
          </table>
        </div>
      ` : ""}
    </div>
  `;
}

function renderEffectQualityRereviewSlaActionReassessmentHistory(history = {}) {
  const summary = history.summary || {};
  const aggregates = history.aggregates || {};
  const items = history.items || [];
  if (!summary.total && !items.length) {
    return `<div class="empty">No effect-quality SLA action reassessment history has been stored yet.</div>`;
  }
  return `
    <div class="sla-policy-quality-summary">
      <span><strong>${fmtNumber(summary.total || 0)}</strong><em>History</em></span>
      <span><strong>${fmtNumber(summary.averageEffectScore || 0)}</strong><em>Hist avg</em></span>
      <span><strong>${fmtNumber(summary.improved || 0)}</strong><em>Hist improved</em></span>
      <span><strong>${fmtNumber(summary.worse || 0)}</strong><em>Hist worse</em></span>
      <span><strong>${fmtNumber(summary.recurrence || 0)}</strong><em>Hist recurrence</em></span>
      <span><strong>${fmtNumber(summary.followUpCreated || 0)}</strong><em>Hist follow-up</em></span>
    </div>
    <div class="sla-history-aggregates">
      <section>
        <strong>Monthly effect history</strong>
        ${renderSlaHistoryGroupRows(aggregates.byMonth || [], "No monthly effect-quality history yet.")}
      </section>
      <section>
        <strong>Effective effect-quality action types</strong>
        ${renderSlaHistoryGroupRows(aggregates.effectiveActionTypes || [], "No effective effect-quality action type yet.")}
      </section>
      <section>
        <strong>Weak effect-quality action types</strong>
        ${renderSlaHistoryGroupRows(aggregates.weakActionTypes || [], "No weak effect-quality action type yet.")}
      </section>
      <section>
        <strong>Root metric history</strong>
        ${renderSlaHistoryGroupRows(aggregates.byIssue || [], "No root-metric effect-quality history yet.")}
      </section>
      <section>
        <strong>Assignee history</strong>
        ${renderSlaHistoryGroupRows(aggregates.byAssignee || [], "No assignee effect-quality history yet.")}
      </section>
    </div>
    <div class="sla-history-items">
      ${items.length ? items.slice(0, 10).map((item) => `
        <article class="sla-history-item ${escapeHtml(item.outcome || "unchanged")}">
          <div>
            <strong>${escapeHtml(item.sourceLabel || item.actionId || "Effect-quality SLA action")}</strong>
            <span>
              ${calibrationAuditQueueBadge(item.outcome || "unchanged", item.outcome === "improved" ? "good" : item.outcome === "worse" ? "danger" : "warning")}
              ${calibrationAuditQueueBadge(`score ${fmtNumber(item.effectScore || 0)}`, item.effectScore >= 70 ? "good" : item.effectScore < 45 ? "danger" : "warning")}
              ${calibrationAuditQueueBadge(item.followUpCreated ? "follow-up created" : item.followUpNeeded ? "follow-up needed" : "no follow-up", item.followUpCreated ? "good" : item.followUpNeeded ? "warning" : "neutral")}
            </span>
          </div>
          <p>${escapeHtml(item.issueKey || item.rootMetric || item.metricLabel || "unknown")} / ${escapeHtml(item.followUpReason || "No reassessment note.")}</p>
          <small>${escapeHtml(item.evaluatedAt || "-")} / ${escapeHtml(item.assignee || item.owner || "unassigned")} / recurrence ${item.recurrence ? "yes" : "no"}</small>
        </article>
      `).join("") : `<div class="empty">No effect-quality reassessment history rows match the current filters.</div>`}
    </div>
  `;
}

function renderEffectQualitySlaActionRecommendationAdjustmentReview(item = {}) {
  if (item.status === "proposed") {
    return `
      <div class="sla-recommendation-adjustment-review">
        <label class="field wide">
          <span>Review note</span>
          <textarea data-effect-quality-rereview-sla-action-recommendation-adjustment-review-note rows="2" placeholder="approval or rejection reason"></textarea>
        </label>
        <div>
          <button class="secondary-button" type="button" data-effect-quality-rereview-sla-action-recommendation-adjustment-decision="approved" data-effect-quality-rereview-sla-action-recommendation-adjustment-id="${escapeHtml(item.adjustmentId || "")}">Approve</button>
          <button class="ghost-button" type="button" data-effect-quality-rereview-sla-action-recommendation-adjustment-decision="rejected" data-effect-quality-rereview-sla-action-recommendation-adjustment-id="${escapeHtml(item.adjustmentId || "")}">Reject</button>
        </div>
      </div>
    `;
  }
  return `
    <small class="sla-recommendation-adjustment-review-log">
      ${escapeHtml(item.status || "reviewed")} by ${escapeHtml(item.reviewedBy || item.updatedBy || "-")} at ${escapeHtml(item.reviewedAt || item.updatedAt || "-")}
      ${item.reviewReason ? ` / ${escapeHtml(item.reviewReason)}` : ""}
    </small>
  `;
}

function renderEffectQualitySlaActionRecommendationAdjustmentCard(item = {}) {
  const tone = slaRecommendationAdjustmentTone(item);
  const priorityAfter = item.status === "approved" && item.activePriority ? item.activePriority : item.proposedPriority;
  return `
    <article class="sla-recommendation-adjustment ${escapeHtml(tone)}" data-effect-quality-rereview-sla-action-recommendation-adjustment-card="${escapeHtml(item.adjustmentId || "")}">
      <div class="sla-recommendation-adjustment-head">
        <div>
          <strong>${escapeHtml(item.sourceLabel || item.sourceKey || "Effect-quality SLA action correction")}</strong>
          <span>
            ${calibrationAuditQueueBadge(item.status || "proposed", tone)}
            ${calibrationAuditQueueBadge(item.approvalMode === "auto" ? "auto approved" : item.status === "proposed" ? "manual review" : "manual", item.approvalMode === "auto" ? "good" : item.status === "proposed" ? "warning" : "neutral")}
            ${item.rollbackAvailable ? calibrationAuditQueueBadge("rollback ready", "warning") : ""}
            ${calibrationAuditQueueBadge(item.direction || "neutral", tone)}
            ${calibrationAuditQueueBadge(`${item.originalPriority || "-"} -> ${priorityAfter || "-"}`, tone)}
            ${calibrationAuditQueueBadge(item.owner || "unassigned", "neutral")}
          </span>
        </div>
        <small>${escapeHtml(item.month || "-")} / ${escapeHtml(item.issueKey || item.rootMetric || "-")}</small>
      </div>
      <p>${escapeHtml(item.reason || "No adjustment reason.")}</p>
      ${renderSlaRecommendationAdjustmentImpact(item)}
      <small class="sla-recommendation-adjustment-meta">
        proposed ${escapeHtml(item.proposedAt || "-")} by ${escapeHtml(item.proposedBy || "system")}
        ${item.status === "approved" ? ` / active priority ${escapeHtml(item.activePriority || item.proposedPriority || "-")}` : ""}
      </small>
      ${renderEffectQualitySlaActionRecommendationAdjustmentReview(item)}
    </article>
  `;
}

function renderEffectQualitySlaActionRecommendationApprovalHistory(history = []) {
  if (!history.length) return `<div class="empty">No effect-quality correction approval or rejection history yet.</div>`;
  return `
    <div class="sla-auto-approval-table">
      <table>
        <thead>
          <tr><th>Decision</th><th>Target</th><th>Priority</th><th>Effect</th><th>Reviewed</th><th>Reason</th></tr>
        </thead>
        <tbody>
          ${history.slice(0, 12).map((item) => `
            <tr>
              <td>${escapeHtml(item.status || "-")}</td>
              <td>${escapeHtml(item.sourceLabel || item.issueKey || item.sourceKey || "-")}</td>
              <td>${escapeHtml(item.originalPriority || "-")} -> ${escapeHtml(item.activePriority || item.proposedPriority || "-")}</td>
              <td>score ${fmtNumber(item.historyEffectScore || 0)} / recurrence ${fmtPercent(item.recurrenceRate || 0)}</td>
              <td>${escapeHtml(item.reviewedAt || item.updatedAt || "-")} / ${escapeHtml(item.reviewedBy || item.updatedBy || "-")}</td>
              <td>${escapeHtml(item.reviewReason || item.reason || "-")}</td>
            </tr>
          `).join("")}
        </tbody>
      </table>
    </div>
  `;
}

function renderEffectQualitySlaActionAutoApprovalPolicy(policy = {}) {
  if (!policy || !policy.policyVersion) return "";
  return `
    <div class="sla-recommendation-adjustment-policy">
      <span><strong>${escapeHtml(policy.policyVersion || "-")}</strong><em>Auto policy</em></span>
      <span><strong>${fmtNumber(policy.minSampleSize || 0)}</strong><em>Min samples</em></span>
      <span><strong>${fmtNumber(policy.minHistoricalApprovalSuccessRate || 0)}%</strong><em>Past approval</em></span>
      <span><strong>${fmtNumber(policy.maxPriorityStepChange || 0)}</strong><em>Max step</em></span>
      <span><strong>${fmtNumber(policy.boost?.minEffectScore || 0)} / ${fmtNumber(policy.boost?.maxRecurrenceRate || 0)}%</strong><em>Boost score / recur</em></span>
      <span><strong>${fmtNumber(policy.downgrade?.maxEffectScore || 0)} / ${fmtNumber(policy.downgrade?.minRecurrenceRate || 0)}%</strong><em>Down score / recur</em></span>
    </div>
  `;
}

function renderEffectQualitySlaActionAutoApprovalLogs(logs = []) {
  if (!logs.length) return `<div class="empty">No auto approval history yet.</div>`;
  return `
    <div class="sla-history-items">
      ${logs.slice(0, 8).map((log) => `
        <article class="sla-history-item ${escapeHtml(log.nextStatus || "approved")}">
          <div>
            <strong>${escapeHtml(log.eventType || "auto_approved")}</strong>
            <span>
              ${calibrationAuditQueueBadge(log.nextStatus || "approved", log.nextStatus === "approved" ? "good" : "warning")}
              ${calibrationAuditQueueBadge(log.policyDecision?.riskLevel || "low", log.policyDecision?.riskLevel === "low" ? "good" : log.policyDecision?.riskLevel === "high" ? "danger" : "warning")}
              ${log.rollbackAvailable ? calibrationAuditQueueBadge("rollback ready", "warning") : ""}
            </span>
          </div>
          <p>${escapeHtml(log.reason || log.policyDecision?.reasons?.join(" ") || "Auto approval decision recorded.")}</p>
          <small>${escapeHtml(log.eventAt || "-")} / ${escapeHtml(log.eventBy || "system_auto")} / ${escapeHtml(log.adjustmentId || "-")}</small>
        </article>
      `).join("")}
    </div>
  `;
}

function renderEffectQualitySlaActionRecommendationAdjustments(adjustments = {}) {
  const summary = adjustments.summary || {};
  const items = adjustments.items || [];
  if (!summary.total && !items.length) {
    return `<div class="empty">No effect-quality SLA recommendation correction proposals yet.</div>`;
  }
  const proposedItems = items.filter((item) => item.status === "proposed");
  const autoApprovedItems = items.filter((item) => item.status === "approved" && item.approvalMode === "auto");
  const manualDecisionItems = items.filter((item) => item.status !== "proposed" && !(item.status === "approved" && item.approvalMode === "auto"));
  const autoLogs = adjustments.autoApprovalLogs || [];
  const approvalHistory = adjustments.approvalHistory || [];
  const workflowSummary = adjustments.workflowSummary || {};
  const policy = adjustments.autoApprovalPolicy || {};
  return `
    <div class="sla-rereview-action-queue">
      <div class="calibration-sla-actions-head">
        <div>
          <strong>Effect-quality recommendation correction approval</strong>
          <span>Low-risk history-based priority changes are auto approved; medium/high-risk changes stay proposed for admin review.</span>
        </div>
      </div>
      <div class="sla-policy-quality-summary">
        <span><strong>${fmtNumber(summary.total || 0)}</strong><em>Corrections</em></span>
        <span><strong>${fmtNumber(summary.proposed || 0)}</strong><em>Proposed</em></span>
        <span><strong>${fmtNumber(summary.approved || 0)}</strong><em>Approved</em></span>
        <span><strong>${fmtNumber(summary.rejected || 0)}</strong><em>Rejected</em></span>
        <span><strong>${fmtNumber(workflowSummary.lowRiskAutoApproved || summary.autoApproved || 0)}</strong><em>Low-risk auto</em></span>
        <span><strong>${fmtNumber(workflowSummary.mediumHighManualReview || workflowSummary.proposedManualReview || 0)}</strong><em>Manual review</em></span>
        <span><strong>${fmtNumber(workflowSummary.activeManualApproved || 0)}</strong><em>Manual active</em></span>
        <span><strong>${fmtNumber(workflowSummary.rollbackAvailable || summary.rollbackAvailable || 0)}</strong><em>Rollback ready</em></span>
        <span><strong>${fmtNumber(summary.boost || 0)} / ${fmtNumber(summary.downgrade || 0)}</strong><em>Boost / down</em></span>
        <span><strong>${fmtNumber(summary.averageEffectScore || 0)}</strong><em>Avg score</em></span>
        <span><strong>${fmtNumber(summary.averageRecurrenceRate || 0)}%</strong><em>Avg recurrence</em></span>
      </div>
      ${renderEffectQualitySlaActionAutoApprovalPolicy(policy)}
      <section class="sla-recommendation-adjustment-section">
        <strong>Manual review required</strong>
        ${proposedItems.length ? proposedItems.map(renderEffectQualitySlaActionRecommendationAdjustmentCard).join("") : `<div class="empty">No proposed effect-quality corrections need review.</div>`}
      </section>
      <section class="sla-recommendation-adjustment-section">
        <strong>Low-risk auto-approved history</strong>
        ${autoApprovedItems.length ? autoApprovedItems.map(renderEffectQualitySlaActionRecommendationAdjustmentCard).join("") : `<div class="empty">No auto-approved effect-quality corrections yet.</div>`}
        ${renderEffectQualitySlaActionAutoApprovalLogs(autoLogs)}
      </section>
      <section class="sla-recommendation-adjustment-section">
        <strong>Manual decisions</strong>
        ${manualDecisionItems.length ? manualDecisionItems.map(renderEffectQualitySlaActionRecommendationAdjustmentCard).join("") : `<div class="empty">No manual approved or rejected effect-quality corrections yet.</div>`}
      </section>
      <section class="sla-recommendation-adjustment-section">
        <strong>Approval and rejection history</strong>
        ${renderEffectQualitySlaActionRecommendationApprovalHistory(approvalHistory)}
      </section>
    </div>
  `;
}

function renderEffectQualitySlaActionAutoPolicyReview(item = {}) {
  if (item.status === "proposed") {
    return `
      <div class="sla-recommendation-adjustment-review">
        <label class="field wide">
          <span>Review note</span>
          <textarea data-effect-quality-rereview-sla-action-auto-policy-adjustment-review-note rows="2" placeholder="approval or rejection reason"></textarea>
        </label>
        <div>
          <button class="secondary-button" type="button" data-effect-quality-rereview-sla-action-auto-policy-adjustment-decision="approved" data-effect-quality-rereview-sla-action-auto-policy-adjustment-id="${escapeHtml(item.policyAdjustmentId || "")}">Approve</button>
          <button class="ghost-button" type="button" data-effect-quality-rereview-sla-action-auto-policy-adjustment-decision="rejected" data-effect-quality-rereview-sla-action-auto-policy-adjustment-id="${escapeHtml(item.policyAdjustmentId || "")}">Reject</button>
        </div>
      </div>
    `;
  }
  return `
    <small class="sla-recommendation-adjustment-review-log">
      ${escapeHtml(item.status || "reviewed")} by ${escapeHtml(item.reviewedBy || item.updatedBy || "-")} at ${escapeHtml(item.reviewedAt || item.updatedAt || "-")}
      ${item.reviewReason ? ` / ${escapeHtml(item.reviewReason)}` : ""}
    </small>
  `;
}

function renderEffectQualitySlaActionAutoPolicyAdjustmentCard(item = {}) {
  const tone = slaAutoPolicyAdjustmentTone(item);
  const before = item.beforePolicy || {};
  const after = item.afterPolicy || {};
  const impact = item.expectedImpact || {};
  const source = item.sourceContext || {};
  const generatedSource = source.source || item.sourcePolicyAdjustmentId || item.sourceSuggestionType;
  const learning = item.qualityLearningAdjustment || source.qualityLearningAdjustment || {};
  const previousQuality = learning.previousQuality || {};
  return `
    <article class="sla-auto-policy-adjustment ${escapeHtml(tone)}" data-effect-quality-rereview-sla-action-auto-policy-adjustment-card="${escapeHtml(item.policyAdjustmentId || "")}">
      <div class="sla-recommendation-adjustment-head">
        <div>
          <strong>${escapeHtml(item.target || item.issueKey || item.candidateType || "Effect-quality policy adjustment")}</strong>
          <span>
            ${calibrationAuditQueueBadge(item.status || "proposed", item.status === "approved" ? "good" : item.status === "rejected" ? "muted" : tone)}
            ${calibrationAuditQueueBadge(item.priority || "medium", tone)}
            ${calibrationAuditQueueBadge(item.candidateType || "policy", "neutral")}
            ${slaPolicyQualityCalibrationSummary(learning) ? calibrationAuditQueueBadge(`quality ${learning.direction || "neutral"}`, slaPolicyQualityCalibrationTone(learning)) : ""}
            ${item.duplicateStatus ? calibrationAuditQueueBadge(item.duplicateStatus, item.duplicateStatus === "created" ? "good" : "warning") : ""}
          </span>
        </div>
        <small>${escapeHtml(item.policyAdjustmentId || "")}</small>
      </div>
      <p>${escapeHtml(item.basis || "")}</p>
      <div class="sla-auto-policy-impact">
        ${renderSlaAutoPolicyValue("Enabled", before.issueAutoApprovalEnabled ? "yes" : "no", after.issueAutoApprovalEnabled ? "yes" : "no")}
        ${renderSlaAutoPolicyValue("Min samples", before.minSampleSize, after.minSampleSize)}
        ${renderSlaAutoPolicyValue("Past approval", before.minHistoricalApprovalSuccessRate, after.minHistoricalApprovalSuccessRate, "%")}
        ${renderSlaAutoPolicyValue("Priority step", before.maxPriorityStepChange, after.maxPriorityStepChange)}
        <span class="${Number(impact.expectedSuccessRateChange || 0) ? "changed" : ""}">
          <strong>Expected success</strong>
          <em>${fmtPercent(impact.currentSuccessRate || 0)} -> ${fmtPercent(impact.expectedSuccessRate || 0)} (${Number(impact.expectedSuccessRateChange || 0) >= 0 ? "+" : ""}${fmtNumber(impact.expectedSuccessRateChange || 0)}p)</em>
        </span>
        <span>
          <strong>Impact scope</strong>
          <em>${escapeHtml(impact.scope || "issue_policy")} / evaluated ${fmtNumber(impact.evaluated || 0)}</em>
        </span>
      </div>
      <div class="sla-recommendation-adjustment-copy">
        <span><strong>Recommendation</strong><em>${escapeHtml(item.recommendation || "No recommendation text.")}</em></span>
        <span><strong>Patch</strong><em>${escapeHtml(JSON.stringify(item.policyPatch || {}))}</em></span>
        ${generatedSource ? `<span><strong>Generated from</strong><em>${escapeHtml(source.source || "policy_effectiveness")} / ${escapeHtml(source.policyAdjustmentId || item.sourcePolicyAdjustmentId || "-")} / ${escapeHtml(source.suggestionType || item.sourceSuggestionType || "-")} / ${escapeHtml(source.outcome || item.sourceEffectOutcome || "-")} / score ${escapeHtml(source.effectScore ?? item.sourceEffectScore ?? "-")}</em></span>` : ""}
        ${learning.reason ? `<span><strong>Quality learning</strong><em>${escapeHtml(learning.status || "none")} / ${escapeHtml(learning.direction || "neutral")} / ${escapeHtml(learning.priorityBefore || "-")} -> ${escapeHtml(learning.priorityAfter || "-")} / success ${fmtPercent(previousQuality.approvalSuccessRate || 0)} / repeat ${fmtPercent(previousQuality.repeatRecommendationRate || 0)} / rejection ${fmtPercent(previousQuality.rejectionRate || 0)}${previousQuality.topRejectionReason ? ` / top rejection: ${escapeHtml(previousQuality.topRejectionReason)}` : ""}</em></span>` : ""}
        ${item.duplicateStatus ? `<span><strong>Duplicate status</strong><em>${escapeHtml(item.duplicateStatus || "-")}${item.duplicateOfPolicyAdjustmentId ? ` / ${escapeHtml(item.duplicateOfPolicyAdjustmentId)}` : ""}</em></span>` : ""}
      </div>
      ${renderEffectQualitySlaActionAutoPolicyReview(item)}
    </article>
  `;
}

function renderEffectQualitySlaActionAutoPolicyWorkflow(workflow = {}) {
  const summary = workflow.summary || {};
  const activePolicy = workflow.activePolicy || {};
  const items = workflow.items || [];
  const proposed = items.filter((item) => item.status === "proposed");
  const history = items.filter((item) => item.status !== "proposed");
  return `
    <section>
      <strong>Effect-quality policy review queue</strong>
      <p class="muted small">Performance-based candidates stay proposed until an admin approves or rejects them; only approved patches are reflected in the active auto-approval policy.</p>
      <div class="calibration-audit-queue-summary compact">
        <span><strong>${fmtNumber(summary.proposed || 0)}</strong><em>Proposed</em></span>
        <span><strong>${fmtNumber(summary.approved || 0)}</strong><em>Approved</em></span>
        <span><strong>${fmtNumber(summary.rejected || 0)}</strong><em>Rejected</em></span>
        <span><strong>${fmtNumber(summary.expectedSuccessRateChangeAvg || 0)}p</strong><em>Avg impact</em></span>
        <span><strong>${escapeHtml(activePolicy.policyVersion || "-")}</strong><em>Active policy</em></span>
        <span><strong>${fmtNumber(activePolicy.activeAdjustmentIds?.length || 0)}</strong><em>Applied patches</em></span>
      </div>
      ${proposed.length ? proposed.map(renderEffectQualitySlaActionAutoPolicyAdjustmentCard).join("") : `<div class="empty">No proposed effect-quality auto-approval policy adjustments match the current performance report.</div>`}
    </section>
    <section>
      <strong>Effect-quality policy approval history</strong>
      ${history.length ? history.map(renderEffectQualitySlaActionAutoPolicyAdjustmentCard).join("") : `<div class="empty">No approved or rejected effect-quality auto-approval policy adjustments yet.</div>`}
    </section>
  `;
}

function renderEffectQualitySlaActionAutoPolicyEffectiveness(effectiveness = {}) {
  const summary = effectiveness.summary || {};
  const items = effectiveness.items || [];
  const generatedProposals = effectiveness.effectGeneratedProposals || [];
  return `
    <section class="sla-auto-policy-effectiveness">
      <strong>Effect-quality policy post-change effect</strong>
      <div class="calibration-audit-queue-summary compact">
        <span><strong>${fmtNumber(summary.total || 0)}</strong><em>Approved policies</em></span>
        <span><strong>${fmtNumber(summary.improved || 0)}</strong><em>Improved</em></span>
        <span><strong>${fmtNumber(summary.unchanged || 0)}</strong><em>Unchanged</em></span>
        <span><strong>${fmtNumber(summary.worse || 0)}</strong><em>Worse</em></span>
        <span><strong>${fmtNumber(summary.rollbackSuggested || 0)}</strong><em>Rollback suggestions</em></span>
        <span><strong>${fmtNumber(summary.additionalAdjustmentSuggested || 0)}</strong><em>Follow-up suggestions</em></span>
        <span><strong>${fmtNumber(summary.avgEffectScore || 0)}</strong><em>Avg effect</em></span>
        <span><strong>${deltaText(summary.avgSuccessRateDelta || 0)}</strong><em>Success delta</em></span>
        <span><strong>${deltaText(summary.avgFalsePositiveDelta || 0)}</strong><em>False positive delta</em></span>
        <span><strong>${deltaText(summary.avgManualReviewDelta || 0)}</strong><em>Manual review delta</em></span>
        <span><strong>${fmtNumber(generatedProposals.length || 0)}</strong><em>Generated proposals</em></span>
      </div>
      ${renderEffectQualitySlaActionAutoPolicyLearningWorkflow(effectiveness.qualityLearningWorkflow || {})}
      ${renderSlaQualityRereviewActionAutoPolicyLearningPerformance(effectiveness.qualityLearningPerformance || {})}
      ${renderEffectQualitySlaActionAutoPolicyLearningRereviewQueue(effectiveness.qualityLearningRereviews || {})}
      ${renderEffectQualitySlaActionAutoPolicyCandidateQuality(effectiveness.effectCandidateQuality || {})}
      ${items.length
        ? items.slice(0, 8).map(renderSlaAutoPolicyEffectivenessCard).join("")
        : `<div class="empty">No approved effect-quality policy effectiveness rows yet.</div>`}
    </section>
  `;
}

function renderEffectQualitySlaActionAutoPolicyLearningReview(item = {}) {
  if (item.status === "proposed") {
    const suggested = item.suggestedLearning || {};
    const priorityOptions = ["urgent", "high", "medium", "low"].map((priority) => `
      <option value="${escapeHtml(priority)}" ${priority === (suggested.priorityAfter || suggested.priorityBefore || "medium") ? "selected" : ""}>${escapeHtml(priority)}</option>
    `).join("");
    return `
      <div class="sla-recommendation-adjustment-review">
        <label class="field wide">
          <span>Review note</span>
          <textarea data-effect-quality-rereview-sla-action-auto-policy-learning-review-note rows="2" placeholder="approval or rejection reason"></textarea>
        </label>
        <label class="field">
          <span>Override priority</span>
          <select data-effect-quality-rereview-sla-action-auto-policy-learning-override-priority>${priorityOptions}</select>
        </label>
        <label class="field wide">
          <span>Override note</span>
          <textarea data-effect-quality-rereview-sla-action-auto-policy-learning-override-note rows="2" placeholder="why this active learning differs from the suggestion"></textarea>
        </label>
        <div>
          <button class="secondary-button" type="button" data-effect-quality-rereview-sla-action-auto-policy-learning-decision="approved" data-effect-quality-rereview-sla-action-auto-policy-learning-id="${escapeHtml(item.calibrationId || "")}">Approve</button>
          <button class="ghost-button" type="button" data-effect-quality-rereview-sla-action-auto-policy-learning-decision="rejected" data-effect-quality-rereview-sla-action-auto-policy-learning-id="${escapeHtml(item.calibrationId || "")}">Reject</button>
          <button class="secondary-button" type="button" data-effect-quality-rereview-sla-action-auto-policy-learning-decision="override" data-effect-quality-rereview-sla-action-auto-policy-learning-id="${escapeHtml(item.calibrationId || "")}">Override</button>
        </div>
      </div>
    `;
  }
  return `
    <small class="sla-recommendation-adjustment-review-log">
      ${escapeHtml(item.status || "reviewed")} by ${escapeHtml(item.reviewedBy || item.updatedBy || "-")} at ${escapeHtml(item.reviewedAt || item.updatedAt || "-")}
      ${item.reviewReason ? ` / ${escapeHtml(item.reviewReason)}` : ""}
      ${item.overrideReason ? ` / override: ${escapeHtml(item.overrideReason)}` : ""}
    </small>
  `;
}

function renderEffectQualitySlaActionAutoPolicyLearningCard(item = {}) {
  const suggested = item.suggestedLearning || {};
  const active = item.activeLearning || null;
  const previous = item.previousQuality || suggested.previousQuality || {};
  const simulation = item.simulation || {};
  const expectedBefore = simulation.expectedImpactBefore || {};
  const expectedAfter = simulation.expectedImpactAfter || {};
  const tone = item.status === "rejected" ? "neutral" : item.status === "approved" || item.status === "overridden" ? "good" : suggested.direction === "downgrade" ? "warning" : suggested.direction === "boost" ? "good" : "neutral";
  return `
    <article class="sla-auto-policy-adjustment ${escapeHtml(tone)}" data-effect-quality-rereview-sla-action-auto-policy-learning-card="${escapeHtml(item.calibrationId || "")}">
      <div class="sla-recommendation-adjustment-head">
        <div>
          <strong>${escapeHtml(item.candidateType || "effect-quality candidate learning")}</strong>
          <span>
            ${calibrationAuditQueueBadge(item.status || "proposed", item.status === "approved" || item.status === "overridden" ? "good" : item.status === "rejected" ? "muted" : "warning")}
            ${calibrationAuditQueueBadge(suggested.direction || "neutral", suggested.direction === "boost" ? "good" : suggested.direction === "downgrade" ? "warning" : "neutral")}
            ${active ? calibrationAuditQueueBadge("active", "good") : calibrationAuditQueueBadge("not active", "warning")}
          </span>
        </div>
        <small>${escapeHtml(item.calibrationId || "")}</small>
      </div>
      <div class="sla-auto-policy-impact">
        <span class="${suggested.priorityBefore !== suggested.priorityAfter ? "changed" : ""}">
          <strong>Suggested priority</strong>
          <em>${escapeHtml(suggested.priorityBefore || "-")} -> ${escapeHtml(suggested.priorityAfter || "-")}</em>
        </span>
        <span class="${active ? "changed" : ""}">
          <strong>Active priority</strong>
          <em>${escapeHtml(suggested.priorityBefore || "-")} -> ${escapeHtml(active?.priorityAfter || suggested.priorityBefore || "-")}</em>
        </span>
        <span>
          <strong>Expected success</strong>
          <em>${fmtPercent(expectedBefore.currentSuccessRate || 0)} -> ${fmtPercent(expectedAfter.expectedSuccessRate || expectedBefore.expectedSuccessRate || 0)}</em>
        </span>
        <span>
          <strong>Prior quality</strong>
          <em>success ${fmtPercent(previous.approvalSuccessRate || 0)} / repeat ${fmtPercent(previous.repeatRecommendationRate || 0)} / reject ${fmtPercent(previous.rejectionRate || 0)}</em>
        </span>
      </div>
      <div class="sla-recommendation-adjustment-copy">
        <span><strong>Suggested reason</strong><em>${escapeHtml(suggested.reason || "-")}</em></span>
        <span><strong>Before recommendation</strong><em>${escapeHtml(simulation.recommendationBefore || "-")}</em></span>
        <span><strong>Suggested recommendation</strong><em>${escapeHtml(simulation.suggestedRecommendationAfter || "-")}</em></span>
        <span><strong>Active recommendation</strong><em>${escapeHtml(simulation.activeRecommendationAfter || "-")}</em></span>
        <span><strong>Top rejection</strong><em>${escapeHtml(previous.topRejectionReason || "-")}${previous.topRejectionCount ? ` / ${fmtNumber(previous.topRejectionCount)} cases` : ""}</em></span>
      </div>
      ${renderEffectQualitySlaActionAutoPolicyLearningReview(item)}
    </article>
  `;
}

function renderEffectQualitySlaActionAutoPolicyLearningWorkflow(workflow = {}) {
  const summary = workflow.summary || {};
  const items = workflow.items || [];
  const proposed = items.filter((item) => item.status === "proposed");
  const history = items.filter((item) => item.status !== "proposed");
  return `
    <section class="sla-policy-candidate-quality">
      <strong>Effect-quality candidate learning review</strong>
      <div class="sla-policy-quality-summary">
        <span><strong>${fmtNumber(summary.proposed || 0)}</strong><em>Proposed</em></span>
        <span><strong>${fmtNumber(summary.active || 0)}</strong><em>Active</em></span>
        <span><strong>${fmtNumber(summary.approved || 0)}</strong><em>Approved</em></span>
        <span><strong>${fmtNumber(summary.overridden || 0)}</strong><em>Overridden</em></span>
        <span><strong>${fmtNumber(summary.rejected || 0)}</strong><em>Rejected</em></span>
        <span><strong>${fmtNumber(summary.boost || 0)} / ${fmtNumber(summary.downgrade || 0)}</strong><em>Boost / down</em></span>
      </div>
      ${proposed.length ? proposed.map(renderEffectQualitySlaActionAutoPolicyLearningCard).join("") : `<div class="empty">No proposed effect-quality candidate learning adjustments yet.</div>`}
      ${history.length ? `
        <section class="sla-recommendation-adjustment-section">
          <strong>Effect-quality learning approval history</strong>
          ${history.map(renderEffectQualitySlaActionAutoPolicyLearningCard).join("")}
        </section>
      ` : ""}
    </section>
  `;
}

function renderEffectQualitySlaActionAutoPolicyCandidateQuality(quality = {}) {
  const summary = quality.summary || {};
  const byType = quality.byType || [];
  const repeatItems = (quality.items || []).filter((item) => item.repeatRecommended).slice(0, 6);
  if (!summary.total && !byType.length) {
    return `
      <section class="sla-policy-candidate-quality">
        <strong>Effect-quality effect candidate quality</strong>
        <div class="empty">No reviewed effect-quality effect-based policy candidate quality data yet.</div>
      </section>
    `;
  }
  return `
    <section class="sla-policy-candidate-quality">
      <strong>Effect-quality effect candidate quality</strong>
      <div class="sla-policy-quality-summary">
        <span><strong>${fmtNumber(summary.total || 0)}</strong><em>Candidates</em></span>
        <span><strong>${fmtPercent(summary.approvalRate || 0)}</strong><em>Approval rate</em></span>
        <span><strong>${fmtPercent(summary.approvalSuccessRate || 0)}</strong><em>Approved success</em></span>
        <span><strong>${fmtNumber(summary.rejected || 0)}</strong><em>Rejected</em></span>
        <span><strong>${fmtNumber(summary.repeatRecommended || 0)}</strong><em>Repeat recommended</em></span>
      </div>
      <div class="sla-auto-approval-table">
        <table>
          <thead>
            <tr><th>Candidate type</th><th>Total</th><th>Approved</th><th>Rejected</th><th>Approval</th><th>Success</th><th>Repeat</th><th>Top rejection reason</th></tr>
          </thead>
          <tbody>
            ${byType.map((row) => `
              <tr>
                <td>${escapeHtml(row.candidateType || "-")}</td>
                <td>${fmtNumber(row.total || 0)}</td>
                <td>${fmtNumber(row.approved || 0)}</td>
                <td>${fmtNumber(row.rejected || 0)}</td>
                <td>${fmtPercent(row.approvalRate || 0)}</td>
                <td>${fmtPercent(row.approvalSuccessRate || 0)}</td>
                <td>${fmtNumber(row.repeatRecommended || 0)}</td>
                <td>${escapeHtml(row.rejectionReasons?.[0]?.reason || "-")}</td>
              </tr>
            `).join("")}
          </tbody>
        </table>
      </div>
      ${repeatItems.length ? `
        <div class="sla-policy-repeat-list">
          ${repeatItems.map((item) => `
            <span class="${escapeHtml(item.qualityOutcome === "failed" ? "danger" : item.status === "rejected" ? "warning" : "neutral")}">
              <strong>${escapeHtml(item.candidateType || "candidate")} / ${escapeHtml(item.target || item.issueKey || "-")}</strong>
              <em>${escapeHtml(item.repeatRecommendationReason || "Repeat review recommended.")}</em>
              <small>${escapeHtml(item.policyAdjustmentId || "-")} / ${escapeHtml(item.status || "-")} / ${escapeHtml(item.qualityOutcome || "-")} / post ${escapeHtml(item.postEffectOutcome || "-")}</small>
            </span>
          `).join("")}
        </div>
      ` : ""}
    </section>
  `;
}

function renderEffectQualitySlaActionAutoPolicyLearningRereviewQueue(queue = {}) {
  return renderSlaQualityRereviewActionAutoPolicyLearningRereviewQueue(queue)
    .replaceAll(
      "data-sla-quality-rereview-auto-policy-learning-rereview-",
      "data-effect-quality-rereview-sla-action-auto-policy-learning-rereview-"
    )
    .replaceAll("Quality learning re-review queue", "Effect-quality candidate learning re-review queue")
    .replaceAll("quality learning re-review items", "effect-quality candidate learning re-review items")
    .replaceAll("quality learning re-review queue", "effect-quality candidate learning re-review queue");
}

function renderInternalQualitySlaLock(lock = {}) {
  const allowed = lock.allowedActions || ["view_status", "approve_or_reject_existing_proposals", "rollback_auto_approved_adjustments"];
  return `
    <section class="internal-quality-lock-card">
      <div>
        <span class="module-eyebrow">${escapeHtml(lock.label || "Internal Quality Management")}</span>
        <strong>SLA v1.0 ${escapeHtml(lock.status || "locked")}</strong>
        <p>${escapeHtml(lock.purpose || "Admin-only quality guard for report reliability, not a customer-facing SaaS feature.")}</p>
      </div>
      <div class="internal-quality-lock-actions">
        ${allowed.map((item) => `<span>${escapeHtml(String(item).replaceAll("_", " "))}</span>`).join("")}
      </div>
      <small>${escapeHtml(lock.extensionRule || "Do not add recursive SLA workflows after v1.0.")}</small>
    </section>
  `;
}

function renderEffectQualitySlaActionAutoApprovalPerformance(performance = {}) {
  const summary = performance.summary || {};
  const aggregates = performance.aggregates || {};
  const items = performance.items || [];
  const candidates = performance.policyAdjustmentCandidates || [];
  const workflow = performance.policyAdjustmentWorkflow || {};
  const workflowItems = workflow.items || [];
  const effectivenessItems = performance.policyEffectiveness?.items || [];
  if (!summary.total && !items.length && !candidates.length && !workflowItems.length && !effectivenessItems.length) {
    return `
      <div class="sla-rereview-action-queue">
        <div class="calibration-sla-actions-head">
          <div>
            <strong>Effect-quality auto-approval performance</strong>
            <span>No auto-approved effect-quality corrections have post-assessment evidence yet.</span>
          </div>
        </div>
        ${renderInternalQualitySlaLock(performance.internalQualityLock || {})}
        <div class="empty">No effect-quality auto-approval performance rows yet.</div>
      </div>
    `;
  }
  return `
    <div class="sla-rereview-action-queue">
      <div class="calibration-sla-actions-head">
        <div>
          <strong>Effect-quality auto-approval performance</strong>
          <span>Auto-approved correction outcomes are linked to later reassessment history, saved as proposed policy changes, and applied only after approval.</span>
        </div>
      </div>
      ${renderInternalQualitySlaLock(performance.internalQualityLock || {})}
      <div class="sla-policy-quality-summary">
        <span><strong>${fmtNumber(summary.total || 0)}</strong><em>Auto approvals</em></span>
        <span><strong>${fmtNumber(summary.evaluated || 0)}</strong><em>Evaluated</em></span>
        <span><strong>${fmtPercent(summary.successRate || 0)}</strong><em>Success</em></span>
        <span><strong>${fmtPercent(summary.rollbackRate || 0)}</strong><em>Rollback</em></span>
        <span><strong>${fmtPercent(summary.recurrenceRate || 0)}</strong><em>Recurrence</em></span>
        <span><strong>${fmtPercent(summary.falsePositiveRate || 0)}</strong><em>False positive</em></span>
        <span><strong>${fmtNumber(summary.avgEffectScore || 0)}</strong><em>Avg score</em></span>
      </div>
      <div class="sla-auto-approval-grid">
        ${renderEffectQualitySlaActionAutoPolicyWorkflow(workflow)}
        ${renderEffectQualitySlaActionAutoPolicyEffectiveness(performance.policyEffectiveness || {})}
        ${renderSlaAutoApprovalPolicyCandidates(candidates)}
        <section>
          <strong>By month</strong>
          ${renderSlaAutoApprovalAggregateRows(aggregates.byMonth || [], "No monthly effect-quality auto-approval performance yet.")}
        </section>
        <section>
          <strong>By root metric</strong>
          ${renderSlaAutoApprovalAggregateRows(aggregates.byIssue || [], "No root-metric effect-quality auto-approval performance yet.")}
        </section>
        <section>
          <strong>By assignee</strong>
          ${renderSlaAutoApprovalAggregateRows(aggregates.byOwner || [], "No assignee effect-quality auto-approval performance yet.")}
        </section>
        ${renderSlaAutoApprovalPerformanceItems(items)}
      </div>
    </div>
  `;
}

function renderSlaQualityRereviewActionAutoPolicyLearningSlaActionReassessment(reassessment = {}) {
  const summary = reassessment.summary || {};
  const items = reassessment.items || [];
  const history = reassessment.history || {};
  if (!summary.total && !items.length) return "";
  return `
    <div class="sla-rereview-action-queue">
      <div class="calibration-sla-actions-head">
        <div>
          <strong>Effect quality SLA action reassessment</strong>
          <span>Completion snapshot versus current operational quality</span>
        </div>
      </div>
      <div class="sla-policy-quality-summary">
        <span><strong>${fmtNumber(summary.total || 0)}</strong><em>Reassessed</em></span>
        <span><strong>${fmtNumber(summary.avgEffectScore || 0)}</strong><em>Avg effect</em></span>
        <span><strong>${fmtNumber(summary.improved || 0)}</strong><em>Improved</em></span>
        <span><strong>${fmtNumber(summary.unchanged || 0)}</strong><em>Unchanged</em></span>
        <span><strong>${fmtNumber(summary.worse || 0)}</strong><em>Worse</em></span>
        <span><strong>${fmtNumber(summary.recurrence || 0)}</strong><em>Recurrence</em></span>
        <span><strong>${fmtNumber(summary.followUpNeeded || 0)}</strong><em>Follow-up</em></span>
      </div>
      ${items.length ? `
        <div class="sla-auto-approval-table">
          <table>
            <thead>
              <tr><th>Completed action</th><th>Outcome</th><th>Effect</th><th>Metric</th><th>Snapshot / current</th><th>Recurrence</th><th>Follow-up</th></tr>
            </thead>
            <tbody>
              ${items.slice(0, 20).map((item) => `
                <tr>
                  <td><strong>${escapeHtml(item.sourceLabel || item.actionId || "Action")}</strong><small>${escapeHtml(item.completedAt ? String(item.completedAt).slice(0, 10) : "-")} / ${escapeHtml(item.assignee || item.owner || "unassigned")}</small></td>
                  <td>${calibrationAuditQueueBadge(item.outcome || "unchanged", item.outcome === "improved" ? "good" : item.outcome === "worse" ? "danger" : "warning")}</td>
                  <td>${fmtNumber(item.effectScore || 0)}</td>
                  <td>${escapeHtml(item.metric?.label || item.issueKey || "-")}<small>${escapeHtml(item.rootMetric || "")}</small></td>
                  <td>${fmtNumber(item.baseline?.value ?? 0)} / ${fmtNumber(item.current?.value ?? 0)}<small>${renderSlaBadge(item.baseline?.sla || {})} -> ${renderSlaBadge(item.current?.sla || {})}</small></td>
                  <td>${calibrationAuditQueueBadge(item.recurrence ? "recurring" : "clear", item.recurrence ? "danger" : "good")}</td>
                  <td>
                    <small>${escapeHtml(item.followUpReason || "")}</small>
                    ${item.followUpCreated ? `<small>created ${escapeHtml(item.followUpActionId || "")}</small>` : item.followUpNeeded ? `<button class="secondary-button" type="button" data-sla-quality-rereview-auto-policy-learning-sla-followup-create="${escapeHtml(item.actionId || "")}">Create follow-up</button>` : ""}
                  </td>
                </tr>
              `).join("")}
            </tbody>
          </table>
        </div>
      ` : `<div class="empty">No completed effect-quality SLA actions have completion snapshots yet.</div>`}
      ${renderEffectQualityRereviewSlaActionReassessmentHistory(history)}
    </div>
  `;
}

function renderSlaQualityRereviewActionAutoPolicyLearningSlaActions(slaActions = {}) {
  const actions = slaActions.items || [];
  if (!actions.length) return "";
  const summary = slaActions.summary || {};
  const queue = slaActions.operationQueue || {};
  const reassessment = slaActions.postReassessment || {};
  const recommendationAdjustments = slaActions.recommendationAdjustments || {};
  const autoApprovalPerformance = slaActions.autoApprovalPerformance || {};
  return `
    <div class="calibration-sla-actions">
      <div class="calibration-sla-actions-head">
        <div>
          <strong>Effect quality learning re-review SLA action operations</strong>
          <span>${fmtNumber(summary.open || 0)} open / ${fmtNumber(summary.saved || 0)} saved / ${fmtNumber(summary.generated || 0)} generated</span>
        </div>
      </div>
      ${renderSlaQualityRereviewActionAutoPolicyLearningSlaActionQueue(queue)}
      ${renderSlaQualityRereviewActionAutoPolicyLearningSlaActionReassessment(reassessment)}
      ${renderEffectQualitySlaActionRecommendationAdjustments(recommendationAdjustments)}
      ${renderEffectQualitySlaActionAutoApprovalPerformance(autoApprovalPerformance)}
      <div class="calibration-sla-action-list">
        ${actions.slice(0, 12).map((action) => `
          <article
            class="calibration-sla-action ${escapeHtml(action.slaLevel || "warning")}"
            data-sla-quality-rereview-auto-policy-learning-sla-action-id="${escapeHtml(action.actionId || "")}"
            data-sla-quality-rereview-auto-policy-learning-sla-action-source-key="${escapeHtml(action.sourceKey || "")}"
            data-sla-quality-rereview-auto-policy-learning-sla-action-source-type="${escapeHtml(action.sourceType || "summary")}"
            data-sla-quality-rereview-auto-policy-learning-sla-action-source-label="${escapeHtml(action.sourceLabel || "")}"
            data-sla-quality-rereview-auto-policy-learning-sla-action-month="${escapeHtml(action.month || "")}"
            data-sla-quality-rereview-auto-policy-learning-sla-action-owner="${escapeHtml(action.owner || "")}"
            data-sla-quality-rereview-auto-policy-learning-sla-action-level="${escapeHtml(action.slaLevel || "")}"
            data-sla-quality-rereview-auto-policy-learning-sla-action-issue-key="${escapeHtml(action.issueKey || "")}"
            data-sla-quality-rereview-auto-policy-learning-sla-action-severity="${escapeHtml(action.severity || "")}"
            data-sla-quality-rereview-auto-policy-learning-sla-action-root-metric="${escapeHtml(action.rootMetric || "")}"
            data-sla-quality-rereview-auto-policy-learning-sla-action-source-metrics="${escapeHtml(JSON.stringify(action.sourceMetrics || {}))}">
            <div>
              <strong>${escapeHtml(action.sourceLabel || action.sourceType || "Effect quality re-review SLA")}</strong>
              <span>
                ${renderSlaBadge({ level: action.slaLevel, label: action.slaLevel === "danger" ? "Risk" : "Watch" })}
                ${calibrationAuditQueueBadge(action.priority || "medium", action.priority === "urgent" || action.priority === "high" ? "danger" : "warning")}
                ${calibrationAuditQueueBadge(action.candidateStatus || (action.isSaved ? "saved" : "generated"), action.isSaved ? "good" : "neutral")}
                ${escapeHtml(action.rootMetric || action.issueKey || "")}
              </span>
            </div>
            <p>${escapeHtml(action.recommendation || "")}</p>
            ${renderSlaHistoryAdjustment(action.historyAdjustment)}
            ${renderEffectQualitySlaActionCompletionSnapshot(action.completionQualitySnapshot)}
            <div class="calibration-sla-action-grid">
              <label>
                <span>Priority</span>
                <select data-sla-quality-rereview-auto-policy-learning-sla-action-field="priority">${slaActionPriorityOptions(action.priority)}</select>
              </label>
              <label>
                <span>Assignee</span>
                <input data-sla-quality-rereview-auto-policy-learning-sla-action-field="assignee" value="${escapeHtml(action.assignee || action.owner || "")}">
              </label>
              <label>
                <span>Target</span>
                <input type="date" data-sla-quality-rereview-auto-policy-learning-sla-action-field="targetDate" value="${escapeHtml(action.targetDate || "")}">
              </label>
              <label>
                <span>Status</span>
                <select data-sla-quality-rereview-auto-policy-learning-sla-action-field="status">${slaActionStatusOptions(action.status)}</select>
              </label>
              <label class="wide">
                <span>Recommended action</span>
                <textarea data-sla-quality-rereview-auto-policy-learning-sla-action-field="recommendation" rows="2">${escapeHtml(action.recommendation || "")}</textarea>
              </label>
              <button class="secondary-button" type="button" data-sla-quality-rereview-auto-policy-learning-sla-action-save="${escapeHtml(action.actionId || "")}">Save action</button>
            </div>
          </article>
        `).join("")}
      </div>
    </div>
  `;
}

function renderSlaQualityRereviewActionAutoPolicyLearningOperationalQuality(quality = {}) {
  const summary = quality.summary || {};
  const monthly = quality.monthly || [];
  const owners = quality.ownerPerformance || [];
  const warningSummary = quality.slaWarningSummary || {};
  const monthlyWarnings = warningSummary.monthly || {};
  const ownerWarnings = warningSummary.owners || {};
  const criteria = quality.slaCriteria || {};
  const normalCriteria = criteria.normal || {};
  const warningCriteria = criteria.warning || {};
  if (!summary.total && !monthly.length && !owners.length) return "";
  return `
    <div class="sla-policy-quality-summary">
      <span><strong>${renderSlaBadge(summary.sla || {})}</strong><em>Ops SLA</em></span>
      <span><strong>${slaQualityRereviewHours(summary.avgProcessingHours)}</strong><em>Avg processing</em></span>
      <span><strong>${fmtNumber(summary.statusTransitionCount || 0)}</strong><em>Status changes</em></span>
      <span><strong>${fmtPercent(summary.reopenRate || 0)}</strong><em>Reopen rate</em></span>
      <span><strong>${fmtNumber(summary.delayedIncompleteItems || 0)}</strong><em>Overdue open</em></span>
      <span><strong>${fmtNumber(summary.activeLinkIssue || summary.activeLinkUnprocessed || 0)}</strong><em>Link issue</em></span>
      <span><strong>${fmtNumber(summary.activeLinkFailed || 0)}</strong><em>Link failed</em></span>
      <span><strong>${fmtPercent(summary.deactivateRate || 0)}</strong><em>Deactivate</em></span>
      <span><strong>${fmtPercent(summary.modifiedProposalRate || 0)}</strong><em>Modify proposal</em></span>
      <span><strong>${fmtNumber(monthlyWarnings.danger || 0)} / ${fmtNumber(monthlyWarnings.warning || 0)}</strong><em>Month risk/watch</em></span>
      <span><strong>${fmtNumber(ownerWarnings.danger || 0)} / ${fmtNumber(ownerWarnings.warning || 0)}</strong><em>Owner risk/watch</em></span>
    </div>
    <div class="calibration-audit-sla-improvements">
      <strong>Operational quality needs</strong>
      ${renderSlaImprovementItems(summary.sla || {})}
    </div>
    <div class="calibration-audit-sla-improvements">
      <strong>SLA criteria</strong>
      <span>Normal: avg ${slaQualityRereviewHours(normalCriteria.avgProcessingHoursMax)} or less / reopen ${fmtPercent(normalCriteria.reopenRateMax || 0)} or less / no overdue or link-open items / owner completion ${fmtPercent(normalCriteria.ownerCompletionRateMin || 0)} or higher</span>
      <span>Watch: avg up to ${slaQualityRereviewHours(warningCriteria.avgProcessingHoursMax)} / reopen up to ${fmtPercent(warningCriteria.reopenRateMax || 0)} / overdue up to ${fmtNumber(warningCriteria.delayedIncompleteItemsMax ?? 0)} / link issues up to ${fmtNumber(warningCriteria.activeLinkIssueMax ?? warningCriteria.activeLinkUnprocessedMax ?? 0)}</span>
    </div>
    ${renderSlaQualityRereviewActionAutoPolicyLearningSlaActions(quality.slaActions || {})}
    ${monthly.length ? `
      <div class="sla-auto-approval-table">
        <table>
          <thead>
            <tr><th>Month</th><th>SLA</th><th>Total</th><th>Completed</th><th>Completion</th><th>Avg time</th><th>Status changes</th><th>Reopen</th><th>Deactivate</th><th>Modify</th><th>Link issue</th><th>Needs</th></tr>
          </thead>
          <tbody>
            ${monthly.map((row) => `
              <tr>
                <td>${escapeHtml(row.label || row.key || "-")}</td>
                <td>${renderSlaBadge(row.sla || {})}</td>
                <td>${fmtNumber(row.total || 0)}</td>
                <td>${fmtNumber(row.completed || 0)}</td>
                <td>${fmtPercent(row.completionRate || 0)}</td>
                <td>${slaQualityRereviewHours(row.avgProcessingHours)}</td>
                <td>${fmtNumber(row.statusTransitionCount || 0)}</td>
                <td>${fmtNumber(row.reopenCount || 0)} / ${fmtPercent(row.reopenRate || 0)}</td>
                <td>${fmtNumber(row.deactivated || 0)} / ${fmtPercent(row.deactivateRate || 0)}</td>
                <td>${fmtNumber(row.modifiedProposed || 0)} / ${fmtPercent(row.modifiedProposalRate || 0)}</td>
                <td>${fmtNumber(row.activeLinkIssue || row.activeLinkUnprocessed || 0)} / ${fmtNumber(row.activeLinkFailed || 0)} failed</td>
                <td>${renderSlaImprovementItems(row.sla || {})}</td>
              </tr>
            `).join("")}
          </tbody>
        </table>
      </div>
    ` : ""}
    ${owners.length ? `
      <div class="sla-auto-approval-table">
        <table>
          <thead>
            <tr><th>Owner</th><th>SLA</th><th>Total</th><th>Completed</th><th>Completion</th><th>Avg time</th><th>Transitions</th><th>Reopen</th><th>Maintained</th><th>Deactivated</th><th>Modified</th><th>Link issue</th><th>Needs</th></tr>
          </thead>
          <tbody>
            ${owners.map((row) => `
              <tr>
                <td>${escapeHtml(row.label || row.key || "unassigned")}</td>
                <td>${renderSlaBadge(row.sla || {})}</td>
                <td>${fmtNumber(row.total || 0)}</td>
                <td>${fmtNumber(row.completed || 0)}</td>
                <td>${fmtPercent(row.completionRate || 0)}</td>
                <td>${slaQualityRereviewHours(row.avgProcessingHours)}</td>
                <td>${fmtNumber(row.statusTransitionCount || 0)}</td>
                <td>${fmtNumber(row.reopenCount || 0)} / ${fmtPercent(row.reopenRate || 0)}</td>
                <td>${fmtNumber(row.maintained || 0)} / ${fmtPercent(row.maintainRate || 0)}</td>
                <td>${fmtNumber(row.deactivated || 0)} / ${fmtPercent(row.deactivateRate || 0)}</td>
                <td>${fmtNumber(row.modifiedProposed || 0)} / ${fmtPercent(row.modifiedProposalRate || 0)}</td>
                <td>${fmtNumber(row.activeLinkIssue || row.activeLinkUnprocessed || 0)} / ${fmtNumber(row.activeLinkFailed || 0)} failed</td>
                <td>${renderSlaImprovementItems(row.sla || {})}</td>
              </tr>
            `).join("")}
          </tbody>
        </table>
      </div>
    ` : ""}
  `;
}

function renderSlaQualityRereviewActionAutoPolicyLearningRereviewQueue(queue = {}) {
  const summary = queue.summary || {};
  const items = queue.items || [];
  const exportUrls = queue.exportUrls || {};
  const operationalQuality = queue.operationalQuality || {};
  if (!summary.total && !items.length) {
    return `
      <section class="sla-policy-candidate-quality">
        <strong>Quality learning re-review queue</strong>
        <div class="empty">No saved quality learning re-review items match the current filters.</div>
      </section>
    `;
  }
  return `
    <section class="sla-policy-candidate-quality">
      <div class="learning-calibration-head">
        <div>
          <strong>Quality learning re-review queue</strong>
          <span>Change history, completion linkage, filtered CSV/JSON exports</span>
        </div>
        <div class="learning-calibration-actions">
          <a class="ghost-button" href="${escapeHtml(exportUrls.json || "#")}" target="_blank" rel="noreferrer">JSON</a>
          <a class="ghost-button" href="${escapeHtml(exportUrls.csv || "#")}" target="_blank" rel="noreferrer">CSV</a>
        </div>
      </div>
      <div class="sla-policy-quality-summary">
        <span><strong>${fmtNumber(summary.total || 0)}</strong><em>Queue</em></span>
        <span><strong>${fmtNumber(summary.open || 0)}</strong><em>Open</em></span>
        <span><strong>${fmtNumber(summary.inProgress || 0)}</strong><em>In progress</em></span>
        <span><strong>${fmtNumber(summary.completed || 0)}</strong><em>Completed</em></span>
        <span><strong>${fmtNumber(summary.overdue || 0)}</strong><em>Overdue</em></span>
        <span><strong>${fmtNumber(summary.avgPerformanceScore || 0)}</strong><em>Avg score</em></span>
      </div>
      ${renderSlaQualityRereviewActionAutoPolicyLearningOperationalQuality(operationalQuality)}
      ${items.length ? items.map(renderSlaQualityRereviewActionAutoPolicyLearningRereviewCard).join("") : `<div class="empty">No quality learning re-review queue items match the current filters.</div>`}
    </section>
  `;
}

function renderSlaQualityRereviewActionAutoPolicyLearningRereviewCard(item = {}) {
  const tone = item.status === "completed" ? "good" : item.dueState === "overdue" || Number(item.performanceScore || 0) <= 35 ? "danger" : item.dueState === "this_week" ? "warning" : "neutral";
  const history = item.changeHistorySummary || {};
  const logs = Array.isArray(item.changeLogs) ? item.changeLogs : [];
  const linkedHistory = Array.isArray(item.linkedCalibrationHistory) ? item.linkedCalibrationHistory : [];
  const operational = item.operationalMetric || {};
  const statusOptions = [
    { value: "open", label: "Open" },
    { value: "in_progress", label: "In progress" },
    { value: "completed", label: "Completed" },
    { value: "deferred", label: "Deferred" },
    { value: "dismissed", label: "Dismissed" }
  ];
  const actionOptions = [
    { value: "watch", label: "Watch" },
    { value: "maintain_active", label: "Maintain active" },
    { value: "deactivate_active", label: "Deactivate active" },
    { value: "propose_modified_calibration", label: "Propose modified" },
    { value: "none", label: "No action" }
  ];
  const after = item.after || item.sourceSnapshot?.after || {};
  const linked = item.linkedCalibrationResult || null;
  return `
    <article class="sla-auto-policy-adjustment ${escapeHtml(tone)}" data-sla-quality-rereview-auto-policy-learning-rereview-card="${escapeHtml(item.rereviewId || "")}">
      <div class="sla-recommendation-adjustment-head">
        <div>
          <strong>${escapeHtml(item.candidateType || "quality learning")} / ${escapeHtml(item.target || item.issueKey || "-")}</strong>
          <span>
            ${calibrationAuditQueueBadge(item.status || "open", item.status === "completed" ? "good" : item.status === "dismissed" ? "muted" : tone)}
            ${calibrationAuditQueueBadge(item.dueState || "no_due", item.dueState === "overdue" ? "danger" : item.dueState === "this_week" ? "warning" : "neutral")}
            ${calibrationAuditQueueBadge(`score ${fmtNumber(item.performanceScore || 0)}`, Number(item.performanceScore || 0) <= 45 ? "danger" : "neutral")}
            ${calibrationAuditQueueBadge(item.followUpActionType || "watch", "neutral")}
          </span>
        </div>
        <small>${escapeHtml(item.rereviewId || "")}</small>
      </div>
      <div class="sla-recommendation-adjustment-copy">
        <span><strong>Reason</strong><em>${escapeHtml(item.reReviewReason || "-")}</em></span>
        <span><strong>Calibration</strong><em>${escapeHtml(item.calibrationId || "-")} / ${escapeHtml(item.decisionType || "-")} / ${escapeHtml(item.decisionAt || "-")}</em></span>
        <span><strong>Current quality</strong><em>success ${fmtPercent(after.approvalSuccessRate || 0)} / repeat ${fmtPercent(after.repeatRecommendationRate || 0)} / rejection ${fmtPercent(after.rejectionRate || 0)}</em></span>
        <span><strong>Change history</strong><em>${fmtNumber(history.totalLogs || 0)} logs / latest ${escapeHtml(history.latestChangedAt || "-")} / ${escapeHtml(history.changedFieldSummary || "no field changes")}</em></span>
        <span><strong>Operations</strong><em>${slaQualityRereviewHours(operational.processingHours)} / ${fmtNumber(operational.statusTransitionCount || 0)} transitions / ${fmtNumber(operational.reopenCount || 0)} reopens / ${escapeHtml(operational.linkedCalibrationResult || "none")}</em></span>
        ${linked ? `<span><strong>Linked result</strong><em>${escapeHtml(linked.actionType || "-")} / ${escapeHtml(linked.previousStatus || "-")} -> ${escapeHtml(linked.nextStatus || "-")} / ${escapeHtml(linked.changedAt || "-")}</em></span>` : ""}
      </div>
      <div class="sla-recommendation-adjustment-review">
        <label class="field">
          <span>Status</span>
          ${renderSlaQualityRereviewSelect("auto-policy-learning-rereview-status", item.status || "open", statusOptions)}
        </label>
        <label class="field">
          <span>Owner</span>
          <input data-sla-quality-rereview-auto-policy-learning-rereview-owner type="text" value="${escapeHtml(item.owner || "")}" placeholder="owner">
        </label>
        <label class="field">
          <span>Due date</span>
          <input data-sla-quality-rereview-auto-policy-learning-rereview-due-date type="date" value="${escapeHtml(item.dueDate || "")}">
        </label>
        <label class="field">
          <span>Follow-up</span>
          ${renderSlaQualityRereviewSelect("auto-policy-learning-rereview-follow-up-action-type", item.followUpActionType || "watch", actionOptions)}
        </label>
        <label class="field wide">
          <span>Memo</span>
          <textarea data-sla-quality-rereview-auto-policy-learning-rereview-memo rows="2" placeholder="review note or completion reason">${escapeHtml(item.memo || "")}</textarea>
        </label>
        <div>
          <button class="secondary-button" type="button" data-sla-quality-rereview-auto-policy-learning-rereview-save="${escapeHtml(item.rereviewId || "")}">Save</button>
        </div>
      </div>
      ${item.completedAt ? `<small class="sla-recommendation-adjustment-review-log">completed by ${escapeHtml(item.completedBy || "-")} at ${escapeHtml(item.completedAt || "-")} / ${escapeHtml(item.completionResult || "-")}</small>` : ""}
      ${linkedHistory.length ? `
        <div class="sla-policy-repeat-list">
          ${linkedHistory.map((entry) => {
            const link = entry.linkedCalibration || {};
            return `
              <span class="good">
                <strong>Active learning linkage</strong>
                <em>${escapeHtml(link.actionType || entry.eventType || "-")} / ${escapeHtml(link.previousStatus || "-")} -> ${escapeHtml(link.nextStatus || "-")}</em>
                <small>${escapeHtml(link.calibrationId || item.calibrationId || "-")} / ${escapeHtml(entry.changedBy || link.changedBy || "-")} / ${escapeHtml(entry.changedAt || link.changedAt || "-")}</small>
              </span>
            `;
          }).join("")}
        </div>
      ` : ""}
      ${logs.length ? `
        <div class="sla-policy-repeat-list">
          ${logs.map((log) => `
            <span class="${escapeHtml(log.eventType === "completed" ? "good" : "neutral")}">
              <strong>${escapeHtml(log.eventType || "updated")} / ${escapeHtml(log.changedBy || "-")}</strong>
              <em>${escapeHtml((log.changedFields || []).join(", ") || "active learning linkage")}</em>
              <small>${escapeHtml(log.changedAt || "-")} / ${escapeHtml(log.completionResult || "no completion")}</small>
            </span>
          `).join("")}
        </div>
      ` : ""}
    </article>
  `;
}

function renderSlaQualityRereviewActionAutoPolicyLearningPerformance(performance = {}) {
  const summary = performance.summary || {};
  const items = performance.items || [];
  const reReviewCandidates = performance.reReviewCandidates || [];
  if (!summary.total && !items.length && !reReviewCandidates.length) {
    return `
      <section class="sla-policy-candidate-quality">
        <strong>Quality learning performance</strong>
        <div class="empty">No reviewed quality learning performance data yet.</div>
      </section>
    `;
  }
  return `
    <section class="sla-policy-candidate-quality">
      <strong>Quality learning performance</strong>
      <div class="sla-policy-quality-summary">
        <span><strong>${fmtNumber(summary.reviewed || 0)}</strong><em>Reviewed</em></span>
        <span><strong>${fmtNumber(summary.active || 0)}</strong><em>Active</em></span>
        <span><strong>${fmtNumber(summary.weakActive || 0)}</strong><em>Weak active</em></span>
        <span><strong>${fmtNumber(summary.avgPerformanceScore || 0)}</strong><em>Avg score</em></span>
        <span><strong>${deltaText(summary.avgApprovalSuccessDelta || 0)}</strong><em>Success delta</em></span>
        <span><strong>${deltaText(summary.avgRepeatDelta || 0)}</strong><em>Repeat delta</em></span>
      </div>
      ${reReviewCandidates.length ? `
        <div class="sla-policy-repeat-list">
          ${reReviewCandidates.map(renderSlaQualityRereviewActionAutoPolicyLearningRereviewCandidate).join("")}
        </div>
      ` : `<div class="empty">No active quality learning re-review candidates yet.</div>`}
      ${renderSlaQualityRereviewActionAutoPolicyLearningPerformanceRows(performance.byDecision || [], "No decision performance rows yet.")}
      ${renderSlaQualityRereviewActionAutoPolicyLearningPerformanceRows(performance.byType || [], "No candidate-type performance rows yet.")}
      ${items.length ? items.slice(0, 8).map(renderSlaQualityRereviewActionAutoPolicyLearningPerformanceCard).join("") : ""}
    </section>
  `;
}

function renderSlaQualityRereviewActionAutoPolicyAdjustmentCard(item = {}) {
  const tone = slaAutoPolicyAdjustmentTone(item);
  const before = item.beforePolicy || {};
  const after = item.afterPolicy || {};
  const impact = item.expectedImpact || {};
  const sourceContext = item.sourceContext || {};
  const learning = item.qualityLearningAdjustment || sourceContext.qualityLearningAdjustment || {};
  const previousQuality = learning.previousQuality || {};
  const fromPostEffect = String(sourceContext.source || "").includes("post_effect") || Boolean(sourceContext.policyAdjustmentId && sourceContext.suggestionType);
  return `
    <article class="sla-auto-policy-adjustment ${escapeHtml(tone)}" data-sla-quality-rereview-action-auto-policy-adjustment-card="${escapeHtml(item.policyAdjustmentId || "")}">
      <div class="sla-recommendation-adjustment-head">
        <div>
          <strong>${escapeHtml(item.target || item.issueKey || item.candidateType || "Re-review policy adjustment")}</strong>
          <span>
            ${calibrationAuditQueueBadge(item.status || "proposed", item.status === "approved" ? "good" : item.status === "rejected" ? "muted" : tone)}
            ${calibrationAuditQueueBadge(item.priority || "medium", tone)}
            ${calibrationAuditQueueBadge(item.candidateType || "policy", "neutral")}
            ${fromPostEffect ? calibrationAuditQueueBadge("post-effect", "warning") : ""}
            ${item.duplicateStatus ? calibrationAuditQueueBadge(item.duplicateStatus, item.duplicateStatus === "created" ? "good" : "warning") : ""}
          </span>
        </div>
        <small>${escapeHtml(item.policyAdjustmentId || "")}</small>
      </div>
      <p>${escapeHtml(item.basis || "")}</p>
      <div class="sla-auto-policy-impact">
        ${renderSlaAutoPolicyValue("Enabled", before.issueAutoApprovalEnabled ? "yes" : "no", after.issueAutoApprovalEnabled ? "yes" : "no")}
        ${renderSlaAutoPolicyValue("Min samples", before.minSampleSize, after.minSampleSize)}
        ${renderSlaAutoPolicyValue("Past approval", before.minHistoricalApprovalSuccessRate, after.minHistoricalApprovalSuccessRate, "%")}
        ${renderSlaAutoPolicyValue("Priority step", before.maxPriorityStepChange, after.maxPriorityStepChange)}
        <span class="${Number(impact.expectedSuccessRateChange || 0) ? "changed" : ""}">
          <strong>Expected success</strong>
          <em>${fmtPercent(impact.currentSuccessRate || 0)} -> ${fmtPercent(impact.expectedSuccessRate || 0)} (${Number(impact.expectedSuccessRateChange || 0) >= 0 ? "+" : ""}${fmtNumber(impact.expectedSuccessRateChange || 0)}p)</em>
        </span>
        <span>
          <strong>Impact scope</strong>
          <em>${escapeHtml(impact.scope || "issue_policy")} / evaluated ${fmtNumber(impact.evaluated || 0)}</em>
        </span>
      </div>
      <div class="sla-recommendation-adjustment-copy">
        <span><strong>Recommendation</strong><em>${escapeHtml(item.recommendation || "No recommendation text.")}</em></span>
        <span><strong>Patch</strong><em>${escapeHtml(JSON.stringify(item.policyPatch || {}))}</em></span>
        ${item.sourcePolicyAdjustmentId || sourceContext.source ? `
          <span><strong>Effect source</strong><em>${escapeHtml(item.sourcePolicyAdjustmentId || sourceContext.policyAdjustmentId || "-")} / ${escapeHtml(item.sourceSuggestionType || sourceContext.suggestionType || "-")} / ${escapeHtml(item.sourceEffectOutcome || sourceContext.outcome || "-")} / score ${escapeHtml(item.sourceEffectScore ?? sourceContext.effectScore ?? "-")}</em></span>
        ` : ""}
        ${learning.reason ? `
          <span><strong>Quality learning</strong><em>${escapeHtml(learning.status || "none")} / ${learning.active ? "active" : "pending"} / ${escapeHtml(learning.direction || "neutral")} / ${escapeHtml(learning.priorityBefore || "-")} -> ${escapeHtml(learning.priorityAfter || "-")} (suggested ${escapeHtml(learning.suggestedPriorityAfter || "-")}) / success ${fmtPercent(previousQuality.approvalSuccessRate || 0)} / repeat ${fmtPercent(previousQuality.repeatRecommendationRate || 0)} / rejection ${fmtPercent(previousQuality.rejectionRate || 0)}${previousQuality.topRejectionReason ? ` / top rejection: ${escapeHtml(previousQuality.topRejectionReason)}` : ""}</em></span>
        ` : ""}
        ${item.duplicateStatus ? `<span><strong>Duplicate status</strong><em>${escapeHtml(item.duplicateStatus || "-")}${item.duplicateOfPolicyAdjustmentId ? ` / ${escapeHtml(item.duplicateOfPolicyAdjustmentId)}` : ""}</em></span>` : ""}
      </div>
      ${renderSlaQualityRereviewActionAutoPolicyReview(item)}
    </article>
  `;
}

function renderSlaQualityRereviewActionAutoPolicyWorkflow(workflow = {}) {
  const summary = workflow.summary || {};
  const activePolicy = workflow.activePolicy || {};
  const items = workflow.items || [];
  const proposed = items.filter((item) => item.status === "proposed");
  const history = items.filter((item) => item.status !== "proposed");
  return `
    <section>
      <strong>Policy review queue</strong>
      <div class="calibration-audit-queue-summary compact">
        <span><strong>${fmtNumber(summary.proposed || 0)}</strong><em>Proposed</em></span>
        <span><strong>${fmtNumber(summary.approved || 0)}</strong><em>Approved</em></span>
        <span><strong>${fmtNumber(summary.rejected || 0)}</strong><em>Rejected</em></span>
        <span><strong>${fmtNumber(summary.expectedSuccessRateChangeAvg || 0)}p</strong><em>Avg impact</em></span>
        <span><strong>${escapeHtml(activePolicy.policyVersion || "-")}</strong><em>Active policy</em></span>
        <span><strong>${fmtNumber(activePolicy.activeAdjustmentIds?.length || 0)}</strong><em>Applied patches</em></span>
      </div>
      ${proposed.length ? proposed.map(renderSlaQualityRereviewActionAutoPolicyAdjustmentCard).join("") : `<div class="empty">No proposed re-review auto-approval policy adjustments match the current performance report.</div>`}
    </section>
    <section>
      <strong>Policy approval history</strong>
      ${history.length ? history.map(renderSlaQualityRereviewActionAutoPolicyAdjustmentCard).join("") : `<div class="empty">No approved or rejected re-review auto-approval policy adjustments yet.</div>`}
    </section>
  `;
}

function slaAutoPolicyEffectTone(item = {}) {
  if (item.outcome === "improved") return "good";
  if (item.outcome === "worse" || item.rollbackSuggested) return "danger";
  if (item.outcome === "pending" || item.additionalAdjustmentSuggested) return "warning";
  return "neutral";
}

function deltaText(value = 0, suffix = "p") {
  const number = Number(value || 0);
  return `${number >= 0 ? "+" : ""}${fmtNumber(number)}${suffix}`;
}

function slaAutoPolicyEffectManualReviewLowerIsBetter(candidateType = "") {
  return ![
    "tighten_issue_policy",
    "additional_tightening_policy",
    "tighten_rereview_action_auto_policy",
    "additional_rereview_tightening",
    "tighten_effect_quality_action_auto_policy",
    "additional_effect_quality_tightening"
  ].includes(String(candidateType || "").trim());
}

function renderSlaPolicyEffectMetric(label, beforeValue, afterValue, deltaValue, lowerIsBetter = false, suffix = "%") {
  const delta = Number(deltaValue || 0);
  const improved = lowerIsBetter ? delta < 0 : delta > 0;
  const worsened = lowerIsBetter ? delta > 0 : delta < 0;
  const tone = improved ? "good" : worsened ? "danger" : "neutral";
  return `
    <span class="${escapeHtml(tone)}">
      <strong>${escapeHtml(label)}</strong>
      <em>${fmtNumber(beforeValue || 0)}${suffix} -> ${fmtNumber(afterValue || 0)}${suffix} (${deltaText(delta)})</em>
    </span>
  `;
}

function renderSlaPolicyEffectSuggestions(suggestions = []) {
  return `
    <div class="sla-policy-effect-suggestions">
      ${suggestions.map((item) => {
        const proposal = item.generatedProposal || null;
        const qualitySummary = slaPolicyQualityCalibrationSummary(proposal?.qualityCalibration || {});
        return `
        <span class="${escapeHtml(item.priority === "high" ? "danger" : item.priority === "medium" ? "warning" : "good")}">
          <strong>${escapeHtml(item.label || item.type || "Suggestion")}</strong>
          <em>${escapeHtml(item.reason || "")}</em>
          ${proposal ? `<small>${escapeHtml(item.generatedCandidateType || "policy_candidate")} -> ${escapeHtml(proposal.policyAdjustmentId || "-")} / ${escapeHtml(proposal.status || "-")} / ${escapeHtml(proposal.duplicateStatus || "created")}${proposal.duplicateOfPolicyAdjustmentId ? ` / duplicate of ${escapeHtml(proposal.duplicateOfPolicyAdjustmentId)}` : ""}</small>` : ""}
          ${qualitySummary ? `<small>${escapeHtml(qualitySummary)}</small>` : ""}
        </span>
      `;
      }).join("")}
    </div>
  `;
}

function renderSlaAutoPolicyEffectivenessCard(item = {}) {
  const tone = slaAutoPolicyEffectTone(item);
  const before = item.before || {};
  const after = item.after || {};
  const delta = item.delta || {};
  return `
    <article class="sla-auto-policy-effectiveness-card ${escapeHtml(tone)}">
      <div class="sla-recommendation-adjustment-head">
        <div>
          <strong>${escapeHtml(item.target || item.issueKey || item.candidateType || "Policy effect")}</strong>
          <span>
            ${calibrationAuditQueueBadge(item.outcome || "pending", tone)}
            ${calibrationAuditQueueBadge(`score ${item.effectScore ?? "-"}`, tone)}
            ${calibrationAuditQueueBadge(item.candidateType || "policy", "neutral")}
            ${item.rollbackSuggested ? calibrationAuditQueueBadge("rollback suggested", "danger") : ""}
            ${item.additionalAdjustmentSuggested ? calibrationAuditQueueBadge("follow-up suggested", "warning") : ""}
          </span>
        </div>
        <small>${escapeHtml(item.approvedAt || "-")} / ${fmtNumber(item.windowDays || 0)} days</small>
      </div>
      <div class="sla-policy-effect-metrics">
        ${renderSlaPolicyEffectMetric("Success", before.successRate, after.successRate, delta.successRate, false)}
        ${renderSlaPolicyEffectMetric("False positive", before.falsePositiveRate, after.falsePositiveRate, delta.falsePositiveRate, true)}
        ${renderSlaPolicyEffectMetric("Rollback", before.rollbackRate, after.rollbackRate, delta.rollbackRate, true)}
        ${renderSlaPolicyEffectMetric("Recurrence", before.recurrenceRate, after.recurrenceRate, delta.recurrenceRate, true)}
        ${renderSlaPolicyEffectMetric("Manual review", before.manualReviewConversionRate, after.manualReviewConversionRate, delta.manualReviewConversionRate, slaAutoPolicyEffectManualReviewLowerIsBetter(item.candidateType))}
        ${renderSlaPolicyEffectMetric("Avg effect", before.avgEffectScore, after.avgEffectScore, delta.avgEffectScore, false, "")}
      </div>
      <div class="sla-recommendation-adjustment-copy">
        <span><strong>Before volume</strong><em>${fmtNumber(before.totalProposals || 0)} proposals / ${fmtNumber(before.autoApprovals || 0)} auto approvals / ${fmtNumber(before.evaluatedAutoApprovals || 0)} evaluated</em></span>
        <span><strong>After volume</strong><em>${fmtNumber(after.totalProposals || 0)} proposals / ${fmtNumber(after.autoApprovals || 0)} auto approvals / ${fmtNumber(after.evaluatedAutoApprovals || 0)} evaluated</em></span>
      </div>
      ${renderSlaPolicyEffectSuggestions(item.suggestions || [])}
    </article>
  `;
}

function renderSlaQualityRereviewActionAutoPolicyEffectiveness(effectiveness = {}) {
  const summary = effectiveness.summary || {};
  const items = effectiveness.items || [];
  return `
    <section class="sla-auto-policy-effectiveness">
      <strong>Post-change policy effect</strong>
      <div class="calibration-audit-queue-summary compact">
        <span><strong>${fmtNumber(summary.total || 0)}</strong><em>Approved policies</em></span>
        <span><strong>${fmtNumber(summary.improved || 0)}</strong><em>Improved</em></span>
        <span><strong>${fmtNumber(summary.unchanged || 0)}</strong><em>Unchanged</em></span>
        <span><strong>${fmtNumber(summary.worse || 0)}</strong><em>Worse</em></span>
        <span><strong>${fmtNumber(summary.rollbackSuggested || 0)}</strong><em>Rollback suggestions</em></span>
        <span><strong>${fmtNumber(summary.additionalAdjustmentSuggested || 0)}</strong><em>Follow-up suggestions</em></span>
        <span><strong>${fmtNumber(summary.avgEffectScore || 0)}</strong><em>Avg effect</em></span>
      </div>
      ${renderSlaQualityRereviewActionAutoPolicyLearningWorkflow(effectiveness.qualityLearningWorkflow || {})}
      ${renderSlaQualityRereviewActionAutoPolicyLearningPerformance(effectiveness.qualityLearningPerformance || {})}
      ${renderSlaQualityRereviewActionAutoPolicyLearningRereviewQueue(effectiveness.qualityLearningRereviews || {})}
      ${renderSlaQualityRereviewActionAutoPolicyCandidateQuality(effectiveness.effectCandidateQuality || {})}
      ${items.length
        ? items.slice(0, 8).map(renderSlaAutoPolicyEffectivenessCard).join("")
        : `<div class="empty">No approved re-review policy effectiveness rows yet.</div>`}
    </section>
  `;
}

function renderSlaQualityRereviewActionAutoPolicyCandidateQuality(quality = {}) {
  const summary = quality.summary || {};
  const byType = quality.byType || [];
  const repeatItems = (quality.items || []).filter((item) => item.repeatRecommended).slice(0, 6);
  if (!summary.total && !byType.length) {
    return `
      <section class="sla-policy-candidate-quality">
        <strong>Re-review effect candidate quality</strong>
        <div class="empty">No reviewed re-review effect-based policy candidate quality data yet.</div>
      </section>
    `;
  }
  return `
    <section class="sla-policy-candidate-quality">
      <strong>Re-review effect candidate quality</strong>
      <div class="sla-policy-quality-summary">
        <span><strong>${fmtNumber(summary.total || 0)}</strong><em>Candidates</em></span>
        <span><strong>${fmtPercent(summary.approvalRate || 0)}</strong><em>Approval rate</em></span>
        <span><strong>${fmtPercent(summary.approvalSuccessRate || 0)}</strong><em>Approved success</em></span>
        <span><strong>${fmtNumber(summary.rejected || 0)}</strong><em>Rejected</em></span>
        <span><strong>${fmtNumber(summary.repeatRecommended || 0)}</strong><em>Repeat recommended</em></span>
      </div>
      <div class="sla-auto-approval-table">
        <table>
          <thead>
            <tr><th>Candidate type</th><th>Total</th><th>Approved</th><th>Rejected</th><th>Approval</th><th>Success</th><th>Repeat</th><th>Top rejection reason</th></tr>
          </thead>
          <tbody>
            ${byType.map((row) => `
              <tr>
                <td>${escapeHtml(row.candidateType || "-")}</td>
                <td>${fmtNumber(row.total || 0)}</td>
                <td>${fmtNumber(row.approved || 0)}</td>
                <td>${fmtNumber(row.rejected || 0)}</td>
                <td>${fmtPercent(row.approvalRate || 0)}</td>
                <td>${fmtPercent(row.approvalSuccessRate || 0)}</td>
                <td>${fmtNumber(row.repeatRecommended || 0)}</td>
                <td>${escapeHtml(row.rejectionReasons?.[0]?.reason || "-")}</td>
              </tr>
            `).join("")}
          </tbody>
        </table>
      </div>
      ${repeatItems.length ? `
        <div class="sla-policy-repeat-list">
          ${repeatItems.map((item) => `
            <span class="${escapeHtml(item.qualityOutcome === "failed" ? "danger" : item.status === "rejected" ? "warning" : "neutral")}">
              <strong>${escapeHtml(item.candidateType || "candidate")} / ${escapeHtml(item.target || item.issueKey || "-")}</strong>
              <em>${escapeHtml(item.repeatRecommendationReason || "Repeat review recommended.")}</em>
              <small>${escapeHtml(item.policyAdjustmentId || "-")} / ${escapeHtml(item.status || "-")} / ${escapeHtml(item.qualityOutcome || "-")} / post ${escapeHtml(item.postEffectOutcome || "-")}</small>
            </span>
          `).join("")}
        </div>
      ` : ""}
    </section>
  `;
}

function renderSlaPolicyCandidateQuality(quality = {}) {
  const summary = quality.summary || {};
  const byType = quality.byType || [];
  const repeatItems = (quality.items || []).filter((item) => item.repeatRecommended).slice(0, 6);
  if (!summary.total && !byType.length) {
    return `
      <section class="sla-policy-candidate-quality">
        <strong>Effect-based candidate quality</strong>
        <div class="empty">No effect-based policy candidate quality data yet.</div>
      </section>
    `;
  }
  return `
    <section class="sla-policy-candidate-quality">
      <strong>Effect-based candidate quality</strong>
      <div class="sla-policy-quality-summary">
        <span><strong>${fmtNumber(summary.total || 0)}</strong><em>Candidates</em></span>
        <span><strong>${fmtPercent(summary.approvalRate || 0)}</strong><em>Approval rate</em></span>
        <span><strong>${fmtPercent(summary.approvalSuccessRate || 0)}</strong><em>Approved success</em></span>
        <span><strong>${fmtNumber(summary.rejected || 0)}</strong><em>Rejected</em></span>
        <span><strong>${fmtNumber(summary.repeatRecommended || 0)}</strong><em>Repeat recommended</em></span>
      </div>
      <div class="sla-auto-approval-table">
        <table>
          <thead>
            <tr><th>Candidate type</th><th>Total</th><th>Approved</th><th>Rejected</th><th>Approval</th><th>Success</th><th>Repeat</th><th>Top rejection reason</th></tr>
          </thead>
          <tbody>
            ${byType.map((row) => `
              <tr>
                <td>${escapeHtml(row.candidateType || "-")}</td>
                <td>${fmtNumber(row.total || 0)}</td>
                <td>${fmtNumber(row.approved || 0)}</td>
                <td>${fmtNumber(row.rejected || 0)}</td>
                <td>${fmtPercent(row.approvalRate || 0)}</td>
                <td>${fmtPercent(row.approvalSuccessRate || 0)}</td>
                <td>${fmtNumber(row.repeatRecommended || 0)}</td>
                <td>${escapeHtml(row.rejectionReasons?.[0]?.reason || "-")}</td>
              </tr>
            `).join("")}
          </tbody>
        </table>
      </div>
      ${repeatItems.length ? `
        <div class="sla-policy-repeat-list">
          ${repeatItems.map((item) => `
            <span class="${escapeHtml(item.qualityOutcome === "failed" ? "danger" : item.status === "rejected" ? "warning" : "neutral")}">
              <strong>${escapeHtml(item.candidateType || "candidate")} / ${escapeHtml(item.target || item.issueKey || "-")}</strong>
              <em>${escapeHtml(item.repeatRecommendationReason || "Repeat review recommended.")}</em>
              <small>${escapeHtml(item.policyAdjustmentId || "-")} / ${escapeHtml(item.status || "-")} / ${escapeHtml(item.qualityOutcome || "-")}</small>
            </span>
          `).join("")}
        </div>
      ` : ""}
    </section>
  `;
}

function renderSlaPolicyCalibrationMetricComparison(label, beforeValue, afterValue, suffix = "%") {
  const delta = Number(afterValue || 0) - Number(beforeValue || 0);
  const tone = delta > 0 ? "good" : delta < 0 ? "danger" : "neutral";
  return `
    <span class="${escapeHtml(tone)}">
      <strong>${escapeHtml(label)}</strong>
      <em>${fmtNumber(beforeValue || 0)}${suffix} -> ${fmtNumber(afterValue || 0)}${suffix} (${deltaText(delta)})</em>
    </span>
  `;
}

function renderSlaPolicyQualityCalibrationPerformance(performance = {}) {
  const summary = performance.summary || {};
  const before = summary.before || {};
  const after = summary.after || {};
  const byDecision = performance.byDecision || [];
  const strongTypes = performance.strongTypes || [];
  const weakTypes = performance.weakTypes || [];
  const reReview = performance.reReviewCandidates || [];
  if (!summary.total && !byDecision.length && !reReview.length) {
    return `
      <section class="sla-policy-candidate-quality">
        <strong>Quality calibration performance</strong>
        <div class="empty">No reviewed quality calibration performance data yet.</div>
      </section>
    `;
  }
  return `
    <section class="sla-policy-candidate-quality">
      <strong>Quality calibration performance</strong>
      <div class="sla-policy-quality-summary">
        <span><strong>${fmtNumber(summary.total || 0)}</strong><em>Reviewed</em></span>
        <span><strong>${fmtNumber(summary.active || 0)}</strong><em>Active</em></span>
        <span><strong>${fmtNumber(summary.avgPerformanceScore || 0)}</strong><em>Avg score</em></span>
        <span><strong>${fmtPercent(after.approvalRate || 0)}</strong><em>After approval</em></span>
        <span><strong>${fmtPercent(after.postSuccessRate || 0)}</strong><em>Post success</em></span>
        <span><strong>${fmtNumber(summary.reReviewNeeded || 0)}</strong><em>Re-review</em></span>
      </div>
      <div class="sla-auto-policy-impact">
        ${renderSlaPolicyCalibrationMetricComparison("Approval", before.approvalRate, after.approvalRate)}
        ${renderSlaPolicyCalibrationMetricComparison("Rejection", before.rejectionRate, after.rejectionRate)}
        ${renderSlaPolicyCalibrationMetricComparison("Override", before.overrideRate, after.overrideRate)}
        ${renderSlaPolicyCalibrationMetricComparison("Post success", before.postSuccessRate, after.postSuccessRate)}
        ${renderSlaPolicyCalibrationMetricComparison("Repeat", before.repeatRecommendationRate, after.repeatRecommendationRate)}
      </div>
      ${byDecision.length ? `
        <div class="sla-auto-approval-table">
          <table>
            <thead>
              <tr><th>Decision</th><th>Total</th><th>Score</th><th>Approval</th><th>Reject</th><th>Post success</th><th>Repeat</th><th>Re-review</th></tr>
            </thead>
            <tbody>
              ${byDecision.map((row) => `
                <tr>
                  <td>${escapeHtml(row.label || row.key || "-")}</td>
                  <td>${fmtNumber(row.total || 0)}</td>
                  <td>${fmtNumber(row.avgPerformanceScore || 0)}</td>
                  <td>${fmtPercent(row.after?.approvalRate || 0)}</td>
                  <td>${fmtPercent(row.after?.rejectionRate || 0)}</td>
                  <td>${fmtPercent(row.after?.postSuccessRate || 0)}</td>
                  <td>${fmtPercent(row.after?.repeatRecommendationRate || 0)}</td>
                  <td>${fmtNumber(row.reReviewNeeded || 0)}</td>
                </tr>
              `).join("")}
            </tbody>
          </table>
        </div>
      ` : ""}
      <div class="sla-policy-repeat-list">
        ${strongTypes.map((row) => `
          <span class="good">
            <strong>${escapeHtml(row.label || row.key || "well matched")}</strong>
            <em>Score ${fmtNumber(row.avgPerformanceScore || 0)} / post success ${fmtPercent(row.after?.postSuccessRate || 0)} / repeat ${fmtPercent(row.after?.repeatRecommendationRate || 0)}</em>
            <small>Well-matched calibration type</small>
          </span>
        `).join("")}
        ${weakTypes.map((row) => `
          <span class="danger">
            <strong>${escapeHtml(row.label || row.key || "weak match")}</strong>
            <em>Score ${fmtNumber(row.avgPerformanceScore || 0)} / rejection ${fmtPercent(row.after?.rejectionRate || 0)} / repeat ${fmtPercent(row.after?.repeatRecommendationRate || 0)}</em>
            <small>Needs calibration review</small>
          </span>
        `).join("")}
      </div>
      ${reReview.length ? `
        <div class="sla-policy-repeat-list">
          ${reReview.map((item) => `
            <span class="danger">
              <strong>${escapeHtml(item.candidateType || "calibration")} / ${escapeHtml(item.target || "-")}</strong>
              <em>${escapeHtml(item.reReviewReason || "Re-review recommended.")}</em>
              <small>${escapeHtml(item.calibrationId || "-")} / score ${fmtNumber(item.performanceScore || 0)} / ${escapeHtml(item.status || "-")} / candidate ${escapeHtml(item.candidateStatus || "-")}</small>
            </span>
          `).join("")}
        </div>
      ` : ""}
    </section>
  `;
}

function renderSlaQualityRereviewSelect(name, value, options) {
  return `
    <select data-sla-quality-rereview-${escapeHtml(name)}>
      ${options.map((option) => `
        <option value="${escapeHtml(option.value)}" ${option.value === value ? "selected" : ""}>${escapeHtml(option.label)}</option>
      `).join("")}
    </select>
  `;
}

function slaQualityRereviewHours(value) {
  return Number.isFinite(Number(value)) ? `${fmtNumber(value)}h` : "-";
}

function renderSlaPolicyQualityRereviewActionReassessmentHistory(history = {}) {
  const summary = history.summary || {};
  const aggregates = history.aggregates || {};
  const items = history.items || [];
  if (!summary.total && !items.length) {
    return `<div class="empty">No re-review action reassessment history has been stored yet.</div>`;
  }
  return `
    <div class="sla-history-aggregates">
      <section>
        <strong>Effective re-review action types</strong>
        ${renderSlaHistoryGroupRows(aggregates.effectiveActionTypes || [], "No effective re-review action type yet.")}
      </section>
      <section>
        <strong>Weak re-review action types</strong>
        ${renderSlaHistoryGroupRows(aggregates.weakActionTypes || [], "No weak re-review action type yet.")}
      </section>
      <section>
        <strong>Assignee history</strong>
        ${renderSlaHistoryGroupRows(aggregates.byAssignee || [], "No assignee re-review history yet.")}
      </section>
    </div>
    <div class="sla-history-items">
      ${items.length ? items.slice(0, 10).map((item) => `
        <article class="sla-history-item ${escapeHtml(item.outcome || "unchanged")}">
          <div>
            <strong>${escapeHtml(item.sourceLabel || item.actionId || "Re-review action")}</strong>
            <span>
              ${calibrationAuditQueueBadge(item.outcome || "unchanged", item.outcome === "improved" ? "good" : item.outcome === "worse" ? "danger" : "warning")}
              ${calibrationAuditQueueBadge(`score ${fmtNumber(item.effectScore || 0)}`, item.effectScore >= 70 ? "good" : item.effectScore < 45 ? "danger" : "warning")}
              ${calibrationAuditQueueBadge(item.followUpCreated ? "follow-up created" : item.followUpNeeded ? "follow-up needed" : "no follow-up", item.followUpCreated ? "good" : item.followUpNeeded ? "warning" : "neutral")}
            </span>
          </div>
          <p>${escapeHtml(item.issueKey || item.rootMetric || item.metricLabel || "unknown")} / ${escapeHtml(item.followUpReason || "No reassessment note.")}</p>
          <small>${escapeHtml(item.evaluatedAt || "-")} / ${escapeHtml(item.assignee || item.owner || "unassigned")} / recurrence ${item.recurrence ? "yes" : "no"}</small>
        </article>
      `).join("") : `<div class="empty">No re-review reassessment history rows match the current filters.</div>`}
    </div>
  `;
}

function renderSlaPolicyQualityRereviewActionReassessment(reassessment = {}) {
  const summary = reassessment.summary || {};
  const items = reassessment.items || [];
  const history = reassessment.history || {};
  const historySummary = history.summary || {};
  return `
    <div class="sla-rereview-action-queue">
      <div class="sla-policy-quality-summary">
        <span><strong>${fmtNumber(summary.total || 0)}</strong><em>Reassessed</em></span>
        <span><strong>${fmtNumber(summary.avgEffectScore || 0)}</strong><em>Avg effect</em></span>
        <span><strong>${fmtNumber(summary.improved || 0)}</strong><em>Improved</em></span>
        <span><strong>${fmtNumber(summary.unchanged || 0)}</strong><em>Unchanged</em></span>
        <span><strong>${fmtNumber(summary.worse || 0)}</strong><em>Worse</em></span>
        <span><strong>${fmtNumber(summary.followUpNeeded || 0)}</strong><em>Follow-up</em></span>
      </div>
      ${items.length ? `
        <div class="sla-auto-approval-table">
          <table>
            <thead>
              <tr><th>Completed action</th><th>Outcome</th><th>Effect</th><th>Metric</th><th>Before / current</th><th>Recurrence</th><th>Follow-up</th></tr>
            </thead>
            <tbody>
              ${items.slice(0, 20).map((item) => `
                <tr>
                  <td><strong>${escapeHtml(item.sourceLabel || item.actionId || "Action")}</strong><small>${escapeHtml(item.completedAt ? String(item.completedAt).slice(0, 10) : "-")} / ${escapeHtml(item.assignee || item.owner || "unassigned")}</small></td>
                  <td>${calibrationAuditQueueBadge(item.outcome || "unchanged", item.outcome === "improved" ? "good" : item.outcome === "worse" ? "danger" : "warning")}</td>
                  <td>${fmtNumber(item.effectScore || 0)}</td>
                  <td>${escapeHtml(item.metric?.label || item.issueKey || "-")}<small>${escapeHtml(item.rootMetric || "")}</small></td>
                  <td>${fmtNumber(item.baseline?.value ?? 0)} / ${fmtNumber(item.current?.value ?? 0)}<small>${renderSlaBadge(item.baseline?.sla || {})} -> ${renderSlaBadge(item.current?.sla || {})}</small></td>
                  <td>${calibrationAuditQueueBadge(item.recurrence ? "recurring" : "clear", item.recurrence ? "danger" : "good")}</td>
                  <td>
                    <small>${escapeHtml(item.followUpReason || "")}</small>
                    ${item.followUpNeeded ? `<button class="secondary-button" type="button" data-sla-quality-rereview-followup-create="${escapeHtml(item.actionId || "")}">Create follow-up</button>` : ""}
                  </td>
                </tr>
              `).join("")}
            </tbody>
          </table>
        </div>
      ` : `<div class="empty">No completed re-review SLA actions have completion snapshots yet.</div>`}
      <div class="sla-policy-quality-summary">
        <span><strong>${fmtNumber(historySummary.total || 0)}</strong><em>History</em></span>
        <span><strong>${fmtNumber(historySummary.improved || 0)}</strong><em>Hist improved</em></span>
        <span><strong>${fmtNumber(historySummary.worse || 0)}</strong><em>Hist worse</em></span>
        <span><strong>${fmtNumber(historySummary.recurrence || 0)}</strong><em>Hist recurrence</em></span>
        <span><strong>${fmtNumber(historySummary.followUpCreated || 0)}</strong><em>Hist follow-up</em></span>
        <span><strong>${fmtNumber(historySummary.averageEffectScore || 0)}</strong><em>Hist avg</em></span>
      </div>
      ${renderSlaPolicyQualityRereviewActionReassessmentHistory(history)}
    </div>
  `;
}

function renderSlaPolicyQualityRereviewActionQueue(queue = {}, reassessment = {}) {
  const summary = queue.summary || {};
  const items = queue.items || [];
  const ownerRows = summary.ownerUnresolved || [];
  return `
    <div class="sla-rereview-action-queue">
      <div class="sla-policy-quality-summary">
        <span><strong>${fmtNumber(summary.open || 0)}</strong><em>Saved open</em></span>
        <span><strong>${fmtNumber(summary.overdue || 0)}</strong><em>Overdue</em></span>
        <span><strong>${fmtNumber(summary.thisWeek || 0)}</strong><em>This week</em></span>
        <span><strong>${fmtNumber(summary.highRisk || 0)}</strong><em>High risk</em></span>
        <span><strong>${fmtNumber(summary.urgent || 0)}</strong><em>Urgent</em></span>
        <span><strong>${fmtNumber(summary.unassigned || 0)}</strong><em>Unassigned</em></span>
      </div>
      ${ownerRows.length ? `
        <div class="sla-auto-approval-table">
          <table>
            <thead>
              <tr><th>Owner</th><th>Open</th><th>Overdue</th><th>This week</th><th>Risk</th><th>Top issue</th></tr>
            </thead>
            <tbody>
              ${ownerRows.map((row) => `
                <tr>
                  <td>${escapeHtml(row.owner || "unassigned")}</td>
                  <td>${fmtNumber(row.open || 0)}</td>
                  <td>${fmtNumber(row.overdue || 0)}</td>
                  <td>${fmtNumber(row.thisWeek || 0)}</td>
                  <td>${fmtNumber(row.highRisk || 0)} / ${fmtNumber(row.urgent || 0)}</td>
                  <td>${escapeHtml(row.topIssue || "-")}</td>
                </tr>
              `).join("")}
            </tbody>
          </table>
        </div>
      ` : ""}
      ${items.length ? `
        <div class="sla-auto-approval-table">
          <table>
            <thead>
              <tr><th>Action</th><th>Status</th><th>Owner</th><th>Target</th><th>Priority</th><th>Risk</th><th>Metric</th><th>Completion snapshot</th></tr>
            </thead>
            <tbody>
              ${items.slice(0, 40).map((action) => {
                const snapshot = action.completionQualitySnapshot || {};
                return `
                  <tr>
                    <td><strong>${escapeHtml(action.sourceLabel || action.sourceType || "Action")}</strong><small>${escapeHtml(action.actionId || "-")}</small></td>
                    <td>${calibrationAuditQueueBadge(action.status || "candidate", action.status === "done" ? "good" : action.status === "dismissed" ? "muted" : action.dueState === "overdue" ? "danger" : "neutral")}</td>
                    <td>${escapeHtml(action.assignee || action.owner || "unassigned")}</td>
                    <td>${escapeHtml(action.targetDate || "-")}<small>${escapeHtml(action.dueState || "")}</small></td>
                    <td>
                      ${calibrationAuditQueueBadge(action.priority || "-", action.priority === "urgent" || action.priority === "high" ? "danger" : "neutral")}
                      ${action.historyAdjustment?.applied ? `<small>hist ${fmtNumber(action.historyAdjustment.historyEffectScore || 0)} / ${escapeHtml(action.historyAdjustment.direction || "neutral")}</small>` : ""}
                    </td>
                    <td>${calibrationAuditQueueBadge(action.riskLevel || action.slaLevel || "-", action.riskLevel === "high" || action.slaLevel === "danger" ? "danger" : "warning")}</td>
                    <td>${escapeHtml(action.issueKey || "-")}<small>${escapeHtml(action.rootMetric || "")}</small></td>
                    <td>${snapshot.capturedAt ? `${escapeHtml(String(snapshot.capturedAt).slice(0, 10))}<small>${renderSlaBadge(snapshot.summary?.sla || {})}</small>` : "-"}</td>
                  </tr>
                `;
              }).join("")}
            </tbody>
          </table>
        </div>
      ` : `<div class="empty">No saved re-review SLA actions match the current action filters.</div>`}
      ${renderSlaPolicyQualityRereviewActionReassessment(reassessment)}
    </div>
  `;
}

function renderSlaPolicyQualityRereviewActions(slaActions = {}) {
  const actions = slaActions.items || [];
  if (!actions.length) return "";
  const summary = slaActions.summary || {};
  const queue = slaActions.operationQueue || {};
  const reassessment = slaActions.postReassessment || {};
  return `
    <div class="calibration-sla-actions">
      <div class="calibration-sla-actions-head">
        <div>
          <strong>Re-review SLA improvement actions</strong>
          <span>${fmtNumber(summary.open || 0)} open / ${fmtNumber(summary.saved || 0)} saved / ${fmtNumber(summary.generated || 0)} generated</span>
        </div>
      </div>
      ${renderSlaPolicyQualityRereviewActionQueue(queue, reassessment)}
      <div class="calibration-sla-action-list">
        ${actions.slice(0, 10).map((action) => `
          <article
            class="calibration-sla-action ${escapeHtml(action.slaLevel || "warning")}"
            data-sla-quality-rereview-action-id="${escapeHtml(action.actionId || "")}"
            data-sla-quality-rereview-action-source-key="${escapeHtml(action.sourceKey || "")}"
            data-sla-quality-rereview-action-source-type="${escapeHtml(action.sourceType || "summary")}"
            data-sla-quality-rereview-action-source-label="${escapeHtml(action.sourceLabel || "")}"
            data-sla-quality-rereview-action-month="${escapeHtml(action.month || "")}"
            data-sla-quality-rereview-action-owner="${escapeHtml(action.owner || "")}"
            data-sla-quality-rereview-action-level="${escapeHtml(action.slaLevel || "")}"
            data-sla-quality-rereview-action-issue-key="${escapeHtml(action.issueKey || "")}"
            data-sla-quality-rereview-action-severity="${escapeHtml(action.severity || "")}"
            data-sla-quality-rereview-action-root-metric="${escapeHtml(action.rootMetric || "")}"
            data-sla-quality-rereview-action-source-metrics="${escapeHtml(JSON.stringify(action.sourceMetrics || {}))}">
            <div>
              <strong>${escapeHtml(action.sourceLabel || action.sourceType || "Re-review SLA")}</strong>
              <span>
                ${renderSlaBadge({ level: action.slaLevel, label: action.slaLevel === "danger" ? "Risk" : "Watch" })}
                ${calibrationAuditQueueBadge(action.priority || "medium", action.priority === "urgent" || action.priority === "high" ? "danger" : "warning")}
                ${calibrationAuditQueueBadge(action.candidateStatus || (action.isSaved ? "saved" : "generated"), action.isSaved ? "good" : "neutral")}
                ${escapeHtml(action.rootMetric || action.issueKey || "")}
              </span>
            </div>
            <p>${escapeHtml(action.recommendation || "")}</p>
            ${renderSlaHistoryAdjustment(action.historyAdjustment)}
            <div class="calibration-sla-action-grid">
              <label>
                <span>Priority</span>
                <select data-sla-quality-rereview-action-field="priority">${slaActionPriorityOptions(action.priority)}</select>
              </label>
              <label>
                <span>Assignee</span>
                <input data-sla-quality-rereview-action-field="assignee" value="${escapeHtml(action.assignee || action.owner || "")}">
              </label>
              <label>
                <span>Target</span>
                <input type="date" data-sla-quality-rereview-action-field="targetDate" value="${escapeHtml(action.targetDate || "")}">
              </label>
              <label>
                <span>Status</span>
                <select data-sla-quality-rereview-action-field="status">${slaActionStatusOptions(action.status)}</select>
              </label>
              <label class="wide">
                <span>Recommended action</span>
                <textarea data-sla-quality-rereview-action-field="recommendation" rows="2">${escapeHtml(action.recommendation || "")}</textarea>
              </label>
              <button class="secondary-button" type="button" data-sla-quality-rereview-action-save="${escapeHtml(action.actionId || "")}">Save action</button>
            </div>
          </article>
        `).join("")}
      </div>
    </div>
  `;
}

function renderSlaPolicyQualityOperationalQuality(quality = {}) {
  const summary = quality.summary || {};
  const monthly = quality.monthly || [];
  const owners = quality.ownerPerformance || [];
  if (!summary.total && !monthly.length && !owners.length) return "";
  return `
    <div class="sla-policy-quality-summary">
      <span><strong>${renderSlaBadge(summary.sla || {})}</strong><em>Overall SLA</em></span>
      <span><strong>${slaQualityRereviewHours(summary.avgProcessingHours)}</strong><em>Avg processing</em></span>
      <span><strong>${fmtNumber(summary.statusTransitionCount || 0)}</strong><em>Status changes</em></span>
      <span><strong>${fmtPercent(summary.reopenRate || 0)}</strong><em>Reopen rate</em></span>
      <span><strong>${fmtNumber(summary.delayedIncompleteItems || 0)}</strong><em>Overdue open</em></span>
      <span><strong>${fmtNumber(summary.activeLinkUnprocessed || 0)}</strong><em>Link open</em></span>
      <span><strong>${fmtPercent(summary.deactivateRate || 0)}</strong><em>Deactivate</em></span>
      <span><strong>${fmtPercent(summary.modifiedProposalRate || 0)}</strong><em>Modify proposal</em></span>
    </div>
    <div class="calibration-audit-sla-improvements">
      <strong>Improvement needed</strong>
      ${renderSlaImprovementItems(summary.sla || {})}
    </div>
    ${renderSlaPolicyQualityRereviewActions(quality.slaActions || {})}
    ${monthly.length ? `
      <div class="sla-auto-approval-table">
        <table>
          <thead>
            <tr><th>Month</th><th>SLA</th><th>Total</th><th>Completed</th><th>Avg time</th><th>Status changes</th><th>Reopen</th><th>Overdue</th><th>Link open</th><th>Needs</th></tr>
          </thead>
          <tbody>
            ${monthly.map((row) => `
              <tr>
                <td>${escapeHtml(row.label || row.key || "-")}</td>
                <td>${renderSlaBadge(row.sla || {})}</td>
                <td>${fmtNumber(row.total || 0)}</td>
                <td>${fmtNumber(row.completed || 0)}</td>
                <td>${slaQualityRereviewHours(row.avgProcessingHours)}</td>
                <td>${fmtNumber(row.statusTransitionCount || 0)}</td>
                <td>${fmtPercent(row.reopenRate || 0)}</td>
                <td>${fmtNumber(row.delayedIncompleteItems || 0)}</td>
                <td>${fmtNumber(row.activeLinkUnprocessed || 0)}</td>
                <td>${renderSlaImprovementItems(row.sla || {})}</td>
              </tr>
            `).join("")}
          </tbody>
        </table>
      </div>
    ` : ""}
    ${owners.length ? `
      <div class="sla-auto-approval-table">
        <table>
          <thead>
            <tr><th>Owner</th><th>SLA</th><th>Total</th><th>Completed</th><th>Completion</th><th>Avg time</th><th>Reopen</th><th>Overdue</th><th>Link open</th><th>Outcomes</th><th>Needs</th></tr>
          </thead>
          <tbody>
            ${owners.map((row) => `
              <tr>
                <td>${escapeHtml(row.label || row.key || "unassigned")}</td>
                <td>${renderSlaBadge(row.sla || {})}</td>
                <td>${fmtNumber(row.total || 0)}</td>
                <td>${fmtNumber(row.completed || 0)}</td>
                <td>${fmtPercent(row.completionRate || 0)}</td>
                <td>${slaQualityRereviewHours(row.avgProcessingHours)}</td>
                <td>${fmtPercent(row.reopenRate || 0)}</td>
                <td>${fmtNumber(row.delayedIncompleteItems || 0)}</td>
                <td>${fmtNumber(row.activeLinkUnprocessed || 0)}</td>
                <td>${fmtNumber(row.maintained || 0)} / ${fmtNumber(row.deactivated || 0)} / ${fmtNumber(row.modifiedProposed || 0)}</td>
                <td>${renderSlaImprovementItems(row.sla || {})}</td>
              </tr>
            `).join("")}
          </tbody>
        </table>
      </div>
    ` : ""}
  `;
}

function renderSlaPolicyQualityRereviews(rereviews = {}) {
  const summary = rereviews.summary || {};
  const items = rereviews.items || [];
  const exportUrls = rereviews.exportUrls || {};
  const operationalQuality = rereviews.operationalQuality || {};
  return `
    <section class="sla-policy-candidate-quality">
      <div class="learning-calibration-head">
        <div>
          <strong>Quality calibration re-review queue</strong>
          <span>Audit trail, active calibration linkage, filtered CSV/JSON exports</span>
        </div>
        <div class="learning-calibration-actions">
          <a class="ghost-button" href="${escapeHtml(exportUrls.json || "#")}" target="_blank" rel="noreferrer">JSON</a>
          <a class="ghost-button" href="${escapeHtml(exportUrls.csv || "#")}" target="_blank" rel="noreferrer">CSV</a>
        </div>
      </div>
      <div class="sla-policy-quality-summary">
        <span><strong>${fmtNumber(summary.total || 0)}</strong><em>Queue</em></span>
        <span><strong>${fmtNumber(summary.open || 0)}</strong><em>Open</em></span>
        <span><strong>${fmtNumber(summary.inProgress || 0)}</strong><em>In progress</em></span>
        <span><strong>${fmtNumber(summary.overdue || 0)}</strong><em>Overdue</em></span>
        <span><strong>${fmtNumber(summary.thisWeek || 0)}</strong><em>This week</em></span>
        <span><strong>${fmtNumber(summary.avgPerformanceScore || 0)}</strong><em>Avg score</em></span>
      </div>
      ${renderSlaPolicyQualityOperationalQuality(operationalQuality)}
      ${items.length ? items.map(renderSlaPolicyQualityRereviewCard).join("") : `<div class="empty">No re-review queue items match the current filters.</div>`}
    </section>
  `;
}

function renderSlaPolicyQualityRereviewCard(item = {}) {
  const tone = item.status === "completed" ? "good" : item.dueState === "overdue" || Number(item.performanceScore || 0) <= 35 ? "danger" : item.dueState === "this_week" ? "warning" : "neutral";
  const history = item.changeHistorySummary || {};
  const operational = item.operationalMetric || {};
  const logs = Array.isArray(item.changeLogs) ? item.changeLogs : [];
  const linkedHistory = Array.isArray(item.linkedCalibrationHistory) ? item.linkedCalibrationHistory : [];
  const statusOptions = [
    { value: "open", label: "Open" },
    { value: "in_progress", label: "In progress" },
    { value: "completed", label: "Completed" },
    { value: "deferred", label: "Deferred" },
    { value: "dismissed", label: "Dismissed" }
  ];
  const actionOptions = [
    { value: "watch", label: "Watch" },
    { value: "maintain_active", label: "Maintain active" },
    { value: "deactivate_active", label: "Deactivate active" },
    { value: "propose_modified_calibration", label: "Propose modified" },
    { value: "none", label: "No action" }
  ];
  return `
    <article class="sla-auto-policy-adjustment ${escapeHtml(tone)}" data-sla-quality-rereview-card="${escapeHtml(item.rereviewId || "")}">
      <div class="sla-recommendation-adjustment-head">
        <div>
          <strong>${escapeHtml(item.candidateType || "calibration")} / ${escapeHtml(item.target || "-")}</strong>
          <span>
            ${calibrationAuditQueueBadge(item.status || "open", item.status === "completed" ? "good" : item.status === "dismissed" ? "muted" : tone)}
            ${calibrationAuditQueueBadge(item.dueState || "no_due", item.dueState === "overdue" ? "danger" : item.dueState === "this_week" ? "warning" : "neutral")}
            ${calibrationAuditQueueBadge(`score ${fmtNumber(item.performanceScore || 0)}`, Number(item.performanceScore || 0) <= 45 ? "danger" : "neutral")}
            ${calibrationAuditQueueBadge(item.followUpActionType || "watch", "neutral")}
          </span>
        </div>
        <small>${escapeHtml(item.rereviewId || "")}</small>
      </div>
      <div class="sla-recommendation-adjustment-copy">
        <span><strong>Reason</strong><em>${escapeHtml(item.reReviewReason || "-")}</em></span>
        <span><strong>Candidate</strong><em>${escapeHtml(item.policyAdjustmentId || "-")} / ${escapeHtml(item.candidateStatus || "-")} / ${escapeHtml(item.qualityOutcome || "-")}</em></span>
        <span><strong>Calibration</strong><em>${escapeHtml(item.calibrationId || "-")}</em></span>
        <span><strong>Change history</strong><em>${fmtNumber(history.totalLogs || 0)} logs / latest ${escapeHtml(history.latestChangedAt || "-")} / ${escapeHtml(history.changedFieldSummary || "no field changes")}</em></span>
        <span><strong>Operations</strong><em>${slaQualityRereviewHours(operational.processingHours)} / ${fmtNumber(operational.statusTransitionCount || 0)} transitions / ${fmtNumber(operational.reopenCount || 0)} reopens / ${escapeHtml(operational.linkedCalibrationResult || "none")}</em></span>
      </div>
      <div class="sla-recommendation-adjustment-review">
        <label class="field">
          <span>Status</span>
          ${renderSlaQualityRereviewSelect("status", item.status || "open", statusOptions)}
        </label>
        <label class="field">
          <span>Owner</span>
          <input data-sla-quality-rereview-owner type="text" value="${escapeHtml(item.owner || "")}" placeholder="owner">
        </label>
        <label class="field">
          <span>Due date</span>
          <input data-sla-quality-rereview-due-date type="date" value="${escapeHtml(item.dueDate || "")}">
        </label>
        <label class="field">
          <span>Follow-up</span>
          ${renderSlaQualityRereviewSelect("follow-up-action-type", item.followUpActionType || "watch", actionOptions)}
        </label>
        <label class="field wide">
          <span>Memo</span>
          <textarea data-sla-quality-rereview-memo rows="2" placeholder="review note or completion reason">${escapeHtml(item.memo || "")}</textarea>
        </label>
        <div>
          <button class="secondary-button" type="button" data-sla-quality-rereview-save="${escapeHtml(item.rereviewId || "")}">Save</button>
        </div>
      </div>
      ${item.completedAt ? `<small class="sla-recommendation-adjustment-review-log">completed by ${escapeHtml(item.completedBy || "-")} at ${escapeHtml(item.completedAt || "-")} / ${escapeHtml(item.completionResult || "-")}</small>` : ""}
      ${linkedHistory.length ? `
        <div class="sla-policy-repeat-list">
          ${linkedHistory.map((entry) => {
            const link = entry.linkedCalibration || {};
            return `
              <span class="good">
                <strong>Active calibration linkage</strong>
                <em>${escapeHtml(link.actionType || entry.eventType || "-")} / ${escapeHtml(link.previousStatus || "-")} -> ${escapeHtml(link.nextStatus || "-")}</em>
                <small>${escapeHtml(link.calibrationId || item.calibrationId || "-")} / ${escapeHtml(entry.changedBy || link.changedBy || "-")} / ${escapeHtml(entry.changedAt || link.changedAt || "-")}</small>
              </span>
            `;
          }).join("")}
        </div>
      ` : ""}
      ${logs.length ? `
        <div class="sla-policy-repeat-list">
          ${logs.map((log) => `
            <span class="${escapeHtml(log.eventType === "completed" ? "good" : "neutral")}">
              <strong>${escapeHtml(log.eventType || "updated")} / ${escapeHtml(log.changedBy || "-")}</strong>
              <em>${escapeHtml((log.changedFields || []).join(", ") || "linked calibration update")}</em>
              <small>${escapeHtml(log.changedAt || "-")} / ${escapeHtml(log.completionResult || "no completion")}</small>
            </span>
          `).join("")}
        </div>
      ` : ""}
    </article>
  `;
}

function renderSlaPolicyQualityCalibrationWorkflow(workflow = {}) {
  const summary = workflow.summary || {};
  const items = workflow.items || [];
  return `
    <section class="sla-policy-candidate-quality">
      <strong>Quality calibration review</strong>
      <div class="sla-policy-quality-summary">
        <span><strong>${fmtNumber(summary.total || 0)}</strong><em>Calibrations</em></span>
        <span><strong>${fmtNumber(summary.proposed || 0)}</strong><em>Proposed</em></span>
        <span><strong>${fmtNumber(summary.active || 0)}</strong><em>Active</em></span>
        <span><strong>${fmtNumber(summary.rejected || 0)}</strong><em>Rejected</em></span>
        <span><strong>${fmtNumber(summary.overridden || 0)}</strong><em>Overridden</em></span>
        <span><strong>${fmtNumber(summary.boostSuggested || 0)} / ${fmtNumber(summary.downgradeSuggested || 0)}</strong><em>Boost / down</em></span>
      </div>
      ${items.length ? items.map(renderSlaPolicyQualityCalibrationWorkflowCard).join("") : `<div class="empty">No quality calibration proposals match the current effectiveness filters.</div>`}
    </section>
  `;
}

function renderSlaPolicyQualityCalibrationWorkflowCard(item = {}) {
  const suggested = item.suggestedCalibration || {};
  const active = item.activeCalibration || null;
  const previous = item.previousQuality || suggested.previousQuality || {};
  const simulation = item.simulation || {};
  const expectedBefore = simulation.expectedImpactBefore || {};
  const expectedAfter = simulation.expectedImpactAfter || {};
  const tone = item.status === "rejected" ? "neutral" : item.status === "approved" || item.status === "overridden" ? "good" : suggested.direction === "downgrade" ? "warning" : suggested.direction === "boost" ? "good" : "neutral";
  const priorityOptions = ["urgent", "high", "medium", "low"].map((priority) => `
    <option value="${escapeHtml(priority)}" ${priority === (suggested.priorityAfter || suggested.priorityBefore || "medium") ? "selected" : ""}>${escapeHtml(priority)}</option>
  `).join("");
  return `
    <article class="sla-auto-policy-adjustment ${escapeHtml(tone)}" data-sla-quality-calibration-card="${escapeHtml(item.calibrationId || "")}">
      <div class="sla-recommendation-adjustment-head">
        <div>
          <strong>${escapeHtml(item.target || item.issueKey || item.candidateType || "Quality calibration")}</strong>
          <span>
            ${calibrationAuditQueueBadge(item.status || "proposed", item.status === "approved" || item.status === "overridden" ? "good" : item.status === "rejected" ? "muted" : "warning")}
            ${calibrationAuditQueueBadge(item.candidateType || "candidate", "neutral")}
            ${calibrationAuditQueueBadge(suggested.direction || "neutral", slaPolicyQualityCalibrationTone(suggested))}
            ${active ? calibrationAuditQueueBadge("active", "good") : calibrationAuditQueueBadge("not active", "warning")}
          </span>
        </div>
        <small>${escapeHtml(item.calibrationId || "")}</small>
      </div>
      <div class="sla-auto-policy-impact">
        <span class="${suggested.priorityBefore !== suggested.priorityAfter ? "changed" : ""}">
          <strong>Suggested priority</strong>
          <em>${escapeHtml(suggested.priorityBefore || "-")} -> ${escapeHtml(suggested.priorityAfter || "-")}</em>
        </span>
        <span class="${active ? "changed" : ""}">
          <strong>Active priority</strong>
          <em>${escapeHtml(suggested.priorityBefore || "-")} -> ${escapeHtml(active?.priorityAfter || suggested.priorityBefore || "-")}</em>
        </span>
        <span>
          <strong>Expected success</strong>
          <em>${fmtPercent(expectedBefore.currentSuccessRate || 0)} -> ${fmtPercent(expectedAfter.expectedSuccessRate || expectedBefore.expectedSuccessRate || 0)}</em>
        </span>
        <span>
          <strong>Prior quality</strong>
          <em>success ${fmtPercent(previous.approvalSuccessRate || 0)} / repeat ${fmtPercent(previous.repeatRecommendationRate || 0)} / total ${fmtNumber(previous.total || 0)}</em>
        </span>
      </div>
      <div class="sla-recommendation-adjustment-copy">
        <span><strong>Suggested reason</strong><em>${escapeHtml(suggested.reason || "-")}</em></span>
        <span><strong>Before recommendation</strong><em>${escapeHtml(simulation.recommendationBefore || "-")}</em></span>
        <span><strong>Suggested recommendation</strong><em>${escapeHtml(simulation.suggestedRecommendationAfter || "-")}</em></span>
        <span><strong>Active recommendation</strong><em>${escapeHtml(simulation.activeRecommendationAfter || "-")}</em></span>
        <span><strong>Top rejection</strong><em>${escapeHtml(previous.topRejectionReason || "-")}${previous.topRejectionCount ? ` / ${fmtNumber(previous.topRejectionCount)} cases` : ""}</em></span>
        <span><strong>Source</strong><em>${escapeHtml(item.sourcePolicyAdjustmentId || "-")} / ${escapeHtml(item.sourceSuggestionType || "-")} / score ${escapeHtml(item.sourceEffectScore ?? "-")}</em></span>
      </div>
      ${item.status === "proposed" ? `
        <div class="sla-recommendation-adjustment-review">
          <label class="field wide">
            <span>Review note</span>
            <textarea data-sla-quality-calibration-review-note rows="2" placeholder="approval, rejection, or override reason"></textarea>
          </label>
          <label class="field">
            <span>Override priority</span>
            <select data-sla-quality-calibration-override-priority>${priorityOptions}</select>
          </label>
          <label class="field wide">
            <span>Override note</span>
            <textarea data-sla-quality-calibration-override-note rows="2" placeholder="why this active priority differs from the suggestion"></textarea>
          </label>
          <div>
            <button class="secondary-button" type="button" data-sla-quality-calibration-decision="approved" data-sla-quality-calibration-id="${escapeHtml(item.calibrationId || "")}">Approve</button>
            <button class="ghost-button" type="button" data-sla-quality-calibration-decision="rejected" data-sla-quality-calibration-id="${escapeHtml(item.calibrationId || "")}">Reject</button>
            <button class="secondary-button" type="button" data-sla-quality-calibration-decision="override" data-sla-quality-calibration-id="${escapeHtml(item.calibrationId || "")}">Override</button>
          </div>
        </div>
      ` : `
        <small class="sla-recommendation-adjustment-review-log">
          ${escapeHtml(item.status || "reviewed")} by ${escapeHtml(item.reviewedBy || item.updatedBy || "-")} at ${escapeHtml(item.reviewedAt || item.updatedAt || "-")}
          ${item.reviewReason ? ` / ${escapeHtml(item.reviewReason)}` : ""}
          ${item.overrideReason ? ` / override: ${escapeHtml(item.overrideReason)}` : ""}
        </small>
      `}
    </article>
  `;
}

function renderSlaAutoPolicyEffectiveness() {
  if (!els.slaAutoPolicyEffectivenessSummary || !els.slaAutoPolicyEffectivenessList) return;
  const report = state.masterDb.slaAutoPolicyEffectiveness;
  if (!report) {
    els.slaAutoPolicyEffectivenessSummary.innerHTML = `<span>SLA 정책 적용 후 효과를 불러오는 중입니다.</span>`;
    els.slaAutoPolicyEffectivenessList.innerHTML = `<div class="empty">SLA 정책 적용 후 효과를 불러오는 중입니다.</div>`;
    return;
  }
  const summary = report.summary || {};
  els.slaAutoPolicyEffectivenessSummary.innerHTML = `
    <span><strong>${fmtNumber(summary.total || 0)}</strong><em>Approved policies</em></span>
    <span><strong>${fmtNumber(summary.pending || 0)}</strong><em>Pending</em></span>
    <span><strong>${fmtNumber(summary.improved || 0)}</strong><em>Improved</em></span>
    <span><strong>${fmtNumber(summary.unchanged || 0)}</strong><em>Unchanged</em></span>
    <span><strong>${fmtNumber(summary.worse || 0)}</strong><em>Worse</em></span>
    <span><strong>${fmtNumber(summary.rollbackSuggested || 0)}</strong><em>Rollback suggestions</em></span>
    <span><strong>${fmtNumber(summary.additionalAdjustmentSuggested || 0)}</strong><em>Follow-up suggestions</em></span>
    <span><strong>${fmtNumber(summary.avgEffectScore || 0)}</strong><em>Avg effect score</em></span>
  `;
  const items = report.items || [];
  els.slaAutoPolicyEffectivenessList.innerHTML = `
    ${renderSlaPolicyQualityCalibrationPerformance(report.qualityCalibrationPerformance || {})}
    ${renderSlaPolicyQualityRereviews(report.qualityCalibrationRereviews || {})}
    ${renderSlaPolicyQualityCalibrationWorkflow(report.qualityCalibrationWorkflow || {})}
    ${renderSlaPolicyCandidateQuality(report.effectCandidateQuality || {})}
    ${items.length
      ? items.map(renderSlaAutoPolicyEffectivenessCard).join("")
      : `<div class="empty">현재 필터에 맞는 승인 정책 사후 효과 데이터가 없습니다.</div>`}
  `;
}

function renderCalibrationAuditQueue() {
  if (!els.calibrationAuditQueueSummary || !els.calibrationAuditQueueList) return;
  const queue = state.masterDb.calibrationAuditQueue;
  if (!queue) {
    els.calibrationAuditQueueSummary.innerHTML = `<span>감사 후속 조치 큐를 불러오는 중입니다.</span>`;
    els.calibrationAuditQueueList.innerHTML = `<div class="empty">감사 후속 조치 큐를 불러오는 중입니다.</div>`;
    return;
  }
  const summary = queue.summary || {};
  const ownerRows = summary.byOwnerOpen || [];
  els.calibrationAuditQueueSummary.innerHTML = `
    <span><strong>${fmtNumber(summary.open || 0)}</strong><em>Open</em></span>
    <span><strong>${fmtNumber(summary.overdue || 0)}</strong><em>Overdue</em></span>
    <span><strong>${fmtNumber(summary.thisWeek || 0)}</strong><em>This week</em></span>
    <span><strong>${fmtNumber(summary.unassignedOpen || 0)}</strong><em>Unassigned</em></span>
    <span><strong>${fmtNumber(summary.resolved || 0)}</strong><em>Resolved</em></span>
  `;
  const ownerSummary = ownerRows.length ? `
    <div class="calibration-audit-owner-summary">
      ${ownerRows.slice(0, 6).map((row) => `
        <span><strong>${escapeHtml(row.owner || "unassigned")}</strong><em>${fmtNumber(row.open)} open / ${fmtNumber(row.overdue)} overdue / ${fmtNumber(row.thisWeek)} this week</em></span>
      `).join("")}
    </div>
  ` : "";
  const items = queue.items || [];
  els.calibrationAuditQueueList.innerHTML = `
    ${ownerSummary}
    ${renderCalibrationAuditOperationQuality(queue.operationQuality || {})}
    ${renderCalibrationAuditBulkHistory(queue.reviewHistory || {})}
    <div class="calibration-audit-queue-items">
      ${items.length ? items.map((item) => `
        <article class="calibration-audit-queue-item ${escapeHtml(calibrationAuditQueueTone(item))}">
          <div class="calibration-audit-queue-head">
            <label class="calibration-audit-queue-select">
              <input type="checkbox" data-calibration-audit-queue-select="${escapeHtml(item.versionId || "")}">
              <span>Select</span>
            </label>
            <div>
              <strong>${escapeHtml(item.companyName || item.companyId || "-")}</strong>
              <span>${escapeHtml(item.versionId || "")} / ${escapeHtml(item.eventMonth || "")} / target ${escapeHtml(item.targetMonth || "-")}</span>
            </div>
          </div>
          <div class="calibration-audit-queue-badges">
            ${calibrationAuditQueueBadge(item.reviewStatus || "pending", calibrationAuditQueueTone(item))}
            ${calibrationAuditQueueBadge(item.dueState || "no_due", item.isOverdue ? "danger" : item.isThisWeek ? "warning" : "neutral")}
            ${calibrationAuditQueueBadge(`owner ${item.followUpOwner || "unassigned"}`, item.followUpOwner ? "neutral" : "warning")}
            ${calibrationAuditQueueBadge(`risk ${item.riskLevel || "none"}`, item.riskLevel === "high" ? "danger" : item.riskLevel === "medium" ? "warning" : "neutral")}
          </div>
          <p>${escapeHtml(item.adminMemo || item.reason || "No memo saved.")}</p>
          <small>Due ${escapeHtml(item.followUpDueDate || "-")} / score ${fmtCalibrationScore(item.executionPerformance?.avgRetrospectiveScore)} / matched plans ${fmtNumber(item.executionPerformance?.matchedPlans || 0)}</small>
          ${renderCalibrationAuditReviewHistory(item.auditReviewLogSummary || {}, item.auditReviewLogs || [])}
          <div class="calibration-audit-queue-edit" data-calibration-audit-queue-version-id="${escapeHtml(item.versionId || "")}" data-calibration-audit-queue-company-id="${escapeHtml(item.companyId || "")}" data-calibration-audit-queue-target-month="${escapeHtml(item.targetMonth || "")}" data-calibration-audit-queue-month="${escapeHtml(item.eventMonth || "")}">
            <label>
              <span>Status</span>
              <select data-queue-review-field="reviewStatus">${calibrationAuditReviewStatusOptions(item.reviewStatus)}</select>
            </label>
            <label>
              <span>Owner</span>
              <input data-queue-review-field="followUpOwner" value="${escapeHtml(item.followUpOwner || "")}">
            </label>
            <label>
              <span>Due</span>
              <input type="date" data-queue-review-field="followUpDueDate" value="${escapeHtml(item.followUpDueDate || "")}">
            </label>
            <label class="wide">
              <span>Memo</span>
              <textarea data-queue-review-field="adminMemo" rows="2">${escapeHtml(item.adminMemo || "")}</textarea>
            </label>
            <button class="secondary-button" type="button" data-calibration-audit-queue-save="${escapeHtml(item.versionId || "")}">Save</button>
          </div>
        </article>
      `).join("") : `<div class="empty">현재 필터에 맞는 감사 후속 조치 항목이 없습니다.</div>`}
    </div>
  `;
  updateCalibrationAuditQueueBulkState();
}

function renderStrategyReviewRows(review = null) {
  const formulas = review?.adminReview?.formulas || [];
  if (!formulas.length) return `<div class="empty">전략 추천 산식을 만들 수 있는 지표가 아직 부족합니다.</div>`;
  const progress = review?.executionProgress || {};
  const monthly = review?.monthlyExecution?.summary || {};
  const retrospective = review?.monthlyRetrospective || {};
  const retroSummary = retrospective.summary || {};
  const automationTrace = retrospective.automationTrace || {};
  const quality = retrospective.adminRecommendationQuality || retrospective.recommendationQuality || {};
  const qualitySummary = quality.summary || {};
  const qualityByStrategy = new Map((quality.items || []).map((item) => [item.strategyId, item]));
  const history = review?.strategyQualityHistory || {};
  const historySummary = history.summary || {};
  const segmentLearning = review?.strategySegmentLearning || {};
  const segmentSummary = segmentLearning.summary || {};
  const targetSegment = segmentLearning.targetSegment || {};
  const experiments = review?.strategyExperiments || [];
  const experimentsByStrategy = new Map((experiments || []).map((item) => [item.strategyId, item]));
  const experimentExecution = review?.strategyExperimentExecution || {};
  const experimentVariants = experimentExecution.variantCounts || {};
  const experimentResults = review?.strategyExperimentResults || {};
  const experimentResultSummary = experimentResults.summary || {};
  const experimentResultsByStrategy = new Map((experimentResults.items || []).map((item) => [item.strategyId, item]));
  const experimentHistory = review?.experimentQualityHistory || {};
  const experimentHistorySummary = experimentHistory.summary || {};
  const integratedLearningApplied = formulas.filter((item) => item.integratedLearningAdjustment?.hasIntegratedLearning);
  const generation = monthly.byGenerationType || {};
  const nextCandidates = review?.nextMonthPlanCandidates || {};
  const nextSummary = nextCandidates.summary || {};
  const kpi = monthly.kpi || progress.kpi || {};
  return `
    ${renderLearningCalibrationPanel(review?.learningCalibration)}
    ${renderLearningCalibrationAuditPanel(review?.learningCalibrationAudit)}
    <div class="strategy-review-summary">
      <strong>실행계획 진행률 ${fmtReportScore(progress.avgProgress || 0)}</strong>
      <span>총 ${fmtNumber(progress.total || 0)}개 · 완료 ${fmtNumber(progress.completedPlans || 0)}개 · 지연 ${fmtNumber(monthly.overdue || progress.overduePlans || 0)}건 · KPI 입력 ${fmtNumber(kpi.filled || 0)}/${fmtNumber(kpi.total || 0)}</span>
      <span>성과 ${fmtReportScore(retroSummary.score || 0)} · 등급 ${escapeHtml(retroSummary.grade || "-")} · 이월 ${fmtNumber((retrospective.carryoverItems || []).length)}건 · 반복 ${fmtNumber((retrospective.repeatStrategies || []).length)}건</span>
      <span>Auto-generated plans ${fmtNumber(generation.auto_generated || retroSummary.autoGeneratedPlans || 0)} · manual ${fmtNumber(generation.manual || retroSummary.manualPlans || 0)} · traced ${fmtNumber((automationTrace.appliedPlans || []).length)}</span>
      <span>Recommendation quality ${fmtReportScore(qualitySummary.avgScore || 0)} · ${escapeHtml(qualitySummary.grade || "-")} · keep ${fmtNumber(qualitySummary.keep || 0)} · adjust ${fmtNumber(qualitySummary.adjust || 0)} · switch ${fmtNumber(qualitySummary.drop || 0)}</span>
      <span>Quality history ${fmtNumber(historySummary.total || 0)} · avg ${fmtReportScore(historySummary.avgScore || 0)} · low ${fmtNumber(historySummary.lowQuality || 0)}</span>
      <span>Segment learning ${fmtNumber(segmentSummary.total || 0)} · avg ${fmtReportScore(segmentSummary.avgScore || 0)} · ${escapeHtml([targetSegment.region, targetSegment.category, targetSegment.seasonType, targetSegment.interestBand, targetSegment.leadtimeBand].filter(Boolean).join(" / ") || "-")}</span>
      <span>A/B experiments ${fmtNumber(experiments.length)} · avg readiness ${fmtReportScore(experiments.length ? experiments.reduce((sum, item) => sum + Number(item.readinessScore || 0), 0) / experiments.length : 0)}</span>
      <span>Experiment execution ${fmtReportScore(experimentExecution.avgProgress || 0)} · A ${fmtNumber(experimentVariants.A || 0)} / B ${fmtNumber(experimentVariants.B || 0)} · stop ${fmtNumber(experimentExecution.stopTriggered || 0)}</span>
      <span>Experiment results ${fmtNumber(experimentResultSummary.total || 0)} · avg ${fmtReportScore(experimentResultSummary.avgScore || 0)} · expand ${fmtNumber(experimentResultSummary.byDecision?.expand || 0)} · stop ${fmtNumber(experimentResultSummary.byDecision?.stop || 0)}</span>
      <span>Experiment quality history ${fmtNumber(experimentHistorySummary.total || 0)} · avg ${fmtReportScore(experimentHistorySummary.avgScore || 0)} · keep ${fmtNumber(experimentHistorySummary.keep || 0)} · drop ${fmtNumber(experimentHistorySummary.drop || 0)}</span>
      <span>Integrated learning ${fmtNumber(integratedLearningApplied.length)} · avg confidence ${fmtReportScore(integratedLearningApplied.length ? integratedLearningApplied.reduce((sum, item) => sum + Number(item.integratedLearningAdjustment?.recommendationConfidenceScore || 0), 0) / integratedLearningApplied.length : 0)}</span>
      <span>Next plan candidates ${fmtNumber(nextSummary.total || 0)} · selectable ${fmtNumber(nextSummary.selectable || 0)} · avg score ${fmtReportScore(nextSummary.avgCandidateScore || 0)} · duplicates ${fmtNumber((nextSummary.duplicateWithExistingPlan || 0) + (nextSummary.duplicateWithCandidate || 0))}</span>
      ${(formulas || []).filter((item) => item.learningAdjustment?.hasHistory).slice(0, 5).map((item) => `
        <em>우선순위 ${fmtNumber(item.originalPriority || item.priority || 0)} → ${fmtNumber(item.priority || 0)} · ${escapeHtml(item.title || "")} · ${escapeHtml(item.learningAdjustment?.adminReason || "")}</em>
      `).join("")}
      ${(formulas || []).filter((item) => item.segmentLearningAdjustment?.hasSegmentHistory).slice(0, 5).map((item) => `
        <em>세그먼트 ${fmtNumber(item.segmentLearningAdjustment?.supportCount || 0)}건 · 우선순위 ${fmtNumber(item.originalPriority || item.priority || 0)} → ${fmtNumber(item.priority || 0)} · ${escapeHtml(item.title || "")} · ${escapeHtml(item.segmentLearningAdjustment?.adminReason || "")}</em>
      `).join("")}
      ${(formulas || []).filter((item) => item.experimentLearningAdjustment?.hasExperimentHistory).slice(0, 5).map((item) => `
        <em>실험학습 ${fmtNumber(item.experimentLearningAdjustment?.historyCount || 0)}건 · 우선순위 ${fmtNumber(item.originalPriority || item.priority || 0)} → ${fmtNumber(item.priority || 0)} · ${escapeHtml(item.title || "")} · ${escapeHtml(item.experimentLearningAdjustment?.adminReason || "")}</em>
      `).join("")}
      ${integratedLearningApplied.slice(0, 5).map((item) => `
        <em>통합학습 ${fmtReportScore(item.integratedLearningAdjustment?.integratedScore || 0)} · 추천신뢰 ${fmtReportScore(item.integratedLearningAdjustment?.recommendationConfidenceScore || 0)} · 우선순위 ${fmtNumber(item.originalPriority || item.priority || 0)} → ${fmtNumber(item.priority || 0)} · ${escapeHtml(item.integratedLearningAdjustment?.adminReason || "")}</em>
      `).join("")}
      ${(experiments || []).slice(0, 5).map((item) => `
        <em>실험 ${escapeHtml(item.category || "")} · 준비도 ${fmtReportScore(item.readinessScore || 0)} · ${escapeHtml(item.adminReview?.formula || "")}</em>
      `).join("")}
      ${(experimentResults.items || []).slice(0, 5).map((item) => `
        <em>실험 결과 ${fmtReportScore(item.performanceScore || 0)} · ${escapeHtml(item.title || "")} · ${escapeHtml(item.adminReview?.formula || item.summary || "")}</em>
      `).join("")}
      ${(quality.items || []).slice(0, 5).map((item) => `
        <em>품질 ${fmtReportScore(item.qualityScore || 0)} · ${escapeHtml(item.title || "")} · ${escapeHtml((item.failureReasons || []).join(" / ") || item.publicSummary || "")}</em>
      `).join("")}
      ${(nextCandidates.items || []).slice(0, 5).map((item) => `
        <em>${escapeHtml(planSourceTypeLabel(item.sourceType))} · ${escapeHtml(item.title || item.category || "")} · ${escapeHtml(item.basis || "")}</em>
      `).join("")}
      ${(progress.incompleteItems || []).slice(0, 5).map((item) => `
        <em>${escapeHtml(item.title || item.category || "전략")} · ${escapeHtml(item.text || "")}</em>
      `).join("")}
    </div>
    <div class="strategy-review-list">
      ${formulas.map((item) => `
        <article class="strategy-review-item">
          <div>
            <span>${escapeHtml(item.category || "전략")}</span>
            <strong>${escapeHtml(item.title || "")}</strong>
          </div>
          <p>${escapeHtml(item.formula || "")}</p>
          <small>${escapeHtml([
            `검수 ${item.reviewStatus?.label || "-"}`,
            `신뢰도 ${item.confidenceGrade || "-"}`,
            `난이도 ${item.executionDifficulty || "-"}`,
            `효과 ${item.expectedEffect || "-"}`,
            `시점 ${item.recommendedTiming || "-"}`,
            `실행 ${executionStatusLabel(item.executionPlan?.status)} ${fmtReportScore(item.executionPlan?.progress || 0)}`,
            item.executionPlan?.sourceCandidateId ? `출처 ${planSourceTypeLabel(item.executionPlan?.sourceType)} ${item.executionPlan?.sourceMonth || ""}` : "출처 수동",
            item.executionPlan?.appliedAt ? `적용 ${String(item.executionPlan.appliedAt).slice(0, 10)} ${item.executionPlan.appliedBy || ""}` : "",
            `지표 ${((item.metricKeys || []).join(", ") || "-")}`
          ].join(" · "))}</small>
          <pre>${escapeHtml(JSON.stringify({
            rawMetricSnapshot: item.rawMetricSnapshot || {},
            recommendationQuality: qualityByStrategy.get(item.strategyId) || null,
            learningAdjustment: item.learningAdjustment || null,
            segmentLearningAdjustment: item.segmentLearningAdjustment || null,
            experimentLearningAdjustment: item.experimentLearningAdjustment || null,
            integratedLearningAdjustment: item.integratedLearningAdjustment || null,
            experimentCandidate: item.experiment || experimentsByStrategy.get(item.strategyId) || null,
            experimentResult: experimentResultsByStrategy.get(item.strategyId) || null
          }, null, 2))}</pre>
        </article>
      `).join("")}
    </div>
  `;
}

function renderMasterCompanyDetail() {
  if (!masterDbAvailable()) return;
  const detail = state.masterDb.detail;
  if (!detail?.company) {
    els.masterCompanyDetail.innerHTML = `<div class="empty">왼쪽 업체를 선택하면 자동 관측값과 관리자 검수값을 분리해 확인하고 수정할 수 있습니다.</div>`;
    return;
  }
  const company = detail.company;
  const profile = detail.profile || {};
  const overrides = profile.overrides || {};
  const observations = detail.observations || [];
  const changeLogs = detail.changeLogs || [];
  els.masterCompanyDetail.innerHTML = `
    <form class="master-profile-form" id="masterProfileForm">
      <div class="master-detail-head">
        <div>
          <h3>${escapeHtml(company.canonicalName || "업체명 미확인")}</h3>
          <p>${escapeHtml(company.companyId)} · 원천 ${escapeHtml(company.identityKey || "")}</p>
        </div>
        <button class="primary-button" type="submit">검수값 저장</button>
      </div>
      <div class="operator-reliability-summary" aria-label="업체 데이터 신뢰도 요약">
        <span><strong>${escapeHtml(profile.finalConfidence || company.autoConfidence || "-")}</strong><em>최종 신뢰도</em></span>
        <span><strong>${fmtNumber(observations.length)}</strong><em>자동 관측값</em></span>
        <span><strong>${fmtNumber(changeLogs.length)}</strong><em>검수 변경 이력</em></span>
        <span><strong>${escapeHtml(profile.b2bVisibility || "검수 필요")}</strong><em>B2B 노출</em></span>
      </div>
      ${renderCompanyReliabilityDetail(state.masterDb.dataReliabilityDetail)}
      <div class="master-form-grid">
        <label class="field"><span>대표 업체명</span><input name="canonicalName" value="${escapeHtml(profile.canonicalName || company.canonicalName || "")}"></label>
        <label class="field"><span>지역</span><input name="region" value="${escapeHtml(profile.region || company.region || "")}"></label>
        <label class="field"><span>업종</span><input name="category" value="${escapeHtml(profile.category || company.category || "")}"></label>
        <label class="field"><span>객실/사이트 기준 수량</span><input name="roomTotal" inputmode="numeric" value="${escapeHtml(overrides.roomTotal ?? "")}"></label>
        <label class="field"><span>데이유즈 기준 수량</span><input name="dayUseTotal" inputmode="numeric" value="${escapeHtml(overrides.dayUseTotal ?? "")}"></label>
        <label class="field"><span>B2B 노출</span><select name="b2bVisibility">
          <option value="eligible" ${profile.b2bVisibility === "eligible" ? "selected" : ""}>노출 가능</option>
          <option value="reference_only" ${profile.b2bVisibility === "reference_only" ? "selected" : ""}>참고 지표만</option>
          <option value="hidden" ${profile.b2bVisibility === "hidden" ? "selected" : ""}>숨김</option>
        </select></label>
        <label class="field"><span>최종 신뢰도</span><select name="finalConfidence">
          <option value="">미정</option>
          ${["A", "B", "C", "D"].map((grade) => `<option value="${grade}" ${profile.finalConfidence === grade ? "selected" : ""}>${grade}</option>`).join("")}
        </select></label>
        <label class="field"><span>검수자</span><input name="reviewedBy" value="${escapeHtml(profile.reviewedBy || "admin")}"></label>
      </div>
      <label class="field"><span>채널 URL</span><textarea name="channelUrls" rows="3" placeholder="채널 URL을 줄바꿈으로 입력">${escapeHtml((overrides.channelUrls || []).join("\n"))}</textarea></label>
      <label class="field"><span>관리자 메모</span><textarea name="notes" rows="3">${escapeHtml(profile.notes || "")}</textarea></label>
    </form>
    <div class="master-detail-columns">
      <section>
        <h3>자동 수집값 property_observations</h3>
        ${renderObservationRows(observations)}
      </section>
      <section>
        <h3>검수 변경 이력 verified_change_logs</h3>
        ${renderChangeRows(changeLogs)}
      </section>
    </div>
    <div class="master-detail-columns strategy-review-columns">
      <section>
        <h3>전략 추천 산식/지표 검수</h3>
        ${renderStrategyReviewRows(state.masterDb.strategyReview)}
      </section>
    </div>
  `;
}

function companyOptionLabel(company = {}) {
  return [company.canonicalName, company.region, company.category].filter(Boolean).join(" · ") || company.companyId;
}

function locationCardsAvailable() {
  return Boolean(els.locationCardConsole && els.locationCardForm && els.locationCardList);
}

function locationCardTypeLabel(value) {
  return {
    region: "지역",
    region_category: "지역+업종",
    property: "업체"
  }[value] || value || "-";
}

function locationCardReviewLabel(value) {
  return {
    draft: "초안",
    review_required: "검수 필요",
    verified: "검수 완료",
    hidden: "비공개"
  }[value] || value || "-";
}

function locationCardReviewTone(value) {
  if (value === "verified") return "good";
  if (value === "review_required") return "warning";
  if (value === "hidden") return "muted";
  return "neutral";
}

function listText(value) {
  return Array.isArray(value) ? value.join("\n") : String(value || "");
}

function populateLocationCardCompanySelects() {
  if (!locationCardsAvailable()) return;
  const companies = state.masterDb.companies || [];
  const options = companies.map((company) => (
    `<option value="${escapeHtml(company.companyId)}">${escapeHtml(companyOptionLabel(company))}</option>`
  )).join("");
  const filterValue = els.locationCardCompanyFilterSelect?.value || "";
  const inputValue = els.locationCardCompanyInput?.value || "";
  if (els.locationCardCompanyFilterSelect) {
    els.locationCardCompanyFilterSelect.innerHTML = `<option value="">전체/지역 카드</option>${options}`;
    els.locationCardCompanyFilterSelect.value = filterValue;
  }
  if (els.locationCardCompanyInput) {
    els.locationCardCompanyInput.innerHTML = `<option value="">지역/업종 카드</option>${options}`;
    els.locationCardCompanyInput.value = inputValue;
  }
}

function selectedCompanyForLocationCard() {
  const companyId = els.locationCardCompanyInput?.value || "";
  return (state.masterDb.companies || []).find((company) => company.companyId === companyId) || null;
}

function syncLocationCardFormForCompany() {
  if (!locationCardsAvailable()) return;
  const company = selectedCompanyForLocationCard();
  if (!company) return;
  const form = els.locationCardForm;
  form.elements.cardType.value = "property";
  if (!form.elements.region.value) form.elements.region.value = company.region || "";
  if (!form.elements.category.value) form.elements.category.value = company.category || "";
}

function resetLocationCardForm(card = null) {
  if (!locationCardsAvailable()) return;
  const form = els.locationCardForm;
  form.reset();
  form.elements.locationCardId.value = card?.locationCardId || "";
  form.elements.cardType.value = card?.cardType || "region_category";
  form.elements.companyId.value = card?.companyId || "";
  form.elements.region.value = card?.region || state.masterDb.detail?.company?.region || "";
  form.elements.category.value = card?.category || state.masterDb.detail?.company?.category || "";
  form.elements.primaryFeature.value = card?.primaryFeature || "";
  form.elements.secondaryFeature.value = card?.secondaryFeature || "";
  form.elements.resources.value = listText(card?.resources);
  form.elements.nearbyCities.value = listText(card?.nearbyCities);
  form.elements.demandKeywords.value = listText(card?.demandKeywords);
  form.elements.searchInterestSummary.value = card?.searchInterestSummary || "";
  form.elements.snsInterestSummary.value = card?.snsInterestSummary || "";
  form.elements.otaExposureSummary.value = card?.otaExposureSummary || "";
  form.elements.leadtimeSummary.value = card?.leadtimeSummary || "";
  form.elements.strategySummary.value = card?.strategySummary || "";
  form.elements.reviewStatus.value = card?.reviewStatus || "review_required";
  form.elements.confidenceGrade.value = card?.confidenceGrade || "C";
  form.elements.reviewedBy.value = card?.reviewedBy || "admin";
  form.elements.exposureEnabled.checked = card ? card.exposureEnabled !== false : true;
  form.elements.adminMemo.value = card?.adminMemo || "";
  if (els.locationCardFormTitle) {
    els.locationCardFormTitle.textContent = card?.locationCardId ? "입지카드 수정" : "입지카드 입력";
  }
}

function focusLocationCardForm(card = null, title = "") {
  if (!locationCardsAvailable()) return;
  if (els.locationCardFormTitle && title) {
    els.locationCardFormTitle.textContent = title;
  } else if (els.locationCardFormTitle && card?.locationCardId) {
    els.locationCardFormTitle.textContent = "입지카드 수정 - 초안 확인";
  }
  els.locationCardForm.scrollIntoView({ behavior: "smooth", block: "start" });
  requestAnimationFrame(() => {
    const focusTarget = els.locationCardForm.querySelector(
      "input[name='primaryFeature'], textarea[name='strategySummary'], input:not([type='hidden']), textarea, select"
    );
    focusTarget?.focus({ preventScroll: true });
  });
}

function locationCardsQuery() {
  const params = new URLSearchParams();
  const region = els.locationCardRegionFilterInput?.value?.trim();
  const category = els.locationCardCategoryFilterInput?.value?.trim();
  const companyId = els.locationCardCompanyFilterSelect?.value || "";
  const reviewStatus = els.locationCardReviewStatusFilterSelect?.value || "";
  const exposure = els.locationCardExposureFilterSelect?.value || "";
  if (region) params.set("region", region);
  if (category) params.set("category", category);
  if (companyId) params.set("companyId", companyId);
  if (reviewStatus) params.set("reviewStatus", reviewStatus);
  if (exposure) params.set("exposure", exposure);
  params.set("limit", "200");
  return `?${params.toString()}`;
}

function renderLocationCardList() {
  if (!locationCardsAvailable()) return;
  const cards = state.masterDb.locationCards || [];
  if (!cards.length) {
    els.locationCardList.innerHTML = `<div class="empty">저장된 입지카드가 없습니다. 지역+업종 카드 또는 업체 카드를 먼저 생성하세요.</div>`;
    return;
  }
  els.locationCardList.innerHTML = cards.map((card) => `
    <article class="location-card-item">
      <div class="location-card-item-head">
        <div>
          <strong>${escapeHtml(card.companyName || card.companyId || [card.region, card.category].filter(Boolean).join(" · ") || "입지카드")}</strong>
          <span>${escapeHtml([card.region, card.category, locationCardTypeLabel(card.cardType)].filter(Boolean).join(" · "))}</span>
        </div>
        <div class="location-card-badges">
          <span class="interest-badge ${locationCardReviewTone(card.reviewStatus)}">${escapeHtml(locationCardReviewLabel(card.reviewStatus))}</span>
          <span class="interest-badge ${card.exposureEnabled === false ? "muted" : "good"}">${card.exposureEnabled === false ? "비공개" : "사업자 반영"}</span>
          <span class="interest-badge neutral">신뢰 ${escapeHtml(card.confidenceGrade || "C")}</span>
        </div>
      </div>
      <div class="location-card-summary">
        <span><b>입지</b>${escapeHtml(card.primaryFeature || "-")}</span>
        <span><b>보조</b>${escapeHtml(card.secondaryFeature || "-")}</span>
        <span><b>키워드</b>${escapeHtml((card.demandKeywords || []).slice(0, 4).join(" · ") || "-")}</span>
        <span><b>접근성</b>${escapeHtml((card.nearbyCities || []).slice(0, 4).join(" · ") || "-")}</span>
      </div>
      <p>${escapeHtml(card.strategySummary || card.searchInterestSummary || card.snsInterestSummary || "전략 연결 요약이 아직 없습니다.")}</p>
      <small>${escapeHtml(card.adminMemo ? `관리자 메모: ${card.adminMemo}` : "관리자 메모 없음")} · ${escapeHtml(card.updatedAt || card.reviewedAt || "")}</small>
      <div class="location-card-actions">
        <button class="ghost-button tiny-button" type="button" data-location-card-id="${escapeHtml(card.locationCardId)}">수정</button>
      </div>
    </article>
  `).join("");
}

async function loadLocationCards() {
  if (!locationCardsAvailable()) return;
  const data = await fetchJson(`/api/admin/master-db/location-cards${locationCardsQuery()}`);
  state.masterDb.locationCards = data.items || [];
  state.masterDb.locationCardLookup = {
    ...(state.masterDb.locationCardLookup || {}),
    ...Object.fromEntries((data.items || []).map((card) => [card.locationCardId, card]))
  };
  renderLocationCardList();
}

function serializeLocationCardForm(form) {
  const data = new FormData(form);
  const payload = {};
  [
    "locationCardId", "cardType", "companyId", "region", "category", "primaryFeature", "secondaryFeature",
    "resources", "nearbyCities", "demandKeywords", "searchInterestSummary", "snsInterestSummary",
    "otaExposureSummary", "leadtimeSummary", "strategySummary", "reviewStatus", "confidenceGrade",
    "reviewedBy", "adminMemo"
  ].forEach((key) => {
    const value = data.get(key);
    if (value !== null && String(value).trim() !== "") payload[key] = value;
  });
  payload.exposureEnabled = Boolean(data.get("exposureEnabled"));
  return payload;
}

async function submitLocationCard(event) {
  event.preventDefault();
  const payload = serializeLocationCardForm(event.currentTarget);
  const result = await fetchJson("/api/admin/master-db/location-cards", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload)
  });
  state.masterDb.status = await fetchJson("/api/admin/master-db/status");
  renderMasterDbStatus();
  if (result.locationCard?.locationCardId) {
    state.masterDb.locationCardLookup = {
      ...(state.masterDb.locationCardLookup || {}),
      [result.locationCard.locationCardId]: result.locationCard
    };
  }
  await loadLocationCards();
  await loadLocationCardRequests();
  resetLocationCardForm(result.locationCard);
  const completedRequests = Number(result.counts?.completedRequests || 0);
  addFeedback(
    completedRequests
      ? `${result.locationCard?.region || "입지카드"} 저장 완료 · 관련 요청 ${fmtNumber(completedRequests)}건 반영 완료`
      : `${result.locationCard?.region || "입지카드"} 저장이 완료되었습니다.`,
    "success"
  );
}

function locationCardRequestsAvailable() {
  return Boolean(els.locationCardRequestConsole && els.locationCardRequestSummary && els.locationCardRequestList);
}

function locationCardRequestStatusLabel(value = "") {
  return {
    requested: "요청 접수",
    draft_created: "초안 생성",
    in_review: "검수중",
    completed: "반영 완료",
    dismissed: "보류"
  }[value] || value || "요청 접수";
}

function locationCardRequestStatusTone(value = "") {
  if (value === "completed") return "good";
  if (["requested", "draft_created", "in_review"].includes(value)) return "warning";
  if (value === "dismissed") return "muted";
  return "neutral";
}

function locationCardRequestSourceLabel(value = "") {
  return {
    business: "B2B 요청",
    admin_search: "관리자 검색",
    data_reliability_queue: "신뢰도 큐"
  }[value] || value || "요청";
}

function locationCardRequestPublicState(item = {}) {
  const cardId = String(item.locationCardId || "").trim();
  if (!cardId) {
    return {
      label: "초안 없음",
      tone: "muted",
      detail: "초안을 생성한 뒤 검수 폼에서 공개 여부를 저장해야 합니다."
    };
  }
  const card = (state.masterDb.locationCards || []).find((entry) => entry.locationCardId === cardId) ||
    state.masterDb.locationCardLookup?.[cardId];
  if (!card) {
    return {
      label: "카드 확인 필요",
      tone: "warning",
      detail: "연결된 입지카드가 현재 목록 조건에 보이지 않습니다. 연결 카드 수정으로 확인하세요."
    };
  }
  if (card.reviewStatus === "verified" && card.exposureEnabled !== false) {
    return {
      label: "공개 가능",
      tone: "good",
      detail: "검수 완료되어 사업자 지역카드에 반영됩니다."
    };
  }
  if (card.reviewStatus === "hidden" || card.exposureEnabled === false) {
    return {
      label: "비공개",
      tone: "muted",
      detail: "사업자 화면에는 아직 반영되지 않습니다."
    };
  }
  return {
    label: "검수 필요",
    tone: "warning",
    detail: "초안 내용을 확인하고 검수 완료/사업자 반영 여부를 저장하세요."
  };
}

async function ensureLocationCardLookupForRequests(items = []) {
  const linkedIds = [...new Set((items || []).map((item) => item.locationCardId).filter(Boolean))];
  if (!linkedIds.length) return;
  const missing = linkedIds.some((cardId) => !state.masterDb.locationCardLookup?.[cardId]);
  if (!missing) return;
  const data = await fetchJson("/api/admin/master-db/location-cards?limit=500");
  state.masterDb.locationCardLookup = {
    ...(state.masterDb.locationCardLookup || {}),
    ...Object.fromEntries((data.items || []).map((card) => [card.locationCardId, card]))
  };
}

function locationCardRequestNextGuide(item = {}, publicState = {}) {
  if (item.status === "completed") return "요청은 반영 완료 상태입니다. 공개 카드 품질만 주기적으로 점검하세요.";
  if (item.status === "dismissed") return "보류된 요청입니다. 필요하면 초안을 다시 만들거나 상태를 검수중으로 바꾸세요.";
  if (!item.locationCardId) return "입지카드 초안 생성 버튼으로 검수 폼을 먼저 만드세요.";
  if (publicState.tone === "good") return "공개 가능한 카드입니다. 저장 시 관련 요청이 자동 반영 완료로 닫힙니다.";
  return publicState.detail || "초안 검수 후 공개 가능 여부를 저장하세요.";
}

function locationCardRequestQuery() {
  const params = new URLSearchParams();
  if (els.locationCardRequestStatusFilter?.value) params.set("status", els.locationCardRequestStatusFilter.value);
  if (els.locationCardRequestSourceFilter?.value) params.set("source", els.locationCardRequestSourceFilter.value);
  params.set("limit", "200");
  return `?${params.toString()}`;
}

function renderLocationCardRequestSummary(data = null) {
  if (!locationCardRequestsAvailable()) return;
  const summary = data?.summary || {};
  const byStatus = summary.byStatus || {};
  const cards = [
    ["전체", summary.total || 0],
    ["활성", summary.active || 0],
    ["요청", byStatus.requested || 0],
    ["초안", byStatus.draft_created || 0],
    ["검수", byStatus.in_review || 0],
    ["완료", byStatus.completed || 0]
  ];
  els.locationCardRequestSummary.innerHTML = cards.map(([label, value]) => `
    <span><strong>${fmtNumber(value)}</strong><em>${escapeHtml(label)}</em></span>
  `).join("");
}

function renderLocationCardRequestItem(item = {}) {
  const publicState = locationCardRequestPublicState(item);
  const linkedCardLabel = item.locationCardId || "초안 미생성";
  const nextGuide = locationCardRequestNextGuide(item, publicState);
  return `
    <article class="location-card-request-item" data-location-card-request-id="${escapeHtml(item.requestId || "")}">
      <div class="location-card-item-head">
        <div>
          <strong>${escapeHtml(item.companyName || item.companyId || [item.region, item.category].filter(Boolean).join(" · ") || "입지카드 요청")}</strong>
          <span>${escapeHtml([item.region, item.category, locationCardRequestSourceLabel(item.source)].filter(Boolean).join(" · "))}</span>
        </div>
        <div class="location-card-badges">
          <span class="interest-badge ${locationCardRequestStatusTone(item.status)}">${escapeHtml(locationCardRequestStatusLabel(item.status))}</span>
          <span class="interest-badge ${publicState.tone}">${escapeHtml(publicState.label)}</span>
          <span class="interest-badge neutral">${escapeHtml(linkedCardLabel)}</span>
        </div>
      </div>
      <div class="location-card-request-detail">
        <span><b>요청 사유</b>${escapeHtml(item.requestReason || "요청 사유가 없습니다.")}</span>
        <span><b>연결 초안</b>${escapeHtml(linkedCardLabel)}</span>
        <span><b>공개 가능 여부</b>${escapeHtml(publicState.label)} · ${escapeHtml(publicState.detail)}</span>
        <span><b>다음 처리</b>${escapeHtml(nextGuide)}</span>
      </div>
      <small>${escapeHtml([item.requestedAt ? `요청 ${String(item.requestedAt).slice(0, 10)}` : "", item.updatedAt ? `갱신 ${String(item.updatedAt).slice(0, 10)}` : ""].filter(Boolean).join(" · "))}</small>
      <div class="location-card-request-actions">
        <button class="secondary-button tiny-button" type="button" data-location-card-request-draft="${escapeHtml(item.requestId || "")}">입지카드 초안 생성</button>
        ${item.locationCardId ? `<button class="ghost-button tiny-button" type="button" data-location-card-request-edit-card="${escapeHtml(item.locationCardId)}">연결 카드 수정</button>` : ""}
        <button class="ghost-button tiny-button" type="button" data-location-card-request-status="${escapeHtml(item.requestId || "")}" data-status="in_review">검수중</button>
        <button class="ghost-button tiny-button" type="button" data-location-card-request-status="${escapeHtml(item.requestId || "")}" data-status="completed">반영 완료</button>
        <button class="ghost-button tiny-button" type="button" data-location-card-request-status="${escapeHtml(item.requestId || "")}" data-status="dismissed">보류</button>
      </div>
    </article>
  `;
}

function renderLocationCardRequests() {
  if (!locationCardRequestsAvailable()) return;
  const data = state.masterDb.locationCardRequests;
  if (!data) {
    els.locationCardRequestSummary.innerHTML = `<div class="empty">입지카드 제작 요청을 불러오는 중입니다.</div>`;
    els.locationCardRequestList.innerHTML = `<div class="empty">입지카드 제작 요청을 불러오는 중입니다.</div>`;
    return;
  }
  renderLocationCardRequestSummary(data);
  const items = data.items || [];
  if (!items.length) {
    els.locationCardRequestList.innerHTML = `<div class="empty">현재 조건에 해당하는 입지카드 제작 요청이 없습니다.</div>`;
    return;
  }
  els.locationCardRequestList.innerHTML = items.map(renderLocationCardRequestItem).join("");
}

async function loadLocationCardRequests() {
  if (!locationCardRequestsAvailable()) return;
  state.masterDb.locationCardRequests = await fetchJson(`/api/admin/master-db/location-card-requests${locationCardRequestQuery()}`);
  await ensureLocationCardLookupForRequests(state.masterDb.locationCardRequests.items || []);
  renderLocationCardRequests();
}

async function createLocationCardDraft(payload = {}) {
  const result = await fetchJson("/api/admin/master-db/location-card-drafts", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload)
  });
  resetLocationCardForm(result.locationCard);
  if (result.locationCard?.locationCardId) {
    state.masterDb.locationCardLookup = {
      ...(state.masterDb.locationCardLookup || {}),
      [result.locationCard.locationCardId]: result.locationCard
    };
  }
  focusLocationCardForm(result.locationCard, "입지카드 수정 - 초안 검수");
  await loadLocationCards();
  await loadLocationCardRequests();
  await loadDataReliabilityActionQueue();
  addFeedback("입지카드 초안이 생성되었습니다. 검수 후 공개 여부를 저장하세요.", "success");
  return result;
}

async function createLocationCardDraftFromSearch() {
  const companyId = els.locationCardCompanyFilterSelect?.value || els.locationCardCompanyInput?.value || "";
  const selectedCompany = (state.masterDb.companies || []).find((company) => company.companyId === companyId) || null;
  const region = els.locationCardRegionFilterInput?.value?.trim() || els.locationCardForm?.elements?.region?.value || selectedCompany?.region || "";
  const category = els.locationCardCategoryFilterInput?.value?.trim() || els.locationCardForm?.elements?.category?.value || selectedCompany?.category || "";
  if (!companyId && !region) {
    addFeedback("입지카드 초안을 만들려면 업체를 선택하거나 지역을 입력하세요.", "warning");
    return null;
  }
  return createLocationCardDraft({
    source: "admin_search",
    companyId,
    companyName: selectedCompany?.canonicalName || "",
    region,
    category,
    adminMemo: "admin search draft"
  });
}

async function createLocationCardDraftFromRequest(requestId = "") {
  if (!requestId) return null;
  const result = await fetchJson(`/api/admin/master-db/location-card-requests/${encodeURIComponent(requestId)}/draft`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({})
  });
  resetLocationCardForm(result.locationCard);
  if (result.locationCard?.locationCardId) {
    state.masterDb.locationCardLookup = {
      ...(state.masterDb.locationCardLookup || {}),
      [result.locationCard.locationCardId]: result.locationCard
    };
  }
  focusLocationCardForm(result.locationCard, "입지카드 수정 - 요청 초안 검수");
  await loadLocationCards();
  await loadLocationCardRequests();
  addFeedback("B2B 요청 기반 입지카드 초안이 생성되었습니다.", "success");
  return result;
}

async function updateLocationCardRequestStatus(requestId = "", status = "") {
  if (!requestId || !status) return null;
  const result = await fetchJson(`/api/admin/master-db/location-card-requests/${encodeURIComponent(requestId)}`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ status })
  });
  await loadLocationCardRequests();
  addFeedback(`입지카드 요청 상태가 ${locationCardRequestStatusLabel(status)}(으)로 변경되었습니다.`, "success");
  return result;
}

async function editLocationCardFromRequest(cardId = "") {
  if (!cardId) return null;
  let card = (state.masterDb.locationCards || []).find((item) => item.locationCardId === cardId);
  if (!card) {
    const data = await fetchJson("/api/admin/master-db/location-cards?limit=500");
    state.masterDb.locationCards = data.items || [];
    state.masterDb.locationCardLookup = {
      ...(state.masterDb.locationCardLookup || {}),
      ...Object.fromEntries((data.items || []).map((entry) => [entry.locationCardId, entry]))
    };
    renderLocationCardList();
    card = state.masterDb.locationCards.find((item) => item.locationCardId === cardId);
  }
  if (!card) {
    addFeedback("연결된 입지카드를 현재 목록에서 찾지 못했습니다. 필터를 초기화하고 다시 확인하세요.", "warning");
    return null;
  }
  resetLocationCardForm(card);
  focusLocationCardForm(card, "입지카드 수정 - 요청 연결 카드");
  return card;
}

async function createLocationCardDraftFromQueue(queueItemId = "") {
  if (!queueItemId) return null;
  return createLocationCardDraft({
    source: "data_reliability_queue",
    queueItemId
  });
}

function populateInterestCompanySelects() {
  if (!interestSignalsAvailable()) return;
  const companies = state.masterDb.companies || [];
  const currentFilter = els.interestCompanyFilterSelect?.value || "";
  const currentInput = els.interestCompanyInput?.value || "";
  const options = companies.map((company) => (
    `<option value="${escapeHtml(company.companyId)}">${escapeHtml(companyOptionLabel(company))}</option>`
  )).join("");
  if (els.interestCompanyFilterSelect) {
    els.interestCompanyFilterSelect.innerHTML = `<option value="">전체/지역 신호</option>${options}`;
    els.interestCompanyFilterSelect.value = currentFilter;
  }
  if (els.interestCompanyInput) {
    els.interestCompanyInput.innerHTML = `<option value="">지역 키워드 신호</option>${options}`;
    els.interestCompanyInput.value = currentInput;
  }
  if (els.interestJobCompanySelect) {
    const currentJobCompany = els.interestJobCompanySelect.value || "";
    els.interestJobCompanySelect.innerHTML = `<option value="">지역 키워드만</option>${options}`;
    els.interestJobCompanySelect.value = currentJobCompany;
  }
}

