function scheduleAuditEventLabel(eventType = "") {
  return {
    policy_created: "정책 생성",
    policy_saved: "정책 저장",
    scheduled_run: "기한 실행",
    forced_run: "강제 실행",
    quota_blocked: "쿼터 차단",
    retry_run_result: "재시도 결과"
  }[eventType] || eventType || "감사 이벤트";
}

function scheduleAuditTone(item = {}) {
  if (item.eventType === "quota_blocked" || item.status === "blocked" || item.status === "failed") return "danger";
  if (["retry_scheduled", "review_required", "changed"].includes(item.status)) return "warning";
  return "good";
}

function scheduleAuditValue(value) {
  if (value === undefined || value === null || value === "") return "-";
  if (typeof value === "object") {
    const text = JSON.stringify(value);
    return text.length > 80 ? `${text.slice(0, 77)}...` : text;
  }
  const text = String(value);
  return text.length > 80 ? `${text.slice(0, 77)}...` : text;
}

function renderScheduleAuditChanges(changes = []) {
  if (!changes.length) return `<span class="muted">변경 필드 없음</span>`;
  return changes.slice(0, 5).map((change) => `
    <span>
      <strong>${escapeHtml(change.field || "-")}</strong>
      <em>${escapeHtml(scheduleAuditValue(change.before))} → ${escapeHtml(scheduleAuditValue(change.after))}</em>
    </span>
  `).join("");
}

