function interestJobSignalTypeForSource(source) {
  if (source === "naver_trend") return "naver_trend";
  if (source === "sns") return "sns_mentions";
  return "search_volume";
}

async function generateInterestJobs() {
  const source = els.interestJobSourceSelect?.value || "naver_searchad";
  const companyId = els.interestJobCompanySelect?.value || "";
  const payload = {
    region: els.interestJobRegionInput?.value?.trim() || els.interestRegionFilterInput?.value?.trim() || "",
    category: els.interestJobCategoryInput?.value?.trim() || "",
    companyId,
    keywords: els.interestJobKeywordsInput?.value || "",
    source,
    signalTypes: [interestJobSignalTypeForSource(source)],
    includeRegionKeywords: Boolean(els.interestJobIncludeRegionInput?.checked),
    includePropertyKeywords: Boolean(els.interestJobIncludePropertyInput?.checked && companyId),
    requestedBy: "admin"
  };
  const result = await fetchJson("/api/admin/master-db/interest-signal-jobs/generate", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload)
  });
  state.masterDb.status = await fetchJson("/api/admin/master-db/status");
  renderMasterDbStatus();
  await Promise.all([loadInterestJobs(), loadInterestSignals(), loadExternalConnectors()]);
  addFeedback(`관심도 수집 큐 ${fmtNumber(result.counts?.created || 0)}건 생성, ${fmtNumber(result.counts?.skipped || 0)}건 중복 제외`, "success");
}

async function updateInterestJobStatus(jobId, status) {
  const payload = { status };
  if (status === "failed") payload.lastError = "관리자 표시: 수집 실패";
  if (status === "review_required") payload.reviewReason = "관리자 표시: 검수 필요";
  const result = await fetchJson(`/api/admin/master-db/interest-signal-jobs/${encodeURIComponent(jobId)}`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload)
  });
  state.masterDb.status = await fetchJson("/api/admin/master-db/status");
  renderMasterDbStatus();
  await Promise.all([loadInterestJobs(), loadInterestSignals()]);
  addFeedback(`${result.job?.keyword || "수집 작업"} 상태를 ${interestJobStatusLabel(status)}로 변경했습니다.`, "success");
}

function externalConnectorRunPayload(extra = {}) {
  const companyTarget = els.externalConnectorCompanyInput?.value?.trim() || "";
  const companyId = /^cmp_/i.test(companyTarget) ? companyTarget : "";
  const companyName = companyId ? "" : companyTarget;
  return {
    connectorMode: els.externalConnectorModeSelect?.value || "auto",
    startDate: els.externalConnectorStartDateInput?.value || "",
    endDate: els.externalConnectorEndDateInput?.value || "",
    timeUnit: els.externalConnectorTimeUnitSelect?.value || "date",
    device: els.externalConnectorDeviceSelect?.value || "",
    platforms: els.externalConnectorSnsPlatformsInput?.value || "",
    snsPlatforms: els.externalConnectorSnsPlatformsInput?.value || "",
    channels: els.externalConnectorOtaChannelsInput?.value || "",
    otaChannels: els.externalConnectorOtaChannelsInput?.value || "",
    companyId,
    companyName,
    region: els.externalConnectorRegionInput?.value || "",
    ...extra
  };
}

async function runInterestJob(jobId) {
  const connectorPayload = externalConnectorRunPayload();
  const result = await fetchJson(`/api/admin/master-db/interest-signal-jobs/${encodeURIComponent(jobId)}/run`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(connectorPayload)
  });
  state.masterDb.status = await fetchJson("/api/admin/master-db/status");
  renderMasterDbStatus();
  await Promise.all([loadInterestJobs(), loadInterestSignals(), loadExternalConnectors()]);
  addFeedback(`${result.job?.keyword || "수집 작업"} ${connectorModeLabel(result.connector?.mode)} 실행 완료: ${interestJobStatusLabel(result.job?.status)}`, "success");
}

async function runQueuedInterestJobs() {
  const source = els.interestJobSourceSelect?.value || "";
  const connectorPayload = externalConnectorRunPayload({ source, limit: 25 });
  const result = await fetchJson("/api/admin/master-db/interest-signal-jobs/run-queued", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(connectorPayload)
  });
  state.masterDb.status = await fetchJson("/api/admin/master-db/status");
  renderMasterDbStatus();
  await Promise.all([loadInterestJobs(), loadInterestSignals(), loadExternalConnectors()]);
  addFeedback(`대기 큐 ${fmtNumber(result.requested || 0)}건 실행: 성공 ${fmtNumber(result.counts?.succeeded || 0)}, 검수 ${fmtNumber(result.counts?.review_required || 0)}, 실패 ${fmtNumber(result.counts?.failed || 0)}`, "success");
}

async function runExternalConnectorQueued(connectorId = "") {
  const selectedConnector = connectorId || els.externalConnectorSourceSelect?.value || "";
  const connectorPayload = externalConnectorRunPayload({ connectorId: selectedConnector, limit: 25 });
  if (selectedConnector === "ota_exposure") {
    const result = await fetchJson("/api/admin/master-db/external-connectors/ota-exposure/run", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(connectorPayload)
    });
    state.masterDb.status = await fetchJson("/api/admin/master-db/status");
    renderMasterDbStatus();
    const currentCompanyId = state.masterDb.detail?.company?.companyId || "";
    await Promise.all([
      currentCompanyId ? loadMasterCompanyDetail(currentCompanyId) : Promise.resolve(),
      loadExternalConnectors()
    ]);
    addFeedback(`OTA 노출 ${fmtNumber(result.requested || 0)}개 업체 실행: 성공 ${fmtNumber(result.counts?.succeeded || 0)}, 검수 ${fmtNumber(result.counts?.review_required || 0)}, 실패 ${fmtNumber(result.counts?.failed || 0)}`, "success");
    return;
  }
  const result = await fetchJson("/api/admin/master-db/external-connectors/run-queued", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(connectorPayload)
  });
  state.masterDb.status = await fetchJson("/api/admin/master-db/status");
  renderMasterDbStatus();
  await Promise.all([loadInterestJobs(), loadInterestSignals(), loadExternalConnectors()]);
  addFeedback(`외부 커넥터 ${fmtNumber(result.requested || 0)}건 실행: 성공 ${fmtNumber(result.counts?.succeeded || 0)}, 검수 ${fmtNumber(result.counts?.review_required || 0)}, 실패 ${fmtNumber(result.counts?.failed || 0)}`, "success");
}

function scheduleCardPayload(connectorId = "") {
  const card = els.externalConnectorScheduleList?.querySelector(`[data-schedule-connector="${CSS.escape(connectorId)}"]`);
  if (!card) return null;
  const field = (name) => card.querySelector(`[data-schedule-field="${name}"]`);
  return {
    connectorId,
    enabled: Boolean(field("enabled")?.checked),
    intervalMinutes: field("intervalMinutes")?.value || 720,
    targetScope: field("targetScope")?.value || "queued_and_retry",
    dailyLimit: field("dailyLimit")?.value || 25,
    retryLimit: field("retryLimit")?.value || 2,
    quotaWarningThreshold: field("quotaWarningThreshold")?.value || 70,
    quotaStopThreshold: field("quotaStopThreshold")?.value || 90,
    runOptions: parseScheduleRunOptions(field("runOptionsText")?.value || ""),
    updatedBy: "admin"
  };
}

async function saveExternalConnectorSchedule(connectorId = "") {
  const policy = scheduleCardPayload(connectorId);
  if (!policy) return;
  const result = await fetchJson("/api/admin/master-db/external-connector-schedules", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ policy, updatedBy: "admin" })
  });
  state.masterDb.externalConnectorSchedules = result;
  await loadExternalConnectors();
  addFeedback(`${connectorId} 자동 실행 정책이 저장되었습니다.`, "success");
}

async function runExternalConnectorSchedule(connectorId = "", force = true) {
  const result = await fetchJson("/api/admin/master-db/external-connector-schedules/run-due", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ connectorId, force })
  });
  state.masterDb.status = await fetchJson("/api/admin/master-db/status");
  renderMasterDbStatus();
  await loadExternalConnectors();
  addFeedback(`스케줄 실행 ${fmtNumber(result.requested || 0)}건 완료 · 쿼터 차단 ${fmtNumber(result.quotaBlocked || 0)}건`, "success");
}

function serializeInterestSignalForm(form) {
  const data = new FormData(form);
  const payload = {};
  [
    "signalId", "region", "companyId", "keyword", "signalType", "scope", "source", "status",
    "score", "trendIndex", "monthlySearchVolume", "pcSearchVolume", "mobileSearchVolume",
    "mentionCount", "positiveMentionCount", "negativeMentionCount", "confidence", "reviewedBy",
    "observedAt", "notes"
  ].forEach((key) => {
    const value = data.get(key);
    if (value !== null && String(value).trim() !== "") payload[key] = value;
  });
  return payload;
}

async function submitInterestSignal(event) {
  event.preventDefault();
  const payload = serializeInterestSignalForm(event.currentTarget);
  const result = await fetchJson("/api/admin/master-db/interest-signals", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload)
  });
  state.masterDb.status = await fetchJson("/api/admin/master-db/status");
  renderMasterDbStatus();
  await loadInterestSignals();
  resetInterestSignalForm(result.signal);
  addFeedback(`${result.signal?.keyword || "관심도 신호"} 저장이 완료되었습니다.`, "success");
}

