async function loadMasterCompanyDetail(companyId) {
  if (!companyId) return;
  const [detail, strategyReview, reliabilityAudit] = await Promise.all([
    fetchJson(`/api/admin/master-db/companies/${encodeURIComponent(companyId)}`),
    fetchJson(`/api/admin/master-db/strategy-recommendations?companyId=${encodeURIComponent(companyId)}`),
    fetchJson(`/api/admin/master-db/data-reliability-audit?companyId=${encodeURIComponent(companyId)}&limit=1`)
  ]);
  state.masterDb.detail = detail;
  state.masterDb.strategyReview = strategyReview;
  state.masterDb.dataReliabilityDetail = reliabilityAudit.items?.[0] || null;
  renderMasterCompanyList();
  renderMasterCompanyDetail();
}

function learningCalibrationParamsFromPanel() {
  const params = new URLSearchParams();
  const panel = els.masterCompanyDetail?.querySelector("[data-learning-calibration-panel]");
  panel?.querySelectorAll("[data-calibration-field]").forEach((input) => {
    params.set(input.dataset.calibrationField, input.value);
  });
  return params;
}

function learningCalibrationSettingsFromPanel() {
  const settings = {};
  learningCalibrationParamsFromPanel().forEach((value, key) => {
    settings[key] = value;
  });
  return settings;
}

function learningCalibrationAuditParamsFromPanel() {
  const params = new URLSearchParams();
  const panel = els.masterCompanyDetail?.querySelector("[data-learning-calibration-audit]");
  let hasCompanyFilterField = false;
  panel?.querySelectorAll("[data-calibration-audit-filter]").forEach((input) => {
    const key = input.dataset.calibrationAuditFilter;
    const value = String(input.value || "").trim();
    if (key === "companyId") hasCompanyFilterField = true;
    if (value) params.set(key, value);
  });
  if (!hasCompanyFilterField && !params.has("companyId")) {
    const companyId = state.masterDb.detail?.company?.companyId;
    if (companyId) params.set("companyId", companyId);
  }
  if (!params.has("limit")) params.set("limit", "20");
  return params;
}

async function applyLearningCalibrationAuditFilters() {
  await refreshLearningCalibrationAuditPanel();
  addFeedback("Learning calibration audit filters applied.", "success");
}

async function refreshLearningCalibrationAuditPanel() {
  if (!els.masterCompanyDetail?.querySelector("[data-learning-calibration-audit]")) return;
  const params = learningCalibrationAuditParamsFromPanel();
  const result = await fetchJson(`/api/admin/master-db/learning-calibration-audit?${params.toString()}`);
  state.masterDb.strategyReview = {
    ...(state.masterDb.strategyReview || {}),
    learningCalibrationAudit: result
  };
  renderMasterCompanyDetail();
}

