function auditReviewPayloadFromQueuePanel(panel, versionId = "") {
  const resolvedVersionId = versionId || panel?.dataset.calibrationAuditQueueVersionId || "";
  const payload = {
    versionId: resolvedVersionId,
    companyId: panel?.dataset.calibrationAuditQueueCompanyId || "",
    targetMonth: panel?.dataset.calibrationAuditQueueTargetMonth || "",
    auditMonth: panel?.dataset.calibrationAuditQueueMonth || "",
    updatedBy: els.masterCompanyDetail?.querySelector("#learningCalibrationAppliedBy")?.value || "admin"
  };
  return payload;
}

function auditReviewPayloadFromQueue(versionId) {
  const panel = Array.from(els.calibrationAuditQueueList?.querySelectorAll("[data-calibration-audit-queue-version-id]") || [])
    .find((item) => item.dataset.calibrationAuditQueueVersionId === versionId);
  const payload = auditReviewPayloadFromQueuePanel(panel, versionId);
  panel?.querySelectorAll("[data-queue-review-field]").forEach((field) => {
    payload[field.dataset.queueReviewField] = field.value;
  });
  return payload;
}

function selectedCalibrationAuditQueuePayloads() {
  return Array.from(els.calibrationAuditQueueList?.querySelectorAll("[data-calibration-audit-queue-select]:checked") || [])
    .map((checkbox) => {
      const item = checkbox.closest(".calibration-audit-queue-item");
      const panel = item?.querySelector("[data-calibration-audit-queue-version-id]");
      return auditReviewPayloadFromQueuePanel(panel, checkbox.dataset.calibrationAuditQueueSelect || "");
    })
    .filter((item) => item.versionId);
}

function calibrationAuditQueueBulkUpdates() {
  const updates = {};
  const status = els.calibrationAuditQueueBulkStatus?.value || "";
  const owner = String(els.calibrationAuditQueueBulkOwner?.value || "").trim();
  const dueDate = els.calibrationAuditQueueBulkDue?.value || "";
  const memo = String(els.calibrationAuditQueueBulkMemo?.value || "").trim();
  if (status) updates.reviewStatus = status;
  if (owner) updates.followUpOwner = owner;
  if (dueDate) updates.followUpDueDate = dueDate;
  if (memo) updates.adminMemo = memo;
  return updates;
}

function updateCalibrationAuditQueueBulkState() {
  const selectedCount = selectedCalibrationAuditQueuePayloads().length;
  if (els.calibrationAuditQueueBulkSelectedCount) {
    els.calibrationAuditQueueBulkSelectedCount.textContent = `${fmtNumber(selectedCount)} selected`;
  }
  if (els.calibrationAuditQueueBulkApplyButton) {
    els.calibrationAuditQueueBulkApplyButton.disabled = selectedCount === 0;
  }
}

function setCalibrationAuditQueueSelection(checked) {
  els.calibrationAuditQueueList?.querySelectorAll("[data-calibration-audit-queue-select]").forEach((checkbox) => {
    checkbox.checked = checked;
  });
  updateCalibrationAuditQueueBulkState();
}

async function saveCalibrationAuditQueueReview(versionId) {
  if (!versionId) return;
  await fetchJson("/api/admin/master-db/learning-calibration-audit-reviews", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(auditReviewPayloadFromQueue(versionId))
  });
  await loadCalibrationAuditQueue();
  await refreshLearningCalibrationAuditPanel();
  addFeedback(`Calibration audit queue item saved: ${versionId}.`, "success");
}

async function saveCalibrationAuditQueueBulkReview() {
  const items = selectedCalibrationAuditQueuePayloads();
  if (!items.length) {
    addFeedback("Select at least one calibration audit queue item.", "error");
    return;
  }
  const updates = calibrationAuditQueueBulkUpdates();
  if (!Object.keys(updates).length) {
    addFeedback("Add at least one bulk review update value.", "error");
    return;
  }
  const result = await fetchJson("/api/admin/master-db/learning-calibration-audit-reviews/bulk", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      items,
      updates,
      updatedBy: els.masterCompanyDetail?.querySelector("#learningCalibrationAppliedBy")?.value || "admin"
    })
  });
  await loadCalibrationAuditQueue();
  await refreshLearningCalibrationAuditPanel();
  addFeedback(`Calibration audit queue bulk update saved: ${fmtNumber(result.bulkReview?.updated || items.length)} items.`, "success");
}

function slaActionPayloadFromCard(actionId) {
  const cards = [
    ...Array.from(els.calibrationAuditQueueList?.querySelectorAll("[data-calibration-sla-action-id]") || []),
    ...Array.from(els.calibrationSlaActionQueueList?.querySelectorAll("[data-calibration-sla-action-id]") || [])
  ];
  const card = cards
    .find((item) => item.dataset.calibrationSlaActionId === actionId);
  let sourceMetrics = {};
  try {
    sourceMetrics = JSON.parse(card?.dataset.slaActionSourceMetrics || "{}");
  } catch {
    sourceMetrics = {};
  }
  const payload = {
    actionId,
    sourceKey: card?.dataset.slaActionSourceKey || "",
    sourceType: card?.dataset.slaActionSourceType || "summary",
    sourceLabel: card?.dataset.slaActionSourceLabel || "",
    month: card?.dataset.slaActionMonth || "",
    owner: card?.dataset.slaActionOwner || "",
    slaLevel: card?.dataset.slaActionLevel || "",
    issueKey: card?.dataset.slaActionIssueKey || "",
    severity: card?.dataset.slaActionSeverity || "",
    rootMetric: card?.dataset.slaActionRootMetric || "",
    sourceMetrics,
    updatedBy: els.masterCompanyDetail?.querySelector("#learningCalibrationAppliedBy")?.value || "admin"
  };
  card?.querySelectorAll("[data-sla-action-field]").forEach((field) => {
    payload[field.dataset.slaActionField] = field.value;
  });
  if (!payload.recommendation) {
    payload.recommendation = card?.querySelector("p")?.textContent || "";
  }
  return payload;
}

