function slaQualityRereviewActionAutoPolicyLearningSlaActionPayloadFromCard(actionId) {
  const card = Array.from(els.slaQualityRereviewActionRecommendationAutoApprovalPerformanceList?.querySelectorAll("[data-sla-quality-rereview-auto-policy-learning-sla-action-id]") || [])
    .find((item) => item.dataset.slaQualityRereviewAutoPolicyLearningSlaActionId === actionId);
  if (!card) return null;
  let sourceMetrics = {};
  try {
    sourceMetrics = JSON.parse(card.dataset.slaQualityRereviewAutoPolicyLearningSlaActionSourceMetrics || "{}");
  } catch {
    sourceMetrics = {};
  }
  const payload = {
    actionId,
    sourceKey: card.dataset.slaQualityRereviewAutoPolicyLearningSlaActionSourceKey || "",
    sourceType: card.dataset.slaQualityRereviewAutoPolicyLearningSlaActionSourceType || "summary",
    sourceLabel: card.dataset.slaQualityRereviewAutoPolicyLearningSlaActionSourceLabel || "",
    month: card.dataset.slaQualityRereviewAutoPolicyLearningSlaActionMonth || "",
    owner: card.dataset.slaQualityRereviewAutoPolicyLearningSlaActionOwner || "",
    slaLevel: card.dataset.slaQualityRereviewAutoPolicyLearningSlaActionLevel || "",
    issueKey: card.dataset.slaQualityRereviewAutoPolicyLearningSlaActionIssueKey || "",
    severity: card.dataset.slaQualityRereviewAutoPolicyLearningSlaActionSeverity || "",
    rootMetric: card.dataset.slaQualityRereviewAutoPolicyLearningSlaActionRootMetric || "",
    sourceMetrics,
    updatedBy: els.masterCompanyDetail?.querySelector("#learningCalibrationAppliedBy")?.value || "admin"
  };
  card.querySelectorAll("[data-sla-quality-rereview-auto-policy-learning-sla-action-field]").forEach((field) => {
    payload[field.dataset.slaQualityRereviewAutoPolicyLearningSlaActionField] = field.value;
  });
  if (!payload.recommendation) {
    payload.recommendation = card.querySelector("p")?.textContent || "";
  }
  return payload;
}

