function serializeMasterProfileForm(form) {
  const data = new FormData(form);
  return {
    canonicalName: data.get("canonicalName"),
    region: data.get("region"),
    category: data.get("category"),
    roomTotal: data.get("roomTotal"),
    dayUseTotal: data.get("dayUseTotal"),
    b2bVisibility: data.get("b2bVisibility"),
    finalConfidence: data.get("finalConfidence"),
    reviewedBy: data.get("reviewedBy"),
    channelUrls: data.get("channelUrls"),
    notes: data.get("notes")
  };
}

async function submitMasterProfile(event) {
  event.preventDefault();
  const companyId = state.masterDb.detail?.company?.companyId;
  if (!companyId) return;
  const payload = serializeMasterProfileForm(event.currentTarget);
  const result = await fetchJson(`/api/admin/master-db/verified-profiles/${encodeURIComponent(companyId)}`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload)
  });
  await loadMasterDbCompanies();
  await loadMasterCompanyDetail(companyId);
  addFeedback(`${result.profile?.canonicalName || "업체"} 검수값을 저장했습니다.`, "success");
}

async function rebuildMasterDb() {
  const body = state.activeRunId ? { runId: state.activeRunId } : {};
  const result = await fetchJson("/api/admin/master-db/rebuild", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body)
  });
  await loadMasterDbCompanies();
  addFeedback(`DB 적재 완료: 업체 ${fmtNumber(result.counts?.companies || 0)}개, 관측값 ${fmtNumber(result.counts?.observations || 0)}개`, "success");
}

function businessMode() {
  return state.appRole === "business";
}

function setTheme(theme) {
  const nextTheme = theme === "dark" ? "dark" : "light";
  document.body.dataset.theme = nextTheme;
  try {
    localStorage.setItem("lodgingDataLabTheme", nextTheme);
  } catch {
    // Ignore private-mode storage failures.
  }
  if (els.themeToggleButton) {
    els.themeToggleButton.textContent = nextTheme === "dark" ? "라이트 모드" : "다크 모드";
    els.themeToggleButton.setAttribute("aria-pressed", String(nextTheme === "dark"));
  }
}

function initializeTheme() {
  let savedTheme = "light";
  try {
    savedTheme = localStorage.getItem("lodgingDataLabTheme") || "light";
  } catch {
    savedTheme = "light";
  }
  setTheme(savedTheme);
}

function fmtReportRate(value) {
  if (value === null || value === undefined || Number.isNaN(Number(value))) return "-";
  return `${Math.round(Number(value) * 100)}%`;
}

function fmtReportScore(value) {
  if (value === null || value === undefined || Number.isNaN(Number(value))) return "-";
  return `${Math.round(Number(value))}점`;
}

function fmtReportPrice(value) {
  if (value === null || value === undefined || Number.isNaN(Number(value))) return "-";
  return `${fmtNumber(Math.round(Number(value)))}원`;
}

function clampPercent(value) {
  const number = Number(value);
  if (!Number.isFinite(number)) return 0;
  return Math.max(0, Math.min(100, number));
}

function statusLabel(value) {
  const labels = {
    above_baseline: "비교군보다 높음",
    below_baseline: "비교군보다 낮음",
    near_baseline: "비교군과 유사",
    insufficient_data: "데이터 부족"
  };
  return labels[value] || value || "-";
}

function positionTone(status, mode = "higher") {
  if (status === "insufficient_data") return "muted";
  if (status === "near_baseline") return "neutral";
  if (mode === "lower") return status === "below_baseline" ? "good" : "warning";
  return status === "above_baseline" ? "good" : "warning";
}

function badge(label, tone = "neutral") {
  return `<span class="business-badge ${tone}">${escapeHtml(label)}</span>`;
}

function reportFlowStatusMeta(status = "loading") {
  return ({
    ready: { label: "신뢰 가능", tone: "good" },
    review: { label: "검수 필요", tone: "warning" },
    empty: { label: "데이터 부족", tone: "muted" },
    loading: { label: "불러오는 중", tone: "neutral" }
  })[status] || { label: "확인 필요", tone: "neutral" };
}

function confidenceReady(grade = "") {
  return ["A", "B"].includes(String(grade || "").toUpperCase());
}

function statusFromCounts(primaryCount = 0, reviewFlag = false, readyThreshold = 1) {
  if (!Number(primaryCount || 0)) return "empty";
  if (reviewFlag || Number(primaryCount || 0) < readyThreshold) return "review";
  return "ready";
}

function businessMonthlyStepTarget(step = "") {
  return ({
    "01": "businessFlowGrid",
    "02": "businessRegionCard",
    "03": "businessStrategySummary",
    "04": "businessOperations",
    "05": "businessRetrospective",
    "06": "businessNextPlan"
  })[String(step || "")] || "businessFlowGrid";
}

function flowObservationCount(flows = {}) {
  return Object.values(flows || {}).reduce((sum, flow) => {
    return sum + Number(flow?.metrics?.observationCount || 0);
  }, 0);
}

function recommendationConfidenceNeedsReview(items = []) {
  return items.some((item) => ["D", ""].includes(String(item.recommendationConfidenceGrade || item.confidenceGrade || "").toUpperCase()));
}

function regionSignalCount(card = {}) {
  return [
    card.structure?.primary,
    card.searchInterest?.score !== null && card.searchInterest?.score !== undefined,
    card.snsInterest?.score !== null && card.snsInterest?.score !== undefined,
    Number(card.otaExposure?.channelCount || 0) > 0,
    Number(card.leadtime?.patternCount || 0) > 0 || Number(card.leadtime?.avgBookingPaceScore || 0) > 0,
    (card.demandKeywords || []).length > 0
  ].filter(Boolean).length;
}

function businessMonthlyFlowSteps() {
  const report = state.business.report;
  const board = state.business.operationsBoard;
  const retrospective = state.business.retrospective;
  const nextPlan = state.business.nextMonthCandidates;
  if (!report) {
    return [
      ["01", "리포트", "loading", "숙소 선택 후 로드됩니다.", "시장 비교를 준비 중입니다."],
      ["02", "지역카드", "loading", "지역 신호를 기다립니다.", "입지·수요 근거를 준비합니다."],
      ["03", "전략 추천", "loading", "실행 카드 생성 전입니다.", "지표 조합을 기다립니다."],
      ["04", "실행계획", "loading", "운영보드 로드 전입니다.", "담당자·KPI 입력을 준비합니다."],
      ["05", "월간 회고", "loading", "회고 로드 전입니다.", "성과 판단을 준비합니다."],
      ["06", "다음달 후보", "loading", "후보 로드 전입니다.", "다음달 계획을 준비합니다."]
    ].map(([step, title, status, summary, nextAction]) => ({ step, title, status, summary, nextAction }));
  }

  const flows = report.flows || {};
  const observationCount = flowObservationCount(flows);
  const companyGrade = report.company?.confidenceGrade || "";
  const regionCard = report.regionCard || {};
  const regionSignals = regionSignalCount(regionCard);
  const recommendations = report.strategyRecommendations || [];
  const operationsSummary = board?.summary || {};
  const operationsTotal = Number(operationsSummary.total || operationsSummary.count || (board?.sections?.all || []).length || 0);
  const retrospectiveSummary = retrospective?.summary || {};
  const retrospectiveTotal = Number(retrospectiveSummary.totalPlans || 0);
  const nextSummary = nextPlan?.summary || {};
  const nextTotal = Number(nextSummary.total || 0);

  return [
    {
      step: "01",
      title: "리포트",
      status: statusFromCounts(observationCount, !confidenceReady(companyGrade), 4),
      summary: `관측 ${fmtNumber(observationCount)}건 · 업체 신뢰도 ${companyGrade || "-"}`,
      nextAction: observationCount ? "지역카드와 전략으로 이어 보세요." : "빠른검색/상세검색 관측이 필요합니다."
    },
    {
      step: "02",
      title: "지역카드",
      status: statusFromCounts(regionSignals, regionSignals < 4, 4),
      summary: `${regionCard.region || report.company?.region || "지역"} · 신호 ${fmtNumber(regionSignals)}/6`,
      nextAction: regionSignals >= 4 ? "전략 근거로 사용할 수 있습니다." : "관심도·OTA·리드타임을 보강하세요."
    },
    {
      step: "03",
      title: "전략 추천",
      status: statusFromCounts(recommendations.length, recommendationConfidenceNeedsReview(recommendations), 3),
      summary: `전략 ${fmtNumber(recommendations.length)}건 · ${report.integratedLearning?.publicSummary || "이번 달 지표 기반"}`,
      nextAction: recommendations.length ? "실행할 카드부터 저장하세요." : "핵심 관측값이 더 필요합니다."
    },
    {
      step: "04",
      title: "실행계획",
      status: board ? statusFromCounts(operationsTotal, Number(operationsSummary.overdue || 0) > 0 || Number(operationsSummary.avgProgress || 0) < 50, 1) : "loading",
      summary: board ? `계획 ${fmtNumber(operationsTotal)}건 · 진행률 ${fmtReportScore(operationsSummary.avgProgress || 0)}` : "운영보드 로드 중",
      nextAction: operationsTotal ? "이번 주와 지연 항목을 먼저 보세요." : "전략 카드를 저장하면 채워집니다."
    },
    {
      step: "05",
      title: "월간 회고",
      status: retrospective ? statusFromCounts(retrospectiveTotal, Number(retrospectiveSummary.incompletePlans || 0) > 0 || Number(retrospectiveSummary.kpiInputRate || 0) < 80, 1) : "loading",
      summary: retrospective ? `성과 ${fmtReportScore(retrospectiveSummary.score || 0)} · 이월 ${(retrospective?.carryoverItems || []).length}건` : "회고 로드 중",
      nextAction: retrospectiveTotal ? "이월·반복 전략을 고르세요." : "실행과 KPI 입력이 필요합니다."
    },
    {
      step: "06",
      title: "다음달 후보",
      status: nextPlan ? statusFromCounts(nextTotal, Number(nextSummary.selectable || 0) === 0 || Number(nextSummary.duplicateWithExistingPlan || 0) > 0, 1) : "loading",
      summary: nextPlan ? `선택 가능 ${fmtNumber(nextSummary.selectable || 0)}/${fmtNumber(nextTotal)}건` : "후보 로드 중",
      nextAction: nextTotal ? "선택한 후보만 생성하세요." : "회고와 추천이 더 필요합니다."
    }
  ];
}

function reliabilityGradeFromStatus(status = "") {
  return ({
    ready: "A",
    review: "B",
    empty: "D",
    loading: "-"
  })[status] || "C";
}

function reliabilityToneForGrade(grade = "") {
  const normalized = String(grade || "").toUpperCase();
  if (["A", "B"].includes(normalized)) return "good";
  if (normalized === "C") return "warning";
  if (["D", "-"].includes(normalized)) return "muted";
  return "neutral";
}

function compactReliabilityNeeds(items = []) {
  const result = [];
  items.forEach((item) => {
    const value = String(item || "").trim();
    if (value && !result.includes(value)) result.push(value);
  });
  return result.length ? result.slice(0, 4) : ["추가 데이터 보강"];
}

function businessStepReliability(step = {}) {
  const report = state.business.report;
  const loading = {
    grade: "-",
    basis: "리포트 로드 대기",
    needs: ["숙소 선택", "리포트 로드"]
  };
  if (!report) return loading;

  const statusGrade = reliabilityGradeFromStatus(step.status);
  if (step.step === "01") {
    const observationCount = flowObservationCount(report.flows || {});
    const rawCompanyGrade = report.company?.confidenceGrade || "";
    const companyGrade = rawCompanyGrade || statusGrade;
    const needs = [];
    if (!observationCount) needs.push("빠른검색", "상세검색");
    if (!confidenceReady(rawCompanyGrade)) needs.push("대표 정보", "기준 수량");
    if (!needs.length) needs.push("지역카드 확인");
    return {
      grade: companyGrade || statusGrade,
      basis: `관측 ${fmtNumber(observationCount)}건 · 신뢰도 ${companyGrade || statusGrade}`,
      needs: compactReliabilityNeeds(needs)
    };
  }

  if (step.step === "02") {
    const card = report.regionCard || {};
    const signalCount = regionSignalCount(card);
    const grade = signalCount >= 5 ? "A" : signalCount >= 4 ? "B" : signalCount >= 2 ? "C" : "D";
    const needs = [];
    if (card.searchInterest?.score === null || card.searchInterest?.score === undefined) needs.push("검색 관심도");
    if (card.snsInterest?.score === null || card.snsInterest?.score === undefined) needs.push("SNS 관심도");
    if (!Number(card.otaExposure?.channelCount || 0)) needs.push("OTA 노출");
    if (!Number(card.leadtime?.patternCount || 0) && !Number(card.leadtime?.avgBookingPaceScore || 0)) needs.push("리드타임");
    if (!(card.demandKeywords || []).length) needs.push("수요 키워드");
    if (!needs.length) needs.push("전략 근거 연결");
    return {
      grade,
      basis: `${card.region || report.company?.region || "지역"} · 신호 ${fmtNumber(signalCount)}/6`,
      needs: compactReliabilityNeeds(needs)
    };
  }

  if (step.step === "03") {
    const recommendations = report.strategyRecommendations || [];
    const reviewCount = recommendations.filter((item) => ["D", ""].includes(String(item.recommendationConfidenceGrade || item.confidenceGrade || "").toUpperCase())).length;
    const grade = !recommendations.length ? "D" : reviewCount ? (reviewCount >= recommendations.length ? "C" : "B") : "A";
    const needs = [];
    if (!recommendations.length) needs.push("가격", "예약률", "리드타임", "관심도");
    if (reviewCount) needs.push("우선순위 검토", "KPI 지정");
    if (!needs.length) needs.push("실행계획 저장");
    return {
      grade,
      basis: `전략 ${fmtNumber(recommendations.length)}건 · 확인 필요 ${fmtNumber(reviewCount)}건`,
      needs: compactReliabilityNeeds(needs)
    };
  }

  if (step.step === "04") {
    const board = state.business.operationsBoard;
    if (!board) return loading;
    const summary = board.summary || {};
    const total = Number(summary.total || summary.count || (board.sections?.all || []).length || 0);
    const overdue = Number(summary.overdue || 0);
    const progress = Number(summary.avgProgress || 0);
    const kpi = summary.kpi || {};
    const missingKpi = Math.max(0, Number(kpi.total || 0) - Number(kpi.filled || 0));
    const grade = !total ? "D" : overdue || progress < 50 ? "C" : missingKpi ? "B" : "A";
    const needs = [];
    if (!total) needs.push("전략 저장");
    if (overdue) needs.push("담당자", "목표일");
    if (progress < 50) needs.push("체크리스트");
    if (missingKpi) needs.push("KPI 현재값");
    if (!needs.length) needs.push("이번 주 실행");
    return {
      grade,
      basis: `계획 ${fmtNumber(total)}건 · 지연 ${fmtNumber(overdue)}건 · 진행률 ${fmtReportScore(progress)}`,
      needs: compactReliabilityNeeds(needs)
    };
  }

  if (step.step === "05") {
    const retrospective = state.business.retrospective;
    if (!retrospective) return loading;
    const summary = retrospective.summary || {};
    const total = Number(summary.totalPlans || 0);
    const incomplete = Number(summary.incompletePlans || 0);
    const kpiRate = Number(summary.kpiInputRate || 0);
    const grade = !total ? "D" : incomplete || kpiRate < 80 ? "C" : "A";
    const needs = [];
    if (!total) needs.push("실행계획", "KPI");
    if (incomplete) needs.push("미완료 원인");
    if (kpiRate < 80) needs.push("KPI 입력");
    if (!needs.length) needs.push("이월 후보 선택");
    return {
      grade,
      basis: `성과 ${fmtReportScore(summary.score || 0)} · KPI ${fmtReportScore(kpiRate)} · 미완료 ${fmtNumber(incomplete)}건`,
      needs: compactReliabilityNeeds(needs)
    };
  }

  if (step.step === "06") {
    const nextPlan = state.business.nextMonthCandidates;
    if (!nextPlan) return loading;
    const summary = nextPlan.summary || {};
    const total = Number(summary.total || 0);
    const selectable = Number(summary.selectable || 0);
    const duplicate = Number(summary.duplicateWithExistingPlan || 0);
    const grade = !total ? "D" : duplicate || !selectable ? "C" : "A";
    const needs = [];
    if (!total) needs.push("회고", "신규 추천");
    if (duplicate) needs.push("중복 검토");
    if (!selectable) needs.push("후보 재검토");
    if (!needs.length) needs.push("후보 생성");
    return {
      grade,
      basis: `후보 ${fmtNumber(total)}건 · 선택 가능 ${fmtNumber(selectable)}건 · 중복 ${fmtNumber(duplicate)}건`,
      needs: compactReliabilityNeeds(needs)
    };
  }

  return {
    grade: statusGrade,
    basis: step.summary || "리포트 상태 확인",
    needs: compactReliabilityNeeds([step.nextAction])
  };
}

