async function startApp() {
  if (businessMode()) {
    await startBusinessApp();
    return;
  }
  if (state.started) return;
  state.started = true;
  initializeTheme();
  initializeDateInputs();
  ensureOperatorInformationArchitecture();
  ensureAuthAccountConsole();
  wireEvents();
  wireAuthAccountEvents();
  addFeedback("키워드를 입력하고 수집 실행을 누르면 진행 상태가 여기에 표시됩니다.", "info");
  loadTrafficKeyStatus().catch(() => {});
  loadAuthAccounts().catch((error) => addFeedback(`계정 관리 로드 실패: ${error.message}`, "error"));
  loadMasterDbCompanies()
    .then(() => Promise.all([loadInterestSignals(), loadInterestJobs(), loadExternalConnectors()]))
    .catch((error) => addFeedback(`DB 콘솔 로드 실패: ${error.message}`, "error"));
  await loadRuns(true);
}

async function boot() {
  initializeTheme();
  ensureAuthShell();
  wireAuthEvents();
  if (await prepareAuthLinkFlow()) return;
  const session = await loadAuthSession();
  if (!session.authenticated) {
    showAuthGate();
    return;
  }
  if (!businessMode() && session.account?.role === "business") {
    window.location.replace("/app");
    return;
  }
  if (!businessMode() && (session.mfa?.enrollmentRequired || session.mfa?.challengeRequired)) {
    showMfaGate(session);
    return;
  }
  showAuthenticatedSession(session);
  await startApp();
}

boot().catch((error) => {
  if (error.status === 401 || error.code === "AUTH_REQUIRED") {
    showAuthGate(error.message);
    return;
  }
  status("오류");
  els.detailPanel.innerHTML = `<div class="empty">${error.message}</div>`;
});
